INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(1, 'plPL', '', '', '', '', 'Wróć do Kanrethada.', '', '', '', '', 0),
(172, 'plPL', 'Tydzień Dziecka', 'Chcesz nam pomóc tu, w sierocińcu? Stokrotne dzięki, $gprzyjacielu:przyjaciółko; – twoja pomoc w Tygodniu Dziecka będzie nieoceniona.$B$BWeź ten gwizdek. Da się go używać tylko przez krótki czas – zwykle nie dłużej, niż trwa sam Tydzień Dziecka. Gdy go użyjesz, porozmawiasz z dzieckiem, którym $gzgodziłeś:zgodziłaś; się zaopiekować. Ponowne użycie odeśle dziecko.$B$BŚmiało, $N – użyj gwizdka i poznaj swojego podopiecznego! Dziecko na pewno nie może się doczekać spotkania z tobą.', 'Użyj gwizdka orczej sieroty, aby porozmawiać z dzieckiem, którym będziesz się opiekować w Tygodniu Dziecka.', '', '', '', '', '', '', 0),
(558, 'plPL', 'Autograf Jainy', 'Mówią, że Lady Jaina Proudmoore z Theramore to jedna z największych bohaterek, jakie kiedykolwiek miało Przymierze. Jak dorosnę, też chcę być bohaterem Przymierza!$B$BZnasz Jainę, $N? Zrobisz coś dla mnie, proszę? Zdobędziesz dla mnie jej autograf? Nie wiem, jak ją o to poprosić, a ona pewnie byłaby zbyt zajęta dla kogoś takiego jak ja... ale ty! Jesteś $gposzukiwaczem:poszukiwaczką; przygód, tak jak ona! Założę się, że da ci autograf bez problemu!$B$BProszę?', 'Udaj się do Theramore i spróbuj zdobyć autograf Lady Jainy Proudmoore dla swojego podopiecznego.', '', 'Wróć do ludzkiej sieroty.', '', '', '', '', 0),
(910, 'plPL', 'W dokach', 'Słyszałem opowieści o potężnych statkach, które pływają między Zapadką a Łupieżczą Zatoką! Ale by było super żeglować po oceanie i walczyć w wielu wielkich bitwach morskich. Może jak dorosnę, zostanę potężnym żeglarzem Hordy! Tak!$B$BZabierzesz mnie do doków w Zapadce, proszę? Obiecuję, że nie wejdę do wody i nie narobię kłopotów – chcę tylko zobaczyć wielkie statki i powąchać słoną morską wodę! Tak!', 'Zabierz swojego podopiecznego do doków w Zapadce na Pustkowiach.', 'Udaj się do doków w Zapadce na Pustkowiach.', 'Porozmawiaj ze swoją orczą sierotą.', '', '', '', '', 0),
(911, 'plPL', 'Brama na rubieże', 'Mówią, że Jesionowa Knieja to nowe rubieże, a Wał Mor\'shan na Pustkowiach to brama do nich. Ale by było super być pionierem i wydzierać nieujarzmionej dziczy wszystko, czego trzeba! Mówią, że to tam Horda i Przymierze będą się w przyszłości ścierać najczęściej, a ja chcę tam być, $N!$B$BZabierzesz mnie na Wał Mor\'shan, żebym zobaczył, jak wyglądają rubieże, proszę? Chcę zobaczyć, gdzie Horda przegania te śmierdzące nocne elfy!', 'Zabierz swojego podopiecznego na Wał Mor\'shan w północnej części Pustkowi, tuż przed wejściem do Jesionowej Kniei.', 'Udaj się na Wał Mor\'shan na Pustkowiach.', 'Porozmawiaj ze swoją orczą sierotą.', '', '', '', '', 0),
(1468, 'plPL', 'Tydzień Dziecka', 'Chcesz nam pomóc tu, w sierocińcu? Stokrotne dzięki, $gprzyjacielu:przyjaciółko; – twoja pomoc w Tygodniu Dziecka będzie nieoceniona.$B$BWeź ten gwizdek. Da się go używać tylko przez krótki czas – zwykle nie dłużej, niż trwa sam Tydzień Dziecka. Gdy go użyjesz, porozmawiasz z dzieckiem, którym $gzgodziłeś:zgodziłaś; się zaopiekować. Ponowne użycie odeśle dziecko.$B$BŚmiało, $N – użyj gwizdka i poznaj swojego podopiecznego! Dziecko na pewno nie może się doczekać spotkania z tobą.', 'Użyj gwizdka ludzkiej sieroty, aby porozmawiać z dzieckiem, którym będziesz się opiekować w Tygodniu Dziecka.', '', '', '', '', '', '', 0),
(1470, 'plPL', 'Przebić zasłonę', 'Witaj, dziecko. Widzę, że wciąż niewiele wiesz o ścieżkach czarnoksiężnika, a moc nadal wymyka ci się z rąk. Wyczuwam twój zapał do nauki.$b$bI nauczysz się.$b$bW niewiedzy nie ma siły. Wiedza to nasza największa potęga. Dzięki niej potrafimy panować nad chaotyczną magią i istotami Pustki, naginając je do swojej woli.$b$bPokażę ci, jak podporządkować sobie sługę, ale najpierw przynieś mi trzy czaszki szkieletów z Grzechoczących Klatek, które kręcą się przy opuszczonej kuźni.', 'Przynieś Venyi Marthand 3 czaszki z Grzechoczących Klatek.', '', 'Wróć do Venyi Marthand w Kotlinie Nocnej Sieci na Polanach Tirisfal.', '', '', '', '', 0),
(1479, 'plPL', 'Konar Wiecznych', 'Słyszałem, że nocne elfy mają bank w drzewie – takim, które wygląda jak niedźwiedź! Ale super! Nocne elfy są fajne, bo lubią przyrodę i w ogóle, ale niedźwiedzie są po prostu totalnie niesamowite!$B$BZabierzesz mnie do Darnassus zobaczyć to niedźwiedzie drzewo, proszę? Jest statek, który zawiezie nas w pobliże, i to nie powinno długo potrwać. Proszę, proszę, proszę!', 'Zabierz sierotę do banku w Darnassus. Sam bank jest wydrążony w drzewie zwanym Konarem Wiecznych.', 'Udaj się do banku w Darnassus, znanego też jako Konar Wiecznych.', 'Porozmawiaj ze swoją ludzką sierotą.', '', '', '', '', 0),
(1558, 'plPL', 'Kamienna Tama', 'W Żelaznej Kuźni mieszkają wszystkie krasnoludy i gnomy. Niedaleko jest miejsce, które nazywa się Loch Modan, i krasnoludy zbudowały tam OGROMNĄ tamę. Mówią, że to jedna z największych rzeczy, jakie ktokolwiek kiedykolwiek zbudował. Łał!$B$BZabierzesz mnie do Loch Modan zobaczyć tę tamę, proszę? To chyba Kamie... yy... Kamyczkowa Tama? Kamienna? Jest wielka – to na pewno. Chciałbym popatrzeć z góry na wielki wodospad. Obiecuję, że nie będę się za bardzo wychylać!', 'Zabierz sierotę na Kamienną Tamę w Loch Modan. Zaprowadź chłopca na środek tamy, żeby mógł popatrzeć z góry na olbrzymi wodospad.', 'Udaj się na szczyt Kamiennej Tamy w Loch Modan.', 'Porozmawiaj ze swoją ludzką sierotą.', '', '', '', '', 0),
(1598, 'plPL', 'Skradziona księga', 'Hej, ty! $n, tak?$b$bMam nadzieję, że na pewno chcesz parać się czarnoksięstwem, bo jeśli sobie nie poradzisz, łatwo pójdziesz na dno.$b$bMam cię uczyć, ale najpierw muszę się upewnić, że masz dość siły.$b$bW opactwie uczył się pewien nowicjusz, który uciekł, żeby przystać do Bractwa Nieskornych. Dlaczego mnie to obchodzi? Cóż, ukradł kilka ważnych ksiąg.$b$bJedna z nich to akurat księga, którą sama chciałam mieć – „Moce Pustki”. Ukradnij ją dla mnie. Trzymają ją ukrytą w swoim namiocie w winnicach.', 'Zdobądź „Moce Pustki” dla Drusilli La Salle.', '', 'Wróć do Drusilli La Salle w Dolinie Północnych Włości w Kniei Elwynn.', '', '', '', '', 0),
(1599, 'plPL', 'Początki', 'To o tobie wszyscy szepczą, prawda? $GNowy czarnoksiężnik:Nowa czarnoksiężniczka;. Ktoś musiał cię polubić, skoro poproszono mnie, żebym oderwał się od badań i zaczął cię szkolić.$b$bBez obaw, nie będę miał ci tego za złe.$b$bNajprostszym z zaklęć przyzywania, jakie poznasz, jest przyzwanie chochlika. Zanim jednak ci je przekażę, musisz dowieść, że masz niezbędne zdolności magiczne i fizyczne.$b$bPrzynieś mi trzy talizmany z piór, które noszą nowicjusze Mroźnej Grzywy w jaskini na południowym zachodzie.', 'Przynieś 3 talizmany z piór Alamarowi Grimmowi w Kowadlinie.', '', 'Wróć do Alamara Grimma na Przełęczy Zimnej Grani w Dun Morogh.', '', '', '', '', 0),
(1687, 'plPL', 'Nawiedzona latarnia', 'Czasem późnym wieczorem nasze opiekunki w sierocińcu opowiadają nam straszne historie. Są EKSTRA! Jedna jest o duchu, który nawiedza latarnię morską w Zachodnim Skraju. Podobno był kapitanem piratów, któremu inni piraci odebrali statek. Łał!$B$BZabierzesz mnie do latarni w Zachodnim Skraju, proszę? Chcę zobaczyć, czy jest tam duch tego kapitana! Obiecuję trzymać się blisko ciebie; nigdzie nie ucieknę ani nic!', 'Zabierz sierotę do latarni morskiej u wybrzeży Zachodniego Skraju.$B', 'Udaj się do Latarni Zachodniego Skraju.', 'Porozmawiaj ze swoją ludzką sierotą.', '', '', '', '', 0),
(1800, 'plPL', 'Sala tronowa Lordaeronu', 'Opiekunki w moim sierocińcu opowiadają wieczorami wspaniałe historie o bitwach i dawnych dziejach, jeśli jesteśmy grzeczni i wypełniamy obowiązki. Jedna była o tym, jak upadł Lordaeron i jak zły Arthas odebrał życie własnemu ojcu, żeby zostać władcą.$B$BOn nie miał honoru, $N! Kiedy dorosnę i zostanę potężnym wojownikiem Hordy, moim ostrzem będzie kierował honor – nigdy zło!$B$BZabierzesz mnie do sali tronowej, proszę? Jest tuż przed zejściem do Podmiasta.', 'Zabierz swojego podopiecznego do dawnej sali tronowej Lordaeronu, która znajduje się tuż przed zejściem do Podmiasta.$B', 'Udaj się do dawnej sali tronowej Lordaeronu, która znajduje się tuż przed zejściem do Podmiasta.', 'Porozmawiaj ze swoją orczą sierotą.', '', '', '', '', 0),
(2000, 'plPL', 'Rokar Cień Ostrza', 'Za dużo masz wolnego czasu, $n. Pora, żebyś lepiej $gpoznał:poznała; nasz fach. Zaledwie wczoraj w nocy pięcioro naszych znaleziono martwych w jednej z rozpadlin Orgrimmaru, a tropów jest niewiele. Są tacy, którzy nam się sprzeciwiają i obracają przeciw nam nasze własne metody.$b$bDlatego uznałem, że $gpowinieneś:powinnaś; nauczyć się sztuki otwierania zamków.$b$bNiestety, moje ręce niezbyt się do tego nadają. Odszukaj Rokara, który mieszka na wzgórzach niedaleko Durotaru. Podejrzewam, że mimo podeszłego wieku wciąż ma do tego dryg.', 'Porozmawiaj z Rokarem Cieniem Ostrza w Durotarze.', '', '', '', '', '', '', 0),
(2882, 'plPL', 'Złoto Cuerga', 'Ta mapa przedstawia odcinek plaży zwrócony ku południowi. Pod mapą widnieją starannie wykaligrafowane słowa...$B$B$BNa południe od Parochlebców bram,$BNa południe od domu, właśnie tam,$BGdzie maszt i flaga, i kości stos,$BKop, jeśli śmiałość dał ci los,$BKop i Cuerga złoto bierz!$BKlucza ci trzeba, klucz ujrzysz też,$BLecz kto go strzeże, krwi w zapłacie chce – wiedz.', 'Znajdź złoto Cuerga!', '', 'Wróć do skarbu pirata.', '', '', '', '', 0),
(3482, 'plPL', '<NYI> <TXT> Podziurawiona czarna skrzynka', '', 'Zanieś tę skrzynkę Kravelowi.', '', '', '', '', '', '', 0),
(3642, 'plPL', 'Przyrzeczenie tajemnicy', 'W gnomiej inżynierii chodzi o teorię inżynieryjną ukształtowaną tak, by służyła naszym potrzebom! Nasze schematy pozwalają budować urządzenia, które panują nad otaczającym nas światem; była o tym mowa w podręczniku, który $gprzeczytałeś:przeczytałaś;.$B$BW podręczniku była też mowa o naszej odwiecznej przysiędze, że schematy pozostaną tajemnicą. Gdy zostaniesz $ggnomim inżynierem:gnomią inżynierką;, klamka zapadła. Do goblińskiej inżynierii nie będziesz mieć żadnego dostępu.$B$BJeśli nadal chcesz zostać $ggnomim inżynierem:gnomią inżynierką;, podpisz ten dokument, przyrzekając dożywotnie zachowanie tajemnicy, i porozmawiaj ze mną ponownie. Dobrze się zastanów, $N.', 'Jeśli zgadzasz się zostać $ggnomim inżynierem:gnomią inżynierką;, kliknij prawym przyciskiem Przyrzeczenie tajemnicy i porozmawiaj jeszcze raz z Oglethorpe\'em Obnoticusem w Łupieżczej Zatoce.', '', 'Wróć do Oglethorpe\'a Obnoticusa na Dzikim Brzegu w Dolinie Cierniodławów.', '', '', '', '', 0),
(4822, 'plPL', 'Lody, lody dla ochłody...', 'LODY! Och, proszę, proszę, proszę, zdobędziesz dla mnie lody?! Truskawkowe to mój ulubiony smak, a na świecie nie ma lepszych lodów truskawkowych niż truskawkowe lody Tigule\'a i Forora! To moje ulubione lody na całym wielkim świecie!$B$BJadłem je raz, dawno temu, kiedy byłem na torze wyścigowym na Migoczących Równinach, ale słyszałem, że teraz mogą je sprzedawać w mieście! Proszę? Ślicznie proszę? Z truskawkowymi lodami Tigule\'a i Forora na czubku??!?!', 'Zdobądź lody truskawkowe dla swojego podopiecznego. Chłopak najwyraźniej woli lody marki Tigule\'a i Forora.', '', 'Wróć do ludzkiej sieroty.', '', '', '', '', 0),
(5628, 'plPL', 'Powrót do domu', '', '', '', '', '', '', '', '', 0),
(5629, 'plPL', 'Powrót do domu', '', '', '', '', '', '', '', '', 0),
(5630, 'plPL', 'Powrót do domu', '', '', '', '', '', '', '', '', 0),
(5631, 'plPL', 'Powrót do domu', '', '', '', '', '', '', '', '', 0),
(5632, 'plPL', 'Powrót do domu', '', '', '', '', '', '', '', '', 0),
(5633, 'plPL', 'Powrót do domu', '', '', '', '', '', '', '', '', 0),
(6661, 'plPL', 'Obława na szczury z podziemnej kolejki', 'Ahoj, hultaju. Arrrr... Arrrr, szukasz roboty? Mamy tu na dole poważny kłopot ze szczurami, a na rufie brakuje rąk do pracy.$B$BCo ty na to? Wystarczy, że weźmiesz ten oto flet szczurołapa i zagrasz melodyjkę koło tego robactwa. Pójdą za tobą na koniec świata!$B$BZłap ino pięć tych małych drani i przyprowadź tutaj. Potrzebne nam żywe.$B$BArrrrr...', 'Złap 5 szczurów z podziemnej kolejki za pomocą fletu szczurołapa. Zaprowadź szczury do Monty\'ego. Nie zapomnij oddać fletu, gdy skończysz.', '', 'Wróć do Monty\'ego w Obozie Internowania Lordamere w Górach Alterak.', 'Schwytane szczury', '', '', '', 0),
(6662, 'plPL', 'Mój brat, Nipsy', 'Mój brat, Nipsy, prowadzi po drugiej stronie podziemnej kolejki interes z kebabami ze szczurów. Musisz mu zanieść tę oto skrzynkę szczurów, zanim się zepsują. Ruszaj się!$B$BKolejką już się kiedyś jechało, hę? To proste. Wejdź na pokład, jak przybije, i ciesz się rejsem. I trzymaj ręce i nogi w środku podczas jazdy, bo do końca życia będziesz kuśtykać na drewnianej nodze.', 'Zanieś karton tajemniczego mięsa Nipsy\'emu na stacji podziemnej kolejki w Wichrogrodzie.', '', '', '', '', '', '', 0),
(6843, 'plPL', 'Da Foo', '', '', '', '', '', '', '', '', 0),
(8259, 'plPL', 'Stosowniejsza nagroda', '', '', '', '', '', '', '', '', 0),
(8344, 'plPL', 'Okna na źródło', 'Zważ na moje słowa, $gmłody:młoda; – nad tą wyspą ciąży skaza, i to znacznie silniejsza niż pozostałości Plagi.$B$BSądzę, że na wyspie jest prawdziwa demoniczna obecność.$B$BNa zachód stąd wznoszą się iglice Akademii Falthrien. Tajemne upiory, od których się tam roi, są oknem na źródło demonicznej mocy. Masz mi przynieść esencje upiorów skażonych i nieskażonych.$B$BW zamian za posłuszeństwo nauczę cię przyzywać chochlika – pierwszego z wielu twoich towarzyszy na ścieżce czarnoksiężnika.', 'Przynieś 4 esencje upiora i 1 skażoną esencję upiora przywoływaczowi Teli\'Larienowi w Słonecznej Iglicy na Wyspie Słońcobieżców.', '', 'Wróć do przywoływacza Teli\'Lariena w Gaju Wszechpieśni.', '', '', '', '', 0),
(8685, 'plPL', 'Nestor Mglisty Krok', '', '', '', '', '', '', '', '', 0),
(8900, 'plPL', 'Najdroższa Elenio,', 'Była taka smutna. Dostrzegłem to, gdy tylko przestałem zważać na jej stan. To znaczy, wyglądała na smutną – a ty byś nie $gwyglądał:wyglądała;?$b$bAle gdy z nią porozmawiałem, pojawiła się między nami więź. Nie sądziłem, że ktokolwiek może zrozumieć, co myślę, a ona potrafiła.$b$bKiedy powiedziałem o tym innym, wyśmiali mnie, więc nigdy więcej się do niej nie odezwałem. Ale tęsknię za nią. Zaniesiesz jej ode mnie ten list? Chcę mieć pewność, że trafi do jej rąk.', 'Dostarcz lekko pognieciony liścik Elenii Haydon, która stoi niedaleko banku w Podmieście.', '', '', '', '', '', '', 0),
(8901, 'plPL', 'Najdroższa Elenio,', 'Czy $gzaznałeś:zaznałaś; kiedyś miłości, $gmłody:młoda;? Mnie była obca aż do niedawna, gdy poznałem dziewczynę z Podmiasta, Elenię. Rzadko się zdarza, by ktoś z mojego ludu spojrzał poza swoich, a co dopiero na jedną z Porzuconych.$b$bAle teraz myśli o niej zaprzątają mi głowę dniami i nocami.$b$bJeśli możesz, zaniesiesz jej ten list? Chcę, żeby przybyła tu, do Mulgoru. Mam nadzieję, że się zgodzi.', 'Dostarcz starannie napisany list Elenii Haydon, która stoi niedaleko banku w Podmieście.', '', '', '', '', '', '', 0),
(8902, 'plPL', 'Najdroższa Elenio,', 'Całe życie temu byłem zaręczony z Elenią, moją ukochaną z dzieciństwa. Minęły lata, odkąd myślałem o niej ostatni raz, lecz ostatnio często zaprząta moje myśli.$b$bMoże mimo wszystkiego, co się wydarzyło, w życiu każdego z nas znajdzie się jeszcze miejsce na naszą miłość.$b$bNa pewno i ona się zmieniła. Dostarczysz jej ode mnie ten list? Zbyt się denerwuję, by wręczyć go osobiście.', 'Dostarcz z miłością ułożony list Elenii Haydon, która stoi niedaleko banku w Podmieście.', '', '', '', '', '', '', 0),
(8903, 'plPL', 'Niebezpieczna miłość', 'W tej epidemii miłości jest coś nienaturalnego. To nie przystoi, kłuje w oczy, a w najgorszym razie może zagrozić bezpieczeństwu samego Przymierza.$b$bPomyśl tylko: a jeśli ta dziwna przypadłość dopadła także strażników? Trzeba coś z tym zrobić.$b$bIdź do któregoś ze strażników tu, w Wichrogrodzie, i sprawdź, czy i jemu udzieliło się to szaleństwo.', 'Zdobądź kartkę od strażnika Wichrogrodu i zanieś ją Aristanowi Mottarowi w Wichrogrodzie.', '', 'Wróć do Aristana Mottara w Wichrogrodzie.', '', '', '', '', 0),
(8904, 'plPL', 'Niebezpieczna miłość', 'W tej epidemii miłości jest coś nienaturalnego. To obrzydliwe, a ponieważ osłabia naszą czujność, może zagrozić nam wszystkim.$b$bWystarczy, że tak wielu z nas dało się wciągnąć w te niedorzeczne zachowania. Ale sądzę, że ogarnęło to nawet naszych strażników, którzy powinni być na takie rzeczy odporni.$b$bZnajdź któregoś z naszych strażników i sprawdź, czy i jemu udzieliło się to szaleństwo.', 'Zdobądź spleśniałą kartkę od strażnika i zanieś ją Fenstadowi Argyle\'owi w Podmieście.', '', 'Wróć do Fenstada Argyle\'a nad Jeziorem Lordamere w Górach Alterak.', '', '', '', '', 0),
(8979, 'plPL', 'Przeczucie Fenstada', 'Chyba znam przyczynę tych zachowań. Czy $gpoczułeś:poczułaś; nową woń niesioną wiatrem, przebijającą się przez smród kanałów? Te nowe wody kolońskie i perfumy, które weszły w modę?$b$bNasze umysły zaćmiła jakaś plugawa alchemia.$b$bJest tylko jeden sposób, by się upewnić – zanieś butelkę wody kolońskiej i butelkę perfum mojej przyjaciółce, aptekarce Zinge. Królewskie Zakłady Chemiczne odkryją prawdę.$b$bPo powrocie zwrócę ci koszt zakupu.', 'Zanieś 1 butelkę wody kolońskiej i 1 butelkę perfum aptekarce Zinge w Aptekarium w Podmieście.', '', 'Wróć do aptekarki Zinge nad Jeziorem Lordamere w Górach Alterak.', '', '', '', '', 0),
(8981, 'plPL', 'Wręczanie prezentów', '', '', '', 'Wróć do Kwee Q. Szybkonóżka.', '', '', '', '', 0),
(8993, 'plPL', 'Wręczanie prezentów', '', '', '', 'Wróć do Kwee Q. Szybkonóżka.', '', '', '', '', 0),
(9024, 'plPL', 'Przeczucie Aristana', 'Mam! Czy $gpoczułeś:poczułaś; nową woń niesioną wiatrem? Te nowe wody kolońskie i perfumy, które weszły w modę? Nasi strażnicy nie zaniedbaliby obowiązków tak łatwo.$b$bChyba że ich umysły zaćmiła jakaś plugawa alchemia.$b$bJest tylko jeden sposób, by się upewnić – zanieś butelkę wody kolońskiej i butelkę perfum Morganowi Pestle\'owi i powiedz mu o moich podejrzeniach. Po powrocie zwrócę ci koszt zakupu.', 'Zanieś 1 butelkę wody kolońskiej i 1 butelkę perfum Morganowi Pestle\'owi w Dzielnicy Handlowej Wichrogrodu.', '', 'Wróć do Morgana Pestle\'a w Wichrogrodzie.', '', '', '', '', 0),
(9025, 'plPL', 'Odkrycie Morgana', 'A niech mnie. Wygląda na to, że Aristan może jednak mieć rację. Znalazłem ślady substancji używanych w eliksirach miłosnych i w podstępnych wywarach mącących umysł.$b$bZdarza się, że perfumy zawierają niektóre z nich, ale kilka składników, które wykryłem... Coś tu śmierdzi.', 'Wróć do Aristana Mottara przed bankiem w Dzielnicy Handlowej Wichrogrodu.', '', '', '', '', '', '', 0),
(9029, 'plPL', 'Bulgoczący kocioł', '', '', '', '', '', '', '', '', 0),
(9065, 'plPL', 'Specjał Pattymaca', 'Hej, ty, zburz tę wieżę!', 'Koniecznie zniszcz tę wieżę!', '', 'Wróć do Kanrethada.', '', '', '', '', 0),
(9094, 'plPL', 'Rękawice Argentowego Brzasku', '', '', '', 'Wróć do kwatermistrza Argentu.', '', '', '', '', 0),
(9154, 'plPL', 'Kaplica Świetlistej Nadziei', 'Plaga powróciła, liczniejsza niż kiedykolwiek dotąd. To musi być sprawka Króla Lisza! Argentowy Brzask werbuje wszystkich chętnych i zdolnych do walki, mężczyzn i kobiety, do obrony naszych ziem.$b$bJeśli łączy nas wspólna sprawa, zanieś ten dokument strażnikowi rejestrów w Kaplicy Świetlistej Nadziei na Wschodnich Plagowiskach.', 'Dostarcz ogłoszenie wezwania do boju strażnikowi rejestrów w Kaplicy Świetlistej Nadziei na Wschodnich Plagowiskach.', '', '', '', '', '', '', 0),
(9317, 'plPL', 'Poświęcone osełki', '', '', '', 'Wróć do kwatermistrza Argentu.', '', '', '', '', 0),
