(25055, 'plPL', 'Badania nad żywiołami', '[ph] Dam ci worek szamańskich rzeczy. Użyj sapty żywiołów, by wejść w świat duchów, i użyj totemu na wzburzonych żywiołakach ziemi.', '', '', '', '', '', '', '', 0),
(25092, 'plPL', 'Badania nad żywiołami', '[ph] Dam ci worek szamańskich rzeczy. Użyj sapty żywiołów, by wejść w świat duchów, i użyj totemu na wzburzonych żywiołakach ognia.', '', '', '', '', '', '', '', 0),
