INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(172, 'plPL', 'Zug zug! Mam na imię Grunth i to chyba ty się mną opiekujesz? Jesteś $gposzukiwaczem:poszukiwaczką; przygód, tak jak moja mama i mój tata. Opiekunka mówi, że zginęli z honorem w bitwie. Miło mi cię poznać.$B$BMam nadzieję, że zrobimy razem mnóstwo rzeczy. Jest parę rzeczy, które chciałbym zrobić, a opiekunka mówi, że w tym tygodniu będziesz dla mnie jak $gstarszy brat:starsza siostra;. Bardzo, bardzo bym tego chciał.', 0),
(558, 'plPL', 'ŁAŁ! $GZdobyłeś:Zdobyłaś; dla mnie autograf Lady Jainy! Bardzo dziękuję! I łał... napisała tu osobistą dedykację – dla mnie! Wiedziałem, że jest superfajna, i może kiedyś sam jej podziękuję... jak zostanę bohaterem Przymierza!$B$BJesteś $gnajlepszy:najlepsza;, $N. Dziękuję, że jesteś dla mnie $gtaki miły:taka miła;.', 0),
(910, 'plPL', 'Łał, ocean jest OGROMNY! Było tam też mnóstwo mew i w ogóle – jest tak głośno i gwarno, jak myślałem. A niedaleko są też piraci – ale super!$B$BDziękuję, że $gzabrałeś:zabrałaś; mnie do Zapadki, $N. Było niesamowicie!', 0),
(911, 'plPL', 'Łał, to w Jesionowej Kniei dzieją się prawdziwe przygody! $GWalczyłeś:Walczyłaś; kiedyś w Jesionowej Kniei, $N? Jak dorosnę i zostanę bohaterem, chcę przyjść do Jesionowej Kniei i walczyć za chwałę Hordy!$B$BDziękuję, że $gzabrałeś:zabrałaś; mnie na rubieże, $N. Jesteś $gnajlepszy:najlepsza;!', 0),
(915, 'plPL', 'Mmmmmmmmm! Uwielbiam ich lody truskawkowe! Jeśli Tigule i Foror coś potrafią, to robić lody!$B$BBardzo ci dziękuję, $N – to najlepszy smakołyk na świecie!', 0),
(925, 'plPL', 'ŁAŁ! $GZdobyłeś:Zdobyłaś; dla mnie odcisk kopyta Kairna! Bardzo dziękuję! I łał... napisał tu osobistą dedykację – dla mnie! Wiedziałem, że jest superfajny, po prostu wiedziałem! Może kiedyś sam mu podziękuję... jak zostanę bohaterem Hordy!$B$BJesteś $gnajlepszy:najlepsza;, $N. Dziękuję, że jesteś dla mnie $gtaki miły:taka miła;.', 0),
(1468, 'plPL', 'Yy... cześć. Mam na imię Randis i to chyba ty się mną opiekujesz? Jesteś $gposzukiwaczem:poszukiwaczką; przygód, tak jak moja mama i mój tata. Miło mi cię poznać.$B$BMam nadzieję, że będziemy się razem świetnie bawić. Jest parę rzeczy, które chciałbym zrobić, a opiekunka mówi, że w tym tygodniu będziesz dla mnie jak $gstarszy brat:starsza siostra;. Bardzo, bardzo bym tego chciał, $gproszę pana:proszę pani;.', 0),
(1470, 'plPL', 'Choć brak ci jeszcze doświadczenia, a twoja nauka dopiero się zaczęła, $gdowiodłeś:dowiodłaś;, że masz dość zdolności, by opanować przyzywanie i pętanie chochlika. Nie daj się zwieść jego rozmiarom. Choć brak mu siły fizycznej, ma moce i spryt, które dobrze ci się przysłużą.$b$bSłuchaj mnie uważnie, $N, bo nie powtórzę tej lekcji, a jej opanowanie pozostawiam tobie.', 0),
(1479, 'plPL', 'Łał, był jeszcze fajniejszy, niż sobie wyobrażałem – Konar Wiecznych! Nie myślałem, że będzie taki wielki, a był! $GWidziałeś:Widziałaś; też tego ptaka na czubku?! Ciekawe, jak zrobili, że gałęzie tak wyglądają!$B$BDzięki, że $gzabrałeś:zabrałaś; mnie do Darnassus, $N. Jesteś super!', 0),
(1485, 'plPL', 'Szkoląc się jako $c, nauczysz się przywoływać najróżniejsze istoty. Niektóre na to nie wyglądają, ale wszystkie są użytecznymi narzędziami.$B$BNie daj się zwieść niewielkim rozmiarom chochlika. Jak z pewnością $gzauważyłeś:zauważyłaś;, to wciąż groźny przeciwnik.', 0),
(1558, 'plPL', 'ŁAŁ – tama była O WIELE większa, niż myślałem! Ledwo słyszałem własne słowa przez szum całej tej pędzącej wody! Ej, myślisz, że kiedyś mogłoby jej zabraknąć wody? Rany, co by było, gdyby ta tama kiedyś pękła! ŁAŁ, to by było straszne!$B$BDzięki, że $gzabrałeś:zabrałaś; mnie zobaczyć tamę. To było bardzo miłe z twojej strony. Mówiłem, że nie będę się za bardzo wychylać!', 0),
(1598, 'plPL', 'Doskonale... Nigdy nie udało mi się dostać do tego tekstu – trzymano go w strzeżonym skrzydle biblioteki, a kręcąc się tam, wzbudziłabym podejrzenia.$B$BCóż, dobrze się $gspisałeś:spisałaś;, zdobywając tę księgę, i jestem przekonana, że pewnie poradzisz sobie z własnym chochlikiem, więc nie ma powodu, żebym nie pokazała ci, jak go przyzwać.', 0),
(1599, 'plPL', 'Bardzo dobrze, bardzo dobrze! Świetnie się $gspisałeś:spisałaś;, $N. Może zainteresowanie, jakie budzisz, jest jednak zasłużone.$B$BO tym zdecydują inni – o ile twój chochlik cię nie pokona i nie zdusi twojej kariery w zarodku. Na razie wystarczy mi, że pewnie przeżyjesz swoje pierwsze miesiące jako $c.$B$BSłówko o chochliku, $N. Jak wie każdy $R, rozmiar bywa mylący – jego magia potrafi być bardzo groźna.', 0),
(1661, 'plPL', 'Gratulacje i niech Światłość ma cię w opiece.', 0),
(1687, 'plPL', 'ŁAŁ, to był najprawdziwszy duch! Ale super – nie mogę się doczekać, aż opowiem wszystkim w sierocińcu. Kapitan Grayson... nawet wyglądał jak pirat! Jak dorosnę, też chcę być duchem pirata!$B$BDzięki, że $gzabrałeś:zabrałaś; mnie do Zachodniego Skraju, $N. Wiem, że w dziczy Zachodniego Skraju czają się straszne rzeczy, i mam nadzieję, że nie było ze mną za dużo kłopotu. Jesteś super!', 0),
(1800, 'plPL', 'Ta sala tronowa była straszna, $N! Chociaż była pusta, czuło się, że stało się tam wielkie zło. Byłem wściekły... ale było mi też smutno. Rozumiem, dlaczego opiekunki opowiadają nam takie historie; ja nigdy tak nie zdradzę swojego ludu!$B$BDziękuję, że $gzabrałeś:zabrałaś; mnie do sali tronowej, $N. Dużo się nauczyłem.', 0),
(2882, 'plPL', 'Ukryty skarb kapitana Cuerga czeka!', 0),
(3638, 'plPL', 'Witaj na pokładzie, $ginżynierze gobliński:inżynierko goblińska; $N! Wkrótce uzyskasz dostęp do najpotężniejszych schematów inżynieryjnych w całym Azeroth.$b$bSkoro $gpoświęciłeś:poświęciłaś; się zgłębianiu tej wiedzy, pora przyjrzeć się twoim pracom z zakresu goblińskiej inżynierii. Potem pomożemy ci ułożyć plan, który pozwoli w pełni wykorzystać twoje talenty w goblińskiej inżynierii!', 0),
(3640, 'plPL', 'Witaj na pokładzie, $N! Wkrótce uzyskasz dostęp do najbardziej zaawansowanych schematów inżynieryjnych w całym Azeroth.$B$BSkoro $gpoświęciłeś:poświęciłaś; się zgłębianiu tej wiedzy, pora przyjrzeć się twoim pracom z zakresu gnomiej inżynierii. Potem pomożemy ci ułożyć plan, który pozwoli w pełni wykorzystać twoje talenty w gnomiej inżynierii!', 0),
(3642, 'plPL', 'Witaj na pokładzie, $N! Wkrótce uzyskasz dostęp do najbardziej zaawansowanych schematów inżynieryjnych w całym Azeroth.$B$BSkoro $gpoświęciłeś:poświęciłaś; się zgłębianiu tej wiedzy, pora przyjrzeć się twoim pracom z zakresu gnomiej inżynierii. Potem pomożemy ci ułożyć plan, który pozwoli w pełni wykorzystać twoje talenty w gnomiej inżynierii!', 0),
(4822, 'plPL', 'Mmmmmmmmm! Uwielbiam ich lody truskawkowe! Jeśli Tigule i Foror coś potrafią, to robić lody!$B$BBardzo ci dziękuję, $N – to najlepszy smakołyk na świecie!', 0),
(6661, 'plPL', 'Te się nadadzą, kamracie. Mój brat potrzebuje ich żywych i wierzgających, bo inaczej kwaśnieją... A nie chcesz kosztować skwaśniałego kebabu ze szczura.', 0),
(6662, 'plPL', 'Biedny Monty. Od wypadków w Gnomoregan nie jest już sobą. Ten chłopak w życiu nie widział oceanu, a co dopiero mówić o byciu jakimś piratem.$b$b<Nipsy wzdycha.>$b$bPrzynajmniej dba o stały dopływ wierzgających stworzonek.', 0),
(8344, 'plPL', 'Dobra robota! Tak, tyle esencji powinno wystarczyć, bym zaczął badania. Mam silne przeczucie, że ta skażona esencja okaże się tym, czego trzeba... oknem, o którym wspominałem.$B$BU progu nauki wykonywanie poleceń mistrzów jest wielce wskazane. Zgodnie z obietnicą oto nagroda za posłuszeństwo i kompetentne wypełnienie poleceń – wiedza, jak przyzwać i spętać własnego chochlika.$B$BUżywaj jej dobrze, $N.', 0),
(8411, 'plPL', 'To są żywioły, których mi trzeba. Teraz pogadamy.', 0),
(8900, 'plPL', 'Nikt by się nie spodziewał, że ork może być tak elokwentny. Rzecz jasna, dotąd nie mieliśmy właściwie okazji ich poznać. Dziękuję, że mi to $gprzyniosłeś:przyniosłaś;.', 0),
(8901, 'plPL', 'Jakże miłe słowa pisze do mnie Temma. Lecz choć jego słowa mnie poruszają, nie mogę brać pod uwagę miłości taurena. Zbyt wiele dzieli nasze myśli, ciała i umysły.$B$BDobrze, że nie muszę wysłuchiwać tych jego wyznań osobiście. Nie zniosłabym tego, że łamię mu serce.', 0),
(8902, 'plPL', 'To przywołuje wspomnienia sprzed całego życia, $N. Elenia Tor. Tak miałam się nazywać, wiesz? Mieliśmy urządzić piękną uroczystość nad brzegiem jeziora. A gdy odszedłby ze służby, znaleźlibyśmy sobie gospodarstwo, by na nim osiąść.$B$BProste to były marzenia.$B$BAle gdyby zobaczył mnie teraz, wątpię, czy w ogóle dostrzegłby we mnie Elenię. Jedynie zimne ciało i martwe serce...', 0),
(8903, 'plPL', 'A więc to prawda. Nie do wiary. Jak mogło do tego dojść? Daj mi chwilę pomyśleć. Musi być jakaś przyczyna.', 0),
(8904, 'plPL', 'A więc to prawda. Nie do wiary. Jak mogło do tego dojść? Daj mi chwilę pomyśleć. Musi być jakaś przyczyna.', 0),
(8979, 'plPL', 'Kolejna obsesja Fenstada, jak widzę. Czy on myśli, że Królewskie Zakłady Chemiczne nie mają nic lepszego do roboty niż prowadzić jego małe śledztwa?$B$BNo dobrze, znów zrobię mu tę przyjemność.', 0),
(9024, 'plPL', 'Rozumiem obawy Aristana, ale naprawdę uważam, że przesadza. Niech młodzi robią, co chcą. Aristan chyba zapomniał, co to znaczy być młodym i zakochanym.$B$BAle lepiej mu tego nie mówić. Zróbmy mu tę przyjemność.', 0),
(9025, 'plPL', 'Choć spodziewałem się, że tak będzie, niepokoi mnie, że moje podejrzenia się potwierdziły. Musimy starannie rozważyć następny krok.$B$BProszę, oto zwrot za zakup wody kolońskiej i perfum.', 0),
(9029, 'plPL', 'Z kotła unosi się przyjemna woń.', 0),
(9154, 'plPL', 'Argentowy Brzask wezwał pomocy, a ty $godpowiedziałeś:odpowiedziałaś; na wezwanie. Nie mamy czasu, by cię szkolić. Pokładamy wiarę w twoich umiejętnościach i w tym, że wraz z nami odeprzesz zagrożenie ze strony Plagi.', 0),
(9525, 'plPL', 'Dzięki tobie ten dzień stał się lepszy, $N. Gdy przyjdzie mi umrzeć, dopilnuję, by stało się to na polu bitwy... we krwi moich przeciwników, których zabiorę ze sobą.', 0),
(10942, 'plPL', 'Hmpf, to ty masz się mną opiekować? Jestem Salandria! Mieszkam tu, odkąd byłam malutka. Rodziców zabrała mi wojna, więc muszę mieszkać w sierocińcu.$b$bNie jest tu tak źle, ale zawsze chciałam gdzieś pojechać – nigdy nawet nie wystawiłam nosa poza miasto. Mam już listę wszystkich fajnych miejsc, które chcę zobaczyć, i superrzeczy, które chcę zrobić.$b$bMogę ruszać, kiedy tylko zechcesz!', 0),
(10943, 'plPL', 'To na pewno ty będziesz $gmoim starszym bratem:moją starszą siostrą; na Tydzień Dziecka! Jestem Dornaa, miło mi cię poznać.$b$b<Na chwilę smutnieje.>$b$bMama i tata zginęli na wojnie, a ja całe życie mieszkam w sierocińcu. Właściwie jest tam miło, ale zawsze chciałam podróżować i oglądać różne rzeczy.$b$bMam już listę miejsc, które moglibyśmy odwiedzić, jeśli można? Już wiem, że będziemy się razem świetnie bawić!$b$bMogę ruszać, kiedy tylko zechcesz!', 0),
(10950, 'plPL', 'Och, jest po prostu cudowne! To znaczy, wygląda na dość stare... i tak, ktoś je naprawdę wysadził. Ale tylko popatrz!$b$bOoo, a $gpatrzyłeś:patrzyłaś; na niebo?$b$bAle super!', 0),
(10951, 'plPL', 'Opowieści nawet w połowie nie oddają tego, jak tu jest super. Niesamowite!$b$bCzy to prawda, że stworzył go potężny czarodziej imieniem Medivh?$b$bCiekawe, co jest po drugiej stronie? Ty tam $gbyłeś:byłaś;, prawda? Hmm, koniecznie musimy pojechać gdzieś po drugiej stronie Mrocznego Portalu!', 0),
(10952, 'plPL', 'Opowieści opiekunki sierocińca nawet w połowie nie oddają tego, jak tu jest super. Niesamowite! Mówiła, że stworzył go potężny czarodziej imieniem Medivh.$b$bCo jest po drugiej stronie? Ty tam $gbyłeś:byłaś;, prawda? Koniecznie musimy pojechać gdzieś po drugiej stronie Mrocznego Portalu!', 0),
(10962, 'plPL', 'Ale super! Mój własny smok! Mam nadzieję, że kiedyś będę miała tyle szczęścia, żeby zaprzyjaźnić się z prawdziwym smokiem.$B$B<Dornaa podskakuje z radości, mocno tuląc nową zabawkę.>$B$BTo była najlepsza wycieczka na świecie! Oby nigdy się nie skończyła.', 0),
(10963, 'plPL', 'Czad! Mój własny smok! Kiedyś będę miała prawdziwego.$B$B<Salandria chytrze zerka na nową zabawkę, a w jej głowie już obracają się trybiki.>$B$BTo była najlepsza wycieczka na świecie! Oby nigdy się nie skończyła.', 0),
(10991, 'plPL', '<Krogulec posłusznie przekazuje słowa Arthorn.>$B$BDobra robota, $N. Obawiałam się, że więzienie sokoła uległo zniszczeniu podczas wybuchu Auchindoun. Jesteśmy już niemal gotowi stawić czoło Anzu, $N. Chętnie poszłabym z tobą, by być przy tym, jak ten samozwańczy „bóg” zostanie strącony z powrotem w otchłań, która go zrodziła!', 0),
(11321, 'plPL', 'Ooo, to tylko bon na kufel... A może po prostu zgrywasz $gniedostępnego:niedostępną;. No to masz, oto tegoroczny kufel.$B$BAle coś czuję, że będziemy się widywać o wiele częściej. W końcu jeśli chcesz wymienić żetony Festiwalu Piwa, to jestem twoją dziewczyną...$B$BA może jego dziewczyną...$B$BOoooch... albo jego...', 0),
(11413, 'plPL', 'A to co? Bon na kufel? Czyli lubisz wypić? Świetnie! Jak już dam ci ten kufel, idź się napić! Potem wypij jeszcze trochę. A po tym może jeszcze parę kolejek... A potem, i to ważne, przyjdź do mnie.$B$BSłuchaj, wiem, że w końcu wrócisz. Jeśli chcesz wymienić swoje żetony Festiwalu Piwa albo odznaki obrońcy beczki, musisz przyjść do mnie.$B$BTak czy siak, oto kufel. I pamiętaj, żeby potem ze mną pogadać.', 0),
(11886, 'plPL', 'To niepokojące, $gprzyjacielu:przyjaciółko;. Wygląda to na znacznie większy spisek niż zwykłe podburzanie miejscowych żywiołów ognia i wody. Coś tu wymaga zbadania...', 0),
(11891, 'plPL', 'Chcą przyzwać do naszego świata władcę mrozu? Nie! Nie mogą zachwiać równowagi!', 0),
(11975, 'plPL', '$GWidziałeś:Widziałaś; to? Wiwatowali na moją cześć!!$B$BTeraz wiem, co czują, kiedy śpiewają na scenie! Poczułam moc i energię!$B$BDokładnie tak, jak śpiewają w swojej piosence!$B$BJuż postanowiłam: jak dorosnę, zostanę gwiazdą rocka!', 0),
(12318, 'plPL', 'Jesteś z obozu Festiwalu Piwa? Cóż za dzień! Może jeszcze uda się ocalić Festiwal Piwa.$B$B$N, trzeba powstrzymać Corena Bimberhausta! Nie możemy pozwolić, by sabotował nasze uświęcone święto. Nasze piwo musi płynąć!', 0),
(12515, 'plPL', 'Mój... mój kapelusz! Ale... jak ci się...?$b$bCóż... mniejsza z tym. Teraz znasz mój sekret. ZOSTAŁEM pokonany... raz. Proszę, weź ten kapelusz w zamian za mój. $GZasłużyłeś:Zasłużyłaś; na niego.', 0),
(12517, 'plPL', 'Twój talent do pióra już zaczyna się ujawniać, $gmłody skrybo:młoda skrybo;. Karty tarota bardzo interesują Festyn Lunomroku, więc nie wahaj się nas wezwać, jeśli uda ci się stworzyć kolejne. Sami też mamy zdolnych rzemieślników, pozwól więc, że zaproponujemy coś w zamian za karty.', 0),
(12518, 'plPL', 'Twoje umiejętności robią ogromne wrażenie! Karty tarota bardzo interesują Festyn Lunomroku, więc nie wahaj się nas wezwać, jeśli uda ci się stworzyć kolejne. Sami też mamy zdolnych rzemieślników, pozwól więc, że zaproponujemy coś w zamian za karty.', 0),
(12752, 'plPL', 'Witaj, $gbracie:siostro;. Może i przybywasz w imieniu Argentowego Brzasku, ale nie po to tu jesteś – jesteś tu, by pomóc swojemu ludowi zdobyć szacunek, na który tak słusznie zasługujemy. Każdy Porzucony przyzna, że cel uświęca środki, a nasze badania nad lekarstwem na zarazę zombie to ta maksyma w praktyce...', 0),
(12753, 'plPL', '$GBracie krasnoludzie:Siostro krasnoludko;, to dla mnie zaszczyt stać u twego boku w dniach próby. Bądź $gbłogosławiony:błogosławiona; i oby sojusz krasnoludów i ludzi przetrwał tysiąc lat.', 0),
(12772, 'plPL', '$N, $gczcigodny nocny elfie:czcigodna nocna elfko;, witaj. Niech Światłość cię opromienia, a twoja pradawna mądrość niech strzeże naszej krainy w potrzebie.', 0),
(12775, 'plPL', '$GBracie:Siostro;, znów wzywa się nas do walki z Plagą. Dobrze, że jesteś; z twoją siłą i z mocą Światłości może jeszcze zwyciężymy.', 0),
(12777, 'plPL', 'Serce wzbiera mi Światłością na widok $gszlachetnego:szlachetnej; draenei, $gktóry:która; przybywa nam z pomocą. Bądź $gbłogosławiony:błogosławiona;!', 0),
(12782, 'plPL', 'Cóż za wspaniały okaz. Mamy do przeprowadzenia wiele eksperymentów, a nasz zapas ochotników jest na wyczerpaniu. A zatem, $gelfie:elfko;, jak sugeruje nazwa, którą twoja rasa sama sobie nadała... Masz krew na zbyciu? Świeża krew jest u nas zawsze mile widziana...', 0),
(12783, 'plPL', 'Cóż za wspaniały, krzepki okaz. Mamy do przeprowadzenia wiele eksperymentów, a nasz zapas ochotników jest na wyczerpaniu. Świeża krew jest u nas zawsze mile widziana, a wściekłość w twojej krwi mogłaby napędzać całe godziny badań.', 0),
(12784, 'plPL', 'Cóż za wspaniały, krzepki okaz. Mamy do przeprowadzenia wiele eksperymentów, a nasz zapas ochotników jest na wyczerpaniu. Świeża krew jest u nas zawsze mile widziana, a ktoś twojej postury z pewnością ma krew na zbyciu...', 0),
(12798, 'plPL', 'Twoja biegłość w inskrypcji wzrosła, skrybo. Karty tarota bardzo interesują Festyn Lunomroku, więc nie wahaj się nas wezwać, jeśli uda ci się stworzyć kolejne. Sami też mamy zdolnych rzemieślników, pozwól więc, że zaproponujemy coś w zamian za karty.', 0),
(12808, 'plPL', '$GBracie gnomie:Siostro gnomko;, to dla mnie zaszczyt stać u twego boku w dniach próby. Bądź $gbłogosławiony:błogosławiona; i oby bystre oczy twojej rasy pomogły znaleźć drogę do naszego ocalenia.', 0),
(12811, 'plPL', 'Cóż za wspaniały, krzepki okaz. Mamy do przeprowadzenia wiele eksperymentów, a nasz zapas ochotników jest na wyczerpaniu. Świeża krew jest u nas zawsze mile widziana, a twoja pierwotna krew mogłaby napędzać całe godziny badań.', 0),
(13250, 'plPL', 'Dziękuję, $N. Dopilnuję, by sama esencja boga była bezpieczna, dopóki nie będzie można przekazać jej Plemieniu Zandalarów.$b$bMoże oni znajdą sposób, by na nowo ucieleśnić z niej Akaliego?', 0),
(13254, 'plPL', 'Z jakimiż okropnościami $gmusiałeś:musiałaś; się mierzyć, przemierzając Górne Miasto.$b$b<Lan\'dalock zerka na zmatowiałą koronę, którą ściskasz w dłoni.>$b$bMoże powinniśmy odłożyć ją dla ich nowego króla, gdy nerubianie postanowią jakiegoś koronować?', 0),
(13311, 'plPL', 'Szybko stajesz się $gmistrzem:mistrzynią; pióra. Karty tarota bardzo interesują Festyn Lunomroku, więc nie wahaj się nas wezwać, jeśli uda ci się stworzyć kolejne. Sami też mamy zdolnych rzemieślników, pozwól więc, że zaproponujemy coś w zamian za karty.', 0),
(13627, 'plPL', 'Same doskonałe deski, i cena też w sam raz! A co najlepsze, te sztywniaki z Krucjaty Argentu nigdy się nie dowiedzą. Oni dostaną swoje ukochane koloseum, a ja premię za ukończenie przed terminem. Wszyscy wygrywają, jak nic.', 0),
(13681, 'plPL', 'Te się nadadzą. Tylko nie rozpowiadaj tym krzyżowcom, skąd je masz. Na pewno by się zdenerwowali. Ale co tam, przecież tytani po nie nie wrócili. Moim zdaniem są do wzięcia. Dobra robota, $N.', 0),
(13820, 'plPL', 'Czyli justycjariuszka przysłała cię do nas? Dobrze, dobrze...$b$bZawsze przyda się więcej rąk do, ee, „rekwirowania” materiałów.', 0),
(13926, 'plPL', 'Ty zabrać nas od młodych pieskoludzi? Dobrze. My już cię lubić. Wredne młode pieskoludzi zabrać nam wszystkie ulubione zabawki.', 0),
(13927, 'plPL', 'Ty zabrać Kekeka na polowanie? Dobrze uciec od wrednej starej pani od sierot, co nie pozwalać Kekekowi polować.', 0),
(13929, 'plPL', 'My nie wiedzieć, że drzewa rosnąć takie wielkie! Nie. Może Wielcy mieć dla niego specjalny plan?', 0),
(13930, 'plPL', 'To miasto w sam raz dla Kekeka. Niedźwiedzioludzie walczyć o dom, tak jak Szalone Serce. Pani od sierot mówić Kekekowi, żeby nie bić się z innymi szczeniakami, ale Kekek i tak się bić.', 0),
(13933, 'plPL', 'My bardzo się cieszyć, że ty nas tu zabrać, $N. My zawsze się martwić, co z nami być, odkąd opiekunka sierocińca znaleźć nas w Sholazar.', 0),
(13934, 'plPL', 'Widzieć? Kekekowi nigdy się nie znudzić mówić: „Kekek ci mówić”.$b$bMoże teraz ty uwierzyć w inne rzeczy, co Kekek ci mówić – na przykład że niebo zielone.', 0),
(13937, 'plPL', 'Ale fajnie! My lubić sklep z zabawkami. Może opiekunka sierocińca czasem nas tu zabrać. My zapytać. Może ty też jej powiedzieć?', 0),
(13950, 'plPL', 'Ale fajnie! My kiedyś pójść tam znowu? My nie móc się doczekać, aż znowu zobaczyć nowego przyjaciela!', 0),
(13951, 'plPL', 'Kekek lubić nowych przyjaciół ze Śniegospadu, może kiedyś wrócić i razem pójść na polowanie. Może my pójść przewracać morsoludzi, jak oni spać.', 0),
(13954, 'plPL', 'Ty myśleć, że ona widzieć już kiedyś wyrocznię? Może my pierwsi, co ją poznać! My myśleć, że ona nas polubić, ale my nie być pewni. Ona nie mówić dużo. Nie. Ale być fajnie!', 0),
(13955, 'plPL', 'Królowa nie taka, jak Kekek się spodziewać, ale Kekek rozumieć czemu. Goście królowej zostać zgnieceni, jakby ona zawsze być wielkim smokiem! Ale Kekek dalej chcieć kiedyś zobaczyć.', 0),
(13956, 'plPL', 'My poznać Wielkiego! Szkoda, że akurat mieć drzemkę, ale my rozumieć. My też lubić drzemki! Może my nauczyć się drzemek od Wielkich, tak jak nauczyć się o kapliczkach i błyskotkach!$b$bMy móc wrócić i odwiedzić Wielkiego jeszcze raz, jak nie spać?', 0),
(13957, 'plPL', 'Ty pomóc Kekekowi nauczyć się książki? Wtedy Kekek polować z Hemetem Nesingwarym!', 0),
(14103, 'plPL', 'Cudownie! Kolejna porcja proszku!$B$BTak między nami jubilerami: zbijam fortunę, sprzedając miejscowym magom z Dalaranu biżuterię z „czystego tytanu”. Mimo całego swojego intelektu nie bardzo umieją obchodzić się ze złotem. Jeśli zdobędziesz więcej, będę tutaj.', 0),
(24871, 'plPL', 'Olbrzym nie żyje? Chwała Światłości!$B$BDroga naprzód i w górę stoi otworem. Weź trochę tych łupów wojennych w dowód naszej wdzięczności, a gdy Mroźny Tron zostanie starty w pył, wypijemy razem za zwycięstwo!', 0),
(24876, 'plPL', 'Olbrzym nie żyje? Chwała Światłości!$B$BDroga naprzód i w górę stoi otworem. Weź trochę tych łupów wojennych w dowód naszej wdzięczności, a gdy Mroźny Tron zostanie starty w pył, wypijemy razem za zwycięstwo!', 0),
(24916, 'plPL', 'Co... jakim cudem to do ciebie trafiło!?$B$B$GWyświadczyłeś:Wyświadczyłaś; mi wielką przysługę, $gbohaterze:bohaterko;. Serce nie pozwoliłoby mi zatrzymać tego medalionu, ale nałożę na niego zaklęcie, które może ci się przydać. Zrób z nim, co zechcesz, lecz nie zapominaj o tych, którzy pomogli ci w tym wiekopomnym dokonaniu.', 0),
(24917, 'plPL', 'Ano. Znam to ostrze... i zawsze będzie mi drogie – jako chwila, która na zawsze przepadnie w czasie.$B$B$GWyświadczyłeś:Wyświadczyłaś; mi wielką przysługę, $gbohaterze:bohaterko;. Ofiarowuję ci dar od mroźnorodnych krasnoludów. Zrób z nim, co zechcesz, lecz nie zapominaj o tych, którzy pomogli ci w tym wiekopomnym dokonaniu.', 0),
(24918, 'plPL', '<Sylwana przez chwilę rozmyśla w milczeniu, po czym znów kieruje na ciebie wzrok.>$B$B$GWyświadczyłeś:Wyświadczyłaś; mi wielką przysługę, $gbohaterze:bohaterko;. Ofiarowuję ci łaskę Królowej Banshee. Zrób z nim, co zechcesz, lecz nie zapominaj o tych, którzy pomogli ci w tym wiekopomnym dokonaniu.', 0),
(24919, 'plPL', '<Uther wpatruje się w odznakę, przez chwilę nie mogąc wydobyć słowa.>$B$BOdznaka Arthasa.$B$BDobrze pamiętam dzień, w którym mu ją wręczyłem...$B$B$GWyświadczyłeś:Wyświadczyłaś; mi wielką przysługę, $gbohaterze:bohaterko;. Moja dusza może teraz spocząć w pokoju. Ofiarowuję ci wspomnienie zagubione w czasie. Zrób z nim, co zechcesz, lecz nie zapominaj o tych, którzy pomogli ci w tym wiekopomnym dokonaniu.', 0),
(25055, 'plPL', 'Dobra robota, $N. Ale w miejsce każdego ujarzmionego żywiołu pojawia się następny. Nasze rozwiązanie jest tylko doraźne. Oby moi bracia z Kręgu Ziemi robili większe postępy.', 0),
(25092, 'plPL', 'Dobra robota, $N. Ale w miejsce każdego ujarzmionego żywiołu pojawia się następny. Nasze rozwiązanie jest tylko doraźne. Oby moi bracia z Kręgu Ziemi robili większe postępy.', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(558, 'plPL', 'Kiedyś chcę być bohaterem, takim jak Jaina... no, znaczy, bohaterem chłopakiem.', 0),
(910, 'plPL', 'Już jesteśmy?', 0),
(911, 'plPL', 'Już jesteśmy?', 0),
(915, 'plPL', 'Szkoda, że nie robią lodów o innych smakach niż truskawkowy, ale chyba mam szczęście, że truskawkowy to mój ulubiony!', 0),
(925, 'plPL', 'Kiedy orkowie byli sami i bez przyjaciół, taureni przyjęli ich w obcej krainie i dzielili się z nimi, nie prosząc o nic w zamian. To jest honor, $N.', 0),
(1470, 'plPL', 'Twoja moc jest teraz niewielka, choć podejrzewam, że już wyczuwasz możliwości.$b$bNawet martwi mogą poczuć, że żyją, gdy przepływa przez nas ta moc.', 0),
(1479, 'plPL', 'Już jesteśmy?', 0),
(1485, 'plPL', 'Ważne, żebyś $gpotrafił:potrafiła; panować nad istotami, które przywołujesz swoją magią. Zbyt mało jest chętnych do poznania naszych ścieżek, żebym miał ryzykować twoje życie, ucząc cię czegoś, zanim będziesz $ggotów:gotowa;.', 0),
(1558, 'plPL', 'Już jesteśmy?', 0),
(1598, 'plPL', 'Zbyt rzucałoby się w oczy, gdybym sama ukradła tę księgę. Co za szczęście, że jeden z ich własnych naiwniaków odwalił za mnie brudną robotę.', 0),
(1599, 'plPL', 'Te talizmany z piór, które noszą nowicjusze, mają jakąś magiczną moc. Ciekawie będzie je zbadać. Nie spodziewałbym się tego po trollach.', 0),
(1687, 'plPL', 'Już jesteśmy?', 0),
(1800, 'plPL', 'Już jesteśmy?', 0),
(2882, 'plPL', 'Ta skrzynia jest zamknięta!', 0),
(3638, 'plPL', 'Jeśli dokument jest podpisany i chcesz mi go wręczyć, to klamka zapadła. Wiesz już, że to podróż w jedną stronę. Jeśli jesteś $ggotów:gotowa;, wskakuj na pokład!', 0),
(3640, 'plPL', 'Jeśli dokument jest podpisany i chcesz mi go wręczyć, to klamka zapadła.$B$BSekrety, którymi się z tobą podzielę, mają taką wagę, że podpisanie Przyrzeczenia tajemnicy jest absolutnie konieczne. Ja je podpisałem, podobnie jak moi bracia i siostry, gnomi inżynierowie. Dołączysz do nie byle jakiego grona, $ginżynierze:inżynierko; $N!', 0),
(3642, 'plPL', 'Jeśli dokument jest podpisany i chcesz mi go wręczyć, to klamka zapadła.$B$BChoć w sprawach polityki mogę się zaciekle nie zgadzać z Gnomoregan – a zwłaszcza z tym głupcem, majstrem Nadiskrą – Przyrzeczenie tajemnicy stoi ponad wszystkim! Musisz zgodzić się obrać jedną ścieżkę i pozostać jej $gwierny:wierna; przez całe życie.', 0),
(4822, 'plPL', 'Szkoda, że nie robią lodów o innych smakach niż truskawkowy, ale chyba mam szczęście, że truskawkowy to mój ulubiony!', 0),
(6661, 'plPL', 'Jarrr... Majtku, co ci tyle schodzi?', 0),
(6662, 'plPL', '<Nipsy wsuwa palec wskazujący w jeden z otworów wentylacyjnych kartonu.>$b$bŻywe i wierzgające... i w samą porę!', 0),
(8344, 'plPL', 'Esencje upiorów dobrze mi posłużą jako materiał do eksperymentów. Tak jak w twoim życiu jako $c, ważne jest, by uczyć się z tego, co znajdujemy w świecie... zanim nagniemy to do swojej woli. Skoro demony są najbogatszym źródłem mocy, taka skaza na wyspie – jeśli naprawdę tu jest – będzie nie lada dobrodziejstwem.$B$BNo... dobrodziejstwem dla nas, czarnoksiężników, rzecz jasna.', 0),
(8411, 'plPL', 'Gdzie żywioły, mon?', 0),
(8900, 'plPL', 'Och, a czemu zawdzięczam tę przyjemność?', 0),
(8901, 'plPL', 'Och, a czemu zawdzięczam tę przyjemność?', 0),
(8902, 'plPL', 'Och, a czemu zawdzięczam tę przyjemność?', 0),
(8903, 'plPL', 'Czy słusznie się martwiłem? Czy strażników dopadła ta miłosna choroba?', 0),
(8904, 'plPL', 'Czy słusznie się martwiłem? Czy nasi durni strażnicy ulegli?', 0),
(8979, 'plPL', 'Czym mogę służyć?', 0),
(8993, 'plPL', 'Czy przychodzisz wręczyć dar miłości i uwielbienia swojemu ulubionemu przywódcy?', 0),
(10962, 'plPL', 'Myślisz, że to prawda, co mówią o Jaskiniach Czasu?', 0),
(10963, 'plPL', 'Jeśli to prawda, co mówią o Jaskiniach Czasu, to musi to być miejsce o wielkiej mocy.', 0),
(10991, 'plPL', '<Z krogulca znów dobywa się głos Arthorn.>$B$BMasz esencję sokoła?', 0),
(11886, 'plPL', 'Co udało ci się odkryć?', 0),
(11891, 'plPL', 'Udało ci się poznać ich sekrety?', 0),
(12193, 'plPL', 'Co słychać, $gprzystojniaku:ślicznotko;? Masz coś dla mnie?', 0),
(12194, 'plPL', 'Co słychać, $gprzystojniaku:ślicznotko;? Masz coś dla mnie?', 0),
(12515, 'plPL', 'W tamtych czasach byłem niepokonany... dumny, i to słusznie. Żaden śmiałek nigdy nie zdobył tego wspaniałego kapelusza...', 0),
(12517, 'plPL', 'Widzę, że udało ci się wykonać talię łotrów! Jestem pod wrażeniem.', 0),
(12518, 'plPL', 'Widzę, że udało ci się skompletować talię magów! Gratulacje!', 0),
(12786, 'plPL', 'Witaj w Gromowych Urwiskach, $n. Wielki aptekarz Putress uprzedził mnie o twoim przybyciu... masz ten zarażony mózg?', 0),
(12788, 'plPL', 'Witaj w Srebrnej Lunie, $n. Wielki aptekarz Putress uprzedził mnie o twoim przybyciu... masz ten zarażony mózg?', 0),
(12798, 'plPL', 'Widzę, że udało ci się skompletować talię mieczy. Znakomicie.', 0),
(13250, 'plPL', 'Masz mojo?$b$bAż mdli na widok upadku kolejnego wielkiego narodu trolli.$b$bNie mogę się oprzeć myśli, że gdyby nie ingerencja Króla Lisza, trolle nie czułyby się zmuszone zwrócić się przeciw własnym bogom i wykraść ich moc, by bronić się przed Plagą.', 0),
(13254, 'plPL', 'Cieszę się, że to ty schodzisz do Azjol-Nerub, a nie ja.$b$bNie lubię przebywać pod powierzchnią świata.', 0),
(13311, 'plPL', 'Widzę, że udało ci się skompletować talię demonów! Gratulacje!', 0),
(13627, 'plPL', 'Masz ten „towar”, o którym rozmawialiśmy?', 0),
(13681, 'plPL', 'Masz ten kamień?', 0),
(13926, 'plPL', 'Ty się nami opiekować?', 0),
(13927, 'plPL', 'Pani od sierot mówić, że Kekek iść z tobą.', 0),
(13929, 'plPL', 'My móc zobaczyć wielkie drzewo? Móc?', 0),
(13930, 'plPL', 'Kekek chcieć odwiedzić drzewo niedźwiedzioludzi. My iść.', 0),
(13933, 'plPL', 'My odwiedzić kapliczkę smoczych stworów?', 0),
(13934, 'plPL', 'Kekek chcieć odwiedzić smoczą świątynię.', 0),
(13937, 'plPL', 'My iść do „Cudowni”?', 0),
(13950, 'plPL', 'Ty zabrać nas do Ustronia Zimopłetwych? Może poznać nowych przyjaciół?', 0),
(13951, 'plPL', 'Ty zabrać teraz Kekeka na Polanę Śniegospadu?', 0),
(13955, 'plPL', 'My iść teraz zobaczyć królową smoków?', 0),
(13956, 'plPL', 'Ty wiedzieć, jak znaleźć Wielkiego? My nigdy żadnego nie widzieć.', 0),
(24916, 'plPL', 'Tak, $N? W czym mogę ci pomóc?', 0),
(24919, 'plPL', 'Czym mogę służyć?', 0),
(25055, 'plPL', 'Czy żywioły są już ujarzmione?', 0),
(25092, 'plPL', 'Czy żywioły są już ujarzmione?', 0);
