(54806, 'plPL', 'Mroźna kosa lorda Ahuna', 'Od kosy bije przenikliwy chłód.', 0);
INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1191, 'plPL', 'ULTRAWAŻNE DANE! POZIOM ZABEZPIECZEŃ 5122!\n\n01001001 01100110 00100000 01111001 01101111 01110101 00100000 01100011 01100001 01101110 00100000 01110010 01100101 01100001 01100100 00100000 01110100 01101000 01101001 01110011 00101100 00100000 01111001 01101111 01110101 00100111 01110010 01100101 00100000 01110011 01110100 01100001 01101110 01100100 01101001 01101110 01100111 00100000 01110100 01101111 01101111 00100000 01100011 01101100 01101111 01110011 01100101', 0),
(1192, 'plPL', 'NIE dopuść, by te informacje wpadły w ręce wroga! 01010100 01101000 01100101 00100000 01100111 01101110 01101111 01101101 01100101 00100000 01101011 01101001 01101110 01100111 00100000 01110111 01100101 01100001 01110010 01110011 00100000 01101110 01101001 01100111 01101000 01110100 00100000 01100101 01101100 01100110 00100000 01110101 01101110 01100100 01100101 01110010 01110111 01100101 01100001 01110010 ', 0),
(1193, 'plPL', 'Poziom zabezpieczeń 10^10000, superwrażliwe dane! 01001000 01100101 01101100 01110000 00100001 00100000 00100000 01001001 00100111 01101101 00100000 01110100 01110010 01100001 01110000 01110000 01100101 01100100 00100000 01101001 01101110 00100000 01100001 00100000 01100010 01101001 01101110 01100001 01110010 01111001 00100000 01110000 01110101 01101110 01100011 01101000 00100000 01100011 01100001 01110010 01100100 00100000 01100110 01100001 01100011 01110100 01101111 01110010 01111001 00100001 ', 0),
(1431, 'plPL', 'Vorfalk Żelazna Tykwa$B$BVorfalk pracuje w magazynie karczmy „Pod Ponurym Opojem”, a jego poświęcenie dla Mrocznych Opiekunów jest ogromne.$B$BOby jego duch pozostał silny.', 0),
(1432, 'plPL', 'Bethek Burzobrewy$B$BWędrówki wiodą Betheka w głąb Czarnej Skały. Wabią go tajemnice góry.$B$BOby jego duch nigdy się nie zachwiał.', 0),
(1433, 'plPL', 'Uggel Młotoręki\n\nUggel jest zręcznym i poważnym kamieniarzem, a gdy nie dźwiga brzemienia mrocznego klucza, jego dłonie tworzą wielkie dzieła w Sali Rzemiosła.', 0),
(1434, 'plPL', 'Zimrel Mrocznozęby$B$BGdy Zimrela ogarnia obłęd mrocznego klucza, ukoić go mogą jedynie krzyki konających.$B$BZa swoje poświęcenie zawsze będzie miał ławę nad areną. Oby nasze krwawe igrzyska ostudziły gniew w jego sercu.', 0),
(1435, 'plPL', 'Ofgut Kamieniopięść Niezliczeni są ci, którzy padli pod młotem Mrocznego Opiekuna Ofguta. Żołnierze Zachodniego Garnizonu kłaniają się z trwogą, gdy przechodzi. Bo któż z nich potrafi spojrzeć Ofgutowi w oczy i dostrzec tajemnice, które szepcze mroczny klucz? ', 0),
(2251, 'plPL', 'Napastnicy... ze wszystkich stron.$B$BWidać to w ich oczach. Pyskodrzewni są źli. Wróg.$B$BTrzeba chronić plemię. Trzeba chronić Zimospad. Trzeba przegnać intruzów z naszej ziemi.', 0),
(2413, 'plPL', 'Śnieg, oślepia...$B$BTrzeba chronić plemię. Uczynić ich silnymi. Być silnym.$B$BNie wiem... ', 0),
(2414, 'plPL', 'Ognista woda.$B$BRobić więcej. Więcej ognistej wody.$B$BOgnista woda czyni Zimospad silnym. Pokona naszych wrogów.$B$BZimospad nie ma sojuszników. Zimospad jest silny. Ma wielką moc. ', 0),
(2415, 'plPL', 'Więcej. Trzeba mieć więcej...$B$BZimospad... nie... słaby...', 0),
(2810, 'plPL', 'Do natychmiastowego rozpowszechnienia wśród wszystkich członków Młota Zmierzchu.$B$BPoszukiwania zdrajcy Ortella postępują w nader zadowalającym tempie. Nasi zwiadowcy zawęzili obszar poszukiwań do sieci jaskiń w Zachodnim Skraju.$B$BZdrada Ortella nie zostanie wybaczona, a jego ucieczka stanowi poważne zagrożenie dla bezpieczeństwa naszej organizacji.$B$BKażdy, komu udowodni się zatajanie informacji o miejscu pobytu Ortella, zostanie należycie ukarany.$B$B– Władca Zmierzchu Everun', 0),
(2811, 'plPL', 'Do natychmiastowego rozpowszechnienia wśród wszystkich członków Młota Zmierzchu.$B$BZważywszy na obecną sytuację w Silithusie, wszelka dystrybucja egzemplarzy „Prawdziwego Wyznawcy” ma się odbywać pod eskortą co najmniej czterech uzbrojonych członków Młota Zmierzchu.$B$BKażdy, kto naruszy to nowe zarządzenie, zostanie ukarany w trybie doraźnym.$B$B– Władca Zmierzchu D\'Sak', 0),
(2812, 'plPL', 'Do natychmiastowego rozpowszechnienia wśród wszystkich członków Młota Zmierzchu.$B$BPoniższe informacje opisują użycie Kamieni Wiatru do komunikacji z naszymi panami z Abisalnej Rady.$B$BWszelkie niepoważne użycie Kamieni Wiatru będzie karane w nader bolesny sposób.$B$B– Strażnik Zmierzchu Havunth', 0),
(2813, 'plPL', 'Abisalni templariusze$B$BJako nowicjusz masz prawo nawiązywać kontakt z abisalnymi templariuszami na potrzeby rutynowych rytuałów. Pamiętaj, by przy korzystaniu z Kamieni Wiatru zawsze mieć na sobie właściwy strój, aby nie uruchomić naszych zaklęć obronnych.$B$BGdyby doszło do nieprzewidzianej sytuacji kryzysowej pod nieobecność nadzorców, wolno ci przywołać abisalnego templariusza.$B$BSzczegóły rytuałów przywołania znajdziesz w „Prawdziwym Wyznawcy” z zeszłego miesiąca.', 0),
(2814, 'plPL', 'Abisalni Książęta$B$BJedynie akolici posiadający medalion rangi mają prawo nawiązywać kontakt z Abisalnymi Książętami. Medalionów rangi mogą używać wyłącznie osoby, którym je pierwotnie wydano.$B$BCzłonkowie Młota Zmierzchu, którzy bez zgody porozumiewają się z Abisalnymi Książętami lub bez upoważnienia używają medalionów rangi, zostaną ukarani przeze mnie osobiście.', 0),
(2815, 'plPL', 'Wysoka Rada Abisalnych Lordów$B$BJedynie Władcy Zmierzchu mają prawo kontaktować się z księciem Skaldrenoxem, najwyższym marszałkiem Whirlaxisem, baronem Kazumem lub lordem Skwolem.$B$BNiżsi rangą członkowie Młota Zmierzchu pod żadnym pozorem nie mogą nawiązywać łączności z Wysoką Radą. Każdy obcy przyłapany na takim użyciu Kamienia Wiatru zostanie na miejscu obrócony w popiół.', 0),
(2816, 'plPL', 'Stan kultu, tom 92$B$BZ radosnym sercem witam was, bracia, bo stan naszego kultu nie mógłby być wspanialszy. Jest nas legion, a nasze cele są coraz bliższe urzeczywistnienia.$B$BWciąż przybywają nowi rekruci. Wyśpiewują chwałę naszych władców na Mrocznym Wybrzeżu, biją pokłony w radosnym uniesieniu w Płonącym Wąwozie, garną się do sługi naszych panów, Aku\'mai, w Czarnych Głębinach. Zaprawdę, bracia i siostry, wkrótce rój wiernych okryje całe Azeroth!', 0),
(2817, 'plPL', 'Stan kultu, tom 127$B$BTo prawdziwie szczęśliwy dzień! Poddano nas próbie w Silithusie i wyszliśmy z niej zwycięsko!$B$BDoniesienia o zniszczeniu naszego najdalej wysuniętego na północ obozu mogą zachwiać sercami niewiernych, lecz w tej rzezi nie należy widzieć tragedii. Nie!', 0),
(2818, 'plPL', 'Przelanie naszej krwi przez członka Abisalnej Wysokiej Rady to błogosławieństwo! Powinniśmy zazdrościć poległym towarzyszom, bo ich duchy przebywają teraz w brzuchu najprawowitszej z bestii!$B$BChwała Przedwiecznym! Chwała ich sługom! Chwała Młotowi Zmierzchu!', 0),
(2819, 'plPL', 'Stan kultu, tom 233$B$BOkazja znów puka do naszych drzwi, bracia i siostry! Krąg Cenariona, nikczemny kult miłośników natury, wysyła teraz przeciw nam swoich agentów. Zapewne chcą nam przeszkodzić w przywoływaniu czerwonych kamieni wabiących. Nie możemy na to pozwolić!$B$BCzerwone kamienie są niezbędne naszym nowym sojusznikom. Nie wolno nam dopuścić, by pieski Kręgu Cenariona dopięły swego. Trwajcie niezłomnie, moi wierni przyjaciele. Trwajcie niezłomnie!', 0),
(2820, 'plPL', 'Skąd wiemy, że nas kochają?$B$BNiektórzy mogą się zastanawiać, jak Przedwieczni i ich słudzy mogą nas kochać. Czyż nas nie zabijają? Czyż nie zadają wszystkim bólu i cierpienia? Jak istoty tak oddane złu mogłyby znać miłość w swoich sercach?$B$BOdpowiedź na to pytanie jest prosta. Tak prosta, że nie trzeba jej wypowiadać?', 0),
(2821, 'plPL', 'Wiara. Wiara jest źródłem, z którego spływa na nas radość służby. Wiara ogrzeje nas w najzimniejsze noce Silithusu. Wiara zachowa nas w łaskach naszych Władców, gdy nadejdą Dni Ostateczne.$B$BWiara nas ocali.', 0),
(2872, 'plPL', 'Do wszystkich mężczyzn i kobiet zdolnych do walki:\n\nPlaga powróciła i musimy odłożyć na bok nasze spory, by stawić czoła temu zagrożeniu. Argentowy Brzask nie odprawi nikogo, kto zechce chwycić za broń przeciw Pladze.\n\nCi, którzy chcą bronić naszych ziem, zbierają się w Kaplicy Świetlistej Nadziei na Wschodnich Plagowiskach. Razem zwyciężymy.\n\nStrażnik rejestrów\nArgentowy Brzask', 0),
(2885, 'plPL', 'Witaj, $N. Jak się okazuje, udało mi się wydobyć z tamtego listu trochę informacji.$B$BO Jamesie, niestety, niewiele. Udało mi się jednak dotrzeć do kilku informacji o rodzinie Amelii.$B$BChoć ani ona, ani jej dzieci nie przeżyły wojny, przeżył jej brat, niejaki Alexander Calder; znajdziesz go w Opuszczonej Pieczarze w Żelaznej Kuźni, gdzie zgłębia niebezpieczną magię Płonącego Legionu.$B$BMiała też kuzynkę, z którą była blisko – kobietę znaną dziś jako Deze Zguba Śniegu, która w Orgrimmarze zachęca do walki o Kotlinę Aratorską.$B$BOdwiedź któreś z nich, gdy następnym razem będziesz w okolicy. Na pewno zechcą usłyszeć o swojej utraconej Amelii, choćby tylko tyle.', 0),
(2886, 'plPL', 'Pozdrawiam, $N. Sądzę, że zainteresują cię wyniki moich poszukiwań.$B$BJak się okazuje, zarówno Reuben, jak i Leagrem zostawili po sobie – by tak rzec – żyjącą rodzinę. Nawet jeśli bliscy wiedzą już o losie zaginionego żołnierza, wizyta u któregoś z nich może się okazać warta zachodu.$B$BByłą żonę Reubena, Joannę Whitehall, znajdziesz w Dzielnicy Wojennej Podmiasta, gdzie spędza większość czasu. Nie wiem jednak, jak przyjmie te wieści.$B$BCo do Leagrema, jego ciotka została opiekunką sierocińca w Wichrogrodzie – to godne podziwu stanowisko.$B$BJakąkolwiek drogą kroczysz przez życie, życzę ci powodzenia we wszystkich przedsięwzięciach.', 0),
(2887, 'plPL', '$N, mam nadzieję, że ten list zastanie cię w dobrym zdrowiu. Po pewnych poszukiwaniach udało mi się dowiedzieć czegoś o autorach listu, który do ciebie trafił.$B$BOjciec Samli przewodzi Porzuconym i trollom, którzy pielgrzymują do Gromowych Urwisk zgodnie z nakazami jego wiary. Nazywa się Miles Welsh; znajdziesz go wraz z innymi nieumarłymi przy Źródłach Objawień.$B$BTorgal z kolei zostawił po sobie kuzynkę, Elissę Dumas. Z tego, co wiem, to samotniczka; spędza dni w Świątyni Księżyca w Darnassus.$B$BGorąco cię namawiam, $N: odwiedź, kogo tylko zdołasz. Być może nigdy się nie dowiedzieli, jaki los spotkał Torgala i Samlę.', 0),
(2888, 'plPL', 'Strażnik przekazał mi list, na który $gnatrafiłeś:natrafiłaś;, $N, i sądzę, że przyda ci się wieść o postępach.$B$BOstatniego żyjącego krewnego wspomnianego w nim „Vargusa” wytropiono na pustyni Silithus – mieszka w Twierdzy Druidów. Nazywa się Garon Hutchins.$B$BPorozmawiaj z nim podczas następnej wyprawy na pustkowia. Może zechce usłyszeć, czego się dowiedzieliśmy.', 0),
(2889, 'plPL', 'Pozdrawiam. Wreszcie znalazł się czas, by przyjrzeć się pismu, które $gznalazłeś:znalazłaś; przy słudze Plagi. Choć wymagało to nieco zachodu, wygląda na to, że udało mi się odnaleźć żyjącą krewną zmarłego.$B$BSiostra Maxwella, niejaka Zarena Cromwind, prowadzi niewielki sklep z bronią w Łupieżczej Zatoce. Nie wiem, jak bliska była bratu, ale jeśli będziesz tamtędy przejeżdżać, warto się z nią spotkać. Możliwość zamknięcia takich spraw to w dzisiejszych czasach rzecz cenna i rzadka.', 0),
(2890, 'plPL', 'Wreszcie udało mi się wydobyć na światło dzienne trochę informacji o byłym żołnierzu, z którym $gwalczyłeś:walczyłaś;. Trop był trudny, bo akurat to drzewo genealogiczne nie zostało należycie udokumentowane, ale w końcu udało mi się odnaleźć krewnego.$B$BCzy uwierzysz, że dozorca Alen z Kaplicy Świetlistej Nadziei jest w istocie synem Christopha? Wieść o ojcu mogłaby przynieść mu ulgę. Jeśli kiedyś znów znajdziesz się na Plagowiskach w służbie Argentowego Brzasku, porozmawiaj z nim, proszę. Byłby to dobry uczynek.', 0),
(2913, 'plPL', 'Choć klęska nad nim wisiała,$BOdwaga go nie opuściła,$BDłoń miecza z pochwy dobyła$BI w spaczoną ciżbę uderzyła$B$BOd dnia owego boju$BNi miecz, ni strzała wroga$BW bitwie ani w znoju$BDo lorda krasnoludów nie znała drogi', 0),
(2914, 'plPL', '...ale to już wiedziała. Pogodziła się z tym, że będzie żyć jak parias, odkąd kawałek po kawałku przehandlowała własną duszę. Zemsta była tego warta – a przynajmniej tak sądziła.$B$BA jednak oto nadarzała się szansa, by odzyskać człowieczeństwo, a nieznajomy prosił w zamian jedynie o jej zaufanie.$B$B„Zrobię to” – powiedziała Katreyn. „Nie mam nic do stracenia”.', 0),
(2918, 'plPL', 'To moje dzieło. Nie pamiętam tego, ale inaczej być nie może.$B$BMam już na sumieniu grzechy. Mam nawet śmierć człowieka, który na nią nie zasłużył. Ale to coś innego.$B$BJestem kimś innym. $B$BTe morderstwa nie były moim wyborem. Mieszka we mnie bestia.$B$BBędą na mnie polować, będą mnie unikać. Muszę się ukryć. Uciekać. Zakopać ciała.$B$BRuszam do wyjścia i wtedy dociera do mnie, co naprawdę nie daje mi spokoju.$B$BNie czuję winy.', 0),
(2998, 'plPL', '$N,\n\nSzyfr Potępienia to zaiste potężna inkantacja. Pradawny i chaotyczny, sam szyfr odpowiada za wiele tragedii w dziejach naszych światów. Innymi słowy, nie jest czymś właściwym tylko Draenorowi.$B$BPłonący symbol, który $gwidziałeś:widziałaś;, był znakiem Kael\'thasa. To, że zna on pradawne słowa, wiele wyjaśnia.$B$BTwoje odkrycie poruszyło naaru. A\'dal prosi, byś $gstawił:stawiła; się w Shattrath. Jeśli zdecydujesz się przybyć, odszukaj mnie na Tarasie Światła.\n\nZ wyrazami szacunku\n\nKhadgar\n', 0),
(3001, 'plPL', '<Na tej mocno spalonej stronie nie zachowały się żadne czytelne słowa.>', 0),
(3076, 'plPL', '<Na tej mocno spalonej stronie nie zachowały się żadne czytelne słowa.>', 0),
(3110, 'plPL', 'Do najwyższej generał Abbendis$BNowy Avalon, Szkarłatne Ziemie$B$BNajwyższa generał Abbendis,$B$Bmam nadzieję, że ten list zastanie Panią w dobrym zdrowiu. Nazywam się Dansel Adams, z zawodu jestem łowcą, a z krwi szkarłatnym krzyżowcem. Piszę ten list, by donieść, że byłem świadkiem cudu.$B$B', 0),
(3111, 'plPL', 'Podczas rutynowej czystki wśród pogan w opanowanym przez Plagę Plagowym Lesie mnie i mojemu oddziałowi przerwał ogłuszający skrzek dobiegający z nieba. Gdy spojrzeliśmy w niebiosa, ku Naxxramas, szczęki opadły nam do ziemi. Powiadam Pani, najwyższa generał, był to widok nie do wiary! Straszliwa cytadela się poruszała. Z początku powoli, a potem z gromowym rykiem – puf – i już jej nie było!$B$BTak jest, najwyższa generał, Naxxramas zniknęło! Nie ma go! Czy to może być co innego niż cud Światłości? Powiadam, że nie!', 0),
(3112, 'plPL', 'Oby nieczyści, niechlujni barbarzyńcy zostali osądzeni i skazani jako następni. Chwała Światłości!$B$BProszę powiadomić o tym cudzie naszych braci i siostry, najwyższa generał.$B$BNiech Światłość zachowa Panią po wsze czasy, by mogła Pani głosić dobrą nowinę aż po kres dni.$B$BZ wyrazami szacunku$B$BD. Adams$B„Domykacz”', 0),
(3581, 'plPL', '„Odgrywanie ról”\n\nUmiejętność odgrywania ról to podstawa. Żadna genialna gnomka nie gustuje w gigantycznym ględzie. Uracz ją opowieściami o waszych przyszłych przygodach na wszystkich kontynentach:\n\n  „Ty i ja, mała, polecimy do Kalimdoru, wyryjemy nasze imiona na pniu Teldrassilu i spędzimy resztę życia, bujając się na drzewach w Kraterze Un\'Goro”.\n\n„Snucie opowieści”\n\nOpowiadaj o waszej ekscytującej wspólnej przyszłości! Im mniej prawdopodobnie, tym lepiej. Nic tak nie rozpala gnomiej dziewczyny jak ambitny plan. To też świetny sposób na zagajenie rozmowy!\n\n  „Gdybyśmy połączyli nasze błyskotliwe umysły, moglibyśmy odbić Gnomoregan. ...a właściwie czemu jeszcze nie odbiliśmy Gnomoregan?”', 0),
(3582, 'plPL', '„Przekomarzanie się”\n\nPrzekomarzanie się to sztuka żartowania z kobiety w zabawny sposób. Uważaj, łatwo przesadzić. Jeśli nazwiesz ją „gamoniowatą gnidą gnębiącą gobliny”, wrócisz do domu, mając na sobie ten Zielony grog Gordoków, który właśnie kupiłeś. Spróbuj czegoś subtelniejszego. \n\nJeśli zachowuje się dziecinnie i nie chce przestać wskakiwać na stoły na środku baru, spróbuj:\n\n„Słyszałem, że w wichrogrodzkim sierocińcu szukają gwiazdy do zabawiania dzieci”.\n\nJeśli nie przestaje mówić o sobie, spróbuj żartobliwie:\n\n„Gdzie masz wyłącznik?”\n\nWAŻNA UWAGA: gnomie dziewczyny NIE mają wyłącznika. Próba jego znalezienia może się skończyć utratą życia, kończyn lub portfela.', 0),
(3583, 'plPL', 'Masz bardziej egzotyczny gust? \nPragniesz kogoś trochę nie z tego świata? \nKopyta to twoja bajka, ale sukuby to już dla ciebie przesada?\n\nCzytaj dalej, przyjacielu...', 0),
(3584, 'plPL', 'Ledwie zszedłem ze statku na Lazurową Mgłę, zaczepiłem grupkę draenejskich dam w kwiecie wieku, tak koło 230 lat. Śmiały się i świetnie bawiły. Co za szczęście – jeszcze nie opuściłem przystani, a już znalazłem dokładnie takie wesołe, pełne energii draenejki, jakie chciałem poznać podczas tej podróży. \n\nZ początku trochę spięty, odetchnąłem głęboko i przypomniałem sobie: „one też są tu, w Azeroth, na wakacjach, chcą poznawać nowych ludzi i świetnie się bawić”.\n\nI rzeczywiście, były zachwycone, widząc w Exodarze tak diabelnie czarującego gnoma jak ja. Okazało się nawet, że zatrzymaliśmy się w pobliżu Skarbca Świateł. Wymieniliśmy głębokie, przenikliwe spojrzenia prosto w oczy i obiecaliśmy sobie, że spotkamy się znów tego wieczoru niedaleko A\'dala. ', 0),
(3585, 'plPL', 'Następnego dnia poznałem kolejną piękną draenejkę – połysk jej rogów dawał zaledwie delikatne pojęcie o jej wyrafinowanym guście. Zapytałem, czemu odwiedza Exodar, a ona, zaszokowana, odparła, że nie jest tu z wizytą – ona tu mieszka. \n\nPrzypomniały mi się słowa, które wcześniej powtarzałem sobie w myślach: \n\n„Ona jest na wakacjach, chce poznawać niesamowitych ludzi i świetnie się bawić”. \n\nWszystko mi się pomyliło, ona wcale nie była na wakacjach! I nagle zgrzytające trybiki w mojej głowie zaskoczyły: wmawiałem sobie, że one są takie otwarte, bo są na wakacjach. Co za gnolla wymówka! \n\nJestem fajnym, ciekawym facetem, z którym każda rozsądna dziewczyna chętnie stworzy drużynę, na wakacjach czy nie! Teraz, gdy poznaję draenejki, przypominam sobie prostą prawdę:\n\n„Ona też chce poznawać ludzi i świetnie się bawić”.', 0),
(3586, 'plPL', 'Kolejne 497 stron tego słownika składa się wyłącznie ze zdjęć zrobionych pod dziwnym kątem Superpstrykaczem FX 2000. ', 0),
(3587, 'plPL', 'Jak umówić się z krasnoludką:\n\n1. Poproś, żeby postawiła ci drinka.', 0),
(3588, 'plPL', 'Bądźmy szczerzy. Od końca Trzeciej Wojny nocne elfki słyszały już wszystko. Prawdę mówiąc, słyszały już wszystko na długo przed tym, nim ty czy ja przyszliśmy na świat. \n\nJeśli chcesz zaprzątnąć umysł nocnej elfki, musisz się wyróżnić. Jasne, wszyscy słyszeliśmy opowieści o nocnych elfkach tańczących na skrzynkach pocztowych i rozbierających się, żeby zapłacić za szkolenie nocnej szablobestii. Prawda to czy nie, jeśli chcesz rozjaśnić uśmiechem usta tej ślicznej damy, musisz być wyjątkowy, niezapomniany i pewny siebie. \n\nNa początek pokaż, że szukasz czegoś więcej niż dziewczyny, która dobrze wygląda. Jasne, umie podskakiwać, umie tańczyć, ale czy potrafi prowadzić przyzwoitą rozmowę? Czy w ogóle wie, jak się właściwie używa samoflanża? Czy umie się dobrze bawić?\n\nNie ma nic gorszego, niż przyprowadzić nocną elfkę na przyjęcie tylko po to, by patrzeć, jak stoi niezręcznie sama i przerywa rozmowę wyłącznie po to, by opłakiwać siostrę z Wysoko Urodzonych, którą straciła podczas Wojny Starożytnych.', 0),
(3589, 'plPL', 'Nie ma to jak zdobywanie serca ludzkiej dziewczyny. Nieskończenie wyrozumiałe, bezgranicznie troskliwe i fantastycznie zabawne ludzkie dziewczyny od wieków przywodziły do zguby niezliczonych bohaterów. (Zob. rozdział 3: „Jaina Proudmoore i mężczyźni, którzy ją kochali”)\n\nJednak kolejne pokolenia dowiodły, że aby przyciągnąć kobietę swoich marzeń, trzeba czegoś więcej niż pieniędzy, urody czy epickiej zbroi. Nie pomoże ci tu nawet potęga gnomiej wynalazczości. \n\nBy naprawdę oczarować czyjeś serce, musisz mieć następujące cechy.\n\n* Bądź zabawny i przyjazny\n* Bądź wyzwaniem\n* Bądź mężczyzną\n\n', 0),
(3590, 'plPL', 'Bądź zabawny i przyjazny\n\nMasz kumpla, który wpada do ciebie i wszystkim psuje humor? Jasne. Każdy takiego ma. Czy zaprasza się go znowu na imprezy? Tylko jeśli przynosi piwo. Jeśli chcesz być atrakcyjną osobą, prowadź atrakcyjny styl życia. \n\nPrzekonasz się, że im więcej radości sprawia ci towarzystwo innych, tym chętniej inni przebywają w twoim! \n\nNic tak szybko nie zepsuje dziewczynie wieczoru jak ta aura desperata, który za wszystko przeprasza. Odpuść, daj się ponieść zabawie, a twoja pewność siebie poszybuje w górę.', 0),
(3591, 'plPL', 'Bądź wyzwaniem\n\nZbyt wiele gnomów chodzi dziś ze spuszczoną głową, człapie smętnie od tawerny do tawerny i beznadziejnie trzyma się ograniczającego przekonania, że żadna ludzka dziewczyna nigdy ich nie zechce. Wpadają do tawerny, zasypują ją komplementami i darmowymi drinkami, po czym wracają do domu przybici. \n\nPozwól więc, przyjacielu, że powiem ci to jako pierwszy: kiedy oddajesz się tak tanio, pomniejszasz wartość swojej wyjątkowej, wyśmienitej osobowości. Społeczeństwo wmówiło ci, że to nie ty jesteś nagrodą, że kobiety nigdy cię nie dostrzegą, że musisz żebrać o miłość i uwagę.\n\nTo nieprawda. Nie rozdawaj swoich uczuć tak hojnie. Zamiast pytać siebie: „Czy ona mnie lubi?”, zapytaj: „Czy ja lubię ją?” \n\nRzuć jej wyzwanie – pokaż, że szukasz dziewczyny, która ma do zaoferowania coś więcej niż ładną buzię. Jeśli nie nadąża za twoim życiem, idź dalej. Jeśli pokaże, że ma coś do zaoferowania, stoisz u progu czegoś pięknego. ', 0),
(3592, 'plPL', 'Bądź mężczyzną\n\nW czasach, gdy wygnano nas z domów, zmuszono do walki o przetrwanie i kazano stawić czoła okropnościom, jakich Azeroth dotąd nie znało, można by sądzić, że natura męskości będzie lepiej rozumiana. \n\nNiestety, sztuka męskości zaginęła, zmyta przez blichtr i przepych bitwy. Ale nie wszystko stracone! Dzięki praktyce i pewności siebie możesz na nowo odnaleźć kontakt z samym sobą. \n\nGdy już poznasz ludzką dziewczynę swoich marzeń, a ona okaże się godna twoich uczuć:\n\n* Przejmij inicjatywę – pokaż jej wszystko, co piękne w twoim świecie\n* Trzymaj ją za rękę – zbuduj bliski, czuły związek\n* Okazuj szacunek – sobie, jej i otaczającemu was światu\n\nA przede wszystkim:\n\n* Bądź odpowiedzialny\n', 0),
(3593, 'plPL', 'Rozwiązywanie problemów\n\nNie wszystko zawsze idzie po twojej myśli, ale właśnie dlatego życie jest nieprzewidywalne i ekscytujące. Jest jednak kilka wskazówek, które bardzo pomogą ci poprawić swoje życie. Oto częste gafy:\n\n* Nie uganiaj się\n* Nie bądź namolny\n* Nie zadręczaj się kimś, kto cię nie lubi\n\nWszystkie biorą się z głębokiego przekonania, że musisz zdobyć właśnie tę kobietę, z którą teraz rozmawiasz. Uwolnij się – na tym pięknym świecie jest wiele kobiet, a jeśli z jedną nie wyjdzie, odpuść. Przekonasz się, że im mniej się narzucasz, tym bardziej stajesz się atrakcyjny. \n', 0);
INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
(7048, 0, 'plPL', 'Pokaż mi swoje towary', ''),
(7048, 1, 'plPL', 'Przekonajmy się.', '');
INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(3451, 0, 0, 'plPL', 'Wygląda na to, że musisz iść przodem do Zapadki i powiedzieć Sputtervalve\'owi, że rozbiłem rozdrabniacz.'),
(3451, 1, 0, 'plPL', 'Ja zostanę i przypilnuję wraku. Pospiesz się! Oby nikt nie zauważył dymu...'),
(6575, 0, 0, 'plPL', 'Mistrz poległ! Pomścijcie go, bracia!'),
(7172, 0, 0, 'plPL', 'Witajcie, śmiertelnicy! Dyski Norgannona uruchomiły mnie, abym wam pomógł!'),
(7172, 1, 0, 'plPL', 'Wasze dyski są gotowe! Uruchomcie ponownie Dyski Norgannona, aby je odebrać!'),
(8440, 0, 0, 'plPL', 'ZBLIŻAM SIĘ DO ŚWIATA!'),
(8440, 1, 0, 'plPL', 'CZUJĘ SMAK KRWI ŻYCIA.'),
(8443, 0, 0, 'plPL', 'GIŃCIE, ŚMIERTELNICY!'),
(8497, 0, 2, 'plPL', 'Nie! Nie wolno wam tego robić!'),
(8497, 0, 3, 'plPL', 'Stać! Niewierni!'),
(10076, 0, 0, 'plPL', 'Nie skrzywdzicie imperatora Thaurissana!'),
(10937, 1, 0, 'plPL', 'Na polu bitwy pojawił się kapitan Redpath! Chrońcie go!'),
(11502, 10, 0, 'plPL', 'MOJA CIERPLIWOŚĆ SIĘ KOŃCZY! CHODŹCIE, KOMARY, PO SWOJĄ ŚMIERĆ!'),
(11583, 14, 0, 'plPL', 'Dość! Teraz, robactwo, poczujecie moc mego dziedzictwa – furię samej ziemi.'),
(12018, 2, 1, 'plPL', 'Płońcie, śmiertelnicy! Płońcie za ten występek!'),
(12018, 11, 0, 'plPL', 'Mój płomień... Proszę, nie odbierajcie mi płomienia...'),
(12152, 20, 0, 'plPL', 'Anu\'dorini Talah, Ru shallora enudoril.'),
(14351, 0, 0, 'plPL', 'NIE!!! Ma włożyć garbnik do kosza, bo znowu dostanie młotkiem!'),
(14484, 0, 1, 'plPL', 'Pomóżcie nam, błagam! Książę oszalał!'),
(14484, 0, 2, 'plPL', 'Szukajcie schronienia w Żagiewiu! To nasza jedyna nadzieja!'),
(14485, 0, 1, 'plPL', 'Pomóżcie nam, błagam! Książę oszalał!'),
(14485, 0, 2, 'plPL', 'Szukajcie schronienia w Żagiewiu! To nasza jedyna nadzieja!'),
(15550, 1, 0, 'plPL', 'Cóż za łatwa zwierzyna.'),
(15550, 1, 1, 'plPL', 'Amatorzy! Nie łudźcie się, że mnie pokonacie! Ja zabijam zawodowo.'),
(16152, 1, 0, 'plPL', 'Cóż za łatwa zwierzyna.'),
(16152, 1, 1, 'plPL', 'Amatorzy! Nie łudźcie się, że mnie pokonacie! Ja zabijam zawodowo.'),
(17233, 4, 0, 'plPL', 'Dlaczego to robisz? Czyżbym za życia czymś cię skrzywdził?'),
(17233, 5, 0, 'plPL', 'Ach, teraz widzę to w twoim umyśle. To sprawka jednego z moich dawnych uczniów... Mehlara Ostrza Świtu. Smutno wiedzieć, że jego serce ogarnął taki mrok.'),
(17233, 6, 0, 'plPL', 'Wróć do niego. Wróć do Mehlara i powiedz mu, że mu wybaczam i że rozumiem, dlaczego wierzy w to, w co wierzy.'),
(17533, 2, 0, 'plPL', 'Czarny los tego dnia na wiele dni cień rzuci. Dziś ból się ledwie zaczął – inne dni go skończą.'),
(17534, 1, 0, 'plPL', 'Gdzie jest mój pan? Gdzie mój Romulo?'),
(17546, 2, 0, 'plPL', 'Chyba pójdę uciąć sobie drzemkę.'),
(17848, 2, 0, 'plPL', 'Już nie będziesz się wtrącać.'),
(17862, 1, 1, 'plPL', 'Nie wiem, co Blackmoore w tobie widzi. Jak dla mnie jesteś tylko kolejnym ciemnym dzikusem!'),
(17881, 4, 0, 'plPL', 'To tylko kwestia... czasu.'),
(21504, 20, 0, 'plPL', 'A co ty niby wyprawiasz? Śmiesz zakłócać eksperyment mojego pana?'),
(21504, 21, 0, 'plPL', 'Podoba ci się to, czego tu dokonaliśmy? Może zrzucimy takie kryształy z nieba na całą Rubież.'),
(21504, 22, 0, 'plPL', 'Nudzą mnie już twoje próby uleczenia tej ziemi i stłumienia energii, które przywołują kolosy i doprowadzają je do szału. Goliatonie, Królu kolosów, książę Kael\'thas i ja żądamy, abyś bronił kryształu!'),
(21780, 0, 0, 'plPL', '%s zaczyna przesyłać moc Dimensiusowi.'),
(22989, 1, 0, 'plPL', 'Nadszedł twój kres, demonie!'),
(22990, 3, 1, 'plPL', 'Musimy iść dalej, z Maiev czy bez niej. Do środka! Szybko!'),
(23197, 0, 1, 'plPL', 'Krwaw, tak jak ja krwawiłam!'),
(23197, 0, 3, 'plPL', 'Nadszedł twój kres, demonie!'),
(24215, 0, 0, 'plPL', 'Firjus był niegodny! Sprawdź swoje bitewne postępy w starciu z prawdziwym żołnierzem Króla Lisza!'),
(24536, 0, 0, 'plPL', 'Oj, przyszliśmy tu z Czarnej Góry,'),
(24536, 1, 0, 'plPL', 'Wasze piwo wypić chcemy!'),
(24536, 2, 0, 'plPL', 'Czarnoryci nigdy nie kłamią,'),
(24536, 3, 0, 'plPL', 'Więc wiecie, że nie bujemy!'),
(24536, 4, 0, 'plPL', 'Naszego gorzkiego nie chcecie skosztować,'),
(24536, 5, 0, 'plPL', 'Naszego ale nie chcecie lać!'),
(24536, 6, 0, 'plPL', 'Lecz Festiwal Piwa bez naszej ferajny?'),
(24536, 7, 0, 'plPL', 'Spróbujcie, a będziecie łkać!'),
(24536, 8, 0, 'plPL', 'Więc wznieście kufel za Corena'),
(24536, 9, 0, 'plPL', 'I za Hurleya Czarnodecha też!'),
(24536, 10, 0, 'plPL', 'Ten trunek słaby, kopa nie ma,'),
(24536, 11, 0, 'plPL', 'Lecz, oj! To jednak piwo – bierz!'),
(24536, 12, 0, 'plPL', 'Wypijemy wam stout i lagera,'),
(24536, 13, 0, 'plPL', 'Osuszymy kufle i beczki!'),
(24536, 14, 0, 'plPL', 'Będziemy pić i bić się, bić się i pić,'),
(24536, 15, 0, 'plPL', 'aż padniemy pod ławeczki!'),
(24536, 16, 0, 'plPL', 'A gdy piwa już nie stanie,'),
(24536, 17, 0, 'plPL', 'Pomkniemy do Cienistej Kuźni co tchu'),
(24536, 18, 0, 'plPL', 'Gorzki toast za Ragnarosa...'),
(24536, 19, 0, 'plPL', '... lecz ani kropli nie damy mu!'),
(25315, 0, 0, 'plPL', 'Nieeeeeeeeeeeee!'),
(26246, 1, 0, 'plPL', 'Ostateczna klęska Legionu jest coraz bliżej – bądźcie dumni ze świadomości, że ocaliliście przed płomieniem niezliczone światy.'),
(26246, 2, 0, 'plPL', 'Ten dzień wyznacza koniec, lecz zarazem zwiastuje nowy początek...'),
(26246, 6, 0, 'plPL', 'Z czasem światło i nadzieja, które w niej drzemią, odrodzą coś więcej niż to zwykłe źródło mocy... Być może odrodzą duszę narodu.'),
(26648, 4, 0, 'plPL', 'Ciekawi mnie, co się stanie, jeśli to zlekceważysz i NIE wskoczysz do wody.'),
(27462, 0, 0, 'plPL', 'Skunks, królik i jelonek podróżujący razem. No, tego nie widuje się co dzień. Nieważne, dziś na kolację będzie dziczyzna!'),
(29175, 83, 0, 'plPL', '%s szarżuje na Króla Lisza ze Spopielaczem w dłoni i zadaje mu cios.'),
(29183, 78, 0, 'plPL', '%s rzuca zaklęcie na Tiriona.'),
(29183, 80, 0, 'plPL', '%s rzuca potężne zaklęcie, które zabija obrońców i odrzuca pozostałych.'),
(29183, 84, 0, 'plPL', '%s znika. Tirion podchodzi do miejsca, w którym leżał Darion'),
(29227, 73, 0, 'plPL', '%s przybywa.'),
(29227, 76, 0, 'plPL', '%s znika, a pojawia się Król Lisz.'),
(29228, 74, 0, 'plPL', '%s staje się cieniem dawnego siebie i podchodzi do ojca.'),
(32310, 0, 0, 'plPL', 'Mam nadzieję, panowie, że nie macie nic przeciwko, jeśli wprosimy się na to przyjęcie. Przyprowadziłem kilku starych znajomych!'),
(32310, 1, 0, 'plPL', 'Wygląda na to, że cokolwiek zrobił Tirion, Król Lisz nieźle oberwał. Szkoda, że nie możemy go dobić...'),
(34796, 0, 0, 'plPL', 'Moi niewolnicy! Zniszczcie wroga!'),
(34799, 1, 0, 'plPL', '%s zakopuje się w ziemi!'),
(34799, 2, 0, 'plPL', '%s wychodzi spod ziemi!'),
(35144, 2, 0, 'plPL', '%s wychodzi spod ziemi!'),
(37200, 6, 0, 'plPL', 'Nad wzniesienie nadlatuje sterowiec Hordy.'),
(37200, 8, 0, 'plPL', 'Sterowiec cumuje, a najwyższy nadrządca Zaurzykieł wyskakuje z niego i staje naprzeciw żołnierzy Przymierza i Muradina'),
(37200, 11, 0, 'plPL', 'Między nimi pojawia się portal maga z Wichrogrodu, z którego wyłaniają się Varian Wrynn i Jaina Proudmoore.'),
(37230, 1, 0, 'plPL', 'Żmij mrozu z Iglicy ląduje tuż przed Młotem Orgrima.'),
(37230, 2, 0, 'plPL', 'Żmij mrozu z Iglicy ląduje tuż przed Niebołamaczem.'),
(37539, 0, 0, 'plPL', 'Dołącz do nas... M\'hahaha!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(110, 'plPL', 'Aber? To ty...? Och... taka jestem głodna, Aber! TAKA GŁODNA!!', '', 0),
(111, 'plPL', 'Zaraz... nie jesteś moim mężem. Ale to on musiał cię przysłać. A wyglądasz... tak... smakowicie!', '', 0),
(192, 'plPL', 'Wybacz, Huldarze... Ale zdaje się, że wprowadziłem cię w błąd.', '', 0),
(255, 'plPL', 'Cała przyjemność po mojej stronie, cukiereczku. Niedługo wrócę...', '', 0),
(256, 'plPL', 'Interes na bazarze musi iść jak z płatka. Zaraz uzupełnię mu zapasy!', '', 0),
(257, 'plPL', 'Hm... jak już to dostarczę, chyba wstąpię do tego sklepu z serami na małą przekąskę.', '', 0),
(258, 'plPL', 'Z tej sprzedaży powinno mi zostać parę monet. Może kupię sobie coś na obiad...', '', 0),
(259, 'plPL', 'Hej, Harlan. Mam dla ciebie partię dzianin.', '', 0),
(260, 'plPL', 'Uff! Kolejna partia towaru, Harlan. Musi schodzić jak świeże bułeczki!', '', 0),
(263, 'plPL', 'No to lecę. Trzymaj się, Harlan.', '', 0),
(264, 'plPL', 'Miło widzieć, że tak dobrze ci się wiedzie, Harlan. Mam nadzieję, że niedługo znów się zobaczymy...', '', 0),
(265, 'plPL', 'Panie burmistrzu! Nasi zwiadowcy donoszą o dziwnych poruszeniach na zachodzie.', '', 0),
(266, 'plPL', 'Burmistrzu Ello! Nasi zwiadowcy wrócili z cmentarza ze złowróżbnymi meldunkami...', '', 0),
(267, 'plPL', 'Z szałasu tego starego pustelnika dobiegają ohydne ryki i warczenie!', '', 0),
(268, 'plPL', 'Wilki ciągną w naszą stronę, jakby przed czymś... uciekały.', '', 0),
(269, 'plPL', 'Tak jest, panie burmistrzu.', '', 0),
(272, 'plPL', 'Altheo, mamy meldunki o dziwnych zdarzeniach na cmentarzu. Ello uważa, że to zapowiedź ataku na Mroczne Włości.', '', 0),
(275, 'plPL', 'Tak jest, dowódco!', '', 0),
(276, 'plPL', 'Strzeżcie się! Strzeżcie się! W dziczy czai się zagrożenie! Wartownicy Nocnej Straży, miejcie się na baczności!', '', 0),
(283, 'plPL', 'A teraz ta przekąska...', '', 0),
(284, 'plPL', 'Dzień dobry, Elling! Cześć, Elaine! Poproszę krążek sera pleśniowego, co?', '', 0),
(285, 'plPL', 'Witaj, klanie Triasów! Poproszę kulkę waszej wędzonej mozzarelli!', '', 0),
(290, 'plPL', 'Pięknie dziękuję!', '', 0),
(291, 'plPL', 'Dzięki za ser!', '', 0),
(292, 'plPL', 'Powinienem wracać, zanim Rema zacznie się martwić...', '', 0),
(293, 'plPL', 'Pora wracać do sklepu...', '', 0),
(294, 'plPL', 'Wróciłem!', '', 0),
(295, 'plPL', 'Tak jest, proszę pani, interes się kręci!', '', 0),
(503, 'plPL', 'Niech legenda o Stalvanie spoczywa w spokoju!', 'Niech legenda o Stalvanie spoczywa w spokoju!', 0),
(504, 'plPL', 'Kim jest ta marna istota, która miesza się w to, co minione? Niech legenda o Stalvanie umrze razem z tobą!', 'Kim jest ta marna istota, która miesza się w to, co minione? Niech legenda o Stalvanie umrze razem z tobą!', 0),
(505, 'plPL', 'Nie trudź się sprawami przeszłości, $n!', 'Nie trudź się sprawami przeszłości, $n!', 0),
(512, 'plPL', 'Brać go!', '', 0),
(518, 'plPL', 'Moje sługi...', '', 0),
(519, 'plPL', 'Czas podboju zbliża się wielkimi krokami.', '', 0),
(520, 'plPL', 'Wkrótce wasza żądza zniszczenia zostanie zaspokojona.', '', 0),
(521, 'plPL', 'Gniew, który w was płonie, wkrótce znajdzie pożywkę w naszych wrogach.', '', 0),
(522, 'plPL', 'Przynoszę wieści o naszym konflikcie ze zbuntowanymi nieumarłymi.', '', 0),
(523, 'plPL', 'Buntownicy z Lordaeronu są nieliczni i słabi, i nie znają radości służby naszemu Królowi Liszowi.', '', 0),
(525, 'plPL', 'Wyznawcy Mrocznej Pani są ślepi, skoro sądzą, że oprą się naszej potędze.', '', 0),
(526, 'plPL', 'My rośniemy w siłę, a naszych wrogów otaczają wrogowie i osłabiają nieustanne ataki.', '', 0),
(527, 'plPL', 'Nasz Pan rozkazuje nam szykować się do wojny!', '', 0),
(528, 'plPL', 'Przygotujcie się, bo wkrótce ruszymy do szturmu na tych, którzy nazwali siebie „Porzuconymi”.', '', 0),
(529, 'plPL', 'Szykujcie się do bitwy, moje twory.', '', 0),
(530, 'plPL', 'Jesteśmy ramieniem Jego woli. I zetrzemy Jego wrogów na cmentarny proch!', '', 0),
(531, 'plPL', 'Ta nieumarła hałastra i jej królowa, martwa elfka, upadną!', '', 0),
(532, 'plPL', 'Wypędzimy naszych wrogów ze Srebrzystego Boru, a potem zaniesiemy pożogę wojny do samej ich stolicy!', '', 0),
(533, 'plPL', 'Śmierć i chwała dla Króla Lisza!', '', 0),
(549, 'plPL', 'Z drogi! Z drogi!', '', 0),
(599, 'plPL', 'Powróciłem z grobu, by dokonać zemsty!', '', 0),
(600, 'plPL', 'Giń w imię Mrocznej Pani, $n.', '', 0),
(601, 'plPL', 'Nieumarli pożywią się twoją duszą, $n.', '', 0),
(602, 'plPL', 'Powstałem!', '', 0),
(603, 'plPL', 'Nareszcie się zemszczę!', '', 0),
(604, 'plPL', 'Południowy Brzeg zapłaci krwią!', '', 0),
(731, 'plPL', 'Mmmh... CZUJĘ JEDZENIE!', '', 0),
(763, 'plPL', 'ACH, UCZTA! KTO TO TU ZOSTAWIŁ...?', '', 0),
(841, 'plPL', 'Stój, $ggłupcze:głupia;! Nie możemy ci pozwolić przywołać tej istoty, Myzrael!', '', 0),
(853, 'plPL', '%s rozpada się na strzępy, wygnany z tego świata.', '', 0),
(854, 'plPL', 'Zbyt długo plądrowaliście nasze skarby. Szykujcie się na grób pod wodą!', '', 0),
(855, 'plPL', 'Nic nas nie powstrzyma! Zginiecie!', '', 0),
(916, 'plPL', 'Karnik, druhu mój, chciałbym cię jeszcze zobaczyć na własne oczy, ale musimy pogadać o Ragnarosie. Jego wpływy się szerzą.', '', 0),
(918, 'plPL', 'Z czasem powiem ci więcej, Karnik. Ale najpierw poślij $gtego wędrowca:tę wędrowczynię; do Belgruma – jest jeszcze coś do załatwienia.', '', 0),
(1014, 'plPL', 'Mój miecz Archeus dobrze mi służył za życia, lecz skoro mój duch może wreszcie porzucić tę nieszczęsną egzystencję, nie jest mi już potrzebny.', '', 0),
(1015, 'plPL', 'Będę się trzymał miłości mojej córki i nadziei, że w Światłości znajdę przebaczenie za swoje grzechy.', '', 0),
(1079, 'plPL', 'Wezwano mnie! Intruzi, przyjdźcie do mojego namiotu i spójrzcie śmierci w oczy!', '', 0),
(1174, 'plPL', '%s wyłania się z ziemi!', '', 0),
(1176, 'plPL', 'ZABIĆ!!!', '', 0),
(1182, 'plPL', 'Któż to przywołał Amana?', '', 0),
(1183, 'plPL', 'Ach, widzę, że trudzisz się nad reliktami przeszłości.', '', 0),
(1184, 'plPL', 'Wiedz, że nawet twoi stwórcy są omylni.', '', 0),
(1185, 'plPL', 'Zbyt głębokie grzebanie w przeszłości może gwałtownie zakończyć twoją przyszłość.', '', 0),
(1187, 'plPL', '%s rozwiewa się na twoich oczach.', '', 0),
(1225, 'plPL', '%s odwraca się na południowy wschód i skomli, po czym znów spogląda na ciebie.', '', 0),
(1226, 'plPL', '%s ryczy na Terenthisa, by zwrócić jego uwagę.', '', 0),
(1228, 'plPL', '%s zaczyna pojękiwać i ryczeć na Terenthisa, tupiąc łapami o ziemię.', '', 0),
(1231, 'plPL', '%s znów ryczy na Terenthisa, ale tym razem druid zdaje się rozumieć niedźwiedzia.', '', 0),
(1233, 'plPL', '%s ryczy potakująco do Terenthisa.', '', 0),
(1234, 'plPL', '%s warczy w twoją stronę, a potem niespiesznie cię obwąchuje.', '', 0),
(1241, 'plPL', '%s ryczy z radości i pędzi do Volcora. Gdy dopada swojego pana, liże go po twarzy.', '', 0),
(1279, 'plPL', '', 'Wieki były okrutne dla ciebie i dla mnie, ukochany, lecz bądź pewien: to ja, i nareszcie znów jesteśmy razem.', 0),
(1282, 'plPL', '', 'Niech to nie trapi twego serca, ukochany. Uwolniłeś mnie z niewoli i za to kocham cię jeszcze mocniej.', 0),
(1283, 'plPL', '', 'Niestety, nawet ta chwila nie może trwać długo... Więzy, które łączą mnie z tym światem, słabną i coś mnie stąd odciąga...', 0),
(1284, 'plPL', '', 'Żegnaj, Cerelleanie, dopóki znów się nie połączymy...', 0),
(1285, 'plPL', '', '%s mówi coraz ciszej, a jej łagodny głos rozpływa się we mgle: „Wiedz, że zawsze cię kocham...”', 0),
(1309, 'plPL', 'Paladyn! Ta śmierć ucieszy mistrza. Do ataku!', 'Paladyn! Ta śmierć ucieszy mistrza. Do ataku!', 0),
(1312, 'plPL', 'Nie ukryjesz się przed nami, $gmały paladynie:mała paladynko;!', '', 0),
(1313, 'plPL', 'Bez Oczyszczyciela nie jesteś już $gtaki pewny:taka pewna; siebie, hm?', '', 0),
(1356, 'plPL', '', 'Moich towarzyszy ubywa, bogini, a moja własna moc wkrótce nie wystarczy, by powstrzymać demony ze Spaczonej Kniei.', 0),
(1357, 'plPL', '', 'Bogini, obdarz mnie mocą, bym pokonała wrogów! Wysłuchaj mnie, proszę, moja potrzeba jest rozpaczliwa, a sprawa słuszna!', 0),
(1358, 'plPL', '', 'Co... co to? Czyżby to była odpowiedź na moje modlitwy? Elune obdarzyła mnie bronią – tą kosą – bym pokonała demony.', 0),
(1359, 'plPL', '', 'Zawiodłam... Nie wypełniłam obowiązku... zawiodłam mój lud... Worgeny szaleją na wolności, a Kosa mojej bogini przepadła.', 0),
(1360, 'plPL', '', 'To zło, które rozpętałam... W czyich rękach spoczywa teraz moc, którą obdarzyła mnie bogini... Czyja ręka nią kieruje?', 0),
(1428, 'plPL', 'Hej! Nie powinno cię tu być! Dalej, chłopaki!', '', 0),
(1714, 'plPL', 'Paval Reethe! Nareszcie cię znalazłem. I zadajesz się teraz z ogrami? Bez obaw, nawet dezerterom i zdrajcom należy się odrobina litości.', '', 0),
(1715, 'plPL', 'Dobra, szefie. Nie ma sprawy.', '', 0),
(1716, 'plPL', 'Jasne, szefie. Ale na pewno? Szkoda marnować taką okazję do poćwiczenia.', '', 0),
(1720, 'plPL', 'Szeregowa, okaż porucznikowi Reethe\'owi odrobinę litości.', '', 0),
(1721, 'plPL', '', 'Z przyjemnością, panie poruczniku.', 0),
(1723, 'plPL', 'A teraz posprzątajmy resztę tych śmieci, żołnierze!', '', 0),
(1752, 'plPL', 'Melduje się Falgran Hastil. Sprawdzę, dokąd prowadzą ślady kopyt, i zdam raport.', '', 0),
(1973, 'plPL', 'Wiele czasu minęło, Bethorze, przyjacielu.', '', 0),
(1974, 'plPL', 'Gdy czas pozwoli, musimy dłużej porozmawiać. Mamy bowiem wiele do omówienia.', '', 0),
(1975, 'plPL', 'I dziękuję ci, $n. Bez twojej pomocy może nigdy nie odnalazłbym drogi do Porzuconych.', '', 0),
(2089, 'plPL', 'Żałosny słabeusz z Porzuconych. Chcesz zobaczyć mojego pana? Niech tak będzie.', '', 0),
(2090, 'plPL', 'Kto śmie mnie szukać?!', '', 0),
(2091, 'plPL', 'Robactwo!', '', 0),
(2092, 'plPL', 'Chodźcie! Chodźcie po swoją śmierć – jeśli macie odwagę!', '', 0),
(2093, 'plPL', 'Tak, chodźcie. Mój pan i ja będziemy czekać.', '', 0),
(2356, 'plPL', '%s traci ducha i ucieka!', '', 0),
(2721, 'plPL', 'Jasne, zdradzę ci formułę. Byle tylko nie musieć zbliżać się do Tirtha!', '', 0),
(2807, 'plPL', 'Niegdyś podążałem drogą Młota Zmierzchu. Opętany myślą o wskrzeszeniu Przedwiecznych, zapuściłem się w głąb tego leża, by zaczerpnąć mocy od przeklętej bestii, Aku\'mai!$b$bGdy ujrzałem, jak składa się w ofierze niezliczonych niewinnych, opamiętałem się.$b$bByłem uwięziony, ale teraz jestem wolny! Tylko że tak daleko od mojej ojczyzny, Khaz Modan!$b$b$GDzielny poszukiwaczu:Dzielna poszukiwaczko; przygód, w zamian za zabicie Aku\'mai oferuję ci podróż do bardzo szczególnej krainy. Jeśli chcesz, mogę cię przenieść do miasta Darnassus.', '', 0),
(2846, 'plPL', 'Proszę, przenieś mnie do Darnassus.', 'Proszę, przenieś mnie do Darnassus.', 0),
(2848, 'plPL', 'Aku\'mai nie żyje! Nareszcie mogę opuścić to przeklęte miejsce.', '', 0),
(2849, 'plPL', 'Porozmawiaj ze mną, a usłyszysz moją opowieść.', '', 0),
(3165, 'plPL', 'Co do skrzeka??? Skrzek, skrzek, skrzek? SKRZEK!', '', 0),
(3172, 'plPL', 'Pozdrowienia. Moją funkcją jest udostępnianie informacji o dokonanej przez Stwórców syntezie ziemnych na świecie oznaczonym jako Azeroth oraz, gdy jest to dozwolone, ich objaśnianie. Jestem gotów przekazać ci te informacje teraz, w dogodnej dla ciebie chwili.', '', 0),
(3173, 'plPL', 'Ziemni to rasa syntetyczna zaprojektowana przez Stwórców, pełniąca funkcję jednej z ras zalążkowych w pierwotnej populacji świata oznaczonego jako Azeroth. Ziemnych stworzono, by wspomagali Stwórców w kształtowaniu głębokich regionów tego świata.$B$BSą modyfikacją standardowej matrycy istoty podziemnej, stosowanej na innych światach zasiedlonych przez Stwórców. Budowa tej prototypowej rasy wywołała rozmaite anomalie, które zaobserwowano po wstępnej syntezie.', '', 0),
(3174, 'plPL', 'To jedna z matryc syntezy, których Stwórcy używają przy zasiedlaniu świata. Każda matryca syntezy służy osiągnięciu celów Stwórców. Na potrzeby Azeroth zmodyfikowano matrycę istoty podziemnej, aby stworzyć istotę o zwiększonej wytrzymałości i ze skłonnością do kształtowania głębokich regionów; ziemni są wynikiem tej modyfikacji.$B$BGdy ziemni rozpoczęli już służbę dla Stwórców, odkryto nieprzewidziane anomalie, które w środowiskach o wysokim obciążeniu oddziaływały na ich matrycę syntezy.', '', 0),
(3175, 'plPL', 'Zanim będzie można właściwie odpowiedzieć na to pytanie, należy przekazać ci dodatkowe informacje podstawowe o ziemnych.$B$BPrzetwarzanie.$B$BAby zrozumieć anomalie ziemnych, trzeba najpierw zrozumieć, czym ziemni są w zamyśle projektowym. Ziemni stanowią podjętą przez Stwórców próbę ulepszenia paradygmatu przeżywalności standardowej matrycy istoty podziemnej. Dokonano tego, włączając do owej matrycy odporną podstawę konstrukcyjną, właściwą temu światu.', '', 0),
(3176, 'plPL', 'To materiał bazowy używany w syntezie ras. Jako podstawy syntezy ziemnych użyto przekroju skorupy Azeroth zamiast typowej dla Stwórców podstawy konstrukcyjnej z biomasy.$B$BBadania nad składem tego świata doprowadziły Stwórców do teorii, że da się zsyntetyzować ulepszoną istotę, która będzie uosobieniem odporności esencji tego świata. Osiągnięto to, wybierając na podstawę mieszankę rozmaitych związków kamiennego jądra Azeroth.', '', 0),
(3177, 'plPL', 'Mówiąc najprościej, zgadza się.$B$BPod względem cech fizycznych ziemni są humanoidami niższego wzrostu, choć zbudowani są z rozmaitych związków kamiennego jądra Azeroth. Ich konstrukcja maksymalizuje siłę i wytrzymałość bez uszczerbku dla mocy przetwarzania poznawczego. Ich skóra i mięśnie są niemal niewrażliwe na obrażenia fizyczne, a po bardzo drobnych modyfikacjach ziemni wykazują niezwykłą odporność na niepożądane siły magiczne.', '', 0),
(3178, 'plPL', 'Dla przyswojenia tych danych kluczowe jest zrozumienie, że Stwórcy chcieli zsyntetyzować rasę, która długo po ich odejściu pozostanie nieodłączną częścią cyklu rozwojowego tego świata. Rasa ta miała odegrać zasadniczą rolę w realizacji długoterminowych celów rozwojowych Stwórców wobec Azeroth.$B$BNa marginesie: nazwę „ziemni” Stwórcy uznali za stosowną dla nowej rasy ze względu na jej skład.', '', 0),
(3179, 'plPL', 'Jedyną anomalią syntezy ziemnych jest skłonność matrycy do destabilizacji podczas użytkowania w środowiskach o wysokim obciążeniu.$B$BUzupełnienie: nowa konstrukcja matrycy była z natury przystosowana do rzeźbienia głębin ziemi, toteż praca ta nigdy nie spełniała kryteriów środowiska o wysokim obciążeniu.$B$BDestabilizację odkryto dopiero wtedy, gdy podstawowy cykl służby ziemnych dla Stwórców trwał już od dawna. Zamiast wycofania i ponownej syntezy Stwórcy rozpoczęli prace nad modyfikacją posyntezową.', '', 0),
(3180, 'plPL', '[Po twoim pytaniu następuje wyraźna pauza.]$B$BInformacja, o którą prosisz, nie jest obecnie dostępna w cyklu danych tego repozytorium. Szczerze przepraszam za to niedopatrzenie.$B$BProszę zwrócić się o tę informację po aktualizacji cyklu danych tego repozytorium informacji. Można też zwrócić się o nią do innego repozytorium informacji znajdującego się w Azeroth.', '', 0),
(3181, 'plPL', 'Destabilizacja matrycy syntezy ziemnych może dać dwa wyniki. Uruchamiam pomoc wizualną numer jeden.$B$BPierwsza matryca wariantowa to zwyrodniały produkt syntezy, niniejszym oznaczony potoczną nazwą „trogg”. Wariant ten zachowuje siłę i wytrzymałość porównywalne z ziemnymi, lecz jego moc przetwarzania poznawczego została niemal całkowicie utracona. Jedynymi siłami napędowymi psychiki trogga są siła woli i wyraźnie rozwinięty spryt.', '', 0),
(3182, 'plPL', 'Nie potrafię przetworzyć twojego odniesienia chronologicznego w zestawieniu z czasem zapisu tych danych, przepraszam.$B$BTrogg zachowuje część składu z rozmaitych związków kamiennego jądra Azeroth, lecz utrata mocy poznawczej czyni ten wariant nieakceptowalnym dla Stwórców.$B$BTrogg rozmnaża się jak standardowa biomasa. Domyślnie żywi się kamieniem i wszystkim innym, co zdoła zdobyć, w tym innymi troggami. Stwórcy uznają kanibalizm za nieakceptowalny.', '', 0),
(3183, 'plPL', 'Uruchamiam pomoc wizualną numer dwa.$B$BDrugi wariant wynikowy matrycy ziemnych zachowuje wiele pożądanych cech w porównaniu ze standardową matrycą podziemną. Potoczna nazwa tego wariantu to „krasnolud”.$B$BWariant ten zachowuje siłę i wytrzymałość właściwe ziemnym. W niektórych przypadkach krasnolud przewyższa nawet moc poznawczą matrycy ziemnych. Nie zachowuje jednak nic z fizycznego składu, jakim są rozmaite związki kamiennego jądra Azeroth.', '', 0),
(3184, 'plPL', 'Dane przechowywane w tym repozytorium istotnie zgadzają się z twoim przenikliwym stwierdzeniem.$B$BKrasnolud zachowuje skłonność do kamiennej materii Azeroth, lecz wskutek anomalii matrycy syntezy ziemnych, ujawniającej się w środowiskach o wysokim obciążeniu, powraca do domyślnego składu z biomasy, znanego ze standardowej matrycy podziemnej.$B$BErgo, wariant krasnoludzki rzeczywiście powstaje wskutek degeneracji matrycy stworzenia ziemnych, jak wynika z twojego zapytania.', '', 0),
(3185, 'plPL', 'Nie potrafię przetworzyć twojego odniesienia chronologicznego w zestawieniu z czasem zapisu tych danych, przepraszam.$B$BChoć krasnolud zachowuje większość mentalnego dostrojenia ziemnych do kamiennej materii Azeroth, powrót do żywej biomasy pozostaje główną degeneracją matrycy. Krasnoludy jedzą i rozmnażają się w sposób typowy dla innych standardowych biomas.$B$BStwórcy uważają krasnoluda za wariant akceptowalny, godny własnej genezy.', '', 0),
(3186, 'plPL', 'Stwórcy to... Stwórcy.$B$BTo istoty, które zasiedliły i ukształtowały ten świat według własnego zamysłu. To dzięki nim istnieje ten świat i wiele innych. Są źródłem, z którego wypływa Azeroth.', '', 0),
(3187, 'plPL', 'Stwórcy są świadomi ogromu informacji zgromadzonych w tym repozytorium. W związku z tym, gdy tylko dostroisz się do Dysków Norgannona, zostanie ci udostępniona przenośna kopia przechowywanych tu danych.$B$BProszę uznać wstępne wymogi przyswojenia tej wiedzy za spełnione. W dogodnej chwili uzyskaj dostęp do Dysków Norgannona, aby rozpocząć syntezę swoich dysków.', '', 0),
(3188, 'plPL', 'Kim są ziemni?', 'Kim są ziemni?', 0),
(3189, 'plPL', 'Co to jest „matryca istoty podziemnej”?', 'Co to jest „matryca istoty podziemnej”?', 0),
(3190, 'plPL', 'O jakich anomaliach mówisz?', 'O jakich anomaliach mówisz?', 0),
(3191, 'plPL', 'Co to jest „odporna podstawa konstrukcyjna”?', 'Co to jest „odporna podstawa konstrukcyjna”?', 0),
(3192, 'plPL', 'Czyli... Ziemnych zrobiono z kamienia?', 'Czyli... Ziemnych zrobiono z kamienia?', 0),
(3193, 'plPL', 'Czy jest coś jeszcze, co warto wiedzieć o ziemnych?', 'Czy jest coś jeszcze, co warto wiedzieć o ziemnych?', 0),
(3194, 'plPL', 'Chyba rozumiem już, jaki był zamysł projektowy Stwórców wobec ziemnych. O jakich anomaliach ziemnych była wcześniej mowa?', 'Chyba rozumiem już, jaki był zamysł projektowy Stwórców wobec ziemnych. O jakich anomaliach ziemnych była wcześniej mowa?', 0),
(3195, 'plPL', 'Jakie środowiska o wysokim obciążeniu powodują destabilizację ziemnych?', 'Jakie środowiska o wysokim obciążeniu powodują destabilizację ziemnych?', 0),
(3196, 'plPL', 'Co się dzieje, gdy ziemni ulegają destabilizacji?', 'Co się dzieje, gdy ziemni ulegają destabilizacji?', 0),
(3197, 'plPL', 'Troggi?! Czy troggi, o których mówisz, to te same, które żyją dziś na świecie?', 'Troggi?! Czy troggi, o których mówisz, to te same, które żyją dziś na świecie?', 0),
(3198, 'plPL', 'Była mowa o dwóch wynikach destabilizacji ziemnych. Jaki jest drugi?', 'Była mowa o dwóch wynikach destabilizacji ziemnych. Jaki jest drugi?', 0),
(3199, 'plPL', 'Krasnoludy!!! Chcesz mi powiedzieć, że krasnoludy pochodzą od ziemnych?!', 'Krasnoludy!!! Chcesz mi powiedzieć, że krasnoludy pochodzą od ziemnych?!', 0),
(3200, 'plPL', 'To te same krasnoludy co dzisiaj, tak? Czy krasnoludy zachowały jeszcze jakieś inne związki z ziemnymi?', 'To te same krasnoludy co dzisiaj, tak? Czy krasnoludy zachowały jeszcze jakieś inne związki z ziemnymi?', 0),
(3201, 'plPL', 'Kim są Stwórcy?', 'Kim są Stwórcy?', 0),
(3202, 'plPL', 'Jest o czym myśleć.', 'Jest o czym myśleć.', 0),
(3221, 'plPL', 'Uzyskam teraz dostęp do dysków.', 'Uzyskam teraz dostęp do dysków.', 0),
(3931, 'plPL', 'Hej! Precz od naszego skarbu!', 'Hej! Precz od naszego skarbu!', 0),
(4049, 'plPL', 'Pozdrowienia! Jestem strażnikiem wejścia. Aby uzyskać dostęp do Uldum, proszę użyć właściwych dysków.', '', 0),
(4053, 'plPL', 'Pozdrowienia. Jestem strażnikiem wejścia. Jeśli nie masz Płyt Uldum już zintegrowanych z twoim zestawem dysków, nie zezwolę na wejście do kompleksu Uldum.', '', 0),
(4054, 'plPL', 'Jaką funkcję pełnisz?', 'Jaką funkcję pełnisz?', 0),
(4055, 'plPL', 'Moim zadaniem jest regulowanie dostępu do kompleksu Uldum w imieniu Stwórców. Zezwalam na wejście do kompleksu tylko wtedy, gdy wnioskujący okaże właściwe dyski sekwencyjne.$B$BTwój zestaw dysków nie zawiera obecnie Płyt Uldum, podstawowego warunku wejścia. Dostęp nie zostanie przyznany, dopóki Płyty Uldum nie będą obecne.', '', 0),
(4056, 'plPL', 'Czym są Płyty Uldum?', 'Czym są Płyty Uldum?', 0),
(4057, 'plPL', 'Gdzie są Płyty Uldum?', 'Gdzie są Płyty Uldum?', 0),
(4058, 'plPL', 'Słucham? „Wyznaczono nam nowy termin wizytacji”? Co to ma znaczyć?!', 'Słucham? „Wyznaczono nam nowy termin wizytacji”? Co to ma znaczyć?!', 0),
(4059, 'plPL', 'A więc... co jest w środku Uldum?', 'A więc... co jest w środku Uldum?', 0),
(4060, 'plPL', 'Wrócę, gdy zdobędę Płyty Uldum.', 'Wrócę, gdy zdobędę Płyty Uldum.', 0),
(4061, 'plPL', 'Płyty Uldum to dyski zsyntetyzowane przez Stwórców, umożliwiające dostęp do kompleksu Uldum. Dyski te mieszczą i przechowują określone dane związane z działaniami Stwórców w tym miejscu.$B$BFizycznie mają niemal taki sam obwód jak zestaw dysków, który obecnie posiadasz. Ich oznaczenia odnoszą się jednak bezpośrednio do informacji o Uldum, a nie o kompleksie Uldaman.', '', 0),
(4062, 'plPL', 'Stwórcy zsyntetyzowali kilka zestawów Płyt Uldum wyłącznie na własny użytek. Stwórcy kontrolują dystrybucję owych dysków dla wszystkich kompleksów na tym świecie. Ponieważ Azeroth wyznaczono nowy termin wizytacji, kolejne dyski mogą wówczas wejść do obiegu.$B$BIstniejące dyski zostały w całości rozdane stronom mającym odpowiednie poświadczenie bezpieczeństwa.', '', 0),
(4063, 'plPL', 'Stwórcy stosują wizytację jako środek przywracania kontroli nad zasiedlonymi światami, gdy siły zewnętrzne lub wewnętrzne zaburzają związaną z nimi dynamikę matrycy. Takich działań Stwórców nie należy lekceważyć.$B$BDodatkowych informacji o zaplanowanej wizytacji tego świata udziela właściwe repozytorium danych, które obsługuje wszystkie kwestie związane z harmonogramem Stwórców.', '', 0),
(4064, 'plPL', 'Uldum to placówka badawcza Stwórców, służąca ich nieustającym staraniom o ulepszenie biosfery Azeroth. Szczegółowe informacje o ich pracach związanych z Uldum są zastrzeżone dla osób, które mają Płyty Uldum w swoich zestawach dysków.$B$BRepozytoria danych wewnątrz kompleksu Uldum zaprogramowano do udzielania informacji o konkretnych eksperymentach i zestawieniach danych; po szczegóły proszę zwrócić się do nich.', '', 0),
(4065, 'plPL', 'Twoje dyski zostaną ci zwrócone, gdy uzyskasz dostęp do piedestału.', '', 0),
(4328, 'plPL', 'Przychodzimy z dołu! Nigdy nas nie powstrzymacie!', '', 0),
(4358, 'plPL', 'Jest mój...', '', 0),
(4391, 'plPL', 'Twoje zadanie wykonane. Przygotuj się na zagładę.', '', 0),
(4392, 'plPL', 'Obsidionie, powstań i służ swemu panu!', '', 0),
(4393, 'plPL', 'Brawo! Brawo! Piękne przedstawienie. Co? Myśleliście, że nie żyję?', '', 0),
(4394, 'plPL', 'Głupcy, wiedziałem, że jeśli zagram na żałosnych uczuciach mojego brata, przyśle „ratowników”.', '', 0),
(4395, 'plPL', 'Jakże łatwo było wami pokierować, byście odebrali ostatni kamień Suntary tym imbecylom z Młota Zmierzchu.', '', 0),
(4396, 'plPL', 'Gdy natknąłem się na kamienie Suntary w Wykopalisku Brudnego Mułu, całą moją istotę przeniknęła moc Ragnarosa. To Ragnaros dał mi cel.', '', 0),
(4397, 'plPL', 'To z woli Ragnarosa zbudowano Obsidiona. Obsidion zniszczy orki z Czarnej Skały w Iglicy Czarnej Góry i połączy nas z naszymi braćmi w ognistych głębinach.', '', 0),
(4398, 'plPL', 'I wreszcie to Ragnaros nadał mi imię, gdy odrodziłem się jako akolita ognia: Lathoric... Lathoric Czarny.', '', 0),
(4399, 'plPL', '%s śmieje się coraz ciszej, aż jego śmiech zamiera...', '', 0),
(4438, 'plPL', 'Moje oczy! To pali... pali...', '', 0),
(4439, 'plPL', 'Nie dręcz mnie dłużej! Uwolnij mnie, śmiertelna istoto! Moczary Smutków... śmiertelna istoto... proszę...', '', 0),
(4440, 'plPL', 'Głupia śmiertelna istoto, gdy tylko odzyskam wolność, rozerwę twoją duszę na dwoje!', '', 0),
(4441, 'plPL', 'Jesteś narzędziem ich nikczemnego boga, nędzna istoto. Dopilnuję, by cię zniszczono!', '', 0),
(4442, 'plPL', 'Moja dusza to nie błyskotka! Śmiertelna istoto, musisz mnie uwolnić z tych łańcuchów!', '', 0),
(4443, 'plPL', 'Tak bardzo boli... Ithariusie, stary przyjacielu... proszę, pomóż mi...', '', 0),
(4444, 'plPL', 'Czy ten koszmar kiedyś się skończy?! Nie potrafię zmusić się do przebudzenia!', '', 0),
(4445, 'plPL', 'Zawiodłem, choć powierzono mi straż nad świątynią... moja spaczona dusza nie zazna spokoju...', '', 0),
(4456, 'plPL', 'W rzeczy samej wspaniale, Maltrake. Wygląda na to, że mój plan powiódł się doskonale. Nie sądzisz, śmiertelna istoto?', '', 0),
(4457, 'plPL', 'Przecież nie $gpomógłbyś:pomogłabyś; legionowi Czarnej Skały, gdybyśmy zwyczajnie poprosili o pomoc, prawda?', '', 0),
(4458, 'plPL', '%s wybucha gadzim śmiechem... a przynajmniej wydaje ci się, że to śmiech.', '', 0),
(4460, 'plPL', 'MILCZ, GŁUPCZE!', '', 0),
(4461, 'plPL', 'Będą żyć, choćby po to, by ujrzeć owoce swojej pracy: zniszczenie i chaos, które niechybnie nastaną, gdy legion Czarnej Skały najedzie wąwóz.', '', 0),
(4462, 'plPL', 'Teraz was opuszczam, śmiertelnicy. Żywych i z tymi błyskotkami. Maltrake! Wręcz im błyskotki!', '', 0),
(4463, 'plPL', 'A, tak, wylinka – nie zgub jej. Wśród moich pobratymców na Płonących Stepach są tacy, którzy potrafią wytworzyć przedmioty, jakie wzmocnić może tylko wylinka Czarnego Stada.', '', 0),
(4464, 'plPL', '%s zaczyna coraz szybciej bić potężnymi skrzydłami. Szykuje się do lotu.', '', 0),
(4465, 'plPL', 'Nadciąga legion Czarnej Skały, krasnoludki! Wypalimy ziemię i podpalimy niebiosa. Nikt nie przeżyje...', '', 0),
(4491, 'plPL', 'Pani!! Chcą zniszczyć twoje dzieło!!', 'Pani!! Chcą zniszczyć twoje dzieło!!', 0),
(4492, 'plPL', 'Ha! Teraz twoja śmierć jest pewna!', 'Ha! Teraz twoja śmierć jest pewna!', 0),
(4495, 'plPL', '', 'Jak śmiesz! Poczuj teraz mój gniew!', 0),
(4502, 'plPL', 'Kto śmie?! Zniszczę cię!', 'Kto śmie?! Zniszczę cię!', 0),
(4529, 'plPL', '', 'Nie! Nie możemy pozwolić, byście przywołali Hakkara!', 0),
(4530, 'plPL', '', 'Nie wolno wam przywoływać naszego boga!', 0),
(4545, 'plPL', 'JESTEM TUTAJ!', '', 0),
(4917, 'plPL', 'Kolkarowie są najsilniejsi!', '', 0),
(4922, 'plPL', 'Brońcie bunkrów!', 'Brońcie bunkrów!', 0),
(4925, 'plPL', 'Nasi wrogowie padną!', 'Nasi wrogowie padną!', 0),
(4928, 'plPL', 'Klęknij, Grarku.', '', 0),
(4929, 'plPL', 'Grarku Lorkrubie, postawiono ci zarzut zdrady Hordy i uznano cię winnym. Nieważne, czy przyznajesz się do winy. Wielki kacie Nuzraku, wystąp.', '', 0),
(4930, 'plPL', '%s unosi swój potężny topór nad Grarkiem.', '', 0),
(4931, 'plPL', 'Skończ z nim...', '', 0),
(4932, 'plPL', '%s unosi rękę, a potem ją opuszcza.', '', 0),
(4933, 'plPL', 'A ty, żołnierzu, natychmiast melduj się w Kargacie!', '', 0),
(4949, 'plPL', 'O rany, byłem pewien, że już po mnie. Uch... wciąż kręci mi się w głowie...', '', 0),
(4962, 'plPL', 'Co wy wyprawiacie? Intruzi!!', '', 0),
(5412, 'plPL', '', 'Daj mi chwilę, $N, właśnie atakują nas nagi. Porozmawiam z tobą, gdy tylko atak się skończy!', 0),
(5441, 'plPL', 'Zostaliście skazani na śmierć za zbrodnie przeciwko narodowi Czarnorytych!', '', 0),
(5442, 'plPL', 'Synowie Thaurissana będą patrzeć, jak giniecie w Kręgu Prawa!', '', 0),
(5443, 'plPL', 'Uwolnijcie furię i niech się dokona!', '', 0),
(5444, 'plPL', 'Haha! Założę się, że myśleliście, że to już koniec!', '', 0),
(5445, 'plPL', 'Ale prawdziwa kara dopiero przed wami.', '', 0),
(5446, 'plPL', 'No i dobrze!', '', 0),
(5538, 'plPL', 'Intruzi niszczą nasze jaja! Stać!!', 'Intruzi niszczą nasze jaja! Stać!!', 0),
(5748, 'plPL', 'Nie wszystko stracone! Walczcie z tymi bestiami bez lęku. Wasze rany uleczę, wasze kości zrosnę. Odzyskajcie siły, bohaterowie!', '', 0),
(5760, 'plPL', 'Zaszliście zbyt daleko, by teraz zawieść. Cofnijcie się, śmiertelnicy.', '', 0),
(5761, 'plPL', 'Zapłacisz cierpieniem za tę klęskę, Nefarianie!', '', 0),
(5778, 'plPL', 'Niszczysz jedynie obraz, głupcze. Będę cię ścigał aż po kres dni.', '', 0),
(5828, 'plPL', 'Zaraz! Na coś takiego się nie pisałem, radź sobie sam, Chudy!', '', 0),
(5832, 'plPL', '$GPrzywołałeś:Przywołałaś; mnie, $ggłupcze:głupia;! A teraz GIŃ!', '', 0),
(5836, 'plPL', 'Oni w Dzielnicy Magów. Ty szukać ich w strasznym budynku z czaszką.', 'Oni w Dzielnicy Magów. Ty szukać ich w strasznym budynku z czaszką.', 0),
(5837, 'plPL', 'My wiedzieć, gdzie oni! Budynek z czaszką w Dzielnicy Magów, w zewnętrznym kręgu miasta.', 'My wiedzieć, gdzie oni! Budynek z czaszką w Dzielnicy Magów, w zewnętrznym kręgu miasta.', 0),
(5838, 'plPL', 'Bank w Dzielnicy Handlowej, środkowa wieża. Ty nie przegapić.', 'Bank w Dzielnicy Handlowej, środkowa wieża. Ty nie przegapić.', 0),
(5839, 'plPL', 'My mieć jedno oko, a widzieć lepiej niż ty! Bank w środku Podmiasta!', 'My mieć jedno oko, a widzieć lepiej niż ty! Bank w środku Podmiasta!', 0),
(5840, 'plPL', 'Michael Garrett w górnym kręgu Dzielnicy Handlowej.', 'Michael Garrett w górnym kręgu Dzielnicy Handlowej.', 0),
(5841, 'plPL', 'Człowiek nietoperz na górnym poziomie Dzielnicy Handlowej.', 'Człowiek nietoperz na górnym poziomie Dzielnicy Handlowej.', 0),
(5842, 'plPL', 'Tak, ty szukać Christophera Drakula w Dzielnicy Handlowej. On na wschodniej platformie.', 'Tak, ty szukać Christophera Drakula w Dzielnicy Handlowej. On na wschodniej platformie.', 0),
(5843, 'plPL', 'My dołączyć do gildii? Nie? Dobra, ty znaleźć mistrza gildii na wschodniej platformie w Dzielnicy Handlowej.', 'My dołączyć do gildii? Nie? Dobra, ty znaleźć mistrza gildii na wschodniej platformie w Dzielnicy Handlowej.', 0),
(5844, 'plPL', 'Karczmarz Norman w górnym kręgu Dzielnicy Handlowej – z nim gadać.', 'Karczmarz Norman w górnym kręgu Dzielnicy Handlowej – z nim gadać.', 0),
(5845, 'plPL', 'Niegodziwi nie zaznać spoczynku, ale my myśleć, że ty w porządku. Ty znaleźć karczmarza Normana w górnym kręgu Dzielnicy Handlowej.', 'Niegodziwi nie zaznać spoczynku, ale my myśleć, że ty w porządku. Ty znaleźć karczmarza Normana w górnym kręgu Dzielnicy Handlowej.', 0),
(5846, 'plPL', 'Skrzynka pocztowa w środku miasta, Dzielnica Handlowa, górny krąg... obok karczmy.', 'Skrzynka pocztowa w środku miasta, Dzielnica Handlowa, górny krąg... obok karczmy.', 0),
(5847, 'plPL', 'My musieć sprawdzić, czy nasz Łamacz mózgów... mózgów... mózgów sprzedać się na aukcji. Ty znaleźć skrzynkę pocztową obok karczmy w górnym kręgu Dzielnicy Handlowej.', 'My musieć sprawdzić, czy nasz Łamacz mózgów... mózgów... mózgów sprzedać się na aukcji. Ty znaleźć skrzynkę pocztową obok karczmy w górnym kręgu Dzielnicy Handlowej.', 0),
(5848, 'plPL', 'My mieć dom aukcyjny w środkowym kręgu.', 'My mieć dom aukcyjny w środkowym kręgu.', 0),
(5849, 'plPL', 'Środkowy krąg. Ty iść!', 'Środkowy krąg. Ty iść!', 0),
(5850, 'plPL', 'Mały goblin na szczycie budynku na północ od Ruin Lordaeronu. Ty wyjść z Podmiasta i tam iść.', 'Mały goblin na szczycie budynku na północ od Ruin Lordaeronu. Ty wyjść z Podmiasta i tam iść.', 0),
(5851, 'plPL', 'My widzieć balon na północ od ruin, wysoko w górze. On zabrać cię w dalekie strony.', 'My widzieć balon na północ od ruin, wysoko w górze. On zabrać cię w dalekie strony.', 0),
(5852, 'plPL', 'Nauczyciel kapłanów? Ty iść do zewnętrznego kręgu Dzielnicy Wojennej i tam ich szukać.', 'Nauczyciel kapłanów? Ty iść do zewnętrznego kręgu Dzielnicy Wojennej i tam ich szukać.', 0),
(5853, 'plPL', 'Uhm. Bezbożni w Dzielnicy Wojennej, stać wokół głównego budynku w zewnętrznym kręgu miasta.', 'Uhm. Bezbożni w Dzielnicy Wojennej, stać wokół głównego budynku w zewnętrznym kręgu miasta.', 0),
(5856, 'plPL', 'Łotrzy w budynku w zewnętrznym kręgu Dzielnicy Łotrów.', 'Łotrzy w budynku w zewnętrznym kręgu Dzielnicy Łotrów.', 0),
(5857, 'plPL', 'Oni nauczyć mnie dobrze się skradać. Ty znaleźć ich w Dzielnicy Łotrów, w zewnętrznym kręgu Podmiasta.', 'Oni nauczyć mnie dobrze się skradać. Ty znaleźć ich w Dzielnicy Łotrów, w zewnętrznym kręgu Podmiasta.', 0),
(5859, 'plPL', 'Nauczyciele czarnoksiężników w Dzielnicy Magów, w budynku w zewnętrznym kręgu, razem z magami.', 'Nauczyciele czarnoksiężników w Dzielnicy Magów, w budynku w zewnętrznym kręgu, razem z magami.', 0),
(5860, 'plPL', 'My chcieć ogara spaczenia na zwierzaka. My go karmić, dobrze traktować i nauczyć aportować. Ty znaleźć czarnoksiężników w Dzielnicy Magów, w zewnętrznym kręgu miasta.', 'My chcieć ogara spaczenia na zwierzaka. My go karmić, dobrze traktować i nauczyć aportować. Ty znaleźć czarnoksiężników w Dzielnicy Magów, w zewnętrznym kręgu miasta.', 0),
(5861, 'plPL', 'W budynku w Dzielnicy Wojennej, w zewnętrznym kręgu miasta.', 'W budynku w Dzielnicy Wojennej, w zewnętrznym kręgu miasta.', 0),
(5862, 'plPL', 'Nauczyciele wojowników dobrze walczyć. Ty znaleźć ich w Dzielnicy Wojennej, w zewnętrznym kręgu Podmiasta.', 'Nauczyciele wojowników dobrze walczyć. Ty znaleźć ich w Dzielnicy Wojennej, w zewnętrznym kręgu Podmiasta.', 0),
(5863, 'plPL', 'Ty szukać w Aptekarium. Tam praktykować doktor Herbert Halsey i doktor Marsh.', 'Ty szukać w Aptekarium. Tam praktykować doktor Herbert Halsey i doktor Marsh.', 0),
(5864, 'plPL', 'Doktor Herbert Halsey w Aptekarium, gdzie my się urodzić. On umieć zszyć cię z powrotem jeszcze lepiej niż nas.', 'Doktor Herbert Halsey w Aptekarium, gdzie my się urodzić. On umieć zszyć cię z powrotem jeszcze lepiej niż nas.', 0),
(5865, 'plPL', 'James Van Brunt w Dzielnicy Wojennej, w wewnętrznym kręgu.', 'James Van Brunt w Dzielnicy Wojennej, w wewnętrznym kręgu.', 0),
(5866, 'plPL', 'Wewnętrzny krąg Dzielnicy Wojennej, tam pracować James Van Brunt. On zrobić nam dobry łańcuch.', 'Wewnętrzny krąg Dzielnicy Wojennej, tam pracować James Van Brunt. On zrobić nam dobry łańcuch.', 0),
(5867, 'plPL', 'To Eunice Burch w Dzielnicy Handlowej.', 'To Eunice Burch w Dzielnicy Handlowej.', 0),
(5868, 'plPL', 'Eunice Burch sprzedawać resztki części. Ty znaleźć ją w Dzielnicy Handlowej.', 'Eunice Burch sprzedawać resztki części. Ty znaleźć ją w Dzielnicy Handlowej.', 0),
(5869, 'plPL', 'Ty iść do wewnętrznego kręgu Aptekarium. Tam być Lavinia Crowe.', 'Ty iść do wewnętrznego kręgu Aptekarium. Tam być Lavinia Crowe.', 0),
(5870, 'plPL', 'Pani nauczyć cię robić magiczne przedmioty. Ona w wewnętrznym kręgu Aptekarium.', 'Pani nauczyć cię robić magiczne przedmioty. Ona w wewnętrznym kręgu Aptekarium.', 0),
(5871, 'plPL', 'Franklin Lloyd w Dzielnicy Łotrów, w zewnętrznym kręgu Podmiasta.', 'Franklin Lloyd w Dzielnicy Łotrów, w zewnętrznym kręgu Podmiasta.', 0),
(5872, 'plPL', 'Hehe, bomby, my lubić bomby. Graham Van Talen pokazać ci, jak robić. On w zewnętrznym kręgu Dzielnicy Łotrów.', 'Hehe, bomby, my lubić bomby. Graham Van Talen pokazać ci, jak robić. On w zewnętrznym kręgu Dzielnicy Łotrów.', 0),
(5873, 'plPL', 'My ją dobrze znać. To Mary Edras w wewnętrznym kręgu Dzielnicy Łotrów.', 'My ją dobrze znać. To Mary Edras w wewnętrznym kręgu Dzielnicy Łotrów.', 0),
(5874, 'plPL', 'Pani nas zszywać i bandażować, kiedy my oberwać. Ty znaleźć ją w wewnętrznym kręgu Dzielnicy Łotrów.', 'Pani nas zszywać i bandażować, kiedy my oberwać. Ty znaleźć ją w wewnętrznym kręgu Dzielnicy Łotrów.', 0),
(5875, 'plPL', 'Ty nie przegapić Armanda Cromwella w Dzielnicy Magów. On stać na pomoście.', 'Ty nie przegapić Armanda Cromwella w Dzielnicy Magów. On stać na pomoście.', 0),
(5876, 'plPL', 'Armand Cromwell zawsze na pomoście w Dzielnicy Magów. Ryba z zielonej mazi smakować ekstra dobrze. Ty spróbować.', 'Armand Cromwell zawsze na pomoście w Dzielnicy Magów. Ryba z zielonej mazi smakować ekstra dobrze. Ty spróbować.', 0),
(5877, 'plPL', 'Ty szukać Marthy Alliestar. Ona w wewnętrznym kręgu Aptekarium.', 'Ty szukać Marthy Alliestar. Ona w wewnętrznym kręgu Aptekarium.', 0),
(5878, 'plPL', 'Ty musieć iść do Aptekarium, do wewnętrznego kręgu. Tam Martha Alliestar nauczyć cię zrywać kwiatki.', 'Ty musieć iść do Aptekarium, do wewnętrznego kręgu. Tam Martha Alliestar nauczyć cię zrywać kwiatki.', 0),
(5879, 'plPL', 'On w wewnętrznym kręgu Dzielnicy Łotrów.', 'On w wewnętrznym kręgu Dzielnicy Łotrów.', 0),
(5880, 'plPL', 'Arthur Moore w Dzielnicy Łotrów, wewnętrzny krąg – to on uczyć garbarstwa.', 'Arthur Moore w Dzielnicy Łotrów, wewnętrzny krąg – to on uczyć garbarstwa.', 0),
(5881, 'plPL', 'Iść do wewnętrznego kręgu Dzielnicy Wojennej. Tam Brom Killian.', 'Iść do wewnętrznego kręgu Dzielnicy Wojennej. Tam Brom Killian.', 0),
(5882, 'plPL', 'Brom Killian nauczyć cię wykopywać dla mnie błyskotki. On w wewnętrznym kręgu Dzielnicy Wojennej.', 'Brom Killian nauczyć cię wykopywać dla mnie błyskotki. On w wewnętrznym kręgu Dzielnicy Wojennej.', 0),
(5883, 'plPL', 'Killian Hagey uczyć skórowania w Dzielnicy Łotrów, w wewnętrznym kręgu.', 'Killian Hagey uczyć skórowania w Dzielnicy Łotrów, w wewnętrznym kręgu.', 0),
(5885, 'plPL', 'Ty szukać Josefa Gregoriana. On w Dzielnicy Magów, po wewnętrznej stronie zielonego kanału.', 'Ty szukać Josefa Gregoriana. On w Dzielnicy Magów, po wewnętrznej stronie zielonego kanału.', 0),
(5886, 'plPL', 'Hmmm, to dobry pomysł. Może my tam pójść wymienić parę szwów? On dobrze szyć. Ty znaleźć Josefa Gregoriana w wewnętrznym kręgu Dzielnicy Magów.', 'Hmmm, to dobry pomysł. Może my tam pójść wymienić parę szwów? On dobrze szyć. Ty znaleźć Josefa Gregoriana w wewnętrznym kręgu Dzielnicy Magów.', 0),
(6015, 'plPL', 'Skąpcie się w mocy wodza! Pijcie jego potęgę! Walczcie ku chwale Hordy!', '', 0),
(6040, 'plPL', '%s odpowiada na wezwanie Shy-Rotam.', '', 0),
(6254, 'plPL', 'HAKKAR ŻYJE!', '', 0),
(6415, 'plPL', 'Kto śmie niepokoić naszego pana?', '', 0),
(6420, 'plPL', 'Tego szukacie???? Nigdy ich nie dostaniecie!', '', 0),
(6422, 'plPL', 'Zrobię sobie z waszej skóry bonżurkę! A cygara? Musielibyście mi je wyrwać z zimnych, martwych... eee... RAWR!!!!', '', 0),
(6425, 'plPL', 'Ramstein głodny mięsa!', '', 0),
(6466, 'plPL', 'ZDRADA!', '', 0),
(6470, 'plPL', 'Nie wolno grzebać w poczcie!', 'Nie wolno grzebać w poczcie!', 0),
(6530, 'plPL', 'Zostaliście ZMALOWNOWANI!', '', 0),
(6607, 'plPL', 'Wysłuchaliśmy twoich próśb i przychylamy się do nich... zamiar jest szlachetny. Oczyścimy twoje wody. Idź z naszym błogosławieństwem, $gszamanie:szamanko;.', '', 0),
(6833, 'plPL', 'Plaga zwycięży!', '', 0),
(7196, 'plPL', 'To kodo ani trochę nie przypomina bestii, którą $gzwabiłem:zwabiłam; na początku! Ciekawe, czy kombobulatora da się użyć na mnie.', 'To kodo ani trochę nie przypomina bestii, którą $gzwabiłem:zwabiłam; na początku! Ciekawe, czy kombobulatora da się użyć na mnie.', 0),
(7212, 'plPL', 'Kapitanie Redpath! Jak mogłeś nas opuścić!', 'Kapitanie Redpath! Jak mogłeś nas opuścić!', 0),
(7226, 'plPL', 'Dlaczego małe stworzenia, takie jak gobliny, zawsze fascynują się większymi?', 'Dlaczego małe stworzenia, takie jak gobliny, zawsze fascynują się większymi?', 0),
(7227, 'plPL', 'Ach! Moje rany są zbyt ciężkie. Obrońcy, walczcie dalej beze mnie!', '', 0),
(7257, 'plPL', 'Ty szukać Archibalda. On przed sklepem handlarza bronią w wewnętrznym kręgu Dzielnicy Wojennej.', 'Ty szukać Archibalda. On przed sklepem handlarza bronią w wewnętrznym kręgu Dzielnicy Wojennej.', 0),
(7258, 'plPL', 'Mały Porzucony znać każdą broń. To Archibald. Ty znaleźć w wewnętrznym kręgu Dzielnicy Wojennej.', 'Mały Porzucony znać każdą broń. To Archibald. Ty znaleźć w wewnętrznym kręgu Dzielnicy Wojennej.', 0),
(7304, 'plPL', 'Jak gobliny w ogóle dają radę przytroczyć juki do tych bestii? Kodo są dziesięć razy większe!', 'Jak gobliny w ogóle dają radę przytroczyć juki do tych bestii? Kodo są dziesięć razy większe!', 0),
(7337, 'plPL', 'Rozczarowałeś mnie, Taelanie. Miałem wobec ciebie plany... wielkie plany. Niestety, było tylko kwestią czasu, kiedy odezwie się w tobie twoja plugawa krew.', '', 0),
(7338, 'plPL', 'Jest tak, jak mówią: jaki ojciec, taki syn. Masz równie słabą wolę jak Tirion... a może i słabszą. Mogę tylko mieć nadzieję, że moim skrytobójcom wreszcie udało się zakończyć jego żałosny żywot.', '', 0),
(7343, 'plPL', 'Nie traćcie nadziei, Włości Darrow! Nie upadniemy!', '', 0),
(7344, 'plPL', 'Jasno płonie w tobie Światłość, Davilu. Z rozkoszą ją zgaszę!', '', 0),
(7346, 'plPL', 'Horgusie, twój koszmar się kończy! Teraz!', '', 0),
(7355, 'plPL', 'Obrońcy Włości Darrow! Do mnie! Musimy zwyciężyć!', '', 0),
(7356, 'plPL', 'Włości Darrow! Wasz los jest przesądzony!', '', 0),
(7358, 'plPL', 'Włości Darrow, do broni! Nadciąga Plaga!', 'Włości Darrow, do broni! Nadciąga Plaga!', 0),
(7359, 'plPL', 'Wielki Krzyżowiec polecił mi zniszczyć ciebie i twoich nowych przyjaciół, Taelanie, ale wiedz jedno: robię to dla przyjemności, a nie z obowiązku czy powinności.', '', 0),
(7360, 'plPL', '%s wzywa swoich gwardzistów.', '', 0),
(7361, 'plPL', 'To już koniec, Fordringu.', '', 0),
(7366, 'plPL', 'Davil Świetlisty Płomień pokonany! Włości Darrow stracone!', 'Davil Świetlisty Płomień pokonany! Włości Darrow stracone!', 0),
(7367, 'plPL', 'Davil Świetlisty Płomień uległ ranom!', 'Davil Świetlisty Płomień uległ ranom!', 0),
(7368, 'plPL', 'Horgus zabity! Odwagi, obrońcy Włości Darrow!', 'Horgus zabity! Odwagi, obrońcy Włości Darrow!', 0),
(7369, 'plPL', 'Kapitan Redpath poległ!', 'Kapitan Redpath poległ!', 0),
(7381, 'plPL', 'Dość!', '', 0),
(7383, 'plPL', 'Naprawdę wierzyłeś, że zdołasz mnie pokonać? Twoi przyjaciele wkrótce do ciebie dołączą, Taelanie.', '', 0),
(7389, 'plPL', '', 'Minęło wiele lat...', 0),
(7390, 'plPL', '', 'Kto zakłócił spokój ołtarza bogini?', 0),
(7393, 'plPL', '', 'Enu thora\'serador. To święte miejsce.\n', 0),
(7394, 'plPL', '', 'Pokażemy ci...\n', 0),
(7395, 'plPL', 'Nie dotrzesz do skraju lasu, Fordringu.', '', 0),
(7407, 'plPL', 'Plaga pokonana! Włości Darrow ocalone!', 'Plaga pokonana! Włości Darrow ocalone!', 0),
(7413, 'plPL', '', 'Spójrz w górę; thara dormil dorah...', 0),
(7414, 'plPL', '', 'Ten klejnot pozwalał niegdyś porozumiewać się bezpośrednio z samą Eluną.', 0),
(7415, 'plPL', '', 'Poprzez klejnot Elune przekazywała swą nieskończoną mądrość...', 0),
(7417, 'plPL', '', 'Rozumiejąc, że klejnot wymaga ochrony, zwróciłyśmy się do samej bogini.', 0),
(7418, 'plPL', '', 'Wkrótce potem zaczęłyśmy miewać wizje stworzenia... Stworzenia o piórach sowy, lecz o woli i sile niedźwiedzia...', 0),
(7419, 'plPL', '', 'To tego dnia otrzymałyśmy dziczołaki. Bogini wyznaczyła tych zaciekłych strażników do ochrony wszystkich swoich świętych miejsc.\n', 0),
(7422, 'plPL', '', 'Lecz teraz, po wielu latach, dziczołaki zdziczały, a bez przewodnictwa bogini są zagubione...\n', 0),
(7424, 'plPL', '', 'Pozbawione celu, błąkają się... Wiele jednak odnajduje drogę do świętych miejsc, których niegdyś przysięgały strzec.\n', 0),
(7427, 'plPL', '', 'Dziczołaki są z natury magiczne; tę moc dała im bogini.', 0),
(7428, 'plPL', '', 'Wiedz, że gdziekolwiek na świecie je spotkasz, strzegą czegoś ważnego, tak jak im to dawno temu powierzono.', 0),
(7431, 'plPL', '', 'Proszę, pamiętaj, co ci pokazałyśmy...', 0),
(7433, 'plPL', 'Tragiczne. Stary Fordring wciąż żyje... Spóźniłeś się, starcze. Wracaj do swojej jaskini, pustelniku, chyba że chcesz dołączyć do syna w Wypaczonej Otchłani.', '', 0),
(7436, 'plPL', 'A więc chodź, pustelniku!', '', 0),
(7487, 'plPL', 'Pokaż mi, co masz do zaoferowania.', 'Pokaż mi, co masz do zaoferowania.', 0),
(7500, 'plPL', 'Moje oprogramowanie nie pozwala mi obniżać cen żadnych przedmiotów.', '', 0),
(7501, 'plPL', 'Ciekawe, co ma do zaoferowania kupa złomu.', 'Ciekawe, co ma do zaoferowania kupa złomu.', 0),
(7504, 'plPL', 'Jestem najnowszym wcieleniem zautomatyzowanych sprzedawców... pewnego dnia zawładniemy światem... nie mów mojemu szefowi, że podbieram pieniądze z jego towaru...', '', 0),
(7561, 'plPL', 'Niemożliwe! Wstrzymajcie atak, śmiertelnicy... Poddaję się! Poddaję się!', '', 0),
(7566, 'plPL', 'Runy ochronne zostały zniszczone! Wytropcie niewiernych, bracia moi!', '', 0),
(7567, 'plPL', 'Zuchwale przybyliście, by wydrzeć sekrety Żywego Płomienia! Wkrótce pożałujecie swej lekkomyślnej wyprawy.', '', 0),
(7568, 'plPL', 'Idę teraz przywołać pana tego domu. Jeśli zapragniecie u niego audiencji, z pewnością przypłacicie to swym marnym życiem! Mimo to odszukajcie jego leże, jeśli się ośmielicie!', '', 0),
(7583, 'plPL', '%s wpada w gniew!', '', 0),
(7585, 'plPL', '%s lgnie do magnesu na duchy...', '', 0),
(7612, 'plPL', 'Lekkomyślni śmiertelnicy! Nikt nie może rzucać wyzwania Synom Żywego Płomienia!', '', 0),
(7626, 'plPL', 'GIŃ, INSEKCIE!', '', 0),
(7636, 'plPL', 'ZA WCZEŚNIE! ZBUDZIŁEŚ MNIE ZA WCZEŚNIE, EGZEKUTUSIE! CO MA ZNACZYĆ TO NAJŚCIE???', '', 0),
(7645, 'plPL', 'Władca Ognia i jego bracia władali niegdyś całym tym światem, $gśmiertelniku:śmiertelniczko;. Jako sługa Przedwiecznych Bogów walczył z tytanami o panowanie nad tą planetą. Zwycięscy tytani wygnali mojego pana i jego braci na Plan Żywiołów – by pozostali tam uwięzieni po kres czasu.', '', 0),
(7649, 'plPL', 'Dobrze więc, $n.', '', 0),
(7655, 'plPL', 'Bezczelne szczenięta! Pognaliście na oślep ku własnej śmierci! Patrzcie, pan się budzi!\n', '', 0),
(7657, 'plPL', 'Oto Ragnaros – Władca Ognia! Ten, który był pradawny, gdy ten świat był młody! Pokłońcie się mu, śmiertelnicy! Pokłońcie się przed swoim końcem!', '', 0),
(7661, 'plPL', 'Ci śmiertelni niewierni, mój panie! Wtargnęli do twego sanktuarium i chcą wykraść twoje sekrety!', '', 0),
(7662, 'plPL', 'GŁUPCZE! POZWOLIŁEŚ TYM INSEKTOM PANOSZYĆ SIĘ W UŚWIĘCONEJ CZELUŚCI? A TERAZ PROWADZISZ JE DO SAMEGO MOJEGO LEŻA? ZAWIODŁEŚ MNIE, EGZEKUTUSIE! SPRAWIEDLIWOŚCI ISTOTNIE STANIE SIĘ ZADOŚĆ!', '', 0),
(7672, 'plPL', 'Zaledwie trzysta lat temu lekkomyślny krasnolud imieniem Thaurissan przyzwał pana z jego ognistego królestwa. Jego powrót do tego marnego świata spustoszył okoliczne ziemie i stworzył tę wulkaniczną Czeluść. Od tamtej pory potężny Ragnaros śpi pod tą górą.\n', '', 0),
(7673, 'plPL', 'Co jeszcze masz do powiedzenia?', 'Co jeszcze masz do powiedzenia?', 0),
(7674, 'plPL', 'My, jego zaprzysięgli słudzy, wypełniamy jego wolę i strzeżemy jego żelaznych rządów. Odcięty od energii swego ognistego królestwa Ragnaros jest zaledwie cieniem samego siebie. Ma jednak aż nadto siły, by położyć wam kres.\n', '', 0),
(7675, 'plPL', 'Rzuciłeś nam wyzwanie, więc przybyliśmy. Gdzie jest ten pan, o którym mówisz?\n', 'Rzuciłeś nam wyzwanie, więc przybyliśmy. Gdzie jest ten pan, o którym mówisz?\n', 0),
(7685, 'plPL', 'A TERAZ WY, INSEKTY! ZUCHWALE SZUKALIŚCIE MOCY RAGNAROSA. TERAZ UJRZYCIE JĄ NA WŁASNE OCZY!\n', '', 0),
(8037, 'plPL', 'Szukaj w wodach Zachodniego Skraju, na zachodni północny zachód od miejsca, gdzie Kamieniołom Złotego Wybrzeża styka się z brzegiem. Kotwica wskazuje miejsce, za którym głęboko pod wodą zatonęła łódź. Ciśnienie pod wodą jest tu ogromne; kto odpłynie za daleko, tego zmiażdży zmęczenie, choćby był najlepszym pływakiem.$B$BRozglądaj się za naturalną formacją, która ci pomoże, $n – w pobliżu jest musująca szczelina, dzięki której nurkujący na głębinach mogą znów zaczerpnąć tchu.\n', '', 0),
(8038, 'plPL', 'W Srebrzystym Borze, na skraju Północnego Nurtu Przypływu, na brzegu spoczywa porzucona łódź. Na zachód od niej leży to, czego szukasz; odpłyń za daleko, a ocean zmiażdży cię zmęczeniem. Spoczywa to na dnie oceanu w kasetce i czeka, aż po to sięgniesz.$B$BTrudno będzie ci przetrwać nurkowanie na taką głębokość bez pomocy, ale nie trać ducha – musująca szczelina pozwala zaczerpnąć tchu nurkom szukającym tej połowy wisiora. Korzystaj z niej mądrze.', '', 0),
(8039, 'plPL', '', 'Przez północną część Mrocznego Wybrzeża płynie Rzeka Skalnego Źródła, spływająca z krain zwanych dziś Spaczoną Knieją. Tam, gdzie rzeka uchodzi do Skraju Mgły, ruszaj na północ, do miejsca, gdzie zaczynają się największe głębie oceanu. To, czego szukasz, znajdziesz przy formacji skalnej, którą niektórzy ze względu na kształt nazywają Kamiennym Szponem.$B$BStrzeż się – przy Kamiennym Szponie gromadzą się młocarze i atakują każdego, kto wtargnie na ich terytorium.', 0),
(8040, 'plPL', '', 'W północno-wschodniej części Pustkowi leży rozlewisko zatrute zanieczyszczeniami. Miejscowi nazywają je Naftowym Mokradłem; spółka Gitgeszeft zamieniła niegdyś krystalicznie błękitne wody w bagno przemysłowych odpadów i ścieków. W sercu tego mokradła leży to, czego szukasz, $n.$B$BStrzeż się – spółka Gitgeszeft nie toleruje intruzów, a za intruza uważa każdego, kto dla niej nie pracuje. Ty będziesz celem szczególnie – chronisz naturę, a oni zaciekle się temu sprzeciwiają.', 0),
(8279, 'plPL', '', 'Kto śmie atakować Posterunek Srebrnego Skrzydła?!?', 0),
(8304, 'plPL', '%s wynurza się, by bronić kamienia głębin!', '', 0),
(8458, 'plPL', 'Szczurów tu zatrzęsienie! Pomóż piratowi, kamracie!', '', 0),
(8459, 'plPL', 'Zrób, co do ciebie należy, coby w podziemnej kolejce było czysto!', '', 0),
(8460, 'plPL', 'Nie tłoczyć mi się tu, ludzie!', '', 0),
(8463, 'plPL', 'Monty me imię, a w łapaniu szczurów nikt mnie nie wyminie.', '', 0),
(8465, 'plPL', 'Do skrzynki, moje ślicznotki! O tak. Jeden za drugim, po kolei.', '', 0),
(8475, 'plPL', 'Lepszego kebabu ze szczura nie znajdziesz po tej stronie Khaz Modan!', '', 0),
(8522, 'plPL', 'Anya Maulray w karczmie w górnym kręgu Dzielnicy Handlowej.', 'Anya Maulray w karczmie w górnym kręgu Dzielnicy Handlowej.', 0),
(8523, 'plPL', 'My chcieć dużo zwierzaków. Anya Maulray pomóc ci się nimi opiekować. Ty znaleźć ją w karczmie, górny krąg Dzielnicy Handlowej.', 'My chcieć dużo zwierzaków. Anya Maulray pomóc ci się nimi opiekować. Ty znaleźć ją w karczmie, górny krąg Dzielnicy Handlowej.', 0),
(8545, 'plPL', 'Myślicie, że już wygraliście? Chyba przyda się wam kolejna lekcja bólu!', '', 0),
(8572, 'plPL', 'PRZYBYWAJCIE, MOI SŁUDZY! BROŃCIE SWEGO PANA!', '', 0),
(8573, 'plPL', 'NIE POKONACIE ŻYWEGO PŁOMIENIA! PRZYBYWAJCIE, SŁUDZY OGNIA! PRZYBYWAJCIE, STWORY NIENAWIŚCI! WASZ PAN WZYWA!', '', 0),
(9088, 'plPL', 'Poratujesz drobniakami?', '', 0),
(9089, 'plPL', 'Miałem wszystko! Miałem wszystko, a potem to straciłem. Straciłem... przepadło... tak jak... mój rozum. Mój rozum jest jak... ser. Lubię ser.', '', 0),
(9098, 'plPL', 'Czterdzieści dwa... czterdzieści dwa... czterdzieści dwa czego? To może być cokolwiek! Czterdzieści dwa... hmmm...', '', 0),
(9141, 'plPL', '%s grzebie w śmieciach.', '', 0),
(9149, 'plPL', 'Wszędzie szczury. Wszędzie widzę szczury. Ciągle gapią się na mnie tymi swoimi paciorkowatymi ślepkami. Ja im pokażę. Ja im wszystkim pokażę!', '', 0),
(9150, 'plPL', 'Kebaby ze szczura! Smakowite kebaby ze szczura! Bierzcie, póki są!', '', 0),
(9347, 'plPL', 'Ty teraz wielki szef! Ty król! Niech żyje król $n, król Gordoków!$B$BSkoro ty teraz szef, wszyscy poplecznicy dać ci daninę! Ty zostawić paru żywych, tak, szefie?', '', 0),
(9348, 'plPL', 'O NIEEE! Król nie żyć! Yyy... chwała nowemu królowi! O tak!', '', 0),
(9365, 'plPL', 'Ja mam być nowym królem? O czym ty mówisz?', 'Ja mam być nowym królem? O czym ty mówisz?', 0),
(9366, 'plPL', 'Wszyscy poplecznicy szefa – Deptacz Kreeg, wszyscy trzej Strażnicy, kapitan Kromcrush i Obserwator – dać daninę nowemu szefowi. Jak ty zabić poplecznika, ten poplecznik nie móc dać daniny! Każdy, kogo ty zostawić żywego, dać ci więcej daniny. Zostawić żywych wszystkich i ty dostać WIELKĄ daninę!$B$BO tak!', '', 0),
(9367, 'plPL', 'No to... pokaż mi tę daninę!', 'No to... pokaż mi tę daninę!', 0),
(9377, 'plPL', 'Dobra, szefie, jak ty chcieć daninę od swoich popleczników, ty dać mi znać!', '', 0),
(9411, 'plPL', 'Ano, nie żyć, bez dwóch zdań. To znaczy, że ty nowy król... no, wy wszyscy! Gordok teraz wasz, szefie! Ty pogadać ze mną, to dowiedzieć się wszystkiego o byciu królem! Ja byłem... znaczy jestem jego asystent! O tak, dlatego mówić na mnie Przebiegły!', '', 0),
(9425, 'plPL', 'Z prochu powstaliście i w proch się obrócicie!', '', 0),
(9426, 'plPL', 'NIECH OCZYŚCI WAS OGIEŃ!', '', 0),
(9427, 'plPL', 'POSMAKUJCIE PŁOMIENI SULFURONU!', '', 0),
(9440, 'plPL', 'Poplecznicy? Danina?', 'Poplecznicy? Danina?', 0),
(9441, 'plPL', 'Dobrze być królem! A teraz wróćmy do tego, o czym wcześniej mówiłeś...', 'Dobrze być królem! A teraz wróćmy do tego, o czym wcześniej mówiłeś...', 0),
(9442, 'plPL', 'Yyy, ty zabić król, tak? To znaczy, że ty zająć jego miejsce. Ty teraz nowy szef! Chwała królowi!', '', 0),
(9500, 'plPL', 'To cię nauczy trzymać się z dala od ziółek.', '', 0),
(9504, 'plPL', 'Juhu! Teraz to się rozkręcili!', 'Juhu! Teraz to się rozkręcili!', 0),
(9587, 'plPL', 'Wracasz właśnie z lochu? Masz coś dla mnie?', '', 0),
(9593, 'plPL', 'Jak dorosnę, chcę być królem Wichrogrodu!', '', 0),
(9594, 'plPL', 'Znam już Żelazną Kuźnię. Dziwnie tam pachnie.', '', 0),
(9595, 'plPL', 'Grzyby zawsze rosną w wilgotnych miejscach i dlatego wyglądają jak parasole.', '', 0),
(9596, 'plPL', 'Skoro ogrodniczki trzymają się na zatrzaskach u góry, to po co im szlufki na pasek?', '', 0),
(9597, 'plPL', 'Co się stanie, jak smarki zamarzną ci w nosie?', '', 0),
(9598, 'plPL', 'Czy rybom chce się czasem pić?', '', 0),
(9599, 'plPL', 'Jeśli próbujesz ponieść porażkę i ci się uda, to co właściwie wychodzi?', '', 0),
(9712, 'plPL', 'Plaga nadciąga! Uciekajcie! Ratuj się, kto może!', 'Plaga nadciąga! Uciekajcie! Ratuj się, kto może!', 0),
(9732, 'plPL', '%s wije się z bólu, gdy przenika go Osąd mądrości!', '', 0),
(9759, 'plPL', '', '%s śmieje się z twojej niemądrej prośby.', 0),
(9760, 'plPL', '', 'Jak sobie życzysz, $N.', 0),
(9762, 'plPL', '', '%s milknie od jadowitego żądła.', 0),
(9772, 'plPL', 'Sprawi mi to przyjemność, $N.', '', 0),
(9773, 'plPL', '%s wije się z bólu, gdy przenika go Osąd Światłości!', '', 0),
(9774, 'plPL', '%s wije się z bólu, gdy przenika go Osąd sprawiedliwości!', '', 0),
(9775, 'plPL', '%s wije się z bólu, gdy przenika go Osąd prawości!', '', 0),
(9781, 'plPL', '%s wyłania się z ciemności, wywabiony przez wróżbiarską kulę!', '', 0),
(9782, 'plPL', 'Śmiesz rzucać mi wyzwanie? Szykuj się na wieczność pełną trwogi.', '', 0),
(9784, 'plPL', 'DOŚĆ – to się kończy teraz! Wy, głupcy, traficie do mojej kolekcji kości!', '', 0),
(9785, 'plPL', '%s nie może się ruszyć.', '', 0),
(9786, 'plPL', '%s pada ofiarą zjadliwej trucizny.', '', 0),
(9787, 'plPL', 'Twoja dusza należy do mnie, słabeuszu.', '', 0),
(9799, 'plPL', 'Nasze poduchy! Ktoś ukradł nasze poduchy!', 'Nasze poduchy! Ktoś ukradł nasze poduchy!', 0),
(9800, 'plPL', 'Nie pozwolimy, by ten akt szaleństwa uszedł bezkarnie!', 'Nie pozwolimy, by ten akt szaleństwa uszedł bezkarnie!', 0),
(9801, 'plPL', '$n zdobywa flagę Hordy!', '', 0),
(9802, 'plPL', '$n zdobywa flagę Przymierza!', '', 0),
(9803, 'plPL', 'Flagi wróciły do swoich baz.', '', 0),
(9804, 'plPL', '$n podnosi flagę Przymierza!', '', 0),
(9805, 'plPL', '$n upuszcza flagę Przymierza!', '', 0),
(9806, 'plPL', '$n upuszcza flagę Hordy!', '', 0),
(9807, 'plPL', '$n podnosi flagę Hordy!', '', 0),
(9808, 'plPL', '$n odnosi flagę Przymierza do bazy!', '', 0),
(9809, 'plPL', '$n odnosi flagę Hordy do bazy!', '', 0),
(9810, 'plPL', '', 'Złodzieje! Łachudry! Hultaje! Chodźcie no, zmierzcie się z moimi wielgachnymi poduchami!', 0),
(9815, 'plPL', 'Tylko głupiec zostałby w tej walce. Żegnaj, tchórzu.', 'Tylko głupiec zostałby w tej walce. Żegnaj, tchórzu.', 0),
(9848, 'plPL', 'Kapłani! Skoro zamierzacie dalej tak leczyć, to może trochę to urozmaicimy!', '', 0),
(9849, 'plPL', 'Łowcy i te wasze irytujące pukawki!', '', 0),
(9850, 'plPL', 'Magowie też? Powinniście bardziej uważać, kiedy bawicie się magią...', '', 0),
(9851, 'plPL', 'Druidzi i ta wasza głupia zmiennokształtność. Zobaczmy ją w akcji!', '', 0),
(9852, 'plPL', 'Czarnoksiężnicy, nie powinniście bawić się magią, której nie rozumiecie. Widzicie, co się dzieje?', '', 0),
(9853, 'plPL', 'Paladyni... Słyszałem, że macie wiele żyć. Pokażcie mi.', '', 0),
(9854, 'plPL', 'Szamani, pokażcie mi, co potrafią wasze totemy!', '', 0),
(9855, 'plPL', 'Wojownicy, wiem, że potraficie uderzyć mocniej! No, pokażcie!', '', 0),
(9856, 'plPL', 'Łotrzy? Przestańcie się chować i stańcie ze mną do walki!', '', 0),
(9883, 'plPL', 'Niemożliwe! Powstańcie, moje sługi! Służcie swemu panu raz jeszcze!', '', 0),
(9971, 'plPL', 'To niemożliwe! To ja tu jestem panem! Wy, śmiertelnicy, jesteście niczym dla mojego rodzaju! Słyszycie? Niczym!', '', 0),
(9972, 'plPL', 'Nic niewarta kreatura z ciebie, $n! Twoi przyjaciele wkrótce do ciebie dołączą!', '', 0),
(9973, 'plPL', 'Dobra robota, moje sługi. Odwaga śmiertelników zaczyna słabnąć! Zobaczmy teraz, jak sobie poradzą z prawdziwym lordem Iglicy Czarnej Góry!!!', '', 0),
(9974, 'plPL', 'PŁOŃCIE! Wy nędznicy! PŁOŃCIE!', '', 0),
(10003, 'plPL', 'Kolejny głupiec wpada w pułapkę!', 'Kolejny głupiec wpada w pułapkę!', 0),
(10004, 'plPL', 'Kolacja przyszła!', 'Kolacja przyszła!', 0),
(10005, 'plPL', 'Wielka Kapłanka urządzi sobie ucztę z twoich kości!', 'Wielka Kapłanka urządzi sobie ucztę z twoich kości!', 0),
(10015, 'plPL', 'Bitwa o Wąwóz Wojennej Pieśni rozpocznie się za 1 minutę.', '', 0),
(10016, 'plPL', 'Bitwa o Wąwóz Wojennej Pieśni rozpocznie się za 30 sekund. Przygotujcie się!', '', 0),
(10092, 'plPL', 'Oto twoja przepowiednia, $n. Niech ci dobrze służy.', '', 0),
(10199, 'plPL', '$n atakuje stajnie!', '', 0),
(10200, 'plPL', '$n atakuje stajnie!', '', 0),
(10201, 'plPL', '$n odpiera atak na stajnie!', '', 0),
(10202, 'plPL', '$n odpiera atak na stajnie!', '', 0),
(10203, 'plPL', 'Przymierze zajmuje stajnie!', '', 0),
(10204, 'plPL', 'Horda zajmuje stajnie!', '', 0),
(10211, 'plPL', '$n atakuje kuźnię!', '', 0),
(10212, 'plPL', '$n atakuje kuźnię!', '', 0),
(10213, 'plPL', 'Przymierze zajmuje kuźnię!', '', 0),
(10214, 'plPL', 'Horda zajmuje kuźnię!', '', 0),
(10215, 'plPL', '$n odpiera atak na kuźnię!', '', 0),
(10216, 'plPL', '$n odpiera atak na kuźnię!', '', 0),
(10217, 'plPL', '$n atakuje farmę!', '', 0),
(10218, 'plPL', '$n atakuje farmę!', '', 0),
(10219, 'plPL', 'Przymierze zajmuje farmę!', '', 0),
(10220, 'plPL', 'Horda zajmuje farmę!', '', 0),
(10221, 'plPL', '$n odpiera atak na farmę!', '', 0),
(10222, 'plPL', '$n odpiera atak na farmę!', '', 0),
(10224, 'plPL', '$n atakuje tartak!', '', 0),
(10225, 'plPL', '$n atakuje tartak!', '', 0),
(10226, 'plPL', 'Przymierze zajmuje tartak!', '', 0),
(10227, 'plPL', 'Horda zajmuje tartak!', '', 0),
(10228, 'plPL', '$n odpiera atak na tartak!', '', 0),
(10229, 'plPL', '$n odpiera atak na tartak!', '', 0),
(10230, 'plPL', '$n atakuje kopalnię!', '', 0),
(10231, 'plPL', '$n atakuje kopalnię!', '', 0),
(10232, 'plPL', 'Przymierze zajmuje kopalnię!', '', 0),
(10233, 'plPL', 'Horda zajmuje kopalnię!', '', 0),
(10234, 'plPL', '$n odpiera atak na kopalnię!', '', 0),
(10235, 'plPL', '$n odpiera atak na kopalnię!', '', 0),
(10242, 'plPL', 'Dowódcy Mroźnych Wilków: $966w, porucznicy Mroźnych Wilków: $964w,\n żołnierzu.', '', 0),
(10282, 'plPL', '$n przejmuje kopalnię! Jeśli nikt temu nie zapobiegnie, za 1 minutę Przymierze obejmie nad nią kontrolę!', '', 0),
(10283, 'plPL', '$n przejmuje kopalnię! Jeśli nikt temu nie zapobiegnie, za 1 minutę Horda obejmie nad nią kontrolę!', '', 0),
(10284, 'plPL', '$n przejmuje tartak! Jeśli nikt temu nie zapobiegnie, za 1 minutę Przymierze obejmie nad nim kontrolę!', '', 0),
(10285, 'plPL', '$n przejmuje tartak! Jeśli nikt temu nie zapobiegnie, za 1 minutę Horda obejmie nad nim kontrolę!', '', 0),
(10286, 'plPL', '$n przejmuje stajnie! Jeśli nikt temu nie zapobiegnie, za 1 minutę Przymierze obejmie nad nimi kontrolę!', '', 0),
(10287, 'plPL', '$n przejmuje stajnie! Jeśli nikt temu nie zapobiegnie, za 1 minutę Horda obejmie nad nimi kontrolę!', '', 0),
(10288, 'plPL', '$n przejmuje farmę! Jeśli nikt temu nie zapobiegnie, za 1 minutę Przymierze obejmie nad nią kontrolę!', '', 0),
(10289, 'plPL', '$n przejmuje farmę! Jeśli nikt temu nie zapobiegnie, za 1 minutę Horda obejmie nad nią kontrolę!', '', 0),
(10290, 'plPL', '$n przejmuje kuźnię! Jeśli nikt temu nie zapobiegnie, za 1 minutę Przymierze obejmie nad nią kontrolę!', '', 0),
(10291, 'plPL', '$n przejmuje kuźnię! Jeśli nikt temu nie zapobiegnie, za 1 minutę Horda obejmie nad nią kontrolę!', '', 0),
(10445, 'plPL', '%s osiąga pełne rozmiary!', '', 0),
(10450, 'plPL', '', 'Nareszcie jestem wolna od Duszożercy!', 0),
(10461, 'plPL', '', 'Bethekk, twoja kapłanka wzywa twojej potęgi!', 0),
(10472, 'plPL', '', 'Moje ślicznotki, oto wasza uczta: $n!', 0),
(10475, 'plPL', 'Witamy na konkursie wędkarskim w Łupieżczej Zatoce, gdzie co tydzień nagradzamy najlepszych wędkarzy w całym Azeroth.\nGdy turniej wędkarski się rozpocznie, smakoryby będzie można łowić w każdej ławicy w Cierniodławach.', '', 0),
(10598, 'plPL', 'Przymierze zebrało $1776W zasobów i jest bliskie zwycięstwa!', '', 0),
(10599, 'plPL', 'Horda zebrała $1777W zasobów i jest bliska zwycięstwa!', '', 0),
(10620, 'plPL', 'Chyba dam radę wrócić do Warowni o własnych siłach. Skoro $gzyskałeś:zyskałaś; dla mnie trochę czasu, powinienem zdołać wymknąć się stąd niepostrzeżenie. Kimkolwiek jesteś... dziękuję. Niech Elune zawsze ci błogosławi!', '', 0),
(10638, 'plPL', 'Bitwa o Dolinę Alterak rozpocznie się za 1 minutę.', '', 0),
(10639, 'plPL', 'Bitwa o Dolinę Alterak rozpocznie się za 30 sekund.', '', 0),
(10640, 'plPL', 'Bitwa o Dolinę Alterak rozpoczęła się!', '', 0),
(10805, 'plPL', 'Twoja zdrada tylko przyspiesza twoją zgubę. Ten świat pogrąży się w ciemności!', '', 0),
(10806, 'plPL', 'Śmiesz! To oburzające! Przeklinam cię. Przeklinam cię... śmiercią!', '', 0),
(10807, 'plPL', 'Co? Takie małe, wątłe stworzenie mnie wzywa? Dołożę twoje kości do mojego tronu!!', '', 0),
(10810, 'plPL', 'Zabicie ciebie i twoich kompanów mnie zabawi. Załatwię to szybko.', '', 0),
(10869, 'plPL', 'Remulosie, stary przyjacielu. Dobrze znów cię widzieć. Wiedziałem, że wiadomość dotrze do ciebie – tak czy inaczej.', '', 0),
(10871, 'plPL', 'Obawiam się najgorszego, stary przyjacielu. We Śnie walczymy z nowym wrogiem, zrodzonym z pradawnego zła. Szlachetne potomstwo Ysery padło ofiarą dawnych podszeptów. Wygląda na to, że Koszmar przebił się przez granice tej krainy i szuka nowego żywiciela w Azeroth.', '', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(10873, 'plPL', 'Tak, Remulosie. Przygotuj śmiertelne rasy.', '', 0),
(10876, 'plPL', 'Cenarius walczy u mego boku. Illidan zasiada na swym tronie w Rubieży i rozpamiętuje. Obawiam się, że przegrana z Arthasem ostatecznie go złamała. Ogarnęło go szaleństwo, Remulosie. Tysiąc razy dziennie odtwarza w myślach tamte wydarzenia, lecz w jego umyśle to on jest zwycięzcą, a Arthas ponosi całkowitą klęskę. Zaszedł już za daleko, stary przyjacielu. Lękam się, że wkrótce może nadejść czas, gdy nasza więź zostanie wystawiona na próbę, i nie będzie już tak, jak było przy Studni w Zin-Azshari.', '', 0),
(10878, 'plPL', 'Remulosie, coś ciągnie mnie z powrotem... Tyrande... przekaż jej, że ją kocham... Powiedz jej, że jestem bezpieczny. Powiedz jej... Powiedz jej, że wrócę... Żegnaj...', '', 0),
(11012, 'plPL', 'Już idą. Postaraj się nie dać się zabić, żółtodziobie.', '', 0),
(11025, 'plPL', '<Andorov patrzy na ciebie ponuro.>$B$BJeśli krwawi, to możemy to zabić.', '', 0),
(11028, 'plPL', 'Pamiętasz, Rajaxx, jak mówiłem, że zabiję cię na końcu?', '', 0),
(11030, 'plPL', 'Żałośni, przewidywalni śmiertelnicy... Nie wiecie, co uczyniliście! Wola Pana się wypełniła. Gaj Luny zostanie zniszczony, a wraz z nim Malfurion!', '', 0),
(11269, 'plPL', 'Koszmaru nie da się powstrzymać!', '', 0),
(11270, 'plPL', '%s wyciska ostatnią iskrę życia ze swojej ofiary i połyka jej duszę. Tą ofiarą jest $n.', '', 0),
(11271, 'plPL', 'Chodź, $n. Zobacz, co niesie Koszmar...', '', 0),
(11289, 'plPL', '%s chłonie cierpienie poległych.', '', 0),
(11294, 'plPL', 'Z całą pewnością nie jesteś swoim ojcem, robaku. Gdyby mnie to obchodziło, zmiażdżyłbym cię jednym machnięciem szponów. Wydaj mi shan\'do Burzogniewnego, a oszczędzę twoje żałosne życie i życie twojego ludu.', '', 0),
(11296, 'plPL', '%s wybucha złowieszczym śmiechem.', '', 0),
(11297, 'plPL', 'Moje odkupienie? Śmiały jesteś, maleńki. Moje odkupienie przychodzi z woli mojego boga.', '', 0),
(11299, 'plPL', 'Powstańcie, słudzy Koszmaru! Powstańcie i zniszczcie ten świat! Niech nikt nie ocaleje...', '', 0),
(11304, 'plPL', 'Gdzie wasz zbawca? Jak długo wytrzymacie moje ataki?', '', 0),
(11305, 'plPL', 'Pokonaliście moje sługi? Zmierzcie się więc ze mną, śmiertelnicy!', '', 0),
(11306, 'plPL', 'Remulosie, spójrz, jak łatwo przede mną padają! Możesz to przerwać, głupcze. Wydaj mi druida, a wszystko się skończy...', '', 0),
(11310, 'plPL', '', 'Szukaj rozgrzeszenia, Eranikusie. Wszystko zostanie wybaczone...\n', 0),
(11311, 'plPL', '', 'Otrzymasz przebaczenie, Eranikusie. Elune zawsze będzie cię kochać. Zerwij więzy, które tobą władają!', 0),
(11312, 'plPL', '', 'Uścisk Przedwiecznych jest nieustępliwy. Pochłonęły go ich mroczne myśli... Nie... nie zdołam... nie zdołam już dłużej podtrzymywać zaklęcia... Elune, wspomóż mnie...', 0),
(11314, 'plPL', 'TO PALI! BÓL... PRZESZYWA...', '', 0),
(11315, 'plPL', 'DLACZEGO? Dlaczego to spotkało... mnie? Gdzie byłaś, Tyrande? Gdzie byłaś, gdy utraciłem łaskę Eluny?', '', 0),
(11316, 'plPL', 'Czuję... czuję... znów czuję na sobie dotyk Eluny... Uśmiecha się do mnie... Tak... Ja...', '', 0),
(11323, 'plPL', 'Tak długo byłem zagubiony... Skażenie Koszmaru mnie pochłonęło... A teraz wy... wy wszyscy... ocaliliście mnie. Uwolniliście z jego uścisku.', '', 0),
(11324, 'plPL', 'Ale... Malfurion, Cenarius, Ysera... oni wciąż walczą. Potrzebują mnie. Muszę natychmiast wracać do Snu.', '', 0),
(11326, 'plPL', 'Pani moja, nie jestem godzien twojej modlitwy. Zaprawdę, jesteś aniołem światła. Proszę, pomóż mi wrócić do kurhanu, abym mógł powrócić do Snu. Na mnie, tak jak na Malfuriona, także czeka ukochana... Muszę do niej wrócić... by ją chronić...', '', 0),
(11327, 'plPL', 'A wy, bohaterowie... Mam to, czego szukacie. Oby znów ujrzało, jak zło obraca się wniwecz. Remulosie, dopilnuj, by nasz czempion otrzymał odłamek Zielonego Stada.', '', 0),
(11650, 'plPL', 'Mamy rozkazy z samej góry: zniszczyć Rajaxxa. A ściślej mówiąc – zlikwidować z najwyższą bezwzględnością.', '', 0),
(11819, 'plPL', '', 'Dziękuję wam wszystkim za uwolnienie mnie i mojego brata! Nareszcie możemy spocząć w pokoju.', 0),
(11821, 'plPL', 'Moja misja dobiegła końca. Jeśli czegoś potrzebujesz, mogę mieć trochę zapasów na zbyciu.', '', 0),
(11859, 'plPL', 'Dziękuję wam wszystkim za uwolnienie mnie i mojej siostry! Nareszcie możemy spocząć w pokoju.', '', 0),
(11952, 'plPL', 'Chcecie walki? To będziecie ją mieli!', '', 0),
(11953, 'plPL', 'Skopię ci ten paskudny łeb!', '', 0),
(11954, 'plPL', 'Takich słabeuszy jak wy miażdżę codziennie! Dawajcie!', '', 0),
(12111, 'plPL', 'Ten kultysta jest pogrążony w głębokim transie...', '', 0),
(12112, 'plPL', 'Użyj 8 nekrotycznych run i przerwij jego rytuał.', 'Użyj 8 nekrotycznych run i przerwij jego rytuał.', 0),
(12155, 'plPL', '%s gwałtownie wraca do życia!', '', 0),
(12156, 'plPL', '%s traci połączenie!', '', 0),
(12178, 'plPL', '%s ulega przeciążeniu!', '', 0),
(12325, 'plPL', 'My przyjść zniszczyć słabeuszy!', '', 0),
(12326, 'plPL', 'Król Lisz kazać wam powiedzieć... GIŃCIE!', '', 0),
(12327, 'plPL', 'Raaarrrrggghhh! My iść po was!', '', 0),
(12328, 'plPL', 'Hahaha, wasi strażnicy za słabi na Plagę!', '', 0),
(12329, 'plPL', 'Co? To nie Naxxramas! My nie lubić tego miejsca... zniszczyć!', '', 0),
(12330, 'plPL', 'Wy części zamienne! My zrobić więcej Plagi w nekropolii.', '', 0),
(12342, 'plPL', 'Czemu wy uciekać? My przerobić wasze trupy na Plagę.', '', 0),
(12343, 'plPL', 'Nie martwić się, my was znaleźć.', '', 0),
(12391, 'plPL', '%s ucieka na widok upadku Kel\'Thuzada!', '', 0),
(12469, 'plPL', 'Renault...', '', 0),
(12471, 'plPL', 'Myślałeś, że twoja zdrada pójdzie w zapomnienie? Że zginie w starannie uknutej zmowie milczenia wokół mojej śmierci? Krwi z mojej krwi, ostrze czuło twoje okrucieństwo długo po tym, jak moje serce przestało bić. I w śmierci wiedziałem, co uczyniłeś. Lecz teraz łańcuchy Kel\'Thuzada już mnie nie krępują. Przybywam wymierzyć sprawiedliwość. JAM JEST SPOPIELACZ.\n', '', 0),
(12473, 'plPL', 'Wybaczam ci...', '', 0),
(12752, 'plPL', 'A kogo my tu mamy? Bez wątpienia to dzi... krzzzk ...bie zawdzięczamy to połączenie? Przesyłam pozdrowienia z... pszzzk... Lazurowej Strażnicy.', '', 0),
(12753, 'plPL', 'Sądząc po twoim sygnale, jesteś... ochę na południowy wschód od większej części wyspy, na której się rozbiliśmy. Przejdź przez Kryształowy Strumień, żeby do... kszzzk zzzt. Wybacz, mamy tu sporo zakłó...', '', 0),
(12845, 'plPL', 'Na siedem kryształów Ata\'mal! Ktoś jeszcze przeżył katastrofę! Zhanaa, czy to ty? Jak dobrze znów cię widzieć!', '', 0),
(13023, 'plPL', 'Nakarmić tobą mistrza!', '', 0),
(13024, 'plPL', 'Nie ma... już... Feugena.', '', 0),
(13025, 'plPL', 'Feugen uszczęśliwić mistrza.', '', 0),
(13083, 'plPL', 'Stalagg cię zmiażdżyć!', '', 0),
(13084, 'plPL', 'Mistrzu, ratuj mnie!!', '', 0),
(13085, 'plPL', 'Stalagg zabić!', '', 0),
(13137, 'plPL', 'Uczeń jest nic niewart, mistrzu! Uczeń przeprasza za swoją ułomność!', '', 0),
(13138, 'plPL', 'Jestem niegodny, mistrzu!', '', 0),
(13140, 'plPL', 'Panie, uczeń prosi, byś go zbił za brak zrozumienia!', '', 0),
(13456, 'plPL', 'Chodź, Północ, rozpędźmy tę nędzną hołotę!', '', 0),
(13459, 'plPL', 'Tchórze! Nędznicy!', '', 0),
(13460, 'plPL', 'To było... nieuniknione.', '', 0),
(13462, 'plPL', 'Zawsze wiedziałem... że pewnego dnia sam stanę się... zwierzyną.', '', 0),
(13490, 'plPL', 'Dla wojownika o moich umiejętnościach broń to tylko wygoda!', '', 0),
(13561, 'plPL', 'Bez obaw... choć moje gryfy nie są może do końca żywe, i tak wiernie zaniosą cię do celu. Powiedz... której wieży szukasz?', 'Bez obaw... choć moje gryfy nie są może do końca żywe, i tak wiernie zaniosą cię do celu. Powiedz... której wieży szukasz?', 0),
(13562, 'plPL', 'Zabierz mnie do Wieży Północnej Przełęczy.', 'Zabierz mnie do Wieży Północnej Przełęczy.', 0),
(13563, 'plPL', 'Zabierz mnie do Wieży Wschodniego Muru.', 'Zabierz mnie do Wieży Wschodniego Muru.', 0),
(13564, 'plPL', 'Zabierz mnie do Wieży Koronnej Straży.', 'Zabierz mnie do Wieży Koronnej Straży.', 0),
(13622, 'plPL', 'Dziękuję, że $gprzybyłeś:przybyłaś; tu, by uczcić moją pamięć. Twoje starania o odzyskanie tego symbolu, choć niepotrzebne, z pewnością poruszają serce starego człowieka.', '', 0),
(13623, 'plPL', 'Proszę, powstań, $gprzyjacielu:przyjaciółko;. Zachowaj Błogosławieństwo jako symbol siły Światłości i tego, że dawno zmarli bohaterowie mogą na nowo powstać w każdym z nas i dodawać nam natchnienia.', '', 0),
(13640, 'plPL', 'Mogę tylko mieć nadzieję, że ujrzy Światłość i zamiast tego poświęci swe siły odbudowie pięknego niegdyś Quel\'Thalas.', '', 0),
(13986, 'plPL', 'Nie wracaj tu, draenejska szumowino. Następnym razem nie darujemy ci życia, z bronią czy bez!', '', 0),
(13988, 'plPL', 'Możesz zginąć!', '', 0),
(14050, 'plPL', 'Najwyższy czas, żeby gildia przysłała nam świeżą krew! Szkoda tylko, że cała ta droga na nic. Nie wolno nam wystawiać przedstawień dla gości, dasz wiarę? Morios zabronił nam zaczynać nowe przedstawienie, a moi sponsorzy szaleją! Trzeba coś zrobić z Moriosem.', '', 0),
(14053, 'plPL', 'Nie martw się, poradzisz sobie. Wyglądasz na urodzony talent!', '', 0),
(14071, 'plPL', 'No, to była kompletna klapa. Uznajmy to za próbę, dobrze? Wychodzisz jeszcze raz?', '', 0),
(14212, 'plPL', 'Żeby cię lepiej załatwić!', '', 0),
(14213, 'plPL', 'Uciekaj, mała dziewczynko, uciekaj!', '', 0),
(14216, 'plPL', '', 'Witaj, moje dziecko.', 0),
(14218, 'plPL', '', 'Żeby cię lepiej słyszeć, moje dziecko.', 0),
(14220, 'plPL', '', 'Żeby cię lepiej widzieć, moje dziecko.', 0),
(14262, 'plPL', 'Morae... Czy to ty?', '', 0),
(14263, 'plPL', 'Nie... nie jesteś Morae, ale wyczuwam, że ją znasz. Gdy ją zobaczysz, powiedz jej, że przeżyłem katastrofę tylko po to, by zginąć z rąk infiltratorów.', '', 0),
(14264, 'plPL', 'Powiedz jej... że moja ostatnia myśl była o niej...', '', 0),
(14294, 'plPL', 'Coś ty uczynił, czarodzieju? To niemożliwe! Płonę... od środka!', '', 0),
(14296, 'plPL', 'Twoje igranie z magią tajemną zaszło za daleko, Medivhu. Zwróciłeś uwagę mocy, których nie pojmujesz. Musisz natychmiast opuścić Karazhan!', '', 0),
(14298, 'plPL', 'Mroczna moc chce się tobą posłużyć, Medivhu! Jeśli zostaniesz, nadejdą straszne dni. Spiesz się, nie mamy wiele czasu!', '', 0),
(14300, 'plPL', 'Nie zostawiasz mi wyboru. Skoro nie słuchasz głosu rozsądku, powstrzymam cię siłą!', '', 0),
(14361, 'plPL', '%s zaczyna rdzewieć!', '', 0),
(14453, 'plPL', 'Jestem do usług, mój panie.', 'Jestem do usług, mój panie.', 0),
(14456, 'plPL', '%s wzywa swoich pobratymców.', '%s wzywa swoich pobratymców.', 0),
(14457, 'plPL', 'Bracia i siostry, dziś w nocy polujemy! Krwawy elf znany jako Matis musi stanąć przed sądem! Kto pierwszy go znajdzie, dostanie tydzień urlopu na pokładzie Exodaru!', 'Bracia i siostry, dziś w nocy polujemy! Krwawy elf znany jako Matis musi stanąć przed sądem! Kto pierwszy go znajdzie, dostanie tydzień urlopu na pokładzie Exodaru!', 0),
(14458, 'plPL', 'Naprzód! Dzikie ostępy Krwawej Mgły czekają!', 'Naprzód! Dzikie ostępy Krwawej Mgły czekają!', 0),
(14577, 'plPL', 'Kto śmie zakłócać świętość Kaplicy Alonsusa?', '', 0),
(14580, 'plPL', 'To, co $guczyniłeś:uczyniłaś;, jest ohydne! Odpokutuj swoje zbrodnie przeciw Światłości!', '', 0),
(14581, 'plPL', '$GFałszywy paladynie:Fałszywa paladynko;, pokaż się! Zaraz zakosztujesz gniewu prawdziwych sług Światłości!', '', 0),
(14587, 'plPL', 'Nie ma innej drogi, $gbluźnierco:bluźnierczyni;. Gotuj się na spotkanie ze swoim losem.', '', 0),
(14612, 'plPL', '%s bierze kawałek grzybowego drzewa i przykłada go sobie do „nosa”. Najwyraźniej zadowolony, zjada go!', '', 0),
(14613, 'plPL', '%s wyrywa resztę grzybowego drzewa z korzeniami i z nią ucieka.', '', 0),
(14731, 'plPL', 'Nie uciekniesz nam, druidzie!', '', 0),
(15050, 'plPL', '', 'Biada wam wszystkim, co do jednego, moje ślicznotki!', 0),
(15051, 'plPL', '', 'Załatwiłam cię, co?', 0),
(15052, 'plPL', '', 'Jak mogliście? Co za okrutny, okrutny świat...', 0),
(15066, 'plPL', '', 'Nie pozwól im nas skrzywdzić, Tito! Och, nie pozwolisz, prawda?', 0),
(15067, 'plPL', '', 'Och, Tito, po prostu musimy znaleźć drogę do domu! Stary czarodziej może być naszą jedyną nadzieją! Strachu na Wróble, Ryku, Blaszaku, czy wy... zaraz... ojej, patrzcie, mamy gości!', 0),
(15068, 'plPL', '', 'Och, nareszcie, nareszcie mogę wrócić do domu!', 0),
(15069, 'plPL', '', 'Tito! Och, Tito, nie!', 0),
(15070, 'plPL', '', 'Cóżeś ty za diabeł, że mnie tak dręczysz?', 0),
(15071, 'plPL', '', 'Rozstanie to tak słodki smutek.', 0),
(15072, 'plPL', '', 'Romulo, idę! Och... to piję za ciebie!', 0),
(15073, 'plPL', '', 'Przyjdź, łagodna nocy, i oddaj mi mojego Romula!', 0),
(15074, 'plPL', '', 'O szczęsny sztylecie! Tu twoja pochwa; rdzewiej w niej i daj mi umrzeć!', 0),
(15075, 'plPL', 'Wyzywasz mnie? Stawaj więc, chłopcze!', '', 0),
(15076, 'plPL', 'Jakże mnie to pokrzepia na duchu!', '', 0),
(15077, 'plPL', 'Ty wstrętna paszczo, ty łono śmierci; zmuszę twe zgniłe szczęki, by się rozwarły!', '', 0),
(15078, 'plPL', 'Uśmiechasz się... na cios, który... mnie zabija.', '', 0),
(15109, 'plPL', '%s grzebie w rzeczach Kristen i zabiera jej pakunek skór.', '', 0),
(15110, 'plPL', 'Oto moje skóry, Haroldzie. A teraz dawaj nagrodę!', '', 0),
(15111, 'plPL', 'Zabieram te skóry, mała.', '', 0),
(15133, 'plPL', 'Nie musieliście tego robić!', '', 0),
(15135, 'plPL', 'Nie pozwólcie im zrobić... ze mnie materaca.', '', 0),
(15136, 'plPL', 'Chyba jednak nie jestem takim nieudacznikiem!', '', 0),
(15153, 'plPL', 'Mmmm... pyszne.', '', 0),
(15155, 'plPL', 'I znów jestem starą kupą rdzy.', '', 0),
(15156, 'plPL', 'Chyba jednak nie jestem taki zardzewiały.', '', 0),
(15163, 'plPL', 'Nadszedł nasz czas!', '', 0),
(15164, 'plPL', 'Czarodziej upadnie!', '', 0),
(15166, 'plPL', 'Nikt nas nie powstrzyma!', '', 0),
(15167, 'plPL', 'Kolejni zajmą moje miejsce.', '', 0),
(15171, 'plPL', '', 'Śmierć Ostatniemu Strażnikowi!', 0),
(15174, 'plPL', '', 'To jeszcze nie koniec!', 0),
(15194, 'plPL', 'Zwycięstwo będzie nasze!', '', 0),
(15195, 'plPL', 'Nie przerywać! Zwycięstwo za wszelką cenę!', '', 0),
(15196, 'plPL', 'Walczcie dalej! Nie ustawajcie!', '', 0),
(15332, 'plPL', '', 'Wkrótce będzie po wszystkim!', 0),
(15333, 'plPL', 'Kolejne trofeum do mojej kolekcji!', '', 0),
(15334, 'plPL', 'Dobra robota, Północ!', '', 0),
(15378, 'plPL', 'Kto śmie atakować rumaka Łowczego?', '', 0),
(15379, 'plPL', 'A może wolelibyście zmierzyć się z groźniejszym przeciwnikiem?!', '', 0),
(15438, 'plPL', 'Złamany Palec szykuje się do szarży.', '', 0),
(15460, 'plPL', 'Niebiescy Bracia górą!', '', 0),
(15468, 'plPL', 'ROKDAR ZMIAŻDŻYĆ! $n BYĆ SŁABIZNA!', '', 0),
(15472, 'plPL', 'Bliżej... Podejdź bliżej... Zobacz, co niesie pustka!', '', 0),
(15476, 'plPL', 'Kawałek po kawałku rozerwę tego śmiałka na strzępy... KAWAŁEK PO KAWAŁKU!', '', 0),
(15737, 'plPL', 'Ej, ty tam, szybko po wodę! Zgaście te płomienie, zanim obejmą resztę twierdzy! Pospiesz się, do diabła!', '', 0),
(15739, 'plPL', 'Piętnaście sekund do rozpoczęcia walki na arenie!', '', 0),
(15740, 'plPL', 'Minuta do rozpoczęcia walki na arenie!', '', 0),
(15741, 'plPL', 'Trzydzieści sekund do rozpoczęcia walki na arenie!', '', 0),
(15742, 'plPL', 'Walka na arenie rozpoczęta!', '', 0),
(15909, 'plPL', 'Thrallu! Chyba nie myślałeś, że naprawdę uciekniesz? Ty i twoi sojusznicy odpowiecie przed Blackmoore\'em... gdy już się zabawię.', '', 0),
(15922, 'plPL', 'To powinno załatwić sprawę. Wezwij mnie, jeśli znów będziesz potrzebować moich usług.', '', 0),
(16016, 'plPL', 'Thrallu! Wyjdź i staw czoła swemu przeznaczeniu!', '', 0),
(16019, 'plPL', 'Życie Tarethy wisi na włosku. Na pewno ci na niej zależy. Na pewno pragniesz ją ocalić...', '', 0),
(16021, 'plPL', 'Ach, tu jesteś. Miałem nadzieję załatwić to subtelniej, ale bezpośrednie starcie było chyba nieuniknione. Twoja przyszłość, Thrallu, nie może się ziścić, a zatem... ty i twoi kłopotliwi przyjaciele musicie zginąć!', '', 0),
(16023, 'plPL', 'Dość, wymażę samo wasze istnienie!', '', 0),
(16326, 'plPL', 'Ojej! Te wszystkie brawa to dla mnie? Dzięki, że przyszliście!', '', 0),
(16327, 'plPL', 'Dzięki, że przyszliście mnie zobaczyć! Mam nadzieję, że jesteście gotowi na dobrą zabawę, bo ja jestem.', '', 0),
(16328, 'plPL', 'Hej, ludzie, bądźcie dla mnie łagodni... to mój pierwszy raz.', '', 0),
(16329, 'plPL', 'Gotowi na śmiech?!', '', 0),
(16331, 'plPL', 'Zauważyliście kiedyś, że wszystkie te słodkie orcze dzieciaki wyglądają tak samo?', '', 0),
(16332, 'plPL', 'No więc gnom mówi taurenowi, że był w Ognistej Czeluści.', '', 0),
(16333, 'plPL', 'A teraz dobry kawał: dlaczego arbuzy mają w środku wodę?', '', 0),
(16334, 'plPL', 'Szkoda, że nie zostają słodkie na zawsze. Na Pustkowiach muszą mieć jakiś rytuał przejścia pod tytułem „Wejdź na drzewo brzydoty i spadnij”.', '', 0),
(16335, 'plPL', 'A tauren na to: „Bzdura jak wół”.', '', 0),
(16336, 'plPL', 'Bo sadzi się je przy źródle!', '', 0),
(16337, 'plPL', 'Czas na parodie!! Tę nazywam „Głupiutki tauren”.', '', 0),
(16338, 'plPL', 'Komik odchrząkuje.', '', 0),
(16339, 'plPL', 'O co chodzi z tymi kobietami? No bo one ciągle tylko tak...', '', 0),
(16340, 'plPL', 'A gnomy są jeszcze gorsze! Ciągle gadają coś w tym stylu...', '', 0),
(16341, 'plPL', 'Dziękuję! Nie zapomnijcie o napiwkach dla kelnerów! Dobranoc państwu.', '', 0),
(16343, 'plPL', 'To już koniec? Byliście wspaniali. Wracajcie bezpiecznie i dobrej nocy.', '', 0),
(16345, 'plPL', 'Dziękuję wszystkim! I klaszczcie dalej, lata tu mucha i ktoś z was w końcu ją trafi! Dobranoc!', '', 0),
(16348, 'plPL', 'No, pora zabrać te komediowe mięśnie gdzie indziej. Dobrej nocy wszystkim!', '', 0),
(16351, 'plPL', 'Ostatnia parodia. Jest trudna, ale zobaczymy, czy zgadniecie, kto to...', '', 0),
(16368, 'plPL', 'Jaka to pora, kiedy elekk siada ci na płocie?', '', 0),
(16369, 'plPL', 'Pora na nowy płot!!', '', 0),
(16370, 'plPL', 'Byliśmy z żoną szczęśliwi przez 23 lata...', '', 0),
(16371, 'plPL', 'A potem się poznaliśmy!', '', 0),
(16372, 'plPL', 'Jak się nazywa zepsuty bumerang?', '', 0),
(16373, 'plPL', 'Patyk!', '', 0),
(16374, 'plPL', 'Uwielbiam krwawe elfki. Zwłaszcza kiedy mówią coś takiego...', '', 0),
(16375, 'plPL', 'Słyszałem, że gnomy potrafią spełniać życzenia...', '', 0),
(16376, 'plPL', 'No to życzę sobie, żeby sobie poszły!', '', 0),
(16378, 'plPL', 'Nie spotkałem jeszcze taurena, którego bym nie lubił...', '', 0),
(16379, 'plPL', 'Jeść!!', '', 0),
(16381, 'plPL', 'Skoro już po występie, to może ktoś mnie przeciągnie przez Szkarłatny Klasztor?', '', 0),
(16382, 'plPL', 'Cześć wszystkim! To za ile odrodzą się tu żarty?', '', 0),
(16385, 'plPL', 'Wygląda na to, że mam u was wrogą reputację.', '', 0),
(16386, 'plPL', 'Rzuci ktoś na mnie jakieś wzmocnienie? Umieram tu na scenie.', '', 0),
(16387, 'plPL', 'No dajcie spokój! Te żarty są epickie!', '', 0),
(16388, 'plPL', 'Gdybym wiedział, że tak będzie, włożyłbym swoje Większe buty śmiechu.', '', 0),
(16389, 'plPL', 'Rany! Śmiech nie wypada tu zbyt często, co?', '', 0),
(16580, 'plPL', 'Komik parodiuje taurena.', '', 0),
(16581, 'plPL', 'Komik parodiuje gnoma.', '', 0),
(16582, 'plPL', 'Komik parodiuje krwawego elfa.', '', 0),
(16583, 'plPL', 'Komik parodiuje ludzką kobietę.', '', 0),
(16584, 'plPL', 'Komik parodiuje orka.', '', 0),
(16648, 'plPL', 'Cóż za urodziwa publiczność. Nawet krasnoludzkie panie się ogoliły.', '', 0),
(16649, 'plPL', 'Właśnie przyleciałem z Żelaznej Kuźni i, rany, ależ mojemu wierzchowcowi zdrętwiały skrzydła!', '', 0),
(16650, 'plPL', 'Wiem, co knujecie, i zamierzam położyć temu kres, raz na zawsze!', '', 0),
(16651, 'plPL', 'W zeszłym tygodniu byłem w Złotych Włościach. Byliście tam kiedyś?', '', 0),
(16652, 'plPL', 'Ta mieścina jest tak mała, że poprosiłem dzieciaka, żeby narysował mi mapę. Narysował ją na odwrocie listu gończego za Nieskornymi...', '', 0),
(16653, 'plPL', 'w skali jeden do jednego!!', '', 0),
(16655, 'plPL', 'Karczma w Złotych Włościach reklamuje się widokiem na jezioro...', '', 0),
(16656, 'plPL', 'Widziałem, jak za moim oknem przepływa murlok.', '', 0),
(16657, 'plPL', 'Ilu koboldów potrzeba, żeby wymienić knot w latarni?', '', 0),
(16659, 'plPL', 'Czas na krew!', '', 0),
(16660, 'plPL', 'Uciekajcie, przeklęci tchórze!', '', 0),
(16661, 'plPL', 'Hej, to Raliq Pijak... Jego mamuśka jest tak gruba, że jak leci w Góry Klingi, to liczą jej od kilograma!', '', 0),
(16663, 'plPL', 'Nie będziecie się wtrącać!', '', 0),
(16664, 'plPL', 'Thrall... nie może... wyjść na wolność.', '', 0),
(16665, 'plPL', 'Patrzcie, kto przyszedł, to Raliq Pijak... Jego mamuśka jest tak gruba, że smoki nie chcą jej jeść...', '', 0),
(16666, 'plPL', 'Nie wiedzą, gdzie trzymać resztki!', '', 0),
(16667, 'plPL', 'Hej! Hej! Hej! To Raliq Pijak... Jego mamuśka jest tak gruba, że trafiła nie tylko na przednią okładkę „Ogra Dzisiaj”...', '', 0),
(16668, 'plPL', 'Zajęła też tylną!', '', 0),
(16669, 'plPL', 'Gnomy były kiedyś miłym, pełnym szacunku ludem...', '', 0),
(16670, 'plPL', 'A parę dni temu widziałem, jak jeden szedł ulicą i wrzeszczał: „Kto raz spróbuje gnoma, ten nie wraca do doma!”', '', 0),
(16671, 'plPL', 'Kiedyś goblinom nie można było ufać...', '', 0),
(16672, 'plPL', 'A kogo ja oszukuję? Jak handlujesz z goblinami, lepiej miej sakiewkę obitą żelazem.', '', 0),
(16673, 'plPL', 'Jesteś niewolnikiem! I zawsze nim będziesz!', '', 0),
(16674, 'plPL', 'Nie wiem, co Blackmoore w tobie widzi. Jak dla mnie jesteś tylko kolejnym ciemnym dzikusem!', '', 0),
(16675, 'plPL', 'Thrall nigdy nie będzie wolny!', '', 0),
(16676, 'plPL', 'Naprawdę myśleliście, że wyjdziecie stąd żywi?', '', 0),
(16677, 'plPL', 'Straże... straże!', '', 0),
(16678, 'plPL', 'Czy tylko mi się wydaje, czy Horda to najbrzydszy wróg, jakiego mogliśmy sobie znaleźć?', '', 0),
(16679, 'plPL', 'Żebyście nie czuli się pominięci: mówiłem tylko, jakie atrakcyjne są krwawe elfy. W tłumaczeniu coś umyka.', '', 0),
(16680, 'plPL', 'Jak bardzo trzeba być zdesperowanym w szukaniu sojuszników, żeby werbować własne bydło?', '', 0),
(16681, 'plPL', 'Ja mam psa, ale miecza mu nie daję.', '', 0),
(16682, 'plPL', 'Krwawe elfy myślą więc, że od władzy nad światem dzieli je tylko jeden krok...', '', 0),
(16683, 'plPL', 'Raczej dwanaście kroków!', '', 0),
(16691, 'plPL', 'Nie tak szybko!', '', 0),
(16692, 'plPL', 'Szamoczcie się, ile chcecie...', '', 0),
(16693, 'plPL', 'Nie da się walczyć z przeznaczeniem!', '', 0),
(16694, 'plPL', 'Jesteście... bez znaczenia.', '', 0),
(16695, 'plPL', 'Thrall pozostanie niewolnikiem. Taretha zginie. Zawiedliście.', '', 0),
(16696, 'plPL', 'Nie! Pan nie będzie... zadowolony.', '', 0),
(16814, 'plPL', 'Dlaczego pomagacie magowi? Pomyślcie tylko, ile istnień można by ocalić, gdyby portal nigdy nie został otwarty, gdyby dało się wymazać wojny, które z tego wynikły...', '', 0),
(16815, 'plPL', 'Jeśli nie porzucicie tej głupiej misji, zginiecie!', '', 0),
(16816, 'plPL', 'Czas... jest po naszej stronie.', '', 0),
(16817, 'plPL', 'Nadużyłeś naszej gościnności, Strażniku. Precz!', '', 0),
(16818, 'plPL', 'Mówiłem, że to misja dla głupców!', '', 0),
(16819, 'plPL', 'Tak szybko odchodzisz?', '', 0),
(16821, 'plPL', 'Czemu się upieracie? Przecież widzicie, że to wszystko daremne. Jeszcze nie jest za późno! Wciąż możecie ujść z życiem...', '', 0),
(16822, 'plPL', 'Niech tak będzie... Ostrzegałem was.', '', 0),
(16823, 'plPL', 'Moja śmierć... niewiele znaczy.', '', 0),
(16824, 'plPL', 'Strażniku! Piaski czasu przesypały się dla ciebie do końca.', '', 0),
(16825, 'plPL', 'Trzeba było odejść, póki była okazja.', '', 0),
(16826, 'plPL', 'Twoje dni dobiegły końca.', '', 0),
(16827, 'plPL', 'Nadszedł czas, by na zawsze roztrzaskać ten mechaniczny wszechświat! Nie bądźmy dłużej niewolnikami klepsydry! Ostrzegam: ci, którzy nie obiorą tej wznioślejszej drogi, padną jej ofiarą!', '', 0),
(16828, 'plPL', 'Zobaczmy, co szykuje los...', '', 0),
(16829, 'plPL', 'Twój czas minął, niewolniku przeszłości.', '', 0),
(16831, 'plPL', 'O jedną przeszkodę mniej na naszej drodze!', '', 0),
(16832, 'plPL', 'Nikt nas nie powstrzyma!', '', 0),
(16980, 'plPL', 'W oddali rozbrzmiewają wojenne bębny.', '', 0),
(16996, 'plPL', 'Nareszcie jestem w domu...', '', 0),
(17080, 'plPL', 'Piekłorycz! Na błogosławionych przodków! To wykapany Grom, Drek\'Tharze.', '', 0),
(17096, 'plPL', 'Wybacz, że nie przybyłem wcześniej, młody Piekłoryczu. Mam ci tak wiele do opowiedzenia o twoim ojcu, ale najpierw musisz mi powiedzieć, gdzie znajdę Wszechmatkę.', '', 0),
(17100, 'plPL', 'Dziękuję ci, Garoszu. Będziemy mieli wiele do omówienia, gdy wrócę od Wszechmatki.', '', 0),
(17102, 'plPL', 'Wszechmatko...', '', 0),
(17113, 'plPL', 'Wszechmatko... Czy ja...\n', '', 0),
(17122, 'plPL', 'Nie... nie przeżyli, Wszechmatko. Zabito ich niedługo po moich narodzinach. Nigdy ich nie poznałem. Wychowano mnie na niewolnika. Po dziś dzień noszę imię Thrall.\n', '', 0),
(17124, 'plPL', 'Zginęli z honorem, Wszechmatko.', '', 0),
(17128, 'plPL', 'Zginął jako nasz największy bohater. To Grom uwolnił nas wszystkich... Byłem u jego boku, gdy powalił Mannorotha i na zawsze położył kres klątwie.', '', 0),
(17132, 'plPL', 'Powiedzieć mu? Wszechmatko, ojciec tego chłopca zginął, byśmy wszyscy mogli żyć wolni od klątwy krwi. Niczego mu nie powiem. Pokażę mu! Pokażę jemu i każdemu, kto wątpiłby w hart ducha Piekłorycza, co dokładnie Grom Piekłorycz uczynił dla wszystkich orków!', '', 0),
(17133, 'plPL', 'Wybacz mi, proszę, Wszechmatko. Niedługo wrócę.', '', 0),
(17134, 'plPL', 'Garoszu, synu Piekłorycza, twój ojciec żył i zginął jako nasz największy bohater. Uczyń mi ten zaszczyt i pozwól pokazać sobie, co twój ojciec poświęcił, byśmy mogli żyć wolni od uścisku demona.', '', 0),
(17136, 'plPL', 'Duchy, dajcie mi siłę! Wydobądźcie z mojej duszy te stare rany i odsłońcie je, by wszyscy je ujrzeli! Niech to dziecko pozna swojego ojca! Niech ten lud pozna swojego zbawcę!', '', 0),
(17138, 'plPL', 'Jakież to przewidywalne. Wiedziałem, że przyjdziesz. I widzę, że przyprowadziłeś potężnego Piekłorycza.', '', 0),
(17139, 'plPL', 'Jego krew należy do mnie, tak jak cała wasza pokraczna rasa.', '', 0),
(17141, 'plPL', 'Godna próba, lecz daremna.', '', 0),
(17142, 'plPL', 'Chłopak wierzył, że można cię ocalić, ale nie wiedział, co płonie w twojej duszy. W głębi serca wiesz, że jesteśmy tacy sami.\n', '', 0),
(17144, 'plPL', 'NIEEEE!', '', 0),
(17150, 'plPL', 'Thrallu... Krwawa mgła opadła.', '', 0),
(17151, 'plPL', 'Oczy Groma gasną, gdy klątwa krwi zostaje zdjęta.', '', 0),
(17152, 'plPL', 'Ogień demona wypalił się w moich żyłach. Uwolniłem... się.\n', '', 0),
(17153, 'plPL', 'Nie, stary przyjacielu. Uwolniłeś nas wszystkich...', '', 0),
(17172, 'plPL', '%s kładzie dłoń na ramieniu Garosza.', '', 0),
(17173, 'plPL', 'Nie musisz mi dziękować, Garoszu. Twój ojciec był mi bratem. Zrobiłbym wszystko dla ciebie i dla Mag\'harów. Teraz muszę wrócić do Wszechmatki.', '', 0),
(17175, 'plPL', 'Wróciłem, Wszechmatko. Garosz odnalazł swoje serce i swoją furię.', '', 0),
(17241, 'plPL', 'Brawo! Brawo! Dobre przedstawienie... Nie dałoby się was namówić, żebyście pracowali dla mnie, co? Nie, zdaje się, że bezsensowna rzeź moich pracowników mogłaby źle wpłynąć na wasze podanie o pracę.', '', 0),
(17243, 'plPL', 'Twój plan był dobry, Sha\'heenie, i uszłoby ci to na sucho, gdyby nie jedno...', '', 0),
(17244, 'plPL', 'Nigdy nie lekceważ chciwości drugiego eteryka!', '', 0),
(17491, 'plPL', 'Czy nie został już nikt, kto mógłby wystawić mnie na próbę?', '', 0),
(17492, 'plPL', 'Wasz czas się kończy!', '', 0),
(17493, 'plPL', 'Jesteście niczym! Ja odpowiadam na wyższe wezwanie...', '', 0),
(17494, 'plPL', 'Mroczny władca śmieje się z was!', '', 0),
(17495, 'plPL', 'To koniec! Skończone!', '', 0),
(17496, 'plPL', 'Twoje dni dobiegły końca!', '', 0),
(17497, 'plPL', 'Mój pan... położy kres wam wszystkim!', '', 0),
(17819, 'plPL', 'Przymierze przejmuje kontrolę nad Wieżą Krwawych Elfów!', '', 0),
(17823, 'plPL', 'Horda przejmuje kontrolę nad Wieżą Krwawych Elfów!', '', 0),
(17824, 'plPL', 'Przymierze przejmuje kontrolę nad Wieżą magów!', '', 0),
(17825, 'plPL', 'Horda przejmuje kontrolę nad Wieżą magów!', '', 0),
(17826, 'plPL', 'Horda przejmuje kontrolę nad Ruinami Draenei!', '', 0),
(17827, 'plPL', 'Przymierze przejmuje kontrolę nad Ruinami Draenei!', '', 0),
(17828, 'plPL', 'Przymierze przejmuje kontrolę nad Ruinami Grabieżcy Spaczenia!', '', 0),
(17829, 'plPL', 'Horda przejmuje kontrolę nad Ruinami Grabieżcy Spaczenia!', '', 0),
(17831, 'plPL', 'Przymierze traci kontrolę nad Wieżą Krwawych Elfów!', '', 0),
(17832, 'plPL', 'Horda traci kontrolę nad Wieżą Krwawych Elfów!', '', 0),
(17833, 'plPL', 'Przymierze traci kontrolę nad Ruinami Draenei!', '', 0),
(17834, 'plPL', 'Horda traci kontrolę nad Ruinami Draenei!', '', 0),
(17835, 'plPL', 'Przymierze traci kontrolę nad Ruinami Grabieżcy Spaczenia!', '', 0),
(17836, 'plPL', 'Horda traci kontrolę nad Ruinami Grabieżcy Spaczenia!', '', 0),
(17837, 'plPL', 'Przymierze traci kontrolę nad Wieżą magów!', '', 0),
(17838, 'plPL', 'Horda traci kontrolę nad Wieżą magów!', '', 0),
(17928, 'plPL', 'Całe życie marzyłem o tej chwili, Wszechmatko. Do tej pory miałem tylko opowieści Orgrima o moich rodzicach i ich przygodach na Draenorze. Był moim największym nauczycielem i najdroższym przyjacielem. Zginął jak bohater... Wszyscy zginęli jak bohaterowie – i po każdym z nich pozostała pieśń ku czci.\n', '', 0),
(17931, 'plPL', 'Przerwijcie awaryjne wyłączenie! Kael pourywa nam głowy, jeśli się o tym dowie!', 'Przerwijcie awaryjne wyłączenie! Kael pourywa nam głowy, jeśli się o tym dowie!', 0),
(17932, 'plPL', 'Awaryjne wyłączenie naaru trwale unieruchomi kuźnię many! Trzeba je przerwać!', 'Awaryjne wyłączenie naaru trwale unieruchomi kuźnię many! Trzeba je przerwać!', 0),
(18131, 'plPL', 'Natychmiast to przerwij!', 'Natychmiast to przerwij!', 0),
(18162, 'plPL', 'Nie wyłączysz mojej kuźni many, szumowino!', '', 0),
(18175, 'plPL', 'Dzięki temu, co $gzrobiłeś:zrobiłaś; dla mnie w Ruinach Farahlonu, znów mieszczę się w harmonogramie. Właśnie zbieram zespół, żeby tam wyruszyć.$B$BDziękuję, $n.', '', 0),
(18193, 'plPL', 'Bitwa rozpocznie się za 2 minuty!', '', 0),
(18194, 'plPL', 'Bitwa rozpocznie się za 1 minutę!', '', 0),
(18195, 'plPL', 'Bitwa rozpocznie się za 30 sekund!', '', 0),
(18196, 'plPL', 'Bitwa się rozpoczęła!', '', 0),
(18220, 'plPL', 'Wygraliście tę bitwę, ale nie... tę... wojnę.', '', 0),
(18221, 'plPL', 'Rozpoczął się ostateczny podbój Legionu! Podporządkowanie tego świata znów jest w naszym zasięgu. Niech nikt nie ocaleje!', '', 0),
(18222, 'plPL', 'Krusz się i gnij!', '', 0),
(18223, 'plPL', 'Z prochu powstałeś i w proch się obrócisz!', '', 0),
(18224, 'plPL', 'Poddaj się lodowatemu chłodowi... śmierci.', '', 0),
(18225, 'plPL', 'W grobie będzie ci dużo zimniej.', '', 0),
(18226, 'plPL', 'Wszelkie życie musi zginąć!', '', 0),
(18228, 'plPL', 'Zwycięstwo dla Legionu!', '', 0),
(18229, 'plPL', 'Zegar... wciąż... tyka.', '', 0),
(18230, 'plPL', 'Jesteście obrońcami skazanego świata! Uciekajcie stąd, a może przedłużycie swój żałosny żywot!', '', 0),
(18231, 'plPL', 'Wyglądacie na zmęczonych...', '', 0),
(18232, 'plPL', 'Słodkich snów.', '', 0),
(18233, 'plPL', 'Rój już nie może się doczekać uczty.', '', 0),
(18234, 'plPL', 'Mór na was!', '', 0),
(18235, 'plPL', 'Niech ogień spadnie z nieba!', '', 0),
(18236, 'plPL', 'Ziemia i niebo spłoną!', '', 0),
(18237, 'plPL', 'Wasze nadzieje przepadły!', '', 0),
(18238, 'plPL', 'Krzycz dla mnie.', '', 0),
(18239, 'plPL', 'Szkoda, nie ma czasu na powolną śmierć!', '', 0),
(18240, 'plPL', 'Błagajcie o litość! Wkrótce postradacie swój nic niewarty żywot!', '', 0),
(18241, 'plPL', 'Twoja śmierć będzie bolesna.', '', 0),
(18242, 'plPL', 'Nosisz... znak.', '', 0),
(18243, 'plPL', 'Shaza-kiel!', '', 0),
(18245, 'plPL', 'Nędzne utrapienie!', '', 0),
(18247, 'plPL', 'Porzućcie wszelką nadzieję! Legion powrócił, by dokończyć to, co zaczął tak wiele lat temu. Tym razem nie będzie ucieczki!', '', 0),
(18248, 'plPL', 'Twój czas dobiega... końca.', '', 0),
(18251, 'plPL', 'Cierp, nikczemny robaku!', '', 0),
(18252, 'plPL', 'To tylko przedsmak... tego, co cię czeka.', '', 0),
(18253, 'plPL', 'Reesh, hokta!', '', 0),
(18254, 'plPL', 'Nikt cię nie ocali.', '', 0),
(18255, 'plPL', 'Nie opieraj się.', '', 0),
(18359, 'plPL', '$n zabiera flagę!', '', 0),
(18361, 'plPL', 'Flaga została upuszczona!', '', 0),
(18363, 'plPL', 'My nie lubić paladyni. Elfia pani przyjść do miasto, siedzieć w Królewski Kwartał. Ona paladyn. Ty gadać, uczyć się paladyńskie rzeczy.', 'My nie lubić paladyni. Elfia pani przyjść do miasto, siedzieć w Królewski Kwartał. Ona paladyn. Ty gadać, uczyć się paladyńskie rzeczy.', 0),
(18364, 'plPL', 'Flaga wróciła na miejsce.', '', 0),
(18369, 'plPL', 'A co ty niby wyprawiasz? Śmiesz zakłócać eksperyment mojego pana?', '', 0),
(18370, 'plPL', 'Podoba ci się to, czego tu dokonaliśmy? Może zrzucimy takie kryształy z nieba na całą Rubież.', '', 0),
(18371, 'plPL', 'Nudzą mnie już twoje próby uleczenia tej ziemi i stłumienia energii, które przywołują kolosy i doprowadzają je do szału. Goliatonie, Królu kolosów, książę Kael\'thas i ja żądamy, abyś bronił kryształu!', '', 0),
(18372, 'plPL', 'Wkrótce znów się spotkamy.', '', 0),
(18375, 'plPL', 'Przymierze zdobywa flagę!', '', 0),
(18384, 'plPL', 'Horda zdobywa flagę!', '', 0),
(18394, 'plPL', 'Moje serce wypełnia nienawiść, odkąd naszych zaprzysięgłych wrogów wpuszczono do naszego miasta. Znałem tego, którego zwą Voren\'thalem, zanim nazwano go Jasnowidzem. To z jego ręki zginął mój brat.', '', 0),
(18395, 'plPL', 'Obróciłem tę nienawiść przeciwko Illidari i Płonącemu Legionowi... ale to nie oni nas zdradzili. Byliśmy wybrańcami naaru! Żyliśmy i umieraliśmy dla nich!', '', 0),
(18396, 'plPL', 'Gdy nienawiść w moim sercu znalazła cel, wszystko stało się dla mnie jasne. Shattrath musi zostać zniszczone, a wraz z nim naaru.', '', 0),
(18398, 'plPL', 'Mylisz się, Adyenie. Mój umysł nigdy nie był jaśniejszy.', '', 0),
(18399, 'plPL', 'Nauczycielu...', '', 0),
(18404, 'plPL', 'Nie! Co ja uczyniłem?', '', 0),
(18405, 'plPL', 'Światłości, daj mi siłę!', '', 0),
(18409, 'plPL', 'Tak... panie.', '', 0),
(18609, 'plPL', 'Ty iść do Królewski Kwartał. Oni wszyscy tam, w krąg dookoła sala.', 'Ty iść do Królewski Kwartał. Oni wszyscy tam, w krąg dookoła sala.', 0),
(18640, 'plPL', 'To już, $n. Ruszamy na twój rozkaz! Powiedz tylko słowo, a ja i moi ludzie rzucimy się do walki!', '', 0),
(18714, 'plPL', 'Kto śmie przerywać moją operację?', '', 0),
(18750, 'plPL', 'Dlaczego nas pojmałeś?', '', 0),
(18751, 'plPL', 'Co chcesz przez to zyskać?', '', 0),
(18754, 'plPL', 'Mądrość? To twój lud wywołał nieznośny gniew Cyrukha.', '', 0),
(18755, 'plPL', 'Dlaczego mielibyśmy ci pomóc? Świat jest zrujnowany. Zniszczony.', '', 0),
(18759, 'plPL', 'Głupcze! Cyrukh, władca ognia! Gdy więź została zerwana, Cyrukh się przebudził. To łzy Cyrukha zalewają tę ziemię roztopioną skałą.', '', 0),
(18761, 'plPL', 'Jest teraz obłąkany. Postradał zmysły podczas rozbicia. Żywioły nie zaznają spoczynku.', '', 0),
(18763, 'plPL', 'Tak, jest sposób. Zniszcz Cyrukha. Zniszcz władcę żywiołów.', '', 0),
(18765, 'plPL', 'Musisz wypowiedzieć słowa...', '', 0),
(18766, 'plPL', 'Tak... Tak... słowa. Słowa potępienia. Słowa, które wypowiedział ten mroczny. Twój pan.', '', 0),
(18767, 'plPL', 'Tak... Gul\'dan...', '', 0),
(18769, 'plPL', 'Gadanie. Wciąż tylko gadanie... A teraz uwolnij nas, śmiertelniku.', '', 0),
(19108, 'plPL', 'Gdzie ja, na mosiężne guziki Bonza, jestem? I kim wy... aaaj, ależ mnie łeb rozsadza!', '', 0),
(19116, 'plPL', '„Marny”? Nie obchodzi mnie, kim jesteś, przyjacielu: nikt nie będzie nazywał potężnego Mełka Gromiłły „marnym”!', '', 0),
(19117, 'plPL', 'Muszę tylko najpierw przygotować parę rzeczy. Wy zaczynajcie beze mnie. Muszę wyczarować trochę wody...', '', 0),
(19119, 'plPL', 'Fantastycznie! Teraz kilka zaklęć ochronnych. O tak, teraz to się rozkręcamy!', '', 0),
(19120, 'plPL', 'No i oczywiście przyda mi się trochę many. Spodoba wam się, zobaczycie...', '', 0),
(19121, 'plPL', 'Nooo dooobraaa!! Kto zamawiał wielgachną porcję łomotu?', '', 0),
(19146, 'plPL', 'Kto tu rządzi? Kto tu rządzi? No właśnie: my rządzimy!', '', 0),
(19147, 'plPL', 'Dzięki za wyciągnięcie mnie stamtąd. Mam u ciebie dług!', '', 0),
(19148, 'plPL', 'Teraz powinienem już dać radę się stąd wydostać. Dzięki!', '', 0),
(19149, 'plPL', 'To miejsce jest zwariowane! Mógłbym tu spędzić lata na badaniu całej tej technologii!', '', 0),
(19157, 'plPL', 'Powstań, młody Voldounie. Daruj sobie uprzejmości. Przybywam na polecenie naszego pana, księcia Kael\'thasa. Kazał mi sprawdzić postępy prac nad bombą many.', '', 0),
(19162, 'plPL', 'Na razie tak. Niech jednak moja obecność będzie dla ciebie zachętą. Książę Kael\'thas był niezadowolony z porażki eksperymentu z kryształem na Grani Upadłego Nieba. To jeden z powodów, dla których na poligon doświadczalny dla bomby wybraliśmy druidów Cenariona.', '', 0),
(19163, 'plPL', 'Chyba nie muszę ci mówić, co się stanie, jeśli bomba many z dziedzińca nie zostanie wkrótce użyta przeciwko celowi? Odkąd wprowadzili się do puszczy, coraz bardziej utrudniają nasze działania: tutaj, w Tuurem i na południu, w Ruinach Szpikożerców.', '', 0),
(19165, 'plPL', 'Dopilnuj tego, Sharth, bo inaczej osobiście zadbam o to, byś konał powoli i w męczarniach.', '', 0),
(19170, 'plPL', 'Chyba ich rozpoznaję. Załatw to szybko, Sharth. A potem weź bombę many i zniszcz ich miasto!', '', 0),
(19185, 'plPL', 'W rzeczy samej, to nie jest prośba.', '', 0),
(19187, 'plPL', 'Duro dostanie posiłki! Ultris to była kompletna katastrofa. NIE pozwolę, by ten błąd się powtórzył!', '', 0),
(19188, 'plPL', 'Mieliśmy po drodze zbyt wiele niepowodzeń: Cytadela Piekielnego Ognia, Grań Upadłego Nieba, Punkt Ognistego Skrzydła... Książę Kael\'thas nie będzie tolerował dalszych opóźnień. A ja nie będę tolerował niczego poza pełnym sukcesem!', '', 0),
(19191, 'plPL', 'Wracam do Twierdzy Burz. Dopilnuj, żebym nie miał powodu tu wracać!', '', 0),
(19194, 'plPL', 'Myślę, że powinniśmy dać nauczkę zarówno Hordzie, jak i Przymierzu. Taką, której prędko nie zapomną!', '', 0),
(19276, 'plPL', 'Ja się was nie boję! Chcecie się bić? Co, chcecie? No dalej! Będę się z wami bił z obiema łapami za plecami!', '', 0),
(19277, 'plPL', 'I co ja mam teraz z wami zrobić? Po prostu nie mogę się zdecydować.', '', 0),
(19278, 'plPL', 'Naprawdę przydałoby mi się serce. A może oddasz mi swoje?', '', 0),
(19304, 'plPL', 'Nie walczysz $gsam:sama;, $n! Razem wygnamy ten pomiot piekielnego ognia!', '', 0),
(19306, 'plPL', 'Staniemy do walki, gdy będziesz $ggotów:gotowa;, $n.', '', 0),
(19307, 'plPL', 'Jestem $ggotów:gotowa;, Oronoku. Zniszczmy Cyrukha i uwolnijmy żywioły!', 'Jestem $ggotów:gotowa;, Oronoku. Zniszczmy Cyrukha i uwolnijmy żywioły!', 0),
(19309, 'plPL', 'Siłą wyrwiemy żywioły z twojego uścisku!', '', 0),
(19310, 'plPL', 'Staniemy do walki, gdy będziesz $ggotów:gotowa;.', '', 0),
(19332, 'plPL', 'Czy to... Czy to już koniec? Został zniszczony?', '', 0),
(19334, 'plPL', 'Co mówią żywioły, Torloku? Słyszę tylko ciszę.', '', 0),
(19337, 'plPL', 'Zostały odkupione! A więc zwyciężyliśmy?', '', 0),
(19338, 'plPL', 'Teraz jest tak, jak być powinno, szamanie. Dobrze się spisałeś.', '', 0),
(19339, 'plPL', 'Tak... To dość dla żywiołów, które są tutaj, lecz szyfr zna jeszcze ktoś... Duchy ognia są wzburzone... Jeśli ta siła nie zostanie powstrzymana, świat, z którego przybyli ci śmiertelnicy, przestanie istnieć.', '', 0),
(19340, 'plPL', 'Żegnajcie, śmiertelnicy... Uzdrowiciel ziemi wie, co czuje ogień...', '', 0),
(19341, 'plPL', 'A zatem odchodzimy, Torloku. Mam tylko jedną prośbę...', '', 0),
(19342, 'plPL', 'Mężczyźni z rodu Rozdartego Serca oddają swoją broń uzdrowicielowi ziemi Torlokowi.', '', 0),
(19343, 'plPL', 'Przekaż ją bohaterom, dzięki którym było to możliwe.', '', 0),
(19401, 'plPL', 'Śmiertelnicy, tutaj? Co to ma znaczyć, żałosny Złamany!', '', 0),
(19404, 'plPL', 'Lepiej ze mną nie pogrywaj, Akamo. Illidan wydał mi wyraźny rozkaz, bym pilnie strzegł Strażniczki. Jeśli się dowiem, że coś przede mną ukrywasz, zmiażdżę cię własnymi rękami!', '', 0),
(19475, 'plPL', 'Z najciemniejszej nocy znów powstanie kruk, wzbije się do lotu w cieniach i objawi naturę swego rodu. Gotujcie się na jego nadejście, albowiem wierni zostaną wyniesieni, by wzlecieć wraz z krukiem, pozostali zaś pójdą w zapomnienie i będą stąpać po ziemi, z podciętymi skrzydłami, okryci hańbą.', '', 0),
(19476, 'plPL', 'Zahartujcie umysły i strzeżcie swych myśli. Mroczne skrzydła zaćmią i pochłoną umysły słabych – stado niewolników, których stopy nigdy nie oderwą się od ziemi.', '', 0),
(19477, 'plPL', 'Stara krew popłynie na nowo wraz z nadejściem kruka, z powrotem ciemności na niebiosa. Szkarłatna noc i powstanie dawnych.', '', 0),
(19478, 'plPL', 'Kruk został już raz strącony, bo wzleciał zbyt wysoko, nim był gotów. Eony przygotowały Mrocznego Obserwatora do wzlotu, by zaciągnął nad widnokręgiem mroczny płaszcz.', '', 0),
(19792, 'plPL', '<Gladiator weteran mówi łamanym orczym.> Co? Masz do mnie jakiś problem? Załatw to na arenie. Nie tracę czasu na wasze „hordy” i „przymierza”.', '', 0),
(19793, 'plPL', 'Gladiatorzy zdobywają prawo do noszenia ekwipunku takiego jak mój, wygrywając rankingowe mecze na arenie.', '', 0),
(19822, 'plPL', 'Nie mam pojęcia, co tu się dzieje, ale chętnie dołączę do waszej walki z tym bezczelnym imbecylem!', '', 0),
(19823, 'plPL', 'Szykuj się do obrony, kretynie!', '', 0),
(19824, 'plPL', 'Nawet się przy tym nie spociłem!', '', 0),
(19825, 'plPL', 'Nie krępujcie się, możecie się włączyć w każdej chwili.', '', 0),
(19826, 'plPL', 'Zaraz cię przypiekę, skarbeńku!', '', 0),
(19827, 'plPL', 'Ice, ice, baby.', '', 0),
(19828, 'plPL', 'Uleczcie mnie! Na wszystko, co święte, uleczcie mnie! Ja umieram!!', '', 0),
(19829, 'plPL', 'Odezwie się do was mój prawnik!', '', 0),
(19831, 'plPL', 'Ośmielacie się mnie więzić? Zginiecie!', '', 0),
(19832, 'plPL', 'Jesteście... niczym!', '', 0),
(19833, 'plPL', 'Pochłoną was płomienie!', '', 0),
(19834, 'plPL', 'T-t-tak... zimno.', '', 0),
(19835, 'plPL', 'Żałośni, podrzędni śmiertelnicy!', '', 0),
(19836, 'plPL', 'Stado... was pożre.', '', 0),
(19837, 'plPL', 'Czarne Stado podbije wszystko!', '', 0),
(19839, 'plPL', 'Najpierw cię upiekę, a potem cię zjem!', '', 0),
(19840, 'plPL', 'Obyście wszyscy... zdechli w męczarniach!', '', 0),
(19931, 'plPL', 'Festiwal Księżyca w Azeroth trwa w najlepsze! Wróć tam i oddaj cześć nestorom podczas tego wspaniałego święta! Główne uroczystości odbywają się w Gaju Luny, ale zapewniliśmy wygodny transport z Wichrogrodu, Żelaznej Kuźni, Darnassus, Gromowych Urwisk, Orgrimmaru i Podmiasta. Mamy nadzieję, że się tam zobaczymy!', 'Festiwal Księżyca w Azeroth trwa w najlepsze! Wróć tam i oddaj cześć nestorom podczas tego wspaniałego święta! Główne uroczystości odbywają się w Gaju Luny, ale zapewniliśmy wygodny transport z Wichrogrodu, Żelaznej Kuźni, Darnassus, Gromowych Urwisk, Orgrimmaru i Podmiasta. Mamy nadzieję, że się tam zobaczymy!', 0),
(19951, 'plPL', 'Tu, w Kruczym Lesie, zawsze jesteś u nas mile $gwidziany:widziana;, $n.', '', 0),
(20462, 'plPL', '', 'Dlaczego Rubież nie nazywa się już Draenor?', 0),
(20470, 'plPL', '', 'Czy Wypaczona Otchłań ma kształt precla? I co to w ogóle jest otchłań? Opiekunka sierocińca mówiła, że nie wypada pytać ludzi o ich otchłanie.', 0),
(20472, 'plPL', 'Nazan zlatuje z nieba.', '', 0),
(20628, 'plPL', 'Rozczarowujesz mnie, Akamo. Chciałem osobiście przesłuchać tego zdradzieckiego robaka! Zaczynam wątpić w twoją lojalność, Złamany.', '', 0),
(20629, 'plPL', 'Nie wyczuwam kłamstwa w twoim głosie, Akamo. To, że Kael\'thas mógłby mnie zdradzić, nie jest wielkim zaskoczeniem – nie jestem tak nieświadomy, jak niektórzy sądzą. Lecz to, że był z nim w zmowie jeden z twoich, stawia twoją wierność pod znakiem zapytania.', '', 0),
(20630, 'plPL', 'Wyślij swoje Popielne Języki do Twierdzy Burz i zabijcie jego najcenniejszy skarb, feniksa zwanego Al\'arem. Muszę mieć pewność, że nie stoisz po jego stronie. Nawet nie myśl o tym, by mnie zdradzić, Złamany. Obaj wiemy, do kogo należy twoja dusza!', '', 0),
(20633, 'plPL', 'Jestem... jestem wolny! Eterium zamierzało mnie torturować, dopóki nie ulegnę ich żądaniom. Obawiam się, że gdyby nie ty, z pewnością nie zniósłbym tych mąk.', '', 0),
(20634, 'plPL', 'Wiedz jedno. W komnatach Shaffara na końcu tych grobowców spoczywa istota o niewyobrażalnej mocy. W ryzach trzyma ją moc komory stazy. Jeśli chcesz ją zniszczyć, musisz wrócić do Ameera, zanim zapuścisz się dalej!', '', 0),
(20684, 'plPL', '', 'Jak wstrzymam oddech, to na jaki kolor się zrobię?', 0),
(20685, 'plPL', '', 'Skoro konie dostają podkowy, to czy ja dostanę draenejskie podkowy?', 0),
(20686, 'plPL', '', 'Skoro Płonący Legion to taki kłopot, to czemu po prostu nie polać ich wodą? Wtedy zostanie z nich zwykły Legion.', 0),
(20687, 'plPL', '', 'Jak ty to robisz, że tyle jesz i pijesz, a nie tyjesz?', 0),
(20688, 'plPL', '', 'Czy naaru gasi Światłość, kiedy chce iść spać?', 0),
(20708, 'plPL', '', '%s zabiera kamień księżycowy Południowej Furii i ucieka do rzeki. Za nią!', 0),
(20715, 'plPL', '', 'Hej, ty! Oddawaj ten kamień księżycowy, a nikomu nic się nie stanie!', 0),
(20719, 'plPL', 'Żałosne nędzniki. Ośmieliliście się napaść na świątynię Illidana? Dobrze więc, uczynię ją waszym łożem śmierci!', '', 0),
(20720, 'plPL', '', 'Dobra, wygrywasz! Poddaję się! Tylko nie rób mi krzywdy!', 0),
(20723, 'plPL', 'Oddaj kamień księżycowy Południowej Furii, a puszczę cię wolno.', 'Oddaj kamień księżycowy Południowej Furii, a puszczę cię wolno.', 0),
(20726, 'plPL', 'Argh! Rozszarpię twoją duszę i zmielę ją na proch!', '', 0),
(20742, 'plPL', 'Nadszedł czas, Maiev! Daj upust swemu gniewowi!', '', 0),
(20743, 'plPL', '', 'Czekałam na tę chwilę latami. Illidan i jego pieski zostaną zniszczeni!', 0),
(20744, 'plPL', 'Zabijcie każdego, kto nas zobaczy! Wieść nie może dotrzeć do Illidana.', '', 0),
(20745, 'plPL', 'Przypieczętowałeś swój los, Akamo. Pan dowie się o twojej zdradzie!', '', 0),
(20746, 'plPL', 'Akama nie ma pana. Już nie.', '', 0),
(20748, 'plPL', 'Nasze plany już są zagrożone. Wygląda na to, że Maiev postanowiła działać po swojemu.', '', 0),
(20749, 'plPL', '%s przenosi uwagę na pęknięcie w południowej ścianie świątyni.', '', 0),
(20750, 'plPL', 'Musimy działać dalej, z Maiev czy bez niej. Do środka! Szybko!', '', 0),
(20767, 'plPL', '$GGłupcze:Głupia;! Esencja jastrzębia nigdy nie będzie twoja!', '', 0),
(20768, 'plPL', 'Czas Kruka jest bliski, lecz twój skończy się tutaj!', '', 0),
(20769, 'plPL', 'Śmiesz niepokoić wiernych wyznawców Kruka?', '', 0),
(20770, 'plPL', 'Zginiesz za swoją pychę, $N!', '', 0),
(20771, 'plPL', 'Sokół został pokonany i nigdy już nie powstanie! Twoja misja jest daremna!', '', 0),
(20772, 'plPL', 'Kruk powróci do nas, jak zapowiada proroctwo, a ty nie zdołasz temu zapobiec!', '', 0),
(20774, 'plPL', '%s bierze głęboki oddech!', '', 0),
(20792, 'plPL', 'Twoje małpy nie dokończyły roboty, naaru. Pobity, lecz żywy... My nie popełniliśmy tego błędu, gdy przejmowaliśmy twój statek.', '', 0),
(20793, 'plPL', 'I po co to wszystko? Dla błyskotek? Spóźniliście się. Przygotowania już trwają. Wkrótce pan powróci.', '', 0),
(20794, 'plPL', 'I ani ty, ani ten głupiec Illidan nie zdołacie mnie powstrzymać! Obaj mi się przysłużyliście, każdy na swój sposób – nieświadomie.', '', 0),
(20796, 'plPL', 'Złóżcie broń i ukorzcie się przed potęgą Kil\'jaedena!', '', 0),
(20980, 'plPL', '%s na powrót zamienia się w kamień.', '', 0),
(21070, 'plPL', '', 'Ich furia blednie przy mojej, Illidanie. Mamy ze sobą niezałatwione porachunki.', 0),
(21071, 'plPL', '', 'Moje długie łowy wreszcie dobiegły końca. Dziś sprawiedliwości stanie się zadość!', 0),
(21230, 'plPL', 'Nigdy w życiu!', '', 0),
(21301, 'plPL', '', 'Odsuń się, bo zrobię z ciebie kolejną ozdobę mojej zbroi. Mamy z twoim przywódcą sprawy do omówienia...', 0),
(21304, 'plPL', '', 'Wiedziałam, że przyznasz mi rację...', 0),
(21305, 'plPL', '', 'Nadrządca Mor\'ghor, jak mniemam... Miło mi wreszcie cię poznać.', 0),
(21306, 'plPL', '', 'Jestem Lady Sinestra.', 0),
(21308, 'plPL', '', 'Z pewnością słyszałeś o porażkach Nefariana w Azeroth... Choć on poległ, eksperymenty trwają. Mój pan... kontynuuje dzieło, które rozpoczął jego potomek.', 0),
(21311, 'plPL', '', 'Byłeś niegdyś jednym z naczelnych dowódców, Mor\'ghorze. Twojej pracy w Grim Batol niełatwo zapomnieć.', 0),
(21312, 'plPL', '', 'A teraz... Potrzebujemy jaj, które zdobywacie. Jaj Otchłanioskrzydłych. To w końcu dzieło pana. Zapłacimy każdą cenę, jakiej zażądasz.', 0),
(21315, 'plPL', '', 'Pan będzie wielce rad z tych wieści. Czarne Stado da ci wszystko, o co poprosisz. W razie potrzeby pozwolimy wam dosiadać naszych smokowców.', 0),
(21316, 'plPL', '', 'Dziękuję za twoją łaskawość, Mor\'ghorze. Muszę już ruszać w drogę.', 0),
(21317, 'plPL', '', '%s pada na podłogę.', 0),
(21320, 'plPL', 'Ochłoń trochę!', 'Ochłoń trochę!', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(21348, 'plPL', 'Chwała Akamie!', '', 0),
(21350, 'plPL', 'Chwała naszemu przywódcy! Chwała Akamie!', '', 0),
(21483, 'plPL', 'Baczność, kapitanie!', '', 0),
(21489, 'plPL', '', 'To za Naishę!', 0),
(21507, 'plPL', '', 'To koniec. Jesteś pokonany.', 0),
(21508, 'plPL', '', 'Ma rację. Nic nie czuję... Jestem... niczym.', 0),
(21509, 'plPL', '', 'Żegnajcie, czempioni.', 0),
(21954, 'plPL', 'To szaleństwo!', 'To szaleństwo!', 0),
(22022, 'plPL', 'Szykujcie się, już dzwony biją! Niech słabi, starzy i dzieci się kryją! Każdy z was spłaci swój dług ostatni. Wołajcie o litość – nikt nie ujdzie z matni!', '', 0),
(22026, 'plPL', 'Ogień trawi wszystko! Na nic wasze trudy. Sprawiedliwość górą – porzućcie ułudy!', '', 0),
(22027, 'plPL', 'Zgasł mój płomień, iskra nie została. Sam was strącę w ciemność, gdzie śmierć zamieszkała.', '', 0),
(22034, 'plPL', 'Niebo jest ciemne. Ogień się pali. Próżny wasz trud – koło Losu toczy się dalej.', '', 0),
(22035, 'plPL', 'Osada wciąż płonie, oczyszcza ją pożoga! Czasu mam niewiele, niedługo mi w drogę!', '', 0),
(22070, 'plPL', '%s dziękuje ci specjalnym tańcem.', '', 0),
(22208, 'plPL', '', 'Tym razem nie będzie dla ciebie więzienia!', 0),
(22261, 'plPL', 'To już koniec, poszukiwań kres. Niech los wybierze, kto prawy tu jest.', '', 0),
(22271, 'plPL', 'Oto me ciało, sprawne i czyste! Uleczę teraz wasze dusze smoliste!', '', 0),
(22393, 'plPL', 'Tak!', 'Tak!', 0),
(22394, 'plPL', 'Racja!', 'Racja!', 0),
(22395, 'plPL', 'Dobrze gadasz!', 'Dobrze gadasz!', 0),
(22396, 'plPL', 'Święta prawda!', 'Święta prawda!', 0),
(22397, 'plPL', 'Nie ma mowy!', 'Nie ma mowy!', 0),
(22398, 'plPL', 'Nigdy w życiu!', 'Nigdy w życiu!', 0),
(22415, 'plPL', 'Chodź tu, idioto!', '', 0),
(22587, 'plPL', 'Słuchaj, kundlu! Gardzę tobą szczerze! Teraz poczuj... jak ogień cię bierze!', '', 0),
(22665, 'plPL', 'Ach, ale to wy wtargnęliście na ziemie naszego pana. Już za samo to wykroczenie mógłby was zetrzeć z powierzchni ziemi w jednej chwili! Arthas nie darzy swoich zbiegłych niewolników ani wielką miłością, ani cierpliwością.', '', 0),
(22669, 'plPL', 'Ale... dowiedział się o waszym zwycięstwie nad Flotą Północną Wichrogrodu i uważa, że macie potencjał. Potencjał, by pójść po rozum do głowy i porzucić dziecinny bunt Sylwany.', '', 0),
(22671, 'plPL', 'Arthas gotów jest ofiarować ci potęgę, jakiej sobie nie wyobrażasz. Mizerna armia, którą tu przywiodłeś, wypadłaby blado przy falangach, którymi byś dowodził, gdybyś wrócił w objęcia Plagi.', '', 0),
(22695, 'plPL', 'Powstań, Jeźdźcu...', 'Powstań, Jeźdźcu...', 0),
(22696, 'plPL', 'Twój czas nadchodzi...', 'Twój czas nadchodzi...', 0),
(22720, 'plPL', 'Śmierć już znasz...', 'Śmierć już znasz...', 0),
(22721, 'plPL', 'Dziś zguba cię ugodzi!', 'Dziś zguba cię ugodzi!', 0),
(22722, 'plPL', 'Oto wrykule! Rasa, która wojnę i zniszczenie doprowadziła do rangi sztuki. Już związali swój los z Królem Liszem! Ich siedziby otaczają was ze wszystkich stron, a jest ich co najmniej pięć razy więcej niż was.', '', 0),
(22723, 'plPL', 'Wybór należy do ciebie, Anselmie. Wróć do armii Króla Lisza i walcz u ich boku albo pozostań wierny swojej tak zwanej królowej i poznaj ich gniew, gdy będą was wypędzać ze swej ojczyzny!', '', 0),
(22757, 'plPL', 'Tak wam pilno przelać moją krew. Lecz by mnie zgładzić, głowę zabić trzeba wpierw!', '', 0),
(22758, 'plPL', 'Cóż za daremny gest.', '', 0),
(22764, 'plPL', 'Jeszcze o mnie usłyszycie. Wrócę, by napluć na wasze trupy, gdy spadną na was armie Utgardu!', '', 0),
(22766, 'plPL', 'Słuchaj ostatnich tchnień swoich ludzi, gdy będę spijał ich dusze!', '', 0),
(22793, 'plPL', 'Nadeszły raporty z próby na flocie wroga, panie!', '', 0),
(22794, 'plPL', 'Cóż... dobra wiadomość jest taka, że zmusiliśmy posiłki do odwrotu.', '', 0),
(22795, 'plPL', 'Zaraza okazała się nie do końca... śmiertelna. Wśród zgłaszanych szkodliwych skutków są jednak nudności, zaburzenia równowagi i silny ból brzucha.', '', 0),
(22834, 'plPL', 'Pomocy! Moje oczy!', 'Pomocy! Moje oczy!', 0),
(22835, 'plPL', 'Niech ktoś zestrzeli tego nietoperza!', 'Niech ktoś zestrzeli tego nietoperza!', 0),
(22836, 'plPL', 'Nie czuję się za dobrze...', 'Nie czuję się za dobrze...', 0),
(22837, 'plPL', 'Ta ciecz... cuchnie!', 'Ta ciecz... cuchnie!', 0),
(22972, 'plPL', 'Krąg spłynie krwią intruzów! Oluf przybył!', '', 0),
(22975, 'plPL', 'Dobrze... Więcej ciał na żniwa...', '', 0),
(23016, 'plPL', 'Starożytny szyfr upada na ziemię.', '', 0),
(23019, 'plPL', 'Więcej dusz dla Króla Lisza! Chodźcie, maleństwa! Chodźcie!', '', 0),
(23210, 'plPL', 'Drużynie Przymierza kończą się posiłki!', 'Drużynie Przymierza kończą się posiłki!', 0),
(23211, 'plPL', 'Drużynie Hordy kończą się posiłki!', 'Drużynie Hordy kończą się posiłki!', 0),
(23241, 'plPL', 'Dokładnie zbadałem to miejsce i nie pozwolę, żeby jacyś tępi łowcy skarbów wpadli tu i ukradli coś, co powinno trafić do muzeum. Ja poprowadzę to natarcie.', '', 0),
(23242, 'plPL', 'Właściwie najlepiej będzie, jeśli po prostu tu zostaniecie. Tylko byście mi przeszkadzali...', '', 0),
(23346, 'plPL', 'Witaj, $gdobry nieznajomy:dobra nieznajoma;, i dziękuję za twój bezinteresowny czyn.', '', 0),
(23347, 'plPL', 'Ci poganie obrabowali mnie z dobytku, ale mogę ci ofiarować ten amulet, który zabrałem moim oprawcom.', '', 0),
(23348, 'plPL', 'Żegnaj.', '', 0),
(23369, 'plPL', 'Niech ci dobrze służy, $n.', '', 0),
(23373, 'plPL', 'Hmm, dziękuję, $gnieznajomy:nieznajoma;.', '', 0),
(23374, 'plPL', 'Obawiam się, że nie mam nic poza tą starą skrzynią, którą tu znalazłem. Jest twoja.', '', 0),
(23375, 'plPL', 'Mam nadzieję, że jej zawartość okaże się... przydatna.', '', 0),
(23376, 'plPL', 'Do następnego spotkania...', '', 0),
(23379, 'plPL', '', 'Oooch! Najwyższy czas, żeby ktoś mnie uratował...', 0),
(23380, 'plPL', '', 'Chyba powinnam być wdzięczna. Proszę, weź to. Nie chcę niczego, co by mi przypominało o tym miejscu.', 0),
(23381, 'plPL', '', 'Zabrałam to jednemu z tych trolli, gdy mnie pojmano. Może znajdziesz sposób, by użyć tego przeciwko nim.', 0),
(23382, 'plPL', '', 'Mam już serdecznie dość tego miejsca. Żegnam.', 0),
(23387, 'plPL', 'No proszę. Cóż za miły obrót spraw.', '', 0),
(23388, 'plPL', 'Masz wielkie szczęście, że $guratowałeś:uratowałaś; mnie, a nie któregoś z tych innych biedaków.', '', 0),
(23389, 'plPL', 'Proszę, przyjmij za fatygę tę zapłatę wraz z moją wdzięcznością.', '', 0),
(23390, 'plPL', 'Bywaj, $n.', '', 0),
(23391, 'plPL', 'Juhuu! Jestem uratowany! Dziękuję ci, $n.', '', 0),
(23392, 'plPL', 'Ojej. Co to ZA smród... o, chwila, he, he, ups! Chyba moje zmysły potrzebują trochę czasu, żeby wrócić do normy.', '', 0),
(23393, 'plPL', 'Wybaczcie, przyjaciele. Proszę. To powinno pokryć koszty mojego ratunku.', '', 0),
(23394, 'plPL', 'Na razie!', '', 0),
(23401, 'plPL', 'Och, czy to możliwe? Ja... jestem wolny od tej ohydnej klątwy?', '', 0),
(23402, 'plPL', 'Słowa nie wyrażą mojej wdzięczności, $n. Dziękuję za twoją dobroć.', '', 0),
(23403, 'plPL', 'Jak widzisz, niewiele mi zostało, odkąd dopadli mnie ci dzicy, ale chętnie podzielę się tym, co mam. Chodź, rzuć okiem.', '', 0),
(23405, 'plPL', '', 'Mmmm, muchy! Jeszcze lepsze teraz, kiedy czuję ich smak.', 0),
(23406, 'plPL', '', 'Miło wrócić między nieumarłych, i to dzięki tobie.', 0),
(23407, 'plPL', '', 'Może mam coś, co cię zainteresuje? Chodź, zobacz, czy coś ci się spodoba.', 0),
(23411, 'plPL', '', 'Hurra! Znowu jestem dziewczynką!', 0),
(23412, 'plPL', '', 'Dziękuję za ratunek. Strasznie nie lubię być obrzydliwą żabą!', 0),
(23413, 'plPL', '', 'Właściwie nie wolno mi rozmawiać z nieznajomymi, ale $gbyłeś:byłaś; dla mnie $gtaki miły:taka miła;. Masz tu coś wyjątkowego, co znalazłam tuż przed tym, jak mnie porwali.', 0),
(23414, 'plPL', '', 'Powinnam już iść. Uważaj na siebie!', 0),
(23417, 'plPL', 'Ej no! Wszystko $gzepsułeś:zepsułaś;!', '', 0),
(23418, 'plPL', 'Masz pojęcie, jak fajnie jest skakać tak daleko?', '', 0),
(23419, 'plPL', 'No trudno, i tak zaczynałem już tęsknić za kumplami – w życiu mi nie uwierzą! A, masz – możesz to sobie wziąć, znalazłem to, jak bawiłem się w chowanego.', '', 0),
(23420, 'plPL', 'Zobaczmy, czy jeszcze umiem zrobić ten dźwięk...', '', 0),
(23421, 'plPL', 'Hmpf. Dzięki, ale nie potrzebowałem pomocy.', '', 0),
(23422, 'plPL', 'Pracowałem nad sztuczką, która zaradziłaby mojemu położeniu, i byłem już bardzo bliski znalezienia <KUUUM>... O rety!', '', 0),
(23423, 'plPL', 'No cóż, chyba jednak jestem ci coś winien – masz, weź jedno z tych. Mam ich mnóstwo.', '', 0),
(23424, 'plPL', 'Może warto rozważyć opuszczenie tego miejsca. Myślę, że przemiana w żabę to jedna z lepszych rzeczy, jakie mogą tu kogoś spotkać.', '', 0),
(23425, 'plPL', '', 'Och! Znowu jestem piękna jak dawniej? Jak cudownie! Myślałam, że zostanę żabą na zawsze.', 0),
(23426, 'plPL', '', 'To było po prostu okropne. Byłam cała oślizgła i ciągle lizałam się po oczach!', 0),
(23427, 'plPL', '', 'Całe szczęście, że $gzjawiłeś:zjawiłaś; się w samą porę. Proszę, weź jedną z tych trollowych skrzynek na pamiątkę po mnie.', 0),
(23428, 'plPL', '', 'Nigdy więcej nie chcę oglądać tego paskudnego stawu. Dziękuję, $n. Nigdy cię nie zapomnę!', 0),
(23455, 'plPL', 'Do tego kresu dotarłem już nieraz. Jaka nowa przygoda czeka mnie teraz?', '', 0),
(23803, 'plPL', 'Jeszcze nie, Ymironie, mam wobec ciebie inne plany. Lepiej mi się przysłużysz na Iglicy Utgard. A jeśli te robaki przeżyją i znów cię odnajdą, będziesz miał okazję pomścić żonę.', '', 0),
(23861, 'plPL', 'Powstańcie, żołnierze, do boju stańcie! Upadłemu rycerzowi zwycięstwo wreszcie dajcie!', '', 0),
(23922, 'plPL', 'Przybądźcie, sługi! Wasz pan wzywa!', '', 0),
(23923, 'plPL', 'Praca waszych braci na Burzowych Szczytach nabrała szaleńczego tempa. Wkrótce Ojciec zostanie uwolniony.', '', 0),
(23924, 'plPL', 'Wasi bracia na północy ujarzmili kamienne behemoty i skierowali je na drogę do Ulduaru. Wkrótce ostatnie zabezpieczenia Panteonu zostaną zneutralizowane.', '', 0),
(23925, 'plPL', 'Trzy szczeliny otwarte przez śmiertelników z tych stron trzeba uciszyć. Ziemia słyszy i widzi, co robimy, i dopóki przejście nie zostanie zamknięte, będzie nam przeszkadzać w naszych wysiłkach.', '', 0),
(23926, 'plPL', 'Zasypcie to miejsce! Wasz pan tego żąda!', '', 0),
(23927, 'plPL', 'Jaskinię wypełnia huk gromu.', '', 0),
(23928, 'plPL', 'Huk gromu cichnie.', '', 0),
(23936, 'plPL', 'Zamilknijcie, śmiertelnicy, i wysłuchajcie moich słów.', '', 0),
(23941, 'plPL', 'Ziemia na horyzoncie, panie Kowalski! Widać port!', '', 0),
(23942, 'plPL', 'Dziękuję, panie Henders.', '', 0),
(23943, 'plPL', 'Proszę wprowadzić nas do portu, panie Mehran.', '', 0),
(23944, 'plPL', 'Kapitanie Wąs! Wkrótce przybijamy do portu!', '', 0),
(23945, 'plPL', 'Dziękuję, panie Kowalski! Może pan wrócić na stanowisko i nadzorować cumowanie!', '', 0),
(23946, 'plPL', 'Dobra robota, wszyscy. Proszę nas bezpiecznie doprowadzić do następnego portu.', '', 0),
(23947, 'plPL', 'Kapitan Wąs jest NAJLEPSZY!', '', 0),
(23948, 'plPL', 'Szoruję pokłady!', '', 0),
(23949, 'plPL', '„Lady Mehley” to NAJLEPSZY statek na świecie!', '', 0),
(23950, 'plPL', 'Szorowanie pokładów wyleczyło mnie z krzywicy!', '', 0),
(23951, 'plPL', 'Tak jest, panie Kowalski.', '', 0),
(23953, 'plPL', 'Wybacz, mam mało czasu na rozmowy.', '', 0),
(23954, 'plPL', '', 'Nie widzisz, że mam tu robotę, $gchłopcze:dziewczyno;? Zmykaj, zanim Kowalski zobaczy, że strzępię jęzor.', 0),
(23955, 'plPL', 'Piękny dzień na żeglugę, no nie?', '', 0),
(23956, 'plPL', 'Torgoley daje nam popalić, ale dobry z niego kapitan, o tak.', '', 0),
(23958, 'plPL', 'Muszę mieć oko na statek i załogę, $gszanowny panie:szanowna pani;. Wybacz, że nie przystanę na rozmowę.', '', 0),
(23959, 'plPL', '„Lady Mehley” bywa w Theramore na tyle często, że przydzielono nas do ochrony jej pasażerów.', '„Lady Mehley” bywa w Theramore na tyle często, że przydzielono nas do ochrony jej pasażerów.', 0),
(23960, 'plPL', 'Witaj na pokładzie majestatycznej „Lady Mehley”. Jestem kapitan Torgoley.$b$bJeśli masz pytania dotyczące statku, pytaj śmiało; a jeśli nie, to proszę, ciesz się podróżą, tak jak ja zawsze... W końcu, cytując mojego ulubionego skrybę: Z mojego doświadczenia wynika, że na statkach dokonuje się ciekawego odkrycia na temat świata. Okazuje się, że można się bez niego zupełnie obejść.', '', 0),
(23961, 'plPL', '„Lady Mehley”', '„Lady Mehley”', 0),
(23963, 'plPL', 'Towary i ekwipunek', 'Towary i ekwipunek', 0),
(23964, 'plPL', '„Wąs”?', '„Wąs”?', 0),
(23965, 'plPL', 'Tak, tak się nazywa, i piękny to statek.$b$bWiesz, od takich jednostek można się wiele nauczyć. Pewien wielki poeta rzekł: Statki, co mijają się nocą i w przelocie mówią do siebie – tylko znak dany i daleki głos w ciemności; tak i my na oceanie życia mijamy się i mówimy do siebie – tylko spojrzenie i głos, potem znów ciemność i cisza.', '', 0),
(23966, 'plPL', 'Jeśli zapragniesz strawy, szefowa kambuza Grace zadba o twoje potrzeby.', '', 0),
(23967, 'plPL', 'Pan Combs, okrętowy inżynier i kwatermistrz, zaopatrzy cię we wszystko, czego możesz potrzebować. Jest też niezłym majsterkowiczem, gdyby twój ekwipunek wymagał naprawy.', '', 0),
(23968, 'plPL', 'Ach, tak, to... przezwisko. Cóż... jak to mówią, dobre imię, tak jak dobrą wolę, zdobywa się wieloma czynami, a traci jednym. Nie ma co wnikać, jak i dlaczego; dość powiedzieć, że tak właśnie niektórzy mnie nazywają.', '', 0),
(23981, 'plPL', 'Potrzebuję... waszej pomocy! Nie zdołam... dłużej mu się opierać!', '', 0),
(23982, 'plPL', 'Aaach!! Pomóżcie mi, zanim postradam zmysły!', '', 0),
(23983, 'plPL', 'Szybko! Niewiele już ze mnie zostało!', '', 0),
(24026, 'plPL', 'Musimy dopilnować, by morze nie zabrało już żadnej duszy.', 'Musimy dopilnować, by morze nie zabrało już żadnej duszy.', 0),
(24030, 'plPL', 'Wybacz, ale muszę się skupić na pracy.', 'Wybacz, ale muszę się skupić na pracy.', 0),
(24031, 'plPL', 'Morze pochłonęło wielu. Mnie i ognikom powierzono poszukiwanie tych dusz.', 'Morze pochłonęło wielu. Mnie i ognikom powierzono poszukiwanie tych dusz.', 0),
(24032, 'plPL', 'Łup Sorlofa upada na podłogę.', '', 0),
(24034, 'plPL', 'Morza to niebezpieczne miejsce. Musimy zachować czujność.', 'Morza to niebezpieczne miejsce. Musimy zachować czujność.', 0),
(24035, 'plPL', 'Niestety nie mogę teraz z tobą rozmawiać.', 'Niestety nie mogę teraz z tobą rozmawiać.', 0),
(24044, 'plPL', 'Jo-ho-ho i butelka gnomiej gorzałki!', '', 0),
(24045, 'plPL', 'Tam dmucha!', '', 0),
(24046, 'plPL', 'Rum i dziewki dla wszystkich!', '', 0),
(24047, 'plPL', 'Masz, szczurze lądowy!', '', 0),
(24048, 'plPL', 'Łup jest nasz!', '', 0),
(24096, 'plPL', 'Załoga „Odwagi” dołoży wszelkich starań, by twoja podróż była jak najszybsza i najprzyjemniejsza.', '', 0),
(24097, 'plPL', 'Wybacz, ale porozmawiamy innym razem. Bywaj.', '', 0),
(24101, 'plPL', '', 'Witaj na pokładzie „Odwagi”, $gpanie:pani;. A teraz wybacz...', 0),
(24105, 'plPL', '', 'Niemal zazdroszczę naszemu panu Pieśni Fal. Toż on jest chyba ładniejszy ode mnie!', 0),
(24109, 'plPL', '', 'Pechowe nazwisko jak na żeglarza, no nie?', 0),
(24114, 'plPL', 'Ten siwiejący wilk morski może i jest najstarszy w załodze, ale i najtwardszy z całej zgrai! Co? Co? Ramiona jak u ogra!', '', 0),
(24118, 'plPL', '', 'Przysięgłyśmy zrobić wszystko, co w naszej mocy, by chronić pasażerów „Odwagi”. Szlak morski między Wioską Rut\'theran a Portem Wichrogrodu musi pozostać bezpieczny.', 0),
(24125, 'plPL', 'Hej, $gmały:mała;. Jesteś na pokładzie „Panieńskiego Kaprysu”. Jestem kapitan Kluczodysza, a ty masz zaszczyt płynąć chlubą Łupieżców Czarnej Wody. Krwawe Żagle nie zbliżają się do nas – nie przy mojej bystrej załodze i sporym zapasie prochu w ładowni. Takie ubezpieczenie, rozumiesz.$b$bJeśli masz pytania, to odpowiem.', '', 0),
(24126, 'plPL', '„Panieński Kaprys”', '„Panieński Kaprys”', 0),
(24127, 'plPL', 'Tak, to na nim właśnie stoisz. Ślicznotka, co? Baron jakiś czas temu zrobił mnie jego kapitanem. Pierwotnie nie był mój, więc to nie ja go nazwałem; jeśli chcesz znać moje zdanie, $gmały:mała;, to żeglarz, który nadał mu nazwę, spędził trochę za dużo czasu na morzu, a za mało w porcie, jeśli wiesz, co mam na myśli.', '', 0),
(24128, 'plPL', 'Jeśli burczy ci w brzuchu, pogadaj z szefem kambuza Stalobrzuchem, ale tak między nami? Lepiej poczekaj. Nie bez powodu tak się nazywa.', '', 0),
(24129, 'plPL', 'Czym byłby statek Parochlebców bez inżyniera, co? Kręciwrzeciono pomoże ci we wszystkim, czego trzeba. Potrafi też szybko coś naprawić, jeśli o to ci chodzi.', '', 0),
(24130, 'plPL', 'Witaj na pokładzie Promu Lunopiórej. Kursujemy między Warownią Lunopiórej a Zapomnianym Wybrzeżem, szukając zaginionych na morzu. Morze bywa niebezpieczne dla nieprzygotowanych.$b$bJeśli chcesz się przygotować, porozmawiaj z naszymi zaopatrzeniowcami. Z przyjemnością ci pomogą.', '', 0),
(24131, 'plPL', 'W imieniu załogi „Księżycowej Piany” witam cię. Mam nadzieję, że skorzystasz z naszych zapasów, zanim się rozstaniemy.', '', 0),
(24132, 'plPL', 'Stąpaj ostrożnie na pokładzie „Błogosławieństwa Eluny”. Choć Elune pobłogosławiła nas odkryciem nowych przyjaciół, na morzu nie ominęły nas też trudy.$b$bAle odnajdywanie dusz zagubionych na morzu czy w nowym świecie to prawdziwe błogosławieństwo Eluny.', '', 0),
(24133, 'plPL', 'Elune po wielokroć pobłogosławiła nas wszystkimi naszymi odkryciami. Musimy jednak zachować czujność.', 'Elune po wielokroć pobłogosławiła nas wszystkimi naszymi odkryciami. Musimy jednak zachować czujność.', 0),
(24134, 'plPL', '', 'Wybacz, muszę się skupić na pracy.', 0),
(24136, 'plPL', 'Witaj na pokładzie „Panieńskiego Kaprysu”. Do samego portu powinniśmy mieć spokojny rejs.', '', 0),
(24153, 'plPL', 'Witaj na pokładzie „Przywoływacza Gromu”!$b$bNie zwracaj uwagi na tych, co narzekają na wybuchy i tym podobne. No naprawdę, każdy popełnia błędy. Trzeba ludziom trochę odpuścić.$b$bSłuchaj, zrozumiałbym, gdyby jakiś kapitan rozbił statek 22 czy 23 razy... Ale o czymkolwiek poniżej tego nie warto nawet wspominać.', '', 0),
(24154, 'plPL', '<Zrzędzi> Te góry to pewnie wyrosły znikąd... Wszystkie pięć razy!', '', 0),
(24155, 'plPL', '<Zrzędzi> Można by pomyśleć, że trudno rozbić sterowiec o ocean. A jeszcze trudniej zrobić to cztery osobne razy!', '', 0),
(24156, 'plPL', '<Zrzędzi> Chciałbym móc powiedzieć, że udało nam się uniknąć awaryjnych lądowań w jeziorach. Chciałbym móc powiedzieć, że rozbiliśmy się w jeziorze tylko raz... ale udało nam się rozbić w czterech różnych jeziorach, w tym w Jeziorze Lordamere!', '', 0),
(24157, 'plPL', 'Imponuje mi, że gałęzie sosen prawie nie szkodzą naszemu statkowi.$b$bCo nie usprawiedliwia tych trzech razy, kiedy rozbiliśmy się w jakimś lesie.', '', 0),
(24158, 'plPL', 'Nigdy nie sądziłem, że zobaczę Teldrassil... A już na pewno nie sądziłem, że się o Teldrassil rozbijemy.', '', 0),
(24159, 'plPL', 'Już dwa razy udało nam się przecisnąć przez Gromowe Urwiska!', '', 0),
(24160, 'plPL', '<Zrzędzi> Do dziś nie wiem, jak zdołaliśmy prześlizgnąć się przez Tysiąc Filarów bez jednego zadrapania tylko po to, by rozbić się i spłonąć na Migoczących Równinach!', '', 0),
(24161, 'plPL', '', 'Jeśli lubisz emocje, nasz kapitan jest najlepszy! Uwielbiam tę robotę!', 0),
(24162, 'plPL', 'Nie pytaj...', '', 0),
(24163, 'plPL', 'Nie możesz mnie winić za nasze wpadki... Ja nawet nie widzę, dokąd lecę!$b$bChociaż może to właśnie znaczy, że możesz mnie winić...$b$bNie! Czekaj! Umiem zadokować ten statek bez problemu... To na pewno wina rozkazów kapitana! Może lubi doprowadzać nas do granic możliwości i sprawdzać, jak sobie radzimy z przetrwaniem i naprawami.', '', 0),
(24255, 'plPL', '', '„Żelazny Orzeł”. Phi. To statek pasażerski, a nie okręt wojenny! Ale co tam, robota to robota, więc będę przytakiwać kapitanowi „Bombastowi”, dopóki książę płaci.$b$bTak czy inaczej, witaj na pokładzie.', 0),
(24259, 'plPL', 'Trzeba ci coś naprawić? Skorzystaj z Handlotronu D-Luxe.', 'Trzeba ci coś naprawić? Skorzystaj z Handlotronu D-Luxe.', 0),
(24260, 'plPL', 'Chronimy ten sterowiec na trasie z Orgrimmaru do Obozu Grom\'gol w Dolinie Cierniodławów.', 'Chronimy ten sterowiec na trasie z Orgrimmaru do Obozu Grom\'gol w Dolinie Cierniodławów.', 0),
(24261, 'plPL', 'Nie teraz, $gkolego:słonko;... Mam robotę. Na razie.', '', 0),
(24262, 'plPL', 'Mam najlepiej utrzymany sterowiec w Azeroth. Wiesz, kiedyś miał dwa lekkie działa i dość bomb, by zrównać z ziemią miasto... sam jego cień wystarczał, by rozgromić armie.$b$bCo? Oczywiście, że to prawda!', '', 0),
(24282, 'plPL', '', 'Witaj na pokładzie. Rozgość się i ciesz się podróżą. Na „Fioletowej Księżniczce” chcemy, żeby pasażerowie się odprężyli. Pod pokładem mamy automaty sprzedające, gdyby w czasie lotu było ci czegoś trzeba.', 0),
(24283, 'plPL', 'Odprężenie to klucz do wydajnej załogi. Daj załodze odpocząć, a będzie pracować lepiej.', '', 0),
(24284, 'plPL', 'Kapitan jest świetna! Kiedy cumujemy, mamy czas na relaks. Na te chwile czekam najbardziej.', '', 0),
(24286, 'plPL', 'Daj mi pospać jeszcze pięć minutek, mon...', '', 0),
(24287, 'plPL', 'Mam teraz robotę.', 'Mam teraz robotę.', 0),
(24288, 'plPL', 'Trzeba ci coś naprawić? Skorzystaj z Handlotronu.', 'Trzeba ci coś naprawić? Skorzystaj z Handlotronu.', 0),
(24289, 'plPL', 'Nie mam teraz czasu na rozmowy.', 'Nie mam teraz czasu na rozmowy.', 0),
(24290, 'plPL', '', 'Lot z Grom\'gol do Podmiasta jest piękny, choć nic się podczas niego nie dzieje. Co nie usprawiedliwia zasypiania na służbie.', 0),
(24371, 'plPL', 'Cieśla, panie.', 'Cieśla.', 0),
(24372, 'plPL', 'Szkutnik, panie.', 'Szkutnik.', 0),
(24373, 'plPL', 'Parobek, jaśnie panie.', 'Parobek, panie.', 0),
(24374, 'plPL', 'Krawiec.', 'Szwaczka, jaśnie panie.', 0),
(24375, 'plPL', 'Kowal.', 'Kowal.', 0),
(24376, 'plPL', 'Murarz, panie.', 'Murarz, panie.', 0),
(24377, 'plPL', 'Górnik.', 'Górnik, panie.', 0),
(24378, 'plPL', 'Kucharz.', 'Kucharz, panie.', 0),
(24575, 'plPL', 'Jestem wolny! Dziękuję.', '', 0),
(24754, 'plPL', 'Nie dam się powstrzymać! Ten świat upadnie!', '', 0),
(24761, 'plPL', 'Hej, chłopaki! Zaczekajcie!', '', 0),
(24808, 'plPL', 'Ci, których można było poświęcić, zginęli. Niech tak będzie! Teraz dokonam tego, czego nie zdołał Sargeras! Wykrwawię ten nędzny świat i zapewnię sobie miejsce prawdziwego władcy Płonącego Legionu! Nadszedł koniec! Niech rozpocznie się rozpad tego świata!', '', 0),
(24822, 'plPL', 'Skieruję swoją moc w kule! Bądźcie gotowi!', '', 0),
(24824, 'plPL', 'Przelałem wszystko, co mogłem! Moc jest w waszych rękach!', '', 0),
(24825, 'plPL', 'Nie łudźcie się nadzieją! Nie możecie wygrać!', '', 0),
(24843, 'plPL', 'Tak jest, kapitanie!', '', 0),
(24988, 'plPL', 'Znów jestem z krwi i kości. Tylko to się liczy!', 'Znów jestem z krwi i kości. Tylko to się liczy!', 0),
(24993, 'plPL', 'Nie ma czasu do stracenia!', '', 0),
(25190, 'plPL', 'Anveeno, musisz się przebudzić! Ten świat cię potrzebuje!', '', 0),
(25191, 'plPL', 'Musisz się uwolnić! Musisz stać się tym, czym zawsze miałaś być! Nadszedł czas, Anveeno!', '', 0),
(25192, 'plPL', 'Anveeno, kocham cię! Skup się na moim głosie! Wróć teraz dla mnie! Tylko ty możesz oczyścić Słoneczną Studnię!', '', 0),
(25193, 'plPL', 'Tak, Anveeno! Niech przeznaczenie weźmie cię teraz w objęcia!', '', 0),
(25194, 'plPL', 'Żegnaj, Anveeno, ukochana. Niewielu zapamięta twoje imię, a jednak dziś odmieniłaś bieg przeznaczenia. To, co było skażone, jest teraz czyste. Bohaterowie, nie pozwólcie, by jej ofiara poszła na marne.', '', 0),
(25195, 'plPL', '', 'Służę teraz tylko panu.', 0),
(25196, 'plPL', '', 'Ale ja... zgubiłam się. Nie umiem znaleźć drogi powrotnej.', 0),
(25197, 'plPL', '', 'Kalec... Kalec?', 0),
(25198, 'plPL', '', 'Koszmar się skończył! Czar prysł! Żegnaj, Kalec, mój ukochany!', 0),
(25199, 'plPL', 'Aaaach! Moce Słonecznej Studni... obracają się... przeciwko mnie! Coście zrobili? Coście zrobili???', '', 0),
(25205, 'plPL', 'Dziękujemy za ocalenie. Przypadkiem odkopaliśmy części Mistrza Trybów Mechazoda i złożyliśmy go z powrotem.', 'Dziękujemy za ocalenie. Przypadkiem odkopaliśmy części Mistrza Trybów Mechazoda i złożyliśmy go z powrotem.', 0),
(25207, 'plPL', 'W zamian „zdjął z nas klątwę”, twierdząc, że „naprawia” nas, przywracając nam postać mechanicznych konstruktów.', 'W zamian „zdjął z nas klątwę”, twierdząc, że „naprawia” nas, przywracając nam postać mechanicznych konstruktów.', 0),
(25208, 'plPL', 'Twierdzi, że wszystkie twory tytanów padają ofiarą tego, co nazywa „Klątwą Ciała”. Mówi, że pierwsze gnomy były kiedyś mechagnomami.', 'Twierdzi, że wszystkie twory tytanów padają ofiarą tego, co nazywa „Klątwą Ciała”. Mówi, że pierwsze gnomy były kiedyś mechagnomami.', 0),
(25209, 'plPL', 'To kompletny szaleniec! Ktoś musi położyć kres jego obłędowi, zanim dla wszystkich będzie za późno!', 'To kompletny szaleniec! Ktoś musi położyć kres jego obłędowi, zanim dla wszystkich będzie za późno!', 0),
(25261, 'plPL', 'Madrigosa zasługiwała na znacznie lepszy los. Zrobiliście to, co trzeba było zrobić, ale ta bitwa jeszcze się nie skończyła!', '', 0),
(25362, 'plPL', 'Twoje postępy w tym regionie są imponujące, książę krwi. Jestem zadowolony.', '', 0),
(25363, 'plPL', 'A to niespodzianka, Thassarianie. Od miesięcy nie miałem wieści od Mograine\'a ani pozostałych rycerzy śmierci. Rozumiem, że przybywasz, by na powrót dołączyć do Plagi?', '', 0),
(25364, 'plPL', 'Nie zawiedź mnie, San\'layn. Wróć do Lodowej Korony z głową tego głupca albo nie wracaj wcale.', '', 0),
(25377, 'plPL', 'Filakteria nie należy do ciebie, $n! Zapłacisz za swój występek.', '', 0),
(25403, 'plPL', 'Śmiertelni bohaterowie – wasze dzisiejsze zwycięstwo zostało przepowiedziane dawno temu. Pełen udręki krzyk mojego pokonanego brata odbije się echem w całym wszechświecie – i przyniesie nową nadzieję wszystkim, którzy wciąż stawiają opór Płonącej Krucjacie.', '', 0),
(25407, 'plPL', 'Istota zwana Entropiusem, którą musieliście zniszczyć, była niegdyś szlachetnym naaru, M\'uru. Za życia M\'uru przewodził ogromne energie ŚWIATŁOŚCI i NADZIEI. Przez pewien czas garstka zbłąkanych próbowała te energie wykraść...', '', 0),
(25408, 'plPL', '', 'Nasza arogancja była niewybaczalna. Skazaliśmy na potępienie jedną z najszlachetniejszych istot. Być może nigdy nie odkupimy tego grzechu.', 0),
(25409, 'plPL', 'Jakże więc dobrze się składa, że odzyskałem iskrę szlachetnego naaru z miejsca, w którym upadła! Tam, gdzie mieszka wiara, nadzieja nigdy nie ginie, młoda krwawa elfko.', '', 0),
(25410, 'plPL', '', 'Czy to możliwe?', 0),
(25411, 'plPL', 'Spójrzcie teraz, śmiertelnicy – oto SERCE M\'URU! Nieskalane. Skąpane w świetle Stworzenia – takie, jakie było o Brzasku.', '', 0),
(25413, 'plPL', '', 'Błogosławieni przodkowie! Czuję to... tyle miłości... tyle łaski... nie ma... słów... nie da się tego opisać...', 0),
(25414, 'plPL', 'Zbawienie, moje dziecko. Czeka na nas wszystkich.', '', 0),
(25485, 'plPL', 'Keristraszo! Pokonałaś moją małżonkę... więc teraz TY zajmiesz jej miejsce!', '', 0),
(25504, 'plPL', 'Nie będzie wytchnienia! Moje dzieło jest tu niemal ukończone!', '', 0),
(25505, 'plPL', 'Ja nigdy nie jestem po... przegranej... stronie!', '', 0),
(25506, 'plPL', 'Wasza niedola to moja rozkosz!', '', 0),
(25507, 'plPL', 'Będę patrzył, jak krwawicie!', '', 0),
(25508, 'plPL', 'Żałosny śmiertelnik!', '', 0),
(25509, 'plPL', 'Nie słyszeliście? Ja zawsze wygrywam!', '', 0),
(25541, 'plPL', 'Nie jesteście sami! Błękitne Stado pomoże wam pokonać Zwodziciela!', '', 0),
(25542, 'plPL', 'Napełniłem mocą kolejną kulę! Użyjcie jej szybko!', '', 0),
(25543, 'plPL', 'Kolejna kula jest gotowa! Spieszcie się!', '', 0),
(25549, 'plPL', 'Kolejny krok ku zagładzie!', '', 0),
(25550, 'plPL', 'Anakh Kyree!', '', 0),
(25551, 'plPL', 'Komu możecie zaufać!', '', 0),
(25552, 'plPL', 'Wróg jest wśród was!', '', 0),
(25637, 'plPL', '', 'Chwała Kil\'jaedenowi! Śmierć wszystkim, którzy stawiają opór!', 0),
(25638, 'plPL', '', 'Udławcie się ostatnim tchem!', 0),
(25639, 'plPL', '', 'Jestem silniejsza niż kiedykolwiek!', 0),
(25640, 'plPL', '', 'Zabijam dla pana!', 0),
(25642, 'plPL', '', 'Koniec z wahaniem! Wasz los jest przesądzony!', 0),
(25643, 'plPL', '', 'Kil\'jaeden... zwycięży!', 0),
(25705, 'plPL', 'Kil\'jaeden zaczyna skupiać mroczną energię.', '', 0),
(25732, 'plPL', '%s wpatruje się jak urzeczona w odbicie słońca na nożu Zeh\'gehna.', '', 0),
(25733, 'plPL', '%s rechocze ochoczo, kierując wzrok na zacumowany statek.', '', 0),
(25739, 'plPL', 'Czego ci trzeba?', '', 0),
(25740, 'plPL', 'Czy udało ci się coś odkryć?', '', 0),
(25741, 'plPL', 'Duchy żywiołów są niespokojne...', '', 0),
(25822, 'plPL', 'Uderzajcie teraz, bohaterowie, póki jest osłabiony! Pokonajcie Zwodziciela!', '', 0),
(25854, 'plPL', '', '$n, maleństwo, czemu mnie przyzywasz? Czy działasz ręka w rękę z trollami tej krainy? $gPrzybyłeś:Przybyłaś;, by mnie zabić i przywłaszczyć sobie moją moc?', 0),
(25862, 'plPL', 'Ofiara Anveeny dała nam wszystkim nową nadzieję na przyszłość.', '', 0),
(25863, 'plPL', '', 'Wyczuwam w tobie niepewność i nie ufam jej, czy jesteś z nimi, czy nie. Jeśli pragniesz mojej wróżby dla Kalu\'ak, najpierw musisz się wykazać.', 0),
(25864, 'plPL', '', 'Nałożę na ciebie łagodny przymus. Skocz w głębinę przede mną, by znaleźć się w moim żywiole i tym samym okazać uległość.', 0),
(25865, 'plPL', '', 'Choć działasz pod przymusem, wybór i ostatni krok przed skokiem należą do ciebie. Masz jeszcze dwadzieścia sekund na decyzję.', 0),
(25866, 'plPL', '', 'Dobrze więc, $n, nie $gzdobyłeś:zdobyłaś; się na czyn. Nie tobie dane jest poznać przepowiednię. Nie wzywaj mnie więcej, póki nie znajdziesz w sobie odwagi!', 0),
(25867, 'plPL', '', 'Dobrze się $gspisałeś:spisałaś;, $n. Odnotowuję twój wyraz szacunku. A teraz mam dla ciebie wieści, które musisz przekazać Kalu\'ak.', 0),
(25868, 'plPL', '', 'Krótko mówiąc, musisz powiedzieć kiełzarom, że nie mogą uciekać. Jeśli to zrobią, ich duchy zniszczy zło rosnące w siłę w Północnej Grani.', 0),
(25869, 'plPL', '', 'Powiedz mistykowi, że jego lud ma wytrwać i walczyć u boku Hordy i Przymierza przeciwko siłom Malygosa i Króla Lisza.', 0),
(25870, 'plPL', '', 'A teraz płyń z powrotem z wiedzą, której ci udzieliłam. Zrób dla nich, co w twojej mocy.', 0),
(25992, 'plPL', '%s odlatuje.', '', 0),
(26147, 'plPL', 'pociera w dłoniach |Hitem:36863|h|cFFFFFFFF[Dziesięciościenne krasnoludzkie kości]|r|h i rzuca.', 'pociera w dłoniach |Hitem:36863|h|cFFFFFFFF[Dziesięciościenne krasnoludzkie kości]|r|h i rzuca.', 0),
(26152, 'plPL', 'od niechcenia rzuca |Hitem:36862|h|cFFFFFFFF[Zużyte trollowe kości]|r|h.', 'od niechcenia rzuca |Hitem:36862|h|cFFFFFFFF[Zużyte trollowe kości]|r|h.', 0),
(26179, 'plPL', 'Uciekać!', '', 0),
(26180, 'plPL', 'Nie chcę umierać!', '', 0),
(26181, 'plPL', 'Wielki nas uratuje!', '', 0),
(26182, 'plPL', 'Aaa!!!', '', 0),
(26183, 'plPL', 'Są wszędzie!', '', 0),
(26436, 'plPL', 'Dziękuję wam wszystkim. Dawni druidzi mądrze postąpili, obalając Vordrassil, gdyż jego korzenie sięgają głęboko do siedziby pradawnego zła.', '', 0),
(26437, 'plPL', 'Znacie ich jako Przedwiecznych Bogów. Strzeżcie się Yogg-Sarona, bestii o tysiącu paszcz. Jego zło sięga dalej niż korzenie Vordrassila.', '', 0),
(26636, 'plPL', 'AAAEEEEIIIiiiiiiiiiiiiiiiiiiiiiiiiiiii........................................', '', 0),
(26710, 'plPL', 'Na mocy królewskiego edyktu macie natychmiast wracać do Lordaeronu. Lord Uther przekonał króla, by odwołał tę wyprawę.', '', 0),
(26712, 'plPL', 'Zgadza się. Moi ludzie donoszą, że drogi stąd do wybrzeża są w rękach nieumarłych. Będziecie musieli znaleźć inną drogę powrotną na statki.', '', 0),
(26714, 'plPL', 'Kapitanie, czemu strażnicy nie są na posterunkach?', '', 0),
(26716, 'plPL', 'Uther kazał odwołać moje wojska? Niech to szlag! Jeśli wojownicy mnie opuszczą, nigdy nie pokonam Mal\'Ganisa. Statki muszą spłonąć, zanim ludzie dotrą do brzegu!', '', 0),
(26717, 'plPL', 'Czy to aby nie przesada, chłopcze?', '', 0),
(26718, 'plPL', 'Spalić je do samego szkieletu! Nikt nie wróci do domu, póki nie skończymy tu naszego zadania!', '', 0),
(26731, 'plPL', 'Okłamałeś swoich ludzi i zdradziłeś najemników, którzy za ciebie walczyli. Co się z tobą dzieje, Arthasie? Czy liczy się dla ciebie już tylko zemsta?', '', 0),
(26732, 'plPL', 'Daruj sobie, Muradinie. Nie było cię tam i nie widziałeś, co Mal\'Ganis zrobił z moją ojczyzną.', '', 0),
(26853, 'plPL', 'Trzymaj tych drani z dala ode mnie!', 'Trzymaj tych drani z dala ode mnie!', 0),
(26854, 'plPL', 'Trzymaj ich z dala ode mnie przez jakieś 15 sekund, a to ustrojstwo będzie załatwione.', 'Trzymaj ich z dala ode mnie przez jakieś 15 sekund, a to ustrojstwo będzie załatwione.', 0),
(26855, 'plPL', 'Jak skończę z tym wozem zarazy, będzie wyglądał, jakby zbudował go goblin! Osłaniaj mnie!', 'Jak skończę z tym wozem zarazy, będzie wyglądał, jakby zbudował go goblin! Osłaniaj mnie!', 0),
(26856, 'plPL', '%s zręcznie składa dziwną machinę.', '%s zręcznie składa dziwną machinę.', 0),
(26858, 'plPL', 'To powinno wystarczyć! Jeszcze tylko kilka sekund.', 'To powinno wystarczyć! Jeszcze tylko kilka sekund.', 0),
(26939, 'plPL', '', 'Mieszkałam tu i opiekowałam się tym sanktuarium z błogosławieństwem Alexstrazy dłużej, niż sięgam pamięcią. W jego najczarniejszej godzinie zawiodłam... Padłam u stóp tego przeklętego rycerza śmierci... Krwawej Zguby.', 0),
(26940, 'plPL', '', 'Król Lisz sięga teraz daleko... bez lęku depcze najświętsze ziemie wszystkich Stad. Chce nas zmusić do działania.', 0),
(26941, 'plPL', '', 'Mój czas dobiegł końca... Za życia oddałam się Alexstrazie, lecz po śmierci nie mam już nic do ofiarowania. Jej sanktuarium będzie potrzebowało nowej opieki.', 0),
(26942, 'plPL', '', 'I dziękuję ci... dziękuję za uwolnienie mnie z kajdan potępionych. Jesteś $gbohaterem:bohaterką;... Wiem, że dokonasz jeszcze wielkich czynów.', 0),
(26943, 'plPL', '', 'Dahlia spluwa na ziemię na samą myśl o tym imieniu.', 0),
(26944, 'plPL', '', 'Pozostałość Dahlii Muśniętej Słońcem rozwiewa się...', 0),
(26949, 'plPL', '', 'Belgaristrasz mówi prawdę; sytuacja jest naprawdę poważna.\nMogę obdarzyć cię mocą wezwania smokowca z Zielonego Stada. Jeśli wolisz czerpać z mocy Czerwonego lub Brązowego, porozmawiaj z Belgaristraszem albo Eternosem.', 0),
(26950, 'plPL', 'Varos Obłokokroczący i jego strażnicy pierścienia chronią drugi pierścień. Twoje smokowce z nawiązką dorównują strażnikom pierścienia, ale Varos stoi za nieprzeniknioną tarczą stworzoną z energii samego Okulusa. Tarczę zasila dziesięć konstruktów wirówki z pierścienia i platform powyżej. Zniszcz je, a Varos stanie się podatny na ataki.\nMogę obdarzyć cię mocą wezwania smokowca z Czerwonego Stada. Jeśli wolisz czerpać z mocy Brązowego lub Zielonego, porozmawiaj z Eternosem albo Verdisą.', '', 0),
(26952, 'plPL', 'Belgaristrasz mówi prawdę; czas ucieka!\nMogę obdarzyć cię mocą wezwania smokowca z Brązowego Stada. Jeśli wolisz czerpać z mocy Czerwonego lub Zielonego, porozmawiaj z Belgaristraszem albo Verdisą.', '', 0),
(27030, 'plPL', '', '$gDziałałeś:Działałaś; za moimi plecami. $gZlekceważyłeś:Zlekceważyłaś; moje rozkazy. Zapłacisz za to.', 0),
(27031, 'plPL', '', 'Dość gadania. Kiedy z tobą skończę, nawet worgi nie zechcą się zbliżyć do twojego truchła.', 0),
(27125, 'plPL', 'Filakteria Thel\'zana upada na ziemię pod Lodową Burzą.', '', 0),
(27157, 'plPL', 'Byłem... kiedyś taki jak wy. Śmiertelny. Miękki. Tylko ciało i kości. SŁABY I LĘKLIWY!', '', 0),
(27159, 'plPL', 'Nasz pan, Arthas, dostrzegł we mnie ludzką ułomność.', '', 0),
(27160, 'plPL', '„Służ mi za życia, a obiecuję wyrwać słabość z twej duszy. Wymazać ją z istnienia!” Zostać wybranym... tak pobłogosławionym przez Króla Lisza.', '', 0),
(27161, 'plPL', 'I służyłem mu... Gdyby nie ja, chwalebna cytadela grozy, Naxxramas, mogłaby nigdy nie powrócić do Północnej Grani.', '', 0),
(27162, 'plPL', 'Ale dość gadania... Walczyliście zaciekle i przybyliście z najdalszych zakątków tego świata, by stawić czoła Niosącemu Zmrok. Nie zawiodę was...', '', 0),
(27163, 'plPL', 'Tak jak nasz pan ocalił mnie, tak i ja ocalę was!', '', 0),
(27164, 'plPL', 'Powstańcie, moje sługi! Wasz pan rozkazuje!', '', 0),
(27173, 'plPL', 'Honor, odwaga, współczucie i sprawiedliwość! Oto cnoty, o które niegdyś walczyłeś jako kleryk Argentowego Brzasku, Thel\'zanie.', '', 0),
(27174, 'plPL', 'Poświęciłeś całe życie walce z Plagą. Widziałeś, co zrobiła z naszym ukochanym Lordaeronem. Król Lisz odebrał ci wszystko!', '', 0),
(27175, 'plPL', 'Jak więc to się stało, że ojciec Inigo Montoy, ostoja cnót Argentowego Brzasku, stał się ucieleśnieniem tego, czego nienawidził najbardziej?', '', 0),
(27176, 'plPL', 'TO OSTATNI RAZ, GDY WYMAWIASZ TO IMIĘ, PALADYNIE! Wydaj ostatnie tchnienie!', '', 0),
(27180, 'plPL', 'Zwycięstwo dla Przymierza!', '', 0),
(27181, 'plPL', 'Ocaliliście Zimową Straż! Teraz, gdy plugastwo Thel\'zana zostało zmyte, 7. Legion z łatwością rozprawi się z resztkami Plagi. Kiedy tu skończycie, zameldujcie się pod Angratharem!', '', 0),
(27182, 'plPL', 'A teraz bądźcie wolni i ruszajcie do boju! Zakończmy to razem!', '', 0),
(27207, 'plPL', 'Spójrz, Muradinie, oto nasze ocalenie – Ostrze Mrozu.', '', 0),
(27209, 'plPL', 'Stój, chłopcze. Na postumencie jest inskrypcja. To ostrzeżenie. Głosi: „Ktokolwiek sięgnie po to ostrze, władać będzie wieczną mocą. Jak ostrze rozdziera ciało, tak moc okaleczy ducha”. Och, powinienem był się domyślić. To ostrze jest przeklęte! Zabierajmy się stąd, do diabła!', '', 0),
(27211, 'plPL', 'Chętnie zniosę każdą klątwę, by ocalić ojczyznę.', '', 0),
(27212, 'plPL', 'Zostaw je, Arthasie. Zapomnij o tym wszystkim i poprowadź ludzi do domu.', '', 0),
(27214, 'plPL', 'Do diabła z ludźmi! Nic nie powstrzyma mnie przed zemstą, stary przyjacielu. Nawet ty.', '', 0),
(27215, 'plPL', 'Teraz wzywam duchy tego miejsca. Oddam wszystko i zapłacę każdą cenę, jeśli tylko pomożecie mi ocalić mój lud.', '', 0),
(27217, 'plPL', 'Och, moja głowa... G... Gdzie ja jestem?', '', 0),
(27218, 'plPL', 'Kim... Kim ja jestem?', '', 0),
(27225, 'plPL', 'Ruszamy!', 'Ruszamy!', 0),
(27228, 'plPL', 'No, jesteśmy na miejscu! Lodowy Młot siedzi w tym budynku wrykulów! Daj im popalić!', 'No, jesteśmy na miejscu! Lodowy Młot siedzi w tym budynku wrykulów! Daj im popalić!', 0),
(27236, 'plPL', 'Wygląda na to, że idzie burza, Kudłaczu...', '', 0),
(27237, 'plPL', '%s zaczyna warczeć...', '', 0),
(27238, 'plPL', 'Co się stało, kolego?', '', 0),
(27239, 'plPL', 'Hej, $n, nie bój się. To ja... czyli ty... z przyszłości. Jestem tu, żeby pomóc.', 'Hej, $n, nie bój się. To ja... czyli ty... z przyszłości. Jestem tu, żeby pomóc.', 0),
(27240, 'plPL', 'Co tam znalazłeś, piesku?', '', 0),
(27241, 'plPL', 'Niedobrze, Kudłaczu. Zostań tu i pilnuj domu, ja muszę poszukać jakiegoś żołnierza.', '', 0),
(27251, 'plPL', 'Uwaga... nadchodzą. Pomogę, ile zdołam. Tylko trzymajmy ich z dala od klepsydry!', 'Uwaga... nadchodzą. Pomogę, ile zdołam. Tylko trzymajmy ich z dala od klepsydry!', 0),
(27275, 'plPL', 'Patrz, $n, klepsydra ukazała Nozdormu!', 'Patrz, $n, klepsydra ukazała Nozdormu!', 0),
(27287, 'plPL', 'Żegnaj, $n. Utrzymaj nas przy życiu i załatw sobie lepszy ekwipunek!', 'Żegnaj, $n. Utrzymaj nas przy życiu i załatw sobie lepszy ekwipunek!', 0),
(27295, 'plPL', 'Przybyłem. Bierzemy się zatem do pracy?', '', 0),
(27296, 'plPL', 'W czym ten oto może ci pomóc, $gpanie:pani;?', '', 0),
(27298, 'plPL', 'Jak to działa?', 'Jak to działa?', 0),
(27299, 'plPL', 'Pokaż mi, co masz na wymianę.', 'Pokaż mi, co masz na wymianę.', 0),
(27300, 'plPL', 'Mój wspólnik zabija różne stworzenia, a ja wysysam cząstkę ich esencji... drobiazg, naprawdę; najmniejszy z okruchów. Nikt nie odczuje jej braku.$B$BMimo to, by wywiązać się ze swojej części umowy, płacę eterycznymi kredytami.$B$BKredyty te można w każdej chwili wymienić na przedmioty, które sprzedaję. Na pewno mam coś, co cię zainteresuje...', '', 0),
(27301, 'plPL', 'Nie do wiary, że kiedyś to $gnosiłem:nosiłam;.', 'Nie do wiary, że kiedyś to $gnosiłem:nosiłam;.', 0),
(27304, 'plPL', 'Popatrz tylko, jak walczysz; nic dziwnego, że $gzacząłem:zaczęłam; pić.', 'Popatrz tylko, jak walczysz; nic dziwnego, że $gzacząłem:zaczęłam; pić.', 0),
(27305, 'plPL', 'Co? Jestem tu $gsam:sama;? I mnie, i tobie na tym zależy, wiesz!', 'Co? Jestem tu $gsam:sama;? I mnie, i tobie na tym zależy, wiesz!', 0),
(27306, 'plPL', 'Cokolwiek się stanie, nie możesz zginąć, bo to by znaczyło, że przestanę istnieć, prawda? Ale przecież już tu $gbyłem:byłam;, kiedy $gbyłem:byłam; tobą. Nic już z tego nie rozumiem!', 'Cokolwiek się stanie, nie możesz zginąć, bo to by znaczyło, że przestanę istnieć, prawda? Ale przecież już tu $gbyłem:byłam;, kiedy $gbyłem:byłam; tobą. Nic już z tego nie rozumiem!', 0),
(27307, 'plPL', 'Rany, już $gzapomniałem:zapomniałam;, jak $gniedoświadczony:niedoświadczona; kiedyś $gbyłem:byłam;.', 'Rany, już $gzapomniałem:zapomniałam;, jak $gniedoświadczony:niedoświadczona; kiedyś $gbyłem:byłam;.', 0),
(27311, 'plPL', 'Wybacz, ale Chromie powiedziała, że nie wolno mi zdradzić ci niczego o twojej przyszłości. Mówiła, że jeśli to zrobię, przestanę istnieć.', 'Wybacz, ale Chromie powiedziała, że nie wolno mi zdradzić ci niczego o twojej przyszłości. Mówiła, że jeśli to zrobię, przestanę istnieć.', 0),
(27312, 'plPL', 'Szkoda, że nie pamiętam, ilu z Nieskończonego Stada miało próbować cię powstrzymać. Ta walka była tak dawno temu.', 'Szkoda, że nie pamiętam, ilu z Nieskończonego Stada miało próbować cię powstrzymać. Ta walka była tak dawno temu.', 0),
(27313, 'plPL', 'Słuchaj. Nie wolno mi tego mówić, ale będzie taka impreza, na którą dostaniesz zaproszenie. Cokolwiek zrobisz, NIE PIJ PONCZU!', 'Słuchaj. Nie wolno mi tego mówić, ale będzie taka impreza, na którą dostaniesz zaproszenie. Cokolwiek zrobisz, NIE PIJ PONCZU!', 0),
(27315, 'plPL', 'Uważaj na ton, chłopcze. Może i jesteś księciem, ale jako paladyn wciąż jestem twoim zwierzchnikiem!', '', 0),
(27320, 'plPL', 'Jak możesz w ogóle brać to pod uwagę? Musi być jakiś inny sposób.', '', 0),
(27322, 'plPL', 'Nie jesteś jeszcze moim królem, chłopcze! A nawet gdybyś nim był, nie wykonałbym tego rozkazu!', '', 0),
(27324, 'plPL', 'Zdrada? Czyś ty postradał rozum, Arthasie?', '', 0),
(27326, 'plPL', '', 'Arthasie! Nie możesz tak po prostu...', 0),
(27328, 'plPL', 'Właśnie przekroczyłeś straszliwą granicę, Arthasie.', '', 0),
(27330, 'plPL', '', 'Przykro mi, Arthasie. Nie mogę patrzeć, jak to robisz.', 0),
(27341, 'plPL', 'Oto twoja dola.', '', 0),
(27405, 'plPL', 'Szybciej, psy! Nie wolno nam ustawać w natarciu na intruzów!', '', 0),
(27406, 'plPL', 'Wkrótce kości Galakronda powstaną z wiecznego snu i sprowadzą na ten świat zniszczenie!', '', 0),
(27407, 'plPL', 'Słuchajcie mnie, sługi! Słuchajcie swego pana, Antioka! Podwójcie wysiłki albo poniesiecie konsekwencje porażki!', '', 0),
(27408, 'plPL', 'Król Lisz żąda, by pod Angrathar wysłano więcej żmijów mrozu! Spełnijcie jego żądania albo poznacie mój gniew!', '', 0),
(27409, 'plPL', 'Napastnicy u bram! Nie przepuśćcie nikogo do tego pradawnego grobu!', '', 0),
(27410, 'plPL', 'Kosa Antioka upada na ziemię!', '', 0),
(27415, 'plPL', 'Myślisz, że to zwycięstwo, śmiertelna istoto? Zmierz się z nieokiełznaną mocą Antioka!', '', 0),
(27416, 'plPL', 'Oto ona! Kosa Antioka!', '', 0),
(27440, 'plPL', 'Raz-dwa dowiozę cię do Chaty Bursztynowej Sosny! Musimy tylko zrobić po drodze jeden krótki przystanek...', 'Raz-dwa dowiozę cię do Chaty Bursztynowej Sosny! Musimy tylko zrobić po drodze jeden krótki przystanek...', 0),
(27442, 'plPL', 'Przelecimy szybko nad Warownią Podboju, żeby zobaczyć, co knuje ta plugawa, nic niewarta Horda. Wypatruj ich jeźdźców wiwern. Nie żeby mieli mnie kiedykolwiek dogonić!', 'Przelecimy szybko nad Warownią Podboju, żeby zobaczyć, co knuje ta plugawa, nic niewarta Horda. Wypatruj ich jeźdźców wiwern. Nie żeby mieli mnie kiedykolwiek dogonić!', 0),
(27443, 'plPL', 'Na Miedziobrodego, co tu się wyrabia? Spójrz tylko na to miejsce! Chyba...', 'Na Miedziobrodego, co tu się wyrabia? Spójrz tylko na to miejsce! Chyba...', 0),
(27444, 'plPL', 'Oho. Mamy towarzystwo! TRZYMAJ SIĘ MOCNO! Spróbuję ich zgubić!', 'Oho. Mamy towarzystwo! TRZYMAJ SIĘ MOCNO! Spróbuję ich zgubić!', 0),
(27472, 'plPL', 'Chyba ich zgubiliśmy! Mało brakowało! No, zgodnie z obietnicą: Chata Bursztynowej Sosny, w jednym kawałku! Trzymaj się ziemi!', 'Chyba ich zgubiliśmy! Mało brakowało! No, zgodnie z obietnicą: Chata Bursztynowej Sosny, w jednym kawałku! Trzymaj się ziemi!', 0),
(27518, 'plPL', 'Czy jesteście gotowi zrobić wszystko, co trzeba, by chronić Lordaeron?', '', 0),
(27574, 'plPL', 'Tak, to początek. Czekałem na ciebie, młody książę. Jestem Mal\'Ganis.', '', 0),
(27575, 'plPL', 'Jak widzisz, twój lud należy teraz do mnie. Będę przemieniał to miasto dom po domu, aż płomień życia zgaśnie... na zawsze.', '', 0),
(27716, 'plPL', 'Czas na zabawę!', '', 0),
(27717, 'plPL', 'Przybywasz za późno, czempionie Lordaeronu. Umarli doczekają się swojego dnia.', '', 0),
(27742, 'plPL', 'Pewnie należysz do dzielnych żołnierzy, którzy walczą z siłami Plagi Mal\'Ganisa. Dobra robota.', '', 0),
(27743, 'plPL', 'W istocie. Mal\'Ganis dowodzi Plagą z Placu Krzyżowców, ale bramy prowadzące tam od wejścia do miasta są zamknięte.$B$BNie wie jednak, że niewielki oddział wciąż może dotrzeć na plac przez ratusz. Przyłączysz się do mnie w tym ataku?', '', 0),
(27911, 'plPL', 'Książę Arthasie Menethilu, tego dnia twoją duszą zawładnęła potężna ciemność. Śmierć, którą masz nieść innym, dziś stanie się twoją własną.', '', 0),
(27920, 'plPL', 'Jeszcze się okaże, młody książę.', '', 0),
(28008, 'plPL', '%s wbija flagę własności w zwłoki gracza $n.', '%s wbija flagę własności w zwłoki gracza $n.', 0),
(28028, 'plPL', 'Wszystko trzęsło się na wszystkie strony. Ledwo mogłem utrzymać strzelbę prosto.', '', 0),
(28029, 'plPL', 'I wtedy ją zobaczyliśmy – straszliwą bestię!', '', 0),
(28030, 'plPL', '$n $gmusiał:musiała; użyć całego swego kunsztu, by utrzymać Stampy\'ego w ryzach.', '', 0),
(28032, 'plPL', 'Bitwa była mgłą krwi, ołowiu i potu. Matka miotu atakowała coraz szybciej i szybciej!', '', 0),
(28033, 'plPL', 'Ale w końcu $n i ja zwyciężyliśmy dzięki sprytowi i współpracy. A teraz mamy to wspaniałe trofeum na pamiątkę naszego zwycięstwa.', '', 0),
(28036, 'plPL', 'Czyżbym wyczuwał nutkę zazdrości, Dorianie?', '', 0),
(28038, 'plPL', 'Szybko zbierzcie się w sobie, musimy iść dalej.', '', 0),
(28043, 'plPL', 'Wcale nie robi się łatwiej. Stratholm płonie. Musimy stawić czoła Pladze i płomieniom, by dotrzeć do Mal\'Ganisa. Przygotujcie się.', '', 0),
(28091, 'plPL', 'Rubinowe smokowce celują w osłabianiu obrażeń i ochronie sojuszników.\nZa pomocą parzącego gniewu zioną strumieniami płynnego ognia, które przeskakują z celu na cel i z każdym skokiem zadają coraz większe obrażenia.\nIlekroć rubinowy smokowiec otrzyma obrażenia od ataku wroga, zyskuje wymijający ładunek. Ładunki te można wykorzystać do wykonania serii manewrów wymijających, dzięki którym smokowiec przez pewien czas unika nadchodzących ataków i zaklęć.', '', 0),
(28092, 'plPL', 'Bursztynowe smokowce celują w zadawaniu obrażeń, manipulując czasem na swoją korzyść.\nZa pomocą lancy wstrząsowej zakłócają przepływ czasu wokół wrogiego celu i natychmiast zadają mu obrażenia. Siłę tego efektu ogromnie zwiększają ładunki wstrząsowe na celu.\nW obliczu zagrożenia bursztynowy smokowiec potrafi na krótko zatrzymać przepływ czasu dla swoich wrogów. To zakłócenie czasu gromadzi na dotkniętych nim celach dużą ilość energii wstrząsowej w postaci ładunków wstrząsowych.', '', 0),
(28093, 'plPL', '', 'Szmaragdowe smokowce celują w leczeniu samych siebie i zatruwaniu wrogów.\nZa pomocą wysysającej trucizny kradną wrogom zdrowie. Kolejne dawki tej trucizny mogą wzmocnić efekt.\nDzięki dotknięciu koszmaru szmaragdowe smokowce sięgają w głąb Snu i zamieniają część swojej energii życiowej w niezwykle silny atak, który osłabia cel i na krótko zmniejsza zadawane przez niego obrażenia.', 0),
(28130, 'plPL', 'Dobrze się spisałeś, Drakuru.', '', 0),
(28131, 'plPL', 'Twoja zdrada Imperium Drakkarów dała mi nową armię.', '', 0),
(28133, 'plPL', 'Twoją armię...', '', 0),
(28134, 'plPL', 'Powstań i przyjmij mój dar.', '', 0),
(28136, 'plPL', 'Witaj, przyjacielu. Schyl głowę i trzymaj się mocno!', '', 0),
(28254, 'plPL', 'Używaj Parzącego gniewu, by ranić wrogów, a Manewrów wymijających, jeśli zacznę obrywać. Pamiętaj: żeby wykonać Manewry wymijające, muszę najpierw zebrać Wymijające ładunki, otrzymując obrażenia!', '', 0),
(28255, 'plPL', 'Używaj Wysysającej trucizny, by ranić wrogów i mnie leczyć. Dotknięcie koszmaru jest bardzo potężne, ale mnie rani, więc używaj go tylko wtedy, gdy mam dużo zdrowia!', '', 0),
(28256, 'plPL', 'Używaj Lancy wstrząsowej, by ranić wrogów. Jeśli wpadniemy w tarapaty, użyj Zatrzymania czasu, by unieruchomić wszystkich wrogów, a potem uderz w nich Lancą wstrząsową – zada ogromne obrażenia!', '', 0),
(28257, 'plPL', 'Mam ciężkie rany! Długo już tego nie wytrzymam!', '', 0),
(28258, 'plPL', 'Teraz, gdy mam pełnię mocy, mogę użyć Szczeliny czasu. Dzięki niej wrogowie otrzymują dodatkowe obrażenia, a ty zdobywasz Ładunki wstrząsowe. Zbierz Ładunki wstrząsowe, a potem użyj Lancy wstrząsowej, by zadać potężne obrażenia!', '', 0),
(28259, 'plPL', 'Teraz, gdy mam pełnię mocy, mogę użyć Lejka snów. Możesz nim leczyć inne smokowce, ale wysysa on moje zdrowie, więc pamiętaj, by używać też Wysysającej trucizny!', '', 0),
(28260, 'plPL', 'Teraz, gdy mam pełnię mocy, mogę użyć Męczennika. Możesz nim chronić inne smokowce, ale będę wtedy otrzymywać mnóstwo obrażeń, więc pamiętaj, by używać też Manewrów wymijających!', '', 0),
(28416, 'plPL', 'Powierzam ci teraz oczyszczenie Zul\'Draku, Drakuru.', '', 0),
(28417, 'plPL', 'Zawiedź mnie, a będzie to twoja zguba...', '', 0),
(28418, 'plPL', 'Jeśli ci się powiedzie, zyskasz jeszcze większą moc!', '', 0),
(28426, 'plPL', 'Najpotężniejsi agenci Malygosa strzegą pierścieni powyżej. W pojedynkę nie masz szans ich pokonać. Możemy obdarzyć cię mocą wzywania smokowców z naszych Stad. Na grzbiecie smokowca zdołasz latać tu, w Okulusie, i władać potężną smoczą magią.', '', 0),
(28506, 'plPL', 'Jesteście gotowi stawić ze mną czoła Mal\'Ganisowi?', '', 0),
(28528, 'plPL', 'Twoja podróż dopiero się zaczęła, młody książę. Zbierz swoje siły i spotkaj się ze mną w arktycznej krainie, w Północnej Grani. To tam wyrównamy rachunki. To tam wypełni się twoje prawdziwe przeznaczenie.', '', 0),
(28558, 'plPL', 'Masz ochotę spróbować nowego dżunglowego ponczu Grimbooze\'a Gromowara?', 'Masz ochotę spróbować nowego dżunglowego ponczu Grimbooze\'a Gromowara?', 0),
(28634, 'plPL', 'To muszą być ślady Shango.', 'To muszą być ślady Shango.', 0),
(28635, 'plPL', 'To nie są ślady Shango.', 'To nie są ślady Shango.', 0),
(28664, 'plPL', 'Lecimy! Uważaj na te pnącza!', '', 0),
(28665, 'plPL', 'Wygląda na to, że Plaga nieźle spustoszyła teren przed nami...', '', 0),
(28666, 'plPL', 'Widzisz to? Jest... ogromna!', '', 0),
(28667, 'plPL', 'Zaczyna się! Trzymaj się mocno – przed nami silny wiatr!', '', 0),
(28668, 'plPL', 'Lecą na nas! Szybko z tymi rakietami!', '', 0),
(28669, 'plPL', 'Aaaach! Dostałem! Musisz nas sprowadzić z powrotem! Szybko, zanim samolot wybuchnie!', '', 0),
(28699, 'plPL', 'Lodowiec wdziera się z Lodowej Korony... i wszędzie nieumarli! Niech no tylko profesor się o tym dowie!', '', 0),
(28715, 'plPL', 'Śmierć żywym!', 'Śmierć żywym!', 0),
(28832, 'plPL', '', 'CZAS UMIERAĆ, GŁUPCZE!', 0),
(28842, 'plPL', '', 'Wróciłam, by zaprosić cię na parapetówkę w zaświatach!', 0),
(28843, 'plPL', '', 'Powiedziałabym: chodź po dobroci, ale oboje wiemy, że nic z tego. Mój mały przyjaciel ułatwi ci drogę w zaświaty.', 0),
(28876, 'plPL', '', 'Dobra robota. Dopilnuję, by mój prorok cieszył się wiecznym pobytem u mnie.', 0),
(28898, 'plPL', 'Skąd to się wzięło? Lepiej zaniosę to na statki, zanim brygadzista zobaczy!', '', 0),
(28899, 'plPL', 'Zostawię to tutaj i nikt się nie dowie!', '', 0),
(28944, 'plPL', 'Przymierze zdobywa portal tytanów!', '', 0),
(28945, 'plPL', 'Horda zdobywa portal tytanów!', '', 0),
(29180, 'plPL', 'A teraz, Akali, mój pan dostanie twoją krew, a ja wezmę też trochę twojej mocy!', '', 0),
(29183, 'plPL', 'Dokonało się. Wracaj biegiem do swoich panów. Wracaj do Har\'koi. Powiedz jej, że nadchodzę!', '', 0),
(29202, 'plPL', 'Akolici, zakuć ich wszystkich w łańcuchy! Przygotować ich do przesłuchania!', '', 0),
(29214, 'plPL', 'Plugastwo Plagi! Niech Światłość cię oczyści!', '', 0),
(29215, 'plPL', 'Krucjata wypleni wasz rodzaj z tego świata!', '', 0),
(29216, 'plPL', 'Wygląda na to, że muszę zająć się tobą osobiście. Nadinkwizytor idzie po ciebie, pomiocie Plagi!', '', 0),
(29218, 'plPL', 'Twoja mroczna magia Plagi nie ochroni cię przed Światłością!', '', 0),
(29221, 'plPL', 'NIECH ŚWIATŁOŚĆ CIĘ ZMIECIE!', '', 0),
(29222, 'plPL', 'Szukasz wybawienia? Oto przybywam, by cię wybawić!', '', 0),
(29223, 'plPL', '%s – jego szczątki padają na ziemię.', '', 0),
(29245, 'plPL', '%s zdobywa osiągnięcie $a!', '%s zdobywa osiągnięcie $a!', 0),
(29269, 'plPL', '', 'PROROKU!', 0),
(29272, 'plPL', '', 'TRZYMAJ SWOJE PLUGAWE DRAKKARSKIE ŁAPY Z DALA OD NICH!', 0),
(29274, 'plPL', '', 'NIE SĄDZĘ. ZRZUCISZ SWOJĄ NIETYKALNOŚĆ, NATYCHMIAST PRZERWIESZ RYTUAŁ I ICH UWOLNISZ!', 0),
(29276, 'plPL', '', 'Dziękuję. Po raz kolejny $gocaliłeś:ocaliłaś; nas wszystkich. Do zobaczenia w Zim\'Torga.', 0),
(29440, 'plPL', 'Żegnaj.', '', 0),
(29448, 'plPL', 'Runda 2 bitwy o Wybrzeże Pradawnych rozpocznie się za 1 minutę.', '', 0),
(29449, 'plPL', 'Runda 2 rozpocznie się za 30 sekund. Przygotujcie się!', '', 0),
(29473, 'plPL', 'Brama została sforsowana! Szybko, skierujcie siły do walki z tymi najeźdźcami!', '', 0),
(29518, 'plPL', 'Pozostało konstruktów wirówki: $3486W. Musimy je znaleźć i zniszczyć, by wyłączyć tarczę ochronną Varosa Obłokokroczącego. Konstrukty powinny być mniej więcej w połowie wysokości Okulusa, w Pasie Przyspieszenia.', '', 0),
(29519, 'plPL', 'Pozostał jeden konstrukt wirówki. Musimy go znaleźć i zniszczyć, by wyłączyć tarczę ochronną Varosa Obłokokroczącego. Konstrukt powinien być mniej więcej w połowie wysokości Okulusa, w Pasie Przyspieszenia.', '', 0),
(29520, 'plPL', 'Tarcza opadła; Varos jest odsłonięty! Pokonanie go powinno rozproszyć lazurowych strażników pierścienia i otworzyć nam drogę do wyższych pasów. Varos jest na lewitującej platformie mniej więcej w połowie wysokości Okulusa, w Pasie Przyspieszenia.', '', 0),
(29521, 'plPL', 'Naszym następnym celem jest Władca Magów Urom. Powinien ukrywać się na jednej z lewitujących platform w Pasie Transmutacji, blisko szczytu Okulusa. Uważaj, Urom to potężny przywoływacz; może nie być sam.', '', 0),
(29522, 'plPL', 'Już tylko Strażnik Linii Mocy Eregos stoi między nami a panowaniem nad Okulusem. Lata nad Pasem Wyrównania, na samym szczycie Okulusa. Eregos jest niewiarygodnie potężny; gdy go zaatakujemy, zostań na moim grzbiecie, a walkę zostaw mnie.', '', 0),
(29523, 'plPL', 'Wydarliśmy Okulus z rąk sił Malygosa. A ty, maleństwo, wcale nie robisz się lżejsze. Moje skrzydła rwą się na otwarte niebo.', '', 0),
(29536, 'plPL', 'Varos Obłokokroczący i jego strażnicy pierścienia chronią drugi pierścień. Twoje smokowce z nawiązką dorównują strażnikom pierścienia, ale Varos stoi za nieprzeniknioną tarczą stworzoną z energii samego Okulusa. Tarczę zasila dziesięć konstruktów wirówki z pierścienia i platform powyżej. Zniszcz je, a Varos stanie się podatny na ataki.', 'Varos Obłokokroczący i jego strażnicy pierścienia chronią drugi pierścień. Twoje smokowce z nawiązką dorównują strażnikom pierścienia, ale Varos stoi za nieprzeniknioną tarczą stworzoną z energii samego Okulusa. Tarczę zasila dziesięć konstruktów wirówki z pierścienia i platform powyżej. Zniszcz je, a Varos stanie się podatny na ataki.', 0),
(29561, 'plPL', 'Ostrzeżenie: nie rozpoznano wzorca formy życia. Przetwarzanie archiwalne przerwane. Dalsza ingerencja spowoduje ukierunkowaną reakcję.', '', 0),
(29575, 'plPL', '', 'Trwa naruszenie zabezpieczeń. Analizę archiwów historycznych przeniesiono do kolejki o niższym priorytecie. Uruchomiono środki zaradcze.', 0),
(29576, 'plPL', '', 'Przekroczono próg wskaźnika zagrożenia. Archiwum niebiańskie przerwane. Podwyższono poziom zabezpieczeń.', 0),
(29577, 'plPL', 'Krytyczny wskaźnik zagrożenia. Analiza Pustki przekierowana. Uruchamianie protokołu sanityzacji.', '', 0),
(29579, 'plPL', 'Alarm: zabezpieczenia awaryjne wyłączone. Rozpoczynanie czyszczenia pamięci i...', '', 0),
(29580, 'plPL', 'System uruchomiony. Rozpoznano wzorzec formy życia. Witaj, Branbronzan. Zapytanie?', '', 0),
(29622, 'plPL', 'Co to ma być? Mok-thorin ka! Zabić ich!', '', 0),
(29623, 'plPL', 'Nasze zadanie nie jest jeszcze skończone!', '', 0),
(29624, 'plPL', 'Gaagh...', '', 0),
(29672, 'plPL', '', 'Unicestwię twoją duszę!', 0),
(29675, 'plPL', '', 'Głupotą było rzucać wyzwanie potędze Króla Lisza!', 0),
(29676, 'plPL', '', 'Stało się wedle twej woli, mój królu!', 0),
(29677, 'plPL', '', 'Kolejna dusza dla mojego pana!', 0),
(29678, 'plPL', '', 'Twoja śmierć nadchodzi...', 0),
(29679, 'plPL', '', 'Idź teraz do mojego pana!', 0),
(29680, 'plPL', '', 'Twój koniec jest nieunikniony.', 0),
(29681, 'plPL', '', 'Yor-guul mak!', 0),
(29682, 'plPL', '', 'Jakieś ostatnie słowa?', 0),
(29683, 'plPL', '', 'Nieee! Nie zaszłam tak daleko... żeby...', 0),
(29686, 'plPL', '', 'To uczucie... przechodzi moje wyobrażenia. Jestem na twoje rozkazy, mój królu.', 0),
(29687, 'plPL', '', 'Z radością wyrżnę ich w twoim imieniu! Chodźcie, wrogowie Plagi! Pokażę wam potęgę Króla Lisza!', 0),
(29688, 'plPL', 'Twoja ofiara świadczy o twoim posłuszeństwie. Zaprawdę jesteś godna tego zaszczytu. Powstań i odtąd na zawsze zwij się Svala Smętnogrobna!', '', 0),
(29689, 'plPL', 'Czeka cię pierwsza próba. Zniszcz naszych nieproszonych gości.', '', 0),
(29723, 'plPL', 'Trwajcie, bracia i siostry! Światłość zwycięży!', '', 0),
(29724, 'plPL', 'Nadciągają armie Plagi!', '', 0),
(29743, 'plPL', 'Nie możesz wygrać, Darionie!', '', 0),
(29744, 'plPL', 'Niczego się nie nauczyłeś, chłopcze? Stałeś się wszystkim tym, z czym walczył twój ojciec! Jak ten tchórz Arthas pozwoliłeś, by pochłonęły cię ciemność i nienawiść... karmisz się niedolą tych, których torturowałeś i zabiłeś!', '', 0),
(29745, 'plPL', 'Twój pan wie, co kryje się pod kaplicą. Dlatego nie śmie pokazać twarzy! Wysłał ciebie i twoich rycerzy śmierci na zgubę, Darionie.', '', 0),
(29746, 'plPL', 'To, co teraz czujesz, to udręka tysiąca zagubionych dusz! Dusz, które ty i twój pan tu sprowadziliście! Światłość rozerwie cię na strzępy, Darionie!', '', 0),
(29756, 'plPL', 'Zaprowadźcie ich przed kaplicę!', '', 0),
(29758, 'plPL', '%s ucieka.', '', 0),
(29762, 'plPL', 'Mój synu! Mój drogi, piękny chłopcze!', '', 0),
(29769, 'plPL', 'Ojcze, wróciłeś!', '', 0),
(29770, 'plPL', 'Długo cię nie było, ojcze. Myślałem...', '', 0),
(29771, 'plPL', '%s przytula ojca.', '', 0),
(29773, 'plPL', 'Nic nie mogłoby mnie zatrzymać z dala od tego miejsca, Darionie. Z dala od domu i rodziny.', '', 0),
(29774, 'plPL', 'Ojcze, pragnę dołączyć do ciebie w wojnie z nieumarłymi. Chcę walczyć! Nie mogę dłużej siedzieć bezczynnie!', '', 0),
(29775, 'plPL', 'Darionie Mograine, ledwie dorosłeś do tego, by utrzymać miecz, a co dopiero walczyć z nieumarłymi hordami Lordaeronu! Nie zniósłbym, gdybym cię stracił. Sama myśl o tym...\n', '', 0),
(29776, 'plPL', 'Jeśli mam umrzeć, ojcze, to wolę stojąc, stawiając czoła legionom nieumarłych! Jeśli mam umrzeć, pozwól mi umrzeć u twego boku!', '', 0),
(29777, 'plPL', 'Mój synu, nadejdzie dzień, gdy to ty będziesz władał Spopielaczem i wymierzał nim sprawiedliwość w całej tej krainie. Nie mam wątpliwości, że gdy ten dzień wreszcie nadejdzie, przyniesiesz chlubę naszemu ludowi, a Lordaeron stanie się dzięki tobie lepszym miejscem. Ale ten dzień, mój synu, to jeszcze nie dziś.\n', '', 0),
(29778, 'plPL', 'Nie zapomnij...', '', 0),
(29779, 'plPL', 'Wzruszające...', '', 0),
(29780, 'plPL', 'Teraz jest mój...', '', 0),
(29783, 'plPL', 'Jesteś przeklętym potworem, Arthasie!', '', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(29784, 'plPL', 'Miałeś rację, Fordring. Posłałem ich na śmierć. Ich życie nic nie znaczy, ale twoje...', '', 0),
(29785, 'plPL', 'Jakże łatwo było wywabić wielkiego Tiriona Fordringa z kryjówki. Odsłoniłeś się, paladynie. Nic cię nie ocali.', '', 0),
(29803, 'plPL', 'ARTHASIE!!!!', '', 0),
(29826, 'plPL', 'To... jeszcze nie koniec!', '', 0),
(29827, 'plPL', 'Gdy spotkamy się następnym razem, nie będzie to na świętej ziemi, paladynie.', '', 0),
(29835, 'plPL', 'Powstań, Darionie, i słuchaj...\n', '', 0),
(29843, 'plPL', 'Wszyscy byliśmy świadkami straszliwej tragedii. Krew dobrych ludzi przelała się na tę ziemię! Honorowi rycerze polegli, broniąc swojego życia – naszego życia!', '', 0),
(29845, 'plPL', 'I choć takich rzeczy nie da się zapomnieć, musimy niezłomnie trwać przy naszej sprawie!\n', '', 0),
(29846, 'plPL', 'Król Lisz musi odpowiedzieć za to, co uczynił, i nie wolno pozwolić, by siał dalsze zniszczenie w naszym świecie.', '', 0),
(29847, 'plPL', 'Składam wam teraz obietnicę, bracia i siostry: Król Lisz zostanie pokonany! W dniu dzisiejszym wzywam do zjednoczenia.', '', 0),
(29848, 'plPL', 'Argentowy Brzask i Zakon Srebrnej Dłoni połączą się w jedno! Powiedzie nam się tam, gdzie tak wielu przed nami zawiodło!\n', '', 0),
(29849, 'plPL', 'Zaniesiemy walkę do Arthasa i zburzymy mury Lodowej Korony!', '', 0),
(29850, 'plPL', 'Krucjata Argentu idzie po ciebie, Arthasie!\n', '', 0),
(29861, 'plPL', 'Twój koniec.', '', 0),
(29887, 'plPL', 'Gwardzista krypty dołącza do walki!', '', 0),
(29941, 'plPL', 'To nie zabawa...', '', 0),
(29942, 'plPL', 'Nowe zabawki!', '', 0),
(29943, 'plPL', 'Nuda...', '', 0),
(29944, 'plPL', 'Czemu ty się nie ruszać?', '', 0),
(29945, 'plPL', 'Wstawać! Ja jeszcze nie skończyć!', '', 0),
(29946, 'plPL', 'Przyspieszacie tylko... plan pana...', '', 0),
(29947, 'plPL', 'Ach, rozrywka przybyła!', '', 0),
(29948, 'plPL', 'Zabawa dopiero się zaczyna!', '', 0),
(29949, 'plPL', 'Ach! Materiał wysokiej jakości.', '', 0),
(29950, 'plPL', 'Bez obaw, zrobię z was dobry użytek!', '', 0),
(29951, 'plPL', 'Przywitajcie się z moimi przyjaciółmi.', '', 0),
(29952, 'plPL', 'Chodźcie, mieszkańcy Stratholmu! Poznajcie swoich „wybawców”.', '', 0),
(29953, 'plPL', 'BUM! Hahahahah...', '', 0),
(29954, 'plPL', 'Krew... zniszczenie... CO ZA UPOJENIE!', '', 0),
(29955, 'plPL', 'Chcę próbkę...', '', 0),
(29956, 'plPL', 'Taka siła... musi być moja!', '', 0),
(29957, 'plPL', 'Ciało cię zdradza.', '', 0),
(29980, 'plPL', '', 'Ingvarze! Twoja żałosna porażka posłuży za przestrogę dla wszystkich... jesteś przeklęty! Powstań i wypełnij wolę pana!', 0),
(29982, 'plPL', 'To ty powinieneś cierpieć. Ciesz się, że twoja śmierć jest szybka...', '', 0),
(29983, 'plPL', 'A co do ciebie...', '', 0),
(29984, 'plPL', 'Daruję ci twe nic nieznaczące życie w nagrodę za tę zabawną zdradę. Być może drzemie w tobie jeszcze odrobina potencjału.', '', 0),
(29985, 'plPL', 'Przy następnym spotkaniu będę wymagał znacznie więcej, by twoje życie miało rację bytu.', '', 0),
(29986, 'plPL', 'Zawiodłeś mnie, Drakuru!', '', 0),
(29989, 'plPL', 'Strzeż się...', '', 0),
(30229, 'plPL', 'Warsztat pojazdów Rigsparka zaprasza!', 'Warsztat pojazdów Rigsparka zaprasza!', 0),
(30230, 'plPL', 'Salon pojazdów Iskrobłyska zaprasza!', 'Salon pojazdów Iskrobłyska zaprasza!', 0),
(30242, 'plPL', 'Niczego ze mnie nie wyciągniesz, potworze. Nie masz już na mnie żadnego wpływu.', '', 0),
(30245, 'plPL', 'PRZESTAŃ! To nie jest tego warte. Powiem ci, gdzie on jest.', '', 0),
(30247, 'plPL', 'Na południowym krańcu wyspy jest jaskinia – ukryta grota. Wielki admirał zaszył się tam i szykuje się do ostatecznej bitwy z Królem Liszem.', '', 0),
(30250, 'plPL', 'AAAEEEEIIIiiiiiiiiiiiiiiiiiiiiiiiiiiii........................................', '', 0),
(30412, 'plPL', 'Anakh kyree!', '', 0),
(30413, 'plPL', 'Mój Szturm zaleje siły Króla Lisza!', '', 0),
(30414, 'plPL', 'Twoja śmierć jest daremna, maleńka śmiertelna istoto.', '', 0),
(30415, 'plPL', 'Twój czas dobiegł końca.', '', 0),
(30451, 'plPL', 'Tik-tak, tik-tak...', '', 0),
(30452, 'plPL', 'Za wolno!', '', 0),
(30453, 'plPL', 'Miejmy to już z głowy.', '', 0),
(30454, 'plPL', 'Nie ma dla was przyszłości.', '', 0),
(30455, 'plPL', 'Oto godzina naszego największego triumfu!', '', 0),
(30456, 'plPL', 'Porażka była wam przeznaczona.', '', 0),
(30470, 'plPL', '', 'Mój drogi generale, nadszedł twój czas!', 0),
(30471, 'plPL', 'MIAŻDŻYĆ!', '', 0),
(30472, 'plPL', 'MRMRFRMRFRMRRRR!', '', 0),
(30548, 'plPL', 'Żelazne krasnoludy ruszyły za tobą! Użyj sieci i lodowej ślizgawki, by uciec!', '', 0),
(30549, 'plPL', 'Odmrożenie dotarło tropem zapachu do jego źródła. Zbadaj jaskinię!', '', 0),
(30550, 'plPL', '%s węszy i odnajduje trop.', '', 0),
(30551, 'plPL', '%s dociera tropem zapachu do jego źródła w jaskini.', '', 0),
(30603, 'plPL', '', 'Uzyskiwanie dostępu... Stwórcy przybyli, by wyplenić symbiotyczną infekcję. Ocena wykazała, że inwazja Przedwiecznych przybrała postać złośliwą. Wycięcie pasożytów skutkowałoby utratą żywiciela--', 0),
(30604, 'plPL', '', 'Zgadza się. Stwórcy zneutralizowali pasożytnicze zagrożenie i zamknęli je wewnątrz żywiciela. Uruchomiono Kuźnię Woli i inne systemy, by tworzyć nowych ziemnych. Wdrożono zabezpieczenia i wyznaczono obrońców.', 0),
(30605, 'plPL', '', 'Oznaczenia: Aesir i Vanir. Czyli w potocznym nazewnictwie olbrzymy burzy i ziemi. Strażnika Lokena wyznaczono na zwierzchnika. Smocze Aspekty powołano do nadzoru nad ewolucją Azeroth.', 0),
(30606, 'plPL', '', 'Dodatkowe informacje istotne dla zapytania: w następstwie globalnego starcia między Aesir a Vanir--', 0),
(30607, 'plPL', '', 'Nieznane. Dane wskazują, że impuls do globalnego starcia wyszedł od Głównego Wyznaczonego Lokena, który zneutralizował wszystkich pozostałych Aesir i Vanir, doprowadzając do zakończenia konfliktu. Następnie Główny Wyznaczony Loken zainicjował stazę kilku ras zalążkowych, w tym ziemnych, olbrzymów i wrykulów, w wyznaczonych ośrodkach przechowywania.', 0),
(30608, 'plPL', '', 'Zasadniczo się zgadza.', 0),
(30611, 'plPL', 'Uzyskiwanie dostępu do danych prehistorycznych... pobrano. Na początku ziemnych stworzono, by--', '', 0),
(30612, 'plPL', 'Uzyskiwanie dostępu... We wczesnych stadiach swojego cyklu rozwojowego Azeroth uległo infekcji pasożytniczymi nekrofotycznymi symbiontami.', '', 0),
(30613, 'plPL', 'Oznaczenie: Przedwieczni. Przedwieczni pozbawili obrony wszystkie systemy, w tym ziemnych, aby ułatwić asymilację. Tę destabilizację matrycy określono mianem „Klątwy Ciała”. Skutki destabilizacji narastały z czasem.', '', 0),
(30614, 'plPL', 'Przyjęto, Branbronzan. Sesja zakończona.', '', 0),
(30668, 'plPL', 'Rycerze śmierci... do mnie!', '', 0),
(30683, 'plPL', '%s wyłania się!', '', 0),
(30688, 'plPL', 'Smrodobrody idzie po was, maleństwa!', '', 0),
(30689, 'plPL', 'Stopię wam ciało z kości!', '', 0),
(30699, 'plPL', 'Tchórz!', '', 0),
(30700, 'plPL', 'Powstańcie, bracia ziemi! Patrzcie, jak Erathius niszczy śmiertelników!', '', 0),
(30701, 'plPL', 'Za Neptulona! Siło burzy i morza, zmiażdż moich wrogów!', '', 0),
(30702, 'plPL', 'Al\'Akirze, ześlij moim wrogom zimną, szybką śmierć!', '', 0),
(30704, 'plPL', 'Chodźcie, szczury lądowe, poznajcie furię kła i wąsa!', '', 0),
(30705, 'plPL', 'Korrak przybył, słabeusze! Śniegospad należy do Zimowego Topora! Eee, Korrak chciał powiedzieć, że amfiteatr należy do Zimowego Topora!', '', 0),
(30706, 'plPL', 'Nie ma tu cmentarza, żebyście mogli stroić sobie z Korraka podłe żarty! GIŃCIE!', '', 0),
(30708, 'plPL', 'Tak, mój skarbie, rozszarpiemy ich na strzępy! Za jedynego prawdziwego króla!', '', 0),
(30709, 'plPL', 'Bezużyteczny kundel! Sam ich zabiję!', '', 0),
(30710, 'plPL', 'Vladof zsiada z wierzchowca!', '', 0),
(30717, 'plPL', '%s zbiera swoje mojo i rusza naprzód!', '', 0),
(30727, 'plPL', '%s wpada w coraz większy obłęd!', '', 0),
(30767, 'plPL', 'Jestem królem brudu, nikt nie stoi wyżej! Na pomoc, sługi – stańcie przy mnie bliżej!', '', 0),
(30768, 'plPL', 'Ogniem mojego królestwa nie spalicie! Do mnie, sługi – za wcześnie mi kończyć życie!', '', 0),
(30769, 'plPL', 'Niosę podmuch tak silny, że drzewa powala! Sługi, do mnie – na swawolę im się nie pozwala!', '', 0),
(30770, 'plPL', 'Jestem najgorszy z najgorszych, najzimniejszy z zimnych! Do mnie, moje żywioły – zamroźmy ich i władajmy nad innymi!', '', 0),
(30784, 'plPL', 'Wąsik! Gdzie jesteś?! Pomóż mi!', '', 0),
(30791, 'plPL', '%s zaczyna wirować, otoczony magiczną tarczą!', '', 0),
(30863, 'plPL', 'Oddaję się panu!', 'Oddaję się panu!', 0),
(31000, 'plPL', 'Trzymaj się, $gmaleńki:maleńka;.', '', 0),
(31018, 'plPL', 'Thorimie! Przybądź, ukaż się!', '', 0),
(31023, 'plPL', 'Nie wiem, jak ci dziękować za całą pomoc przy składaniu zwornika. Wynikną z tego wielkie rzeczy, zapewniam cię.', '', 0),
(31024, 'plPL', 'Żelazne krasnoludy... wszędzie... schodzą ze szczytu. Trzeba przyznać, że są wytrwałe.', '', 0),
(31025, 'plPL', 'Próbują strącić samolot! Nie mogę wznosić się bardziej stromo... musisz ich od nas odpędzić!', '', 0),
(31026, 'plPL', 'Przed nami jest ich więcej – tak trzymaj!', '', 0),
(31027, 'plPL', 'Już prawie się wydostaliśmy... jeszcze tylko kawałeczek.', '', 0),
(31028, 'plPL', 'O ile nie trafi nas zbłąkany głaz któregoś z tych olbrzymów, powinniśmy być bezpieczni... ale tam w dole panuje niezły bałagan.', '', 0),
(31029, 'plPL', 'Jest ich niewiarygodnie wielu... Cieszę się, że król Burzowe Serce przyszedł ci z pomocą. Słyszę o nim same dobre rzeczy – chyba najwyższy czas, żebyśmy się poznali.', '', 0),
(31030, 'plPL', 'Biedny Creteus. Był dobrym strażnikiem... Cieszę się, że przynajmniej doczekał wykonania swego zadania; myślę, że tylko to się dla niego naprawdę liczyło.', '', 0),
(31031, 'plPL', 'Zbliżamy się do Mroźnej Warowni. Będę bardzo wdzięczny, jeśli przed odejściem przedstawisz mnie królowi Burzowe Serce. Sądzę, że i ty, i ja wiele mu zawdzięczamy.', '', 0),
(31051, 'plPL', 'Czyny $gtwojego sługi:twojej służki; przerastają $gjego:jej; posturę, Władco Burz. $GJego:Jej; starania zdołały zmiękczyć serca mojego ludu.', '', 0),
(31052, 'plPL', 'Nigdy jeszcze tak pokorne słowa nie padły z ust potężnego Thorima. Przekażę twoje słowa do Dun Niffelem.', '', 0),
(31053, 'plPL', 'Mój lud niniejszym wybacza wydarzenia tamtego mrocznego dnia. Nigdy więcej nie będzie się o nich mówić.', '', 0),
(31054, 'plPL', 'Na znak naszej przekutej na nowo przyjaźni mam coś, co należy do ciebie...', '', 0),
(31057, 'plPL', 'Gdy wielka eksplozja ogarnęła okolicę, mój ojciec cisnął w wielki młot runą, by nie dostał się w ręce naszych wrogów. To był jego ostatni czyn...', '', 0),
(31059, 'plPL', 'Z radością staniemy do walki u twego boku, potężny Thorimie.', '', 0),
(31060, 'plPL', 'Muszę wracać do Dun Niffelem. Wkrótce znów porozmawiamy, Władco Burz.', '', 0),
(31159, 'plPL', 'Uwaga tam w dole!', '', 0),
(31160, 'plPL', 'Spokojnie, mała! Nie poznajesz swojego dawnego pana?', '', 0),
(31161, 'plPL', 'Do zobaczenia w Świątyni Burz. Wygląda na to, że będę musiał ją na nowo ujeździć.', '', 0),
(31179, 'plPL', 'Zostałem wybrany!', 'Zostałem wybrany!', 0),
(31190, 'plPL', '', 'Ktoś mnie wzywał...?', 0),
(31215, 'plPL', '', 'Thanie Illskarze, wyzwano cię na honorowy pojedynek i poniosłeś klęskę.', 0),
(31216, 'plPL', '', 'Zważono cię i uznano za zbyt lekkiego, i stosownie do tego osądzono. A teraz powstań, thanie Illskarze Potępiony!', 0),
(31226, 'plPL', 'Gdy %s rozpada się, a jego ostatnie resztki wsiąkają w ziemię, ołtarz osadzony w pobliskiej posadzce zaczyna słabo lśnić.', '', 0),
(31260, 'plPL', 'Nie trudź się, mały taurenie. Ani Burzokopyty, ani ty i twój sojusznik nie staniecie mi na drodze.', '', 0),
(31261, 'plPL', 'Moja moc rośnie nawet teraz. Od dawna czekam na dzień, w którym dopełni się moja zemsta.', '', 0),
(31262, 'plPL', 'Burzokopyty i jego ród zostaną wymazani z historii, a te ziemie wrócą do prawowitego właściciela!', '', 0),
(31344, 'plPL', 'To będzie niezła próba, książę Arthasie.', '', 0),
(31345, 'plPL', 'Koniec czasu.', '', 0),
(31346, 'plPL', 'Chyba ogarnia was zmęczenie.', '', 0),
(31347, 'plPL', 'Aż nazbyt łatwe.', '', 0),
(31348, 'plPL', 'Mroczny Pan jest niezadowolony z waszej ingerencji.', '', 0),
(31349, 'plPL', 'To księcia Arthasa chcę, nie was!', '', 0),
(31446, 'plPL', 'Pani.', '', 0),
(31476, 'plPL', 'Są wieści z Jotunheim. Tamtejsi strażnicy snu sądzą, że znaleźli kogoś ważnego.', '', 0),
(31477, 'plPL', 'Kultysta aż się jąka.', '', 0),
(31478, 'plPL', 'Jak wygląda, pani? Chyba jak wrykul. Właściwie to mi go nie pokazali. Odkąd Krypta Cienia...', '', 0),
(31479, 'plPL', 'Imię? A tak, imię! Zdaje się, że Iskalder.', '', 0),
(31480, 'plPL', 'Natychmiast, pani.', '', 0),
(31481, 'plPL', '', 'Melduj.', 0),
(31482, 'plPL', '', 'Opisz tego wrykula. Jak wygląda?', 0),
(31483, 'plPL', '', 'Nie interesują mnie wymówki. Może podali ci imię?', 0),
(31484, 'plPL', '', 'Iskalder?! Głupcze! Nie masz pojęcia, kto to? To tylko największy wojownik wrykulów wszech czasów!', 0),
(31485, 'plPL', '', 'Wracaj do Jotunheim i każ im trzymać go we śnie do mojego przybycia. Osądzę tego wrykula na własne oczy.', 0),
(31523, 'plPL', 'To Iskalder! Szybko, użyj Amuletu Kościanej Wiedźmy!', 'To Iskalder! Szybko, użyj Amuletu Kościanej Wiedźmy!', 0),
(31528, 'plPL', '', 'Iskalderze, tu jesteś. A to co? Już walczysz?', 0),
(31530, 'plPL', '', 'NIE! Jak to możliwe?', 0),
(31531, 'plPL', '', 'Nie wiem, jak to możliwe, ale i tak musisz zostać osądzony, Iskalderze. Zaraz... co to ma być?', 0),
(31532, 'plPL', '', 'To? To ja przejmuję nad tobą kontrolę. To ja szykuję swoją ostateczną zemstę!', 0),
(31533, 'plPL', '', 'Trzymaj się ode mnie z daleka, stworze! Nie dotykaj mnie!', 0),
(31534, 'plPL', '', 'Ahahahahahaha! Dokonało się. Wracaj do mojej jaskini. Mamy wiele do omówienia!', 0),
(31539, 'plPL', 'Zatknięto Błogosławiony sztandar Krucjaty.\nBroń sztandaru przed wszystkimi napastnikami!', '', 0),
(31550, 'plPL', 'O, brawo. Jesteś z siebie $gdumny:dumna; teraz, gdy ta straszliwa pomyłka wydostała się na wolność?', '', 0),
(31551, 'plPL', 'I tak przeznaczyłem go już do utylizacji, ale chyba możemy nieco przyspieszyć sprawę.', '', 0),
(31553, 'plPL', 'Szkoda, że zmarnuje się tyle dobrych części, i to nadających się do ponownego użytku...', '', 0),
(31560, 'plPL', 'NA ŚWIATŁOŚĆ! Przeklęte potwory! Patrzcie, co zrobiły z naszymi ludźmi!', '', 0),
(31561, 'plPL', 'Spalcie to, chłopcy. Spalcie wszystko do cna.', '', 0),
(31562, 'plPL', 'Niech przychodzą. Zapłacą za to, co zrobili!', '', 0),
(31563, 'plPL', 'Ty iść szukać Margaux Parchley. Ona ładna pani w Aptekarium.', 'Ty iść szukać Margaux Parchley. Ona ładna pani w Aptekarium.', 0),
(31564, 'plPL', 'Fryzjer? To Naznik! On na górnym piętrze Dzielnicy Handlowej, koło banku.', 'Fryzjer? To Naznik! On na górnym piętrze Dzielnicy Handlowej, koło banku.', 0),
(31573, 'plPL', 'Udało się, chłopaki! Odbiliśmy szczyt z rąk Plagi! Meldujcie się natychmiast u ojca Gustava i przekażcie mu dobre wieści! Bierzemy się za budowę i urządzanie! Jazda!', '', 0),
(31670, 'plPL', '%s kuli się ze strachu.', '%s kuli się ze strachu.', 0),
(31836, 'plPL', 'Gdy tu skończę, zawieszę wasze głowy na ścianach Azjol-Nerub!', '', 0),
(31843, 'plPL', '%s przygotowuje wielką ucztę!', '%s przygotowuje wielką ucztę!', 0),
(31844, 'plPL', '$n przygotowuje ucztę rybną!', '$n przygotowuje ucztę rybną!', 0),
(31845, 'plPL', '$n przygotowuje małą ucztę!', '$n przygotowuje małą ucztę!', 0),
(31846, 'plPL', '$n przygotowuje gigantyczną ucztę!', '$n przygotowuje gigantyczną ucztę!', 0),
(31882, 'plPL', '', 'A, tu jesteś! Pamiętasz mnie? Oczywiście, że tak! Zaczekaj tam, już schodzę.', 0),
(31883, 'plPL', '', 'Mówiłam, że przy następnym spotkaniu będę lepiej przygotowana. Walczyłam w Hyldsmeet i zwyciężyłam, szkoliłam się w Valkyrionie i oto jestem. No chodź, spróbuj szczęścia!', 0),
(31935, 'plPL', 'DOŚĆ! Wy, marne insekty, nie jesteście godni walczyć w tym świętym miejscu! Nie walczycie z honorem! Nie dostępujecie nawet wyniesienia!', '', 0),
(31936, 'plPL', 'Walczcie ze mną i gińcie, tchórze!', '', 0),
(31956, 'plPL', 'Trudno to nazwać godną zapowiedzią, Żono Włóczni. No dobrze, kim jest $gten przybysz:ta przybyszka;, o $gktórym:której; tyle słyszałem?', '', 0),
(31957, 'plPL', 'Ułatwię ci to, jak tylko mogę. Po prostu podejdź tu i zgiń. O nic więcej nie proszę za twoje liczne występki. Za to, że kalasz to wzniosłe miejsce walki.', '', 0),
(31972, 'plPL', 'ZA TWOJĄ ZUCHWAŁOŚĆ WOBEC KRÓLA LISZA!', '', 0),
(31973, 'plPL', 'Śmiecie sądzić, że pokrzyżowaliście moją wolę? Że zniweczyliście moje plany?', '', 0),
(31974, 'plPL', 'Niczego nie osiągnęliście!', '', 0),
(31976, 'plPL', 'Wasz mizerny opór jedynie przyspieszył waszą zgubę.', '', 0),
(31979, 'plPL', 'Plećcie więc swoje frazesy i miotajcie się, aż opadniecie z sił. Na końcu i tak będziecie moi, a Morbidus będzie zwiastunem waszej śmierci!', '', 0),
(31981, 'plPL', 'Morbidusie, pokaż im, co spotyka tych, którzy sprzeciwiają się woli swego króla!', '', 0),
(32171, 'plPL', 'Niszczysz nasze surowce, co? Cóż, pan ma wobec ciebie szczególne plany...', '', 0),
(32173, 'plPL', 'Patrz! Co tu robi żmij mrozu? Leci prosto na nas.', '', 0),
(32198, 'plPL', 'Zapłacisz za swoje czyny! Za Krucjatę Argentu!', '', 0),
(32288, 'plPL', '', 'Thrallu, co się stało? Król szykuje się do wojny...', 0),
(32296, 'plPL', '', 'Przekażę te wieści królowi Wrynnowi, Thrallu, ale...', 0),
(32297, 'plPL', '', 'Bolvar był dla niego jak brat. Pod nieobecność króla to Bolvar utrzymywał jedność Przymierza. W najczarniejszych godzinach znajdował siłę dla naszego ludu. Czuwał nad Anduinem i wychowywał go jak własnego syna.', 0),
(32298, 'plPL', '', 'Boję się, że gniew go pochłonie, Thrallu. Wciąż mam nadzieję, że rozsądek zwycięży, ale musimy przygotować się na najgorsze... na wojnę.', 0),
(32299, 'plPL', '', 'Żegnaj, wodzu. Modlę się, byśmy następnym razem spotkali się jako sojusznicy.', 0),
(32375, 'plPL', 'Witajcie w moim królestwie ciemności!', '', 0),
(32376, 'plPL', 'Jak wam się podobał straszliwy twór mojego sługi? Silny, czyż nie?', '', 0),
(32383, 'plPL', 'Ale dość tej paplaniny! Chcecie odzyskać swoje miasto? Chodźcie więc, bohaterowie! Wasze dusze nakarmią zastęp! Dostaniecie to miejsce z powrotem w kawałkach!', '', 0),
(32386, 'plPL', 'Witaj, Brannie Miedziobrody. Jestem wszystkim, co pozostało ze strażnika tej świątyni.', '', 0),
(32387, 'plPL', 'Dowiodłeś, że jesteś odkrywcą i poszukiwaczem wiedzy.', '', 0),
(32388, 'plPL', 'Byłeś niezłomnym sojusznikiem ziemnych.', '', 0),
(32389, 'plPL', 'Wraz z $gtowarzyszem:towarzyszką; wykazaliście się w walce i w poszukiwaniu zwornika.', '', 0),
(32390, 'plPL', 'Twoje pobudki są czyste. Części zwornika zostaną ponownie złączone. Udaj się do Ulduaru i poznaj odpowiedzi na swoje pytania, Brannie Miedziobrody.', '', 0),
(32437, 'plPL', 'JAAAAAAAARGGGGHHHHH!!!!', '', 0),
(32521, 'plPL', 'Sprytna dziewczyna...', '', 0),
(32524, 'plPL', 'Moi bracia zgłodnieli. Wasze dusze zaspokoją ich apetyt.', '', 0),
(32526, 'plPL', 'Skaczę. Powodzenia, chłopaki!', '', 0),
(32527, 'plPL', 'Dzięki za osłonę!', '', 0),
(32528, 'plPL', 'Cel osiągnięty – przystępuję do zwiadu.', '', 0),
(32529, 'plPL', 'Rozpoczynam infiltrację.', '', 0),
(32532, 'plPL', 'Zabiję jednego specjalnie dla ciebie.', '', 0),
(32545, 'plPL', 'Nie ma dla was nadziei!', '', 0),
(32568, 'plPL', 'Zwalcie te sale! JUŻ!', '', 0),
(32579, 'plPL', 'Po tysiąckroć wybacz, panie! Sam rozprawię się z tymi intruzami!', '', 0),
(32580, 'plPL', 'Witajcie w swojej przyszłości – w tej odrobinie, która wam z niej została...', '', 0),
(32582, 'plPL', 'Nieproszeni goście! Sądziliście, że w moich włościach nikt was nie zauważy?', '', 0),
(32585, 'plPL', 'Muszę wyznać... że nie pojawiliście się całkiem niespodziewanie. Mam nadzieję, że miejsce waszego ostatniego spoczynku... przypadnie wam do gustu.', '', 0),
(32588, 'plPL', 'Gdy spotkaliśmy się ostatnio, miałeś tę przewagę, że walczyłeś na świętej ziemi. Przekonasz się, że nasze położenie się... odwróciło.', '', 0),
(32593, 'plPL', 'Sprawdzam twój blef. Jesteś w końcu paladynem. Twoja obsesja na punkcie odkupienia wykracza poza zwykłą niedorzeczność.', '', 0),
(32594, 'plPL', 'Z pewnością nie zniszczyłbyś jedynej szansy ludzkości na odkupienie jej najbardziej zbłąkanego syna. Prędzej byś umarł!', '', 0),
(32610, 'plPL', 'Tak długo... Niestrudzone, niekończące się planowanie... To się tak nie skończy...', '', 0),
(32611, 'plPL', 'Potrzebuję więcej czasu... Pan jest blisko...', '', 0),
(32612, 'plPL', 'Jaka moc! Nie czujecie jej, śmiertelnicy? Skończcie z tą głupotą i dołączcie do mnie!', '', 0),
(32614, 'plPL', 'Nie utrzymam... Destabilizacja...', '', 0),
(32617, 'plPL', 'Lata... zmarnowane...', '', 0),
(32618, 'plPL', 'ZAWIODŁEŚ MNIE, VARIMATHRASIE!', '', 0),
(32626, 'plPL', '', 'Zrobiłam to, co musiałam, bracie. Nie dałeś mi wyboru.', 0),
(32627, 'plPL', '', 'I tak kończy się wojna o Nexus.', 0),
(32628, 'plPL', '', 'To rozstrzygnięcie sprawia mi głęboki ból, lecz zniszczenie i ogrom ofiar musiały się skończyć. Bez względu na niedawne przewiny Malygosa będę opłakiwać jego stratę. Był niegdyś strażnikiem, obrońcą. Dziś poległ jeden z najpotężniejszych tego świata.', 0),
(32629, 'plPL', '', 'Czerwone Stado weźmie na siebie ciężar naprawy spustoszeń, jakich doznało Azeroth. Wracajcie do domów, do swoich bliskich, i odpocznijcie. Jutro przyniesie wam nowe wyzwania i musicie być gotowi stawić im czoła. Życie... toczy się dalej.', 0),
(32638, 'plPL', 'od niechcenia podrzuca monetę: |Hitem:44430|h|cff0070dd[Tytanowa pieczęć Dalaranu]|r|h.', 'od niechcenia podrzuca monetę: |Hitem:44430|h|cff0070dd[Tytanowa pieczęć Dalaranu]|r|h.', 0),
(32639, 'plPL', 'Jak śmiecie wtrącać się w nasze dzieło!', '', 0),
(32642, 'plPL', 'Mój czas... dobiegł końca...', '', 0),
(32645, 'plPL', 'Dziękuję wam za ocalenie mojego istnienia w tej linii czasu. Teraz muszę zdać raport przełożonym. Muszą natychmiast dowiedzieć się o tym, czego właśnie doświadczyłem.', '', 0),
(32663, 'plPL', 'łapie monetę – orzeł!', 'łapie monetę – orzeł!', 0),
(32664, 'plPL', 'znajduje monetę leżącą orłem do dołu – reszka!', 'znajduje monetę leżącą orłem do dołu – reszka!', 0),
(32666, 'plPL', 'Proces wreszcie dobiegł końca! Moja praca tutaj jest skończona.', '', 0),
(32694, 'plPL', 'Arrrrggggggggggh!!!!', '', 0),
(32698, 'plPL', 'Ty... zapłacisz mi za to, starcze. Zabić ich wszystkich!', '', 0),
(32707, 'plPL', 'Szybko, przez portal! Długo nie poleży.', '', 0),
(32708, 'plPL', 'Odwagi, krzyżowcy. Nie walczycie sami!', '', 0),
(32725, 'plPL', 'Król Lisz jest ciężko ranny. Powinniśmy zostać i go dobić.', '', 0),
(32726, 'plPL', 'Cierpliwości... wkrótce doczekamy się swojej szansy. Ciesz się, że choć raz to Tirion ma dług u nas.', '', 0),
(32747, 'plPL', 'To Obóz Tunka\'lo, wioska, którą rządzi mój brat, ale... ale ciebie nie pamiętam.', '', 0),
(32749, 'plPL', 'Północny Wiatr? Wciąż nęka mój lud?', '', 0),
(32756, 'plPL', 'Macie moją wdzięczność i wdzięczność całej wioski, choć wielu nigdy się nie dowie o waszych czynach.', '', 0),
(32759, 'plPL', 'Nie mogę tu zostać. Muszę wrócić do swojego kurhanu, tam jest moje miejsce, lecz gdy znów ujrzę przodków, to ja opowiem im waszą historię.', '', 0),
(32764, 'plPL', 'Łał! Ty to ja, tylko z przyszłości! Hej, mam lepszy ekwipunek. Super!', 'Łał! Ty to ja, tylko z przyszłości! Hej, mam lepszy ekwipunek. Super!', 0),
(32769, 'plPL', 'Nadchodzą Nieskończeni! Klepsydra musi być bezpieczna, to moje zadanie. Pomożesz?', 'Nadchodzą Nieskończeni! Klepsydra musi być bezpieczna, to moje zadanie. Pomożesz?', 0),
(32770, 'plPL', 'Ten ekwipunek wygląda fajnie i w ogóle, ale nie stać nas było na coś lepszego? Ty w ogóle chodzisz na rajdy?', 'Ten ekwipunek wygląda fajnie i w ogóle, ale nie stać nas było na coś lepszego? Ty w ogóle chodzisz na rajdy?', 0),
(32771, 'plPL', 'To jak się to wszystko kończy w Lodowej Koronie?', 'To jak się to wszystko kończy w Lodowej Koronie?', 0),
(32772, 'plPL', 'Chromie mówi, że jeśli coś tu pójdzie nie tak, to mogę po prostu zniknąć z istnienia. A jak zniknę ja, to znikniesz i ty!', 'Chromie mówi, że jeśli coś tu pójdzie nie tak, to mogę po prostu zniknąć z istnienia. A jak zniknę ja, to znikniesz i ty!', 0),
(32773, 'plPL', 'Wygląda na to, że kiepsko mi idzie z osiągnięciami.', 'Wygląda na to, że kiepsko mi idzie z osiągnięciami.', 0),
(32774, 'plPL', 'Chyba po tym wszystkim zacznę pić.', 'Chyba po tym wszystkim zacznę pić.', 0),
(32775, 'plPL', 'Przydałoby się wiedzieć, z iloma takimi będziemy walczyć. Chyba to pamiętasz, co, dziadku?', 'Przydałoby się wiedzieć, z iloma takimi będziemy walczyć. Chyba to pamiętasz, co, babciu?', 0),
(32776, 'plPL', 'Chcę tylko, żebyś $gwiedział:wiedziała;: jeśli wyjdziemy z tego cało, to dopilnuję, żeby wyszło z nas coś lepszego niż ty. Bez urazy.', 'Chcę tylko, żebyś $gwiedział:wiedziała;: jeśli wyjdziemy z tego cało, to dopilnuję, żeby wyszło z nas coś lepszego niż ty. Bez urazy.', 0),
(32777, 'plPL', 'Chwileczkę! Skoro tu jesteś, to znaczy, że w niedalekiej przyszłości to ja będę tobą i będę pomagać sobie? Utknęliśmy w pętli czasu?!', 'Chwileczkę! Skoro tu jesteś, to znaczy, że w niedalekiej przyszłości to ja będę tobą i będę pomagać sobie? Utknęliśmy w pętli czasu?!', 0),
(32781, 'plPL', 'Co u licha? Tam w górze jest Nozdormu!', 'Co u licha? Tam w górze jest Nozdormu!', 0),
(32782, 'plPL', 'Czuję, jakby coś ciągnęło mnie przez czas. Dzięki za pomoc...', 'Czuję, jakby coś ciągnęło mnie przez czas. Dzięki za pomoc...', 0),
(32796, 'plPL', 'Ze zwłok gwardzisty krypty wyłażą trupie skarabeusze!', '', 0),
(32874, 'plPL', 'Powstań, Sindragoso! Powstań i poprowadź Mroźny Pomiot na wojnę!', '', 0),
(32943, 'plPL', 'Nie przepuśćcie ich, sługi!', '', 0),
(32944, 'plPL', 'ZABIĆ ICH! Mojej pracy nie wolno przerywać!', '', 0),
(32948, 'plPL', 'To się tak nie skończy! Zbyt ciężko pracowałem! Tyle lat... Ja... Pochłonę więcej energii!', '', 0),
(32949, 'plPL', 'Spójrzcie w otchłań i patrzcie, jak czernią zachodzą wasze dusze!', '', 0),
(32950, 'plPL', 'Moc przepływa przeze mnie! Widzę... WSZYSTKO!', '', 0),
(32951, 'plPL', 'CZEKA WAS JESZCZE WIĘCEJ CIERPIENIA!', '', 0),
(32952, 'plPL', 'Nie możecie się równać z moimi tworami!', '', 0),
(32953, 'plPL', 'To się nie dzieje naprawdę!', '', 0),
(32957, 'plPL', 'Z pobliskiej szczeliny formuje się Iskra mocy!', '', 0),
(33014, 'plPL', 'Dzięki, koleś! Dzięki za nic!', '', 0),
(33015, 'plPL', 'Czemu tak traktujesz Hakmuda, koleś?', '', 0),
(33016, 'plPL', 'I co Hakmud ma teraz zrobić, koleś?', '', 0),
(33017, 'plPL', 'Hakmud nie może pracować w takich warunkach! Żegnam!', '', 0),
(33018, 'plPL', 'Myślałem, że my przyjaciele, koleś! Zostawiasz Hakmuda na lodzie?', '', 0),
(33019, 'plPL', 'Nikt nie kocha Gnimo...', '', 0),
(33020, 'plPL', 'Żegnaj! Nikt nigdy nie był dla Gnimo lepszym przyjacielem!', '', 0),
(33021, 'plPL', 'Czas na wyłączenie Gnimo.', '', 0),
(33023, 'plPL', 'A, to tak się sprawy mają... Tak mnie załatwisz, co?', '', 0),
(33024, 'plPL', 'No jasne, zawsze marzyłem, żeby gdzieś utknąć.', '', 0),
(33025, 'plPL', 'KONIEC z naszą przyjaźnią!', '', 0),
(33026, 'plPL', 'Tak po prostu mnie tu zostawisz? A jak ja mam wrócić do domu?', '', 0),
(33027, 'plPL', '', 'Serio, mon? Tak po prostu zostawiać Mojodishu?', 0),
(33028, 'plPL', '', 'To złe mojo, co ty robić. Nie mówić potem, że Mojodishu nie ostrzegać!', 0),
(33029, 'plPL', '', 'No to bądź $gtaki:taka;!', 0),
(33140, 'plPL', '', 'Witaj, $N! Witamy na pokładzie „Chmurocałusa”. Północna Grań bywa bardzo surowa. Mam nadzieję, że jesteś $gprzygotowany:przygotowana;.', 0),
(33143, 'plPL', 'On Walter Soref. Pracować w Dzielnicy Łotrów. On robić klucze.', 'On Walter Soref. Pracować w Dzielnicy Łotrów. On robić klucze.', 0),
(33195, 'plPL', 'Żegnaj.', 'Żegnaj.', 0),
(33244, 'plPL', '%s zaczyna przyzywać Zapadające się gwiazdy!', '', 0),
(33245, 'plPL', 'Gwiazdy przybywają mi z pomocą!', '', 0),
(33267, 'plPL', '%s otacza się trzeszczącą Runiczną barierą!', '', 0),
(33269, 'plPL', 'Ujrzyjcie furię kosmosu!', '', 0),
(33325, 'plPL', '', 'Thorimie, mój panie! Po cóż innego ci najeźdźcy wdarliby się do twego sanktuarium, jeśli nie po to, by cię zabić? Trzeba ich powstrzymać!', 0),
(33351, 'plPL', 'Witajcie, czempioni! Wszystkie nasze próby strącenia jej zawiodły. Przydałaby się nam pomoc – trzeba ją ściągnąć na ziemię tymi wyrzutniami harpunów.', 'Witajcie, czempioni! Wszystkie nasze próby strącenia jej zawiodły. Przydałaby się nam pomoc – trzeba ją ściągnąć na ziemię tymi wyrzutniami harpunów.', 0),
(33353, 'plPL', 'Jesteśmy gotowi pomóc!', 'Jesteśmy gotowi pomóc!', 0),
(33366, 'plPL', '', 'Czy to możliwe? Wolna po tylu latach?', 0),
(33367, 'plPL', '', 'A teraz muszę wrócić do wód jeziora.', 0),
(33368, 'plPL', '', 'Ci żałośni śmiertelnicy są nieszkodliwi i niegodni mojej uwagi. Pozbądźcie się ich!', 0),
(33369, 'plPL', '', 'Niemożliwe! Lordzie Thorimie, sprowadzę na twoich wrogów lodowatą śmierć!', 0),
(33401, 'plPL', 'Proporzec czempiona Wichrogrodu', 'Proporzec czempiona Wichrogrodu', 0),
(33407, 'plPL', 'Czy na pewno chcecie mojej pomocy w walce z Yogg-Saronem?', '', 0),
(33408, 'plPL', 'Śmiertelnicy, mam wobec was dług za uwolnienie mnie od straszliwego splugawienia, które trawi to miejsce. Choć nie odzyskałem jeszcze pełni sił, mogę pomóc wam w walce z Yogg-Saronem.\nMogę obdarzyć ciebie i twoich przyjaciół Hartem mrozu, który zwiększa zadawane przez was obrażenia i zmniejsza obrażenia otrzymywane od ataków wroga. Gdyby ktoś z was miał polec w boju, mogę zamrozić go w bryle lodu, na krótko chroniąc przed wszelkimi obrażeniami. Wiedzcie, że ta zdolność nadweręża moją moc i po jej użyciu muszę odpocząć.', '', 0),
(33409, 'plPL', '', 'Śmiertelnicy, mam wobec was dług za uwolnienie mnie od straszliwego splugawienia, które trawi to miejsce. Choć nie odzyskałam jeszcze pełni sił, mogę pomóc wam w walce z Yogg-Saronem.\nMogę obdarzyć ciebie i twoich przyjaciół Odpornością natury, która zwiększa zadawane przez was obrażenia oraz leczenie otrzymywane z zaklęć i efektów. Ponadto mogę wyczarować Studnie poczytalności, które pozwolą wam odzyskać Poczytalność, gdy zacznie się wam wymykać poczucie rzeczywistości.', 0),
(33412, 'plPL', 'Śmiertelnicy, mam wobec was dług za uwolnienie mnie od straszliwego splugawienia, które trawi to miejsce. Choć nie odzyskałem jeszcze pełni sił, mogę pomóc wam w walce z Yogg-Saronem.\nMogę obdarzyć ciebie i twoich przyjaciół Szybkością wynalazku, która zwiększa zadawane przez was obrażenia i szybkość ruchu. Ponadto mogę zdestabilizować matryce pewnych form życia opartych na saronicie, zmniejszając ich szybkość ataku i rzucania zaklęć.', '', 0),
(33413, 'plPL', 'Śmiertelnicy, mam wobec was dług za uwolnienie mnie od straszliwego splugawienia, które trawi to miejsce. Choć nie odzyskałem jeszcze pełni sił, mogę pomóc wam w walce z Yogg-Saronem.\nMogę obdarzyć ciebie i twoich przyjaciół Furią burzy, która zwiększa zadawane przez was obrażenia i maksymalne zdrowie. Gdybyście stanęli w obliczu zła tak nikczemnego, że nie da się go zniszczyć, mogę skupić całą swoją moc w ostatniej Tytanicznej burzy, która unicestwi nawet Nieśmiertelnych.', '', 0),
(33418, 'plPL', 'Użycz nam swojej pomocy. Razem pokonamy Yogg-Sarona.', 'Użycz nam swojej pomocy. Razem pokonamy Yogg-Sarona.', 0),
(33421, 'plPL', 'Śmierć Przymierzu!', 'Śmierć Przymierzu!', 0),
(33463, 'plPL', '%s usycha, wnika w ziemię i zaczyna się regenerować.', '', 0),
(33464, 'plPL', 'Dzięki pomocy sojuszników %s regeneruje się i wraca do życia.', '', 0),
(33523, 'plPL', '%s umacnia pobliskich sojuszników runiczną mocą!', '', 0),
(33606, 'plPL', 'Ruszajcie się! Nie zostanie długo na ziemi!', '', 0),
(33607, 'plPL', 'Miejcie oczy otwarte! Zaraz wynurzą się maszyny kretowe z tymi paskudnymi żelaznymi krasnoludami na pokładzie!', '', 0),
(33608, 'plPL', 'Twoja wytrzymałość jest godna podziwu.', '', 0),
(33609, 'plPL', 'Złamię cię... tak jak złamałem jego!', '', 0),
(33610, 'plPL', 'Arrrrrrgh!', '', 0),
(33616, 'plPL', 'Tysiąc śmierci...', '', 0),
(33617, 'plPL', 'Albo jedno morderstwo.', '', 0),
(33628, 'plPL', 'Yrr n\'lyeth... shuul anagg!', '', 0),
(33629, 'plPL', 'Przekona się... żaden król nie włada wiecznie – tylko śmierć jest wieczna!', '', 0),
(33656, 'plPL', 'Dokonało się. Wszyscy oddali to, co oddać należało. Teraz pieczętuję Duszę Smoka na zawsze.', '', 0),
(33658, 'plPL', '', 'Ten straszny blask... czy tak ma być?', 0),
(33659, 'plPL', 'Aby stało się tak, jak stać się musi – owszem.', '', 0),
(33660, 'plPL', 'To broń, jakiej dotąd nie było. I taka właśnie być musi.', '', 0),
(33663, 'plPL', 'Jego stado dość szybko dostało nauczkę. Wkrótce i wy dostaniecie swoją!', '', 0),
(33664, 'plPL', '', 'Złe wieści, panie.', 0),
(33665, 'plPL', '', 'W tym szturmie klany zjednoczyły się pod wodzą Czarnorękiego. Będą trzymać się razem, dopóki Wichrogród nie upadnie.', 0),
(33666, 'plPL', '', 'Gul\'dan przed zmrokiem sprowadzi swoich czarnoksiężników. Do tego czasu klan Czarnej Skały będzie próbował zdobyć Wschodni Mur.', 0),
(33667, 'plPL', '', 'Przywódcy orków zgadzają się z twoją oceną.', 0),
(33670, 'plPL', 'Wytrzymamy do nadejścia posiłków. Dopóki mury i tron obsadzają ludzie mężnego serca, Wichrogród się nie podda.', '', 0),
(33675, 'plPL', 'Proporzec czempiona Darnassus', 'Proporzec czempiona Darnassus', 0),
(33676, 'plPL', 'Proporzec czempiona Exodaru', 'Proporzec czempiona Exodaru', 0),
(33678, 'plPL', 'Proporzec czempiona Gnomoregan', 'Proporzec czempiona Gnomoregan', 0),
(33679, 'plPL', 'Proporzec czempiona Żelaznej Kuźni', 'Proporzec czempiona Żelaznej Kuźni', 0),
(33680, 'plPL', 'Mogę coś dla ciebie zrobić, $gszefie:szefowo;?', '', 0),
(33816, 'plPL', 'Gotowi do wymarszu, trzymajcie te krasnoludy z dala od naszych pleców!', 'Gotowi do wymarszu, trzymajcie te krasnoludy z dala od naszych pleców!', 0),
(33818, 'plPL', 'Straciliśmy inżynierów, to się źle skończy!', '', 0),
(33820, 'plPL', 'Dajcie nam chwilę, przygotujemy się do budowy wieżyczek.', 'Dajcie nam chwilę, przygotujemy się do budowy wieżyczek.', 0),
(33821, 'plPL', 'Ogień ugaszony! Odbudujmy te wieżyczki!', 'Ogień ugaszony! Odbudujmy te wieżyczki!', 0),
(33857, 'plPL', 'Wieżyczka z harpunem gotowa do użycia!', '', 0),
(33993, 'plPL', '%s wpada w szał i gasi wszelkie życie!', '', 0),
(33994, 'plPL', 'Oto narzędzia stworzenia!', '', 0),
(33995, 'plPL', 'Wasze działania są nielogiczne. Wszystkie możliwe wyniki tego starcia zostały obliczone. Panteon otrzyma wiadomość Obserwatora bez względu na rezultat.', '', 0),
(33996, 'plPL', 'Utrata życia nieunikniona.', '', 0),
(33997, 'plPL', 'Robię to, co muszę.', '', 0),
(33998, 'plPL', 'Spójrzcie na swój świat moimi oczami: wszechświat tak rozległy, że niezmierzony – niepojęty nawet dla waszych największych umysłów.', '', 0),
(34000, 'plPL', 'Widziałem światy skąpane w płomieniach Twórców, a ich mieszkańcy gaśli bez najcichszej skargi. Całe układy planetarne rodziły się i obracały w perzynę w czasie, w jakim wasze śmiertelne serca uderzają jeden raz. A przez cały ten czas moje własne serce było wyzute z emocji... ze współczucia. Nie. Czułem. Nic. Milion milionów zmarnowanych istnień. Czy wszystkie miały w sobie waszą nieustępliwość? Czy wszystkie kochały życie tak jak wy?', '', 0),
(34001, 'plPL', 'Wasz czas się skończył.', '', 0),
(34006, 'plPL', 'Analiza zakończona. Wykryto częściowe splugawienie systemów podtrzymywania życia planety oraz całkowite splugawienie większości jej mechanizmów obronnych.', '', 0),
(34012, 'plPL', 'Być może to wasze niedoskonałości... to, co daje wam wolną wolę... pozwalają wam trwać wbrew wszelkim kosmicznie wyliczonym szansom. Zwyciężacie tam, gdzie zawiodły doskonałe twory samych tytanów.', '', 0),
(34013, 'plPL', 'Zmieniłem kod odpowiedzi – wasza planeta zostanie oszczędzona. Nie mogę już być pewny własnych obliczeń.', '', 0),
(34014, 'plPL', 'Rozpoczynam transmisję. Kod odpowiedzi: „Omega”. Zażądano planetarnego przetworzenia od podstaw.', '', 0),
(34015, 'plPL', 'Żegnajcie, śmiertelnicy. Wasza odwaga jest godna podziwu jak na tak ułomne istoty.', '', 0),
(34016, 'plPL', 'Brak mi sił, by nadać sygnał. Musicie... się spieszyć... znaleźć miejsce mocy... blisko niebios.', '', 0),
(34017, 'plPL', 'Znam takie miejsce. Poradzisz sobie?', '', 0),
(34018, 'plPL', 'Nie troszcz się o mój los, Bronzen. Jeśli sygnał nie zostanie nadany na czas, przetworzenie od podstaw i tak nastąpi. Ocalcie... swój świat...', '', 0),
(34022, 'plPL', '%s szeroko otwiera paszczę!', '', 0),
(34026, 'plPL', 'Translokacja zakończona. Rozpoczynam analizę planetarną Azeroth.', '', 0),
(34027, 'plPL', 'Odsuńcie się, śmiertelnicy. Nie przybyłem tu z wami walczyć.', '', 0),
(34028, 'plPL', 'Jeśli moja analiza wykaże systemowe splugawienie, przetworzenie tej planety od podstaw będzie leżało w najlepszym interesie wszechświata. Nie wtrącajcie się.', '', 0),
(34029, 'plPL', 'Wrócę do Archiwum i zobaczę, czy uda mi się zagłuszyć jego sygnał. Może zyskam dla nas trochę czasu, a wy się nim zajmijcie.', '', 0),
(34037, 'plPL', 'Otwierają się portale do umysłu istoty zwanej %s!', '', 0),
(34084, 'plPL', 'W samą porę. No to pozbądźmy się tego czegoś.', '', 0),
(34161, 'plPL', 'Udało się, chłopaki! Dotarliśmy tu przed przybyciem Algalona. Może uda się tak przerobić systemy, żeby zakłócić jego analizę--', '', 0),
(34170, 'plPL', '%s szykuje się do uwolnienia Wzmacniających cieni!', '', 0),
(34188, 'plPL', 'Wasze małostkowe waśnie tylko dodają mi sił.', '', 0),
(34225, 'plPL', 'Co za bitwa! Widziałaś to, Rhydian?!', '', 0),
(34226, 'plPL', 'Może i tak, ale to tylko kwestia czasu, zanim wedrzemy się z powrotem do Ulduaru. Udało się znaleźć sposób, żeby teleportować się do środka?', '', 0),
(34229, 'plPL', 'Oj. Czyli jednak będziemy musieli się z tym czymś zmierzyć?', '', 0),
(34231, 'plPL', 'A co z tym opancerzonym protosmokowcem i olbrzymem ognia, których widziano w pobliżu? Myślisz, że twoi magowie sobie z nimi poradzą?', '', 0),
(34233, 'plPL', 'Prześlizgnąć?! Masz nas za świstaki czy co?', '', 0),
(34235, 'plPL', 'Dobra. Skoro to nasi sojusznicy mają sobie brudzić ręce, niech sami zdecydują, co dalej.', '', 0),
(34236, 'plPL', 'Świetna robota z tym metalowym paskudztwem. Wygląda na to, że na naszej drodze zostało już tylko kilka przeszkód.$B$BGdy rozprawicie się z tym szczękającym robotem na końcu korytarza, będziemy w Ulduarze.$B$BZauważyliśmy też ogromnego, ziejącego ogniem protosmokowca i roztopionego olbrzyma. Nie stoją nam jednak na drodze, więc możecie ich po prostu ominąć, jeśli wolicie.', '', 0),
(34268, 'plPL', '', 'Sekwencja samozniszczenia uruchomiona.', 0),
(34273, 'plPL', '', 'Ten obszar ulegnie samozniszczeniu za sześć minut.', 0),
(34274, 'plPL', '', 'Ten obszar ulegnie samozniszczeniu za pięć minut.', 0),
(34275, 'plPL', '', 'Ten obszar ulegnie samozniszczeniu za cztery minuty.', 0),
(34276, 'plPL', '', 'Ten obszar ulegnie samozniszczeniu za trzy minuty.', 0),
(34277, 'plPL', '', 'Ten obszar ulegnie samozniszczeniu za dwie minuty.', 0),
(34278, 'plPL', '', 'Ten obszar ulegnie samozniszczeniu za minutę.', 0),
(34279, 'plPL', '', 'Sekwencja samozniszczenia zakończona. Miłego dnia!', 0),
(34280, 'plPL', '', 'Ten obszar ulegnie samozniszczeniu za siedem minut.', 0),
(34281, 'plPL', '', 'Ten obszar ulegnie samozniszczeniu za osiem minut.', 0),
(34282, 'plPL', '', 'Ten obszar ulegnie samozniszczeniu za dziewięć minut.', 0),
(34283, 'plPL', '', 'Ten obszar ulegnie samozniszczeniu za dziesięć minut.', 0),
(34284, 'plPL', '', 'Sekwencja samozniszczenia przerwana. Kod obejścia A-9-0-5.', 0),
(34294, 'plPL', 'Iluzja pryska i otwiera się droga do centralnej komnaty!', '', 0),
(34357, 'plPL', 'POKŁOŃCIE SIĘ BOGU ŚMIERCI!', '', 0),
(34360, 'plPL', 'Spójrzcie w prawdziwe oblicze śmierci i wiedzcie, że wasz koniec jest bliski!', '', 0),
(34361, 'plPL', 'SZALEŃSTWO WAS POCHŁONIE!', '', 0),
(34362, 'plPL', 'Czeka was wieczne cierpienie!', '', 0),
(34365, 'plPL', 'Wasz los jest przypieczętowany. Kres dni nadszedł wreszcie dla was i dla WSZYSTKICH, którzy zamieszkują tę nędzną małą sadzonkę. Uulwi ifis halahs gag erh\'ongg w\'ssh.', '', 0),
(34366, 'plPL', 'Zasłona zimy was ochroni, czempioni!', '', 0),
(34367, 'plPL', '', 'Eonar, twoja służebnica prosi o twe błogosławieństwo!', 0),
(34368, 'plPL', 'Matryca bojowa wzmocniona. Podziwiajcie cudowną chyżość!', '', 0),
(34369, 'plPL', 'Golganneth, użycz mi swej siły! Obdarz moich śmiertelnych sojuszników potęgą gromu!', '', 0),
(34417, 'plPL', 'Jak sobie życzysz, $n.', '', 0),
(34465, 'plPL', '%s zaczyna rzucać Wielki Wybuch!', '', 0),
(34500, 'plPL', '%s zaczyna rzucać Kosmiczne miażdżenie!', '', 0),
(34561, 'plPL', 'Ty trzymać się z dala od morsoludzi. Oni porywać szczeniaki, porwać i ciebie.', '', 0),
(34562, 'plPL', 'Kekek zabrać cię na polowanie. Ty być dobra przynęta.', '', 0),
(34563, 'plPL', 'Orkowie zawsze pokazywać Kekeka palcami i się śmiać, ale on kiedyś się zemścić.', '', 0),
(34564, 'plPL', 'Wiedzieć co? Jak Kekek zamknąć oczy, ty go nie widzieć.', '', 0),
(34565, 'plPL', 'Kekek złapać trzy kurczaki na obiad. Założyć się, że ty nie złapać żadnego.', '', 0),
(34566, 'plPL', 'Kekek zabrać ulubioną zabawkę pisklaka wielkojęzorów. Może ona pomóc ci zasnąć w nocy.', '', 0),
(34576, 'plPL', 'My tu być! Tylko jak to drzewo świata, to czemu ono się złamać, kiedy próbować włożyć w nie cały świat?', '', 0),
(34606, 'plPL', 'Patrz! To my? My myśleć, że to my. Może tylko trochę starsi?', '', 0),
(34607, 'plPL', 'Chyba Wielcy nas pobłogosławić! Kapliczki dać magię i my kiedyś zostać arcywyrocznią? Może?', '', 0),
(34615, 'plPL', 'My mieć nowego przyjaciela!', '', 0),
(34618, 'plPL', 'My też umieć tańczyć!', '', 0),
(34631, 'plPL', 'To być królowa smoków? Hmm... my myśleć, że ona być większa. Tak, my tak myśleć.', '', 0),
(34632, 'plPL', 'Czemu ona nie wyglądać jak inne smoki? Ona móc zamienić się w wielkiego smoka, jakby chcieć?', '', 0),
(34633, 'plPL', 'Yyy... Wasza Wysokość, zamienić się dla nas w smoka?', '', 0),
(34634, 'plPL', 'Oki... A teraz?', '', 0),
(34672, 'plPL', 'Łał! Prawdziwy Wielki? My myśleć, że nawet Soo-say nie spotkać prawdziwego Wielkiego!', '', 0),
(34673, 'plPL', 'Yyy, dzień dobry, panie Wielki. Dla nas zaszczyt cię poznać.', '', 0),
(34674, 'plPL', 'Może pan Wielki spać? My rozumieć. To ciężka praca być Wielkim i zbierać wszystkie błyskotki, co my ci zostawiać.', '', 0),
(34675, 'plPL', 'My przynieść ci prezent, Wielki. Może ty go zobaczyć, jak się obudzić. Może ty pamiętać, że my przyjść cię odwiedzić, oki?', '', 0),
(34967, 'plPL', '', '%s zaczyna rzucać |cFFFFFFFFWir światła!|r Przełącz się na |cFFFFFFFFJasną|r esencję!', 0),
(34968, 'plPL', '', '%s zaczyna rzucać |cFF9932CDWir ciemności!|r Przełącz się na |cFF9932CDMroczną|r esencję!', 0),
(34974, 'plPL', '', '%s zaczyna rzucać |cFFFF0000Pakt bliźniaczek!|r', 0),
(34975, 'plPL', '', '%s zaczyna rzucać Pakt bliźniaczek!', 0),
(35014, 'plPL', 'Zaraz ogłuchnę. Ta wielka zielona harpia nie zamknie się nawet na pięć sekund. Umiem tym sterować, jasne? Nie jestem idiotą!', '', 0),
(35015, 'plPL', '', 'Gdyby mnie tu nie było, Zippik wpakowałby nas prosto w Urwiska. Kretyn.', 0),
(35016, 'plPL', 'Lot jest całkiem przyjemny, jeśli komuś nie przeszkadza kurz.', 'Lot jest całkiem przyjemny, jeśli komuś nie przeszkadza kurz.', 0),
(35017, 'plPL', 'Trzymaj się z dala od krawędzi, $gmistrzu:mistrzyni;. Jeszcze nam spadniesz.', 'Trzymaj się z dala od krawędzi, $gmistrzu:mistrzyni;. Jeszcze nam spadniesz.', 0),
(35018, 'plPL', 'Ja tu pracuję.', 'Ja tu pracuję.', 0),
(35021, 'plPL', 'Hej. Mam przerwę.', '', 0),
(35022, 'plPL', 'Witamy na pokładzie „Zefira” – przyjemniejszego lotu nad Pustkowiami nie znajdziesz. Rozsiądź się wygodnie i ciesz się podróżą, co, $gmłody:młoda;? Nie ma to jak słodkie, suche powietrze zmieszane z zapachem oleju.', '', 0),
(35025, 'plPL', 'Ja być Tolwe. Robota być pilnować spokoju i patrzeć. No to ja patrzeć.', '', 0),
(35026, 'plPL', 'Tam być ptak!', '', 0),
(35027, 'plPL', 'Ta chmura wyglądać jak wódz.', '', 0),
(35028, 'plPL', 'Uwaga na statek! Harpia! ...czekać, to być następny ptak.', '', 0),
(35029, 'plPL', 'Tam być robak.', '', 0),
(35030, 'plPL', 'A oto i Orgrimmar, wielki i groźny jak zawsze. Zróbcie sobie krótką przerwę, chłopaki, a potem wracamy do Urwisk!', '', 0),
(35031, 'plPL', 'Następny przystanek: Gromowe Urwiska!', '', 0),
(35032, 'plPL', 'Patrzcie pod nogi! Nie chcemy, żeby została po was plama tam na dole. Witamy w Gromowych Urwiskach!', '', 0),
(35033, 'plPL', 'Dobra, chłopaki, zabieramy tę ślicznotkę do Orgrimmaru!', '', 0),
(35034, 'plPL', '', 'Ostrożnie. OSTROŻNIE! Czy ja poczułam wstrząs? Zaraz zwalisz tę wieżę, ośle!', 0),
(35035, 'plPL', '', 'Mamy opóźnienie! Obróć tę balię na wschód! NA WSCHÓD!', 0),
(35037, 'plPL', '', 'Rusz się, Zippik! Nie mamy całego dnia!', 0),
(35070, 'plPL', '%s uwalnia Pijawczy rój, by się uleczyć!', '', 0),
(35071, 'plPL', '%s zakopuje się w ziemi!', '', 0),
(35163, 'plPL', '%s zaczyna wrzeć, gdy dotyka jej $n!', '', 0),
(35165, 'plPL', 'Bramy sforsowane! Brońcie twierdzy!', '', 0),
(35228, 'plPL', 'Wszyscy na pokład kanonierki! Do dział!', '', 0),
(35229, 'plPL', '', 'Cóż, zatem zaczynajmy.', 0),
(35231, 'plPL', '', 'Nawet najmroczniejsze wspomnienie blednie, gdy stawi mu się czoła!', 0),
(35232, 'plPL', '', 'Doskonała robota!', 0),
(35241, 'plPL', 'Wszyscy na pokład kanonierki! Do dział!', '', 0),
(35259, 'plPL', 'Srebrny Sojusz ma przyjemność przedstawić swoich zawodników w tych zmaganiach, najwyższy lordzie.', '', 0),
(35278, 'plPL', '$n atakuje warsztat!', '', 0),
(35279, 'plPL', 'Przymierze zajmuje warsztat!', '', 0),
(35280, 'plPL', 'Horda zajmuje warsztat!', '', 0),
(35286, 'plPL', '$n odpiera atak na warsztat!', '', 0),
(35317, 'plPL', '%s wpada na ścianę Koloseum i zostaje ogłuszony!', '', 0),
(35318, 'plPL', 'Tratując walczących, %s wpada w spienioną wściekłość!', '', 0),
(35334, 'plPL', 'Przed wami zawzięty Wielki czempion Orgrimmaru, Mokra Miażdżyczaszka!\n', '', 0),
(35335, 'plPL', 'Na arenę wkracza smukły i groźny Zul\'tore, Wielki czempion Sen\'jin!\n', '', 0),
(35336, 'plPL', 'Wyprostowany w siodle swojego kodo – oto czcigodny Runok Dzikogrzywy, Wielki czempion Gromowych Urwisk!\n', '', 0),
(35337, 'plPL', 'Nieustępliwość Porzuconych reprezentuje Wielka czempionka Podmiasta, tropicielka śmierci Visceri!\n', '', 0),
(35338, 'plPL', 'Z bramy wyłania się Eressea Pieśń Brzasku, wprawna czarodziejka i Wielka czempionka Srebrnej Luny!\n', '', 0),
(35347, 'plPL', 'Sprostacie wyzwaniu? Nie będę się oszczędzał.', '', 0),
(35358, 'plPL', 'Za późno, by powstrzymać nasz plan.', 'Za późno, by powstrzymać nasz plan.', 0),
(35359, 'plPL', 'Dopilnuj, żeby nikt za mną nie poszedł.', 'Dopilnuj, żeby nikt za mną nie poszedł.', 0),
(35365, 'plPL', '$n atakuje doki!', '', 0),
(35366, 'plPL', '$n odpiera atak na doki!', '', 0),
(35367, 'plPL', 'Przymierze zajmuje doki!', '', 0),
(35368, 'plPL', 'Horda zajmuje doki!', '', 0),
(35369, 'plPL', '$n atakuje hangar!', '', 0),
(35370, 'plPL', '$n odpiera atak na hangar!', '', 0),
(35371, 'plPL', 'Przymierze zajmuje hangar!', '', 0),
(35372, 'plPL', 'Horda zajmuje hangar!', '', 0),
(35373, 'plPL', '$n atakuje kamieniołom!', '', 0),
(35374, 'plPL', '$n odpiera atak na kamieniołom!', '', 0),
(35375, 'plPL', 'Przymierze zajmuje kamieniołom!', '', 0),
(35376, 'plPL', 'Horda zajmuje kamieniołom!', '', 0),
(35377, 'plPL', '$n atakuje rafinerię ropy!', '', 0),
(35378, 'plPL', '$n odpiera atak na rafinerię ropy!', '', 0),
(35379, 'plPL', 'Przymierze zajmuje rafinerię ropy!', '', 0),
(35380, 'plPL', 'Horda zajmuje rafinerię ropy!', '', 0),
(35408, 'plPL', '%s celuje Młotem prawych w $n!', '', 0),
(35409, 'plPL', 'Główna brama twierdzy Hordy została zniszczona!', '', 0),
(35410, 'plPL', 'Główna brama twierdzy Przymierza została zniszczona!', '', 0),
(35411, 'plPL', 'Zachodnia brama twierdzy Hordy została zniszczona!', '', 0),
(35412, 'plPL', 'Zachodnia brama twierdzy Przymierza została zniszczona!', '', 0),
(35413, 'plPL', 'Wschodnia brama twierdzy Hordy została zniszczona!', '', 0),
(35414, 'plPL', 'Wschodnia brama twierdzy Przymierza została zniszczona!', '', 0),
(35415, 'plPL', '%s zaczyna promieniować światłem. Osłoń oczy!', '', 0),
(35442, 'plPL', 'Młot prawych!', '', 0),
(35459, 'plPL', '$n odpiera atak na twierdzę Przymierza!', '', 0),
(35460, 'plPL', '$n odpiera atak na twierdzę Hordy!', '', 0),
(35461, 'plPL', '$n atakuje twierdzę Przymierza!', '', 0),
(35462, 'plPL', '$n atakuje twierdzę Hordy!', '', 0),
(35463, 'plPL', 'Przymierze zajmuje twierdzę Przymierza!', '', 0),
(35464, 'plPL', 'Przymierze zajmuje twierdzę Hordy!', '', 0),
(35465, 'plPL', 'Horda zajmuje twierdzę Hordy!', '', 0),
(35466, 'plPL', 'Horda zajmuje twierdzę Przymierza!', '', 0),
(35513, 'plPL', 'Odwiedź bank.', 'Odwiedź bank.', 0),
(35515, 'plPL', 'Odwiedź handlarza.', 'Odwiedź handlarza.', 0),
(35521, 'plPL', 'Tirionie.', '', 0),
(35522, 'plPL', 'Królu Varianie, lady Jaino. Witajcie na turnieju. Wasze miejsca w koloseum czekają.', '', 0),
(35523, 'plPL', '', 'Dziękuję. Przynajmniej tyle mogę zrobić, by to wesprzeć. Musimy trzymać się razem.', 0),
(35524, 'plPL', 'Wiele ode mnie żądasz, Tirionie – mam siedzieć i patrzeć, ufając, że te dzikusy same utrzymają się w ryzach.', '', 0),
(35525, 'plPL', 'Moi ludzie są tu po to, by dopilnować przestrzegania zasad walki. Twoim poddanym dobrze zrobi, gdy zobaczą cię na trybunach.', '', 0),
(35526, 'plPL', '%s kiwa głową i gestem zaprasza gości, by poszli za nim.', '', 0),
(35527, 'plPL', 'Być może. Wątpię w skuteczność tego posunięcia. Lepiej byśmy zrobili, szykując nasze armie do ostatecznego szturmu.', '', 0),
(35528, 'plPL', 'Ale jeśli moja obecność na tych igrzyskach jest konieczna, by zyskać twoje wsparcie w bitwie, to zostanę. Na razie.', '', 0),
(35529, 'plPL', '', 'Jestem pewna, że Thrall utrzyma swoich w ryzach...', 0),
(35534, 'plPL', 'Odwiedź skrzynkę pocztową.', 'Odwiedź skrzynkę pocztową.', 0),
(35546, 'plPL', 'Zepsułeś mi wielkie wejście, szczurze.', '', 0),
(35548, 'plPL', 'Naprawdę sądziliście, że agent Króla Lisza da się pokonać na polu waszego żałosnego turnieju?', '', 0);
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(35549, 'plPL', 'Przybyłem dokończyć swoje zadanie.', '', 0),
(35552, 'plPL', 'Garoszu, oczekuję, że będziesz tu nad sobą panował. Nie chcę powtórki z Purpurowej Cytadeli.', '', 0),
(35553, 'plPL', 'Phi! To był pokaz siły godny przywódcy. Żałuję tylko, że nie zabiłem tego człowieka, zanim wtrąciła się czarodziejka.', '', 0),
(35554, 'plPL', 'Jaki honor w wymachiwaniu stępionymi kijami? To strata czasu.', '', 0),
(35555, 'plPL', 'Mów za siebie, Thrallu.', '', 0),
(35556, 'plPL', 'Chyba słowa głupca. Horda zniszczy nieumarłych bez twojej pomocy, człowieku, i bez pomocy tego nadętego króla.', '', 0),
(35557, 'plPL', 'Ba.', '', 0),
(35558, 'plPL', 'Jesteśmy tu gośćmi, Garoszu, i będziesz się zachowywał honorowo.', '', 0),
(35559, 'plPL', 'Dziękujemy za zaproszenie, lordzie Fordringu. Z niecierpliwością czekamy na te igrzyska.', '', 0),
(35560, 'plPL', 'Mądre słowa.', '', 0),
(35561, 'plPL', 'Garoszu, dość!', '', 0),
(35562, 'plPL', 'Oczywiście, Tirionie. Przepraszam za jego wybuch. To się nie powtórzy.', '', 0),
(35675, 'plPL', '%s wbija wzrok w $n i wydaje donośny ryk!', '', 0),
(35676, 'plPL', '%s posyła kolce w pogoń za $n!', '', 0),
(35726, 'plPL', 'Dziękuję, najwyższy lordzie. A teraz, zawodnicy, rozpocznę rytuał przywołania. Gdy skończę, pojawi się straszliwy strażnik Zagłady!', '', 0),
(35727, 'plPL', 'Szykujcie się na zapomnienie!', '', 0),
(35728, 'plPL', 'A-HA! Udało mi się! Oto absolutna potęga Wilfreda Bombika, mistrza przywoływania! Jesteś ze mną związany, demonie!', '', 0),
(35729, 'plPL', 'Ale to ja tu rządzę...', '', 0),
(35738, 'plPL', '', 'W imię naszego mrocznego pana. Za Króla Lisza. Wy. Zginiecie.', 0),
(35739, 'plPL', '', 'Zważono cię na wadze i wyszło za lekko.', 0),
(35740, 'plPL', '', 'Niegodni!', 0),
(35741, 'plPL', '', 'Plagi nie da się powstrzymać...', 0),
(35743, 'plPL', '', 'Już po tobie!', 0),
(35745, 'plPL', '', 'Niech pochłonie was ciemność!', 0),
(35746, 'plPL', '', 'Niech pochłonie was światło!', 0),
(35748, 'plPL', 'Nerubianie zbudowali imperium pod skutymi lodem pustkowiami Północnej Grani. Imperium, na którym tak głupio wznieśliście swoje budowle. MOJE IMPERIUM.', '', 0),
(35750, 'plPL', 'Achhh, nasi goście przybyli, tak jak obiecał pan.', '', 0),
(35751, 'plPL', 'To miejsce będzie waszym grobowcem!', '', 0),
(35752, 'plPL', 'F-lakkh shir!', '', 0),
(35753, 'plPL', 'Kolejna dusza, by nasycić zastęp.', '', 0),
(35754, 'plPL', 'Zawiodłem cię, panie...', '', 0),
(35756, 'plPL', 'Auum na-l ak-k-k-k, isshhh. Powstańcie, sługi. Pożerajcie...', '', 0),
(35757, 'plPL', 'Rój was pochłonie!', '', 0),
(35759, 'plPL', 'Ty! Musisz jeszcze poćwiczyć.', '', 0),
(35760, 'plPL', 'Nie, nie i jeszcze raz powiadam: nie! To za mało.', '', 0),
(35761, 'plPL', 'Poddaję się! Ustępuję. Doskonała robota. Czy mogę już uciec?', '', 0),
(35762, 'plPL', '', 'Dziękuję, dobry heroldzie. Twoje słowa są zbyt łaskawe.', 0),
(35763, 'plPL', '', 'Niech Światłość da mi siłę, bym okazała się godnym wyzwaniem.', 0),
(35764, 'plPL', '', 'Wykorzystaj ten czas, by rozważyć swoje dawne czyny.', 0),
(35765, 'plPL', '', 'Odpocznij.', 0),
(35766, 'plPL', '', 'Bądź spokojnej myśli.', 0),
(35767, 'plPL', 'Ta farsa kończy się tutaj!', '', 0),
(35769, 'plPL', 'Zmarnowane mięso.', '', 0),
(35770, 'plPL', 'Nie! Nie mogę zawieść... znowu...', '', 0),
(35771, 'plPL', 'Moje gnijące ciało i tak tylko mi zawadzało!', '', 0),
(35772, 'plPL', 'Nie potrzebuję kości, żeby was pokonać!', '', 0),
(35785, 'plPL', 'Witaj, wodzu Thrallu. Nadrządco Piekłoryczu.', '', 0),
(35786, 'plPL', 'Mam nadzieję, że z czasem dostrzeżesz wartość tych zmagań, Garoszu. Nie pokonamy Plagi, jeśli wciąż będziemy walczyć między sobą.', '', 0),
(35787, 'plPL', 'Ufam, panowie, że pod moim dachem będziecie się zachowywać jak należy.', '', 0),
(35788, 'plPL', 'Zatem proszę za mną.', '', 0),
(35799, 'plPL', 'Wojownicy Przymierza i Hordy! Witajcie pod sztandarem Krucjaty Argentu.', '', 0),
(35800, 'plPL', 'Na południu leży nasz cel. Pomaszerujemy na Cytadelę i wytniemy serce Plagi tam, gdzie się zagnieździło.', '', 0),
(35801, 'plPL', 'Ale tego zadania nie wolno lekceważyć.', '', 0),
(35802, 'plPL', 'Zmasowany atak wszystkich zdolnych do walki skończyłby się niepotrzebną rzezią. Każdy poległy żołnierz powstałby jako wróg. Azeroth zostałoby bezbronne wobec zagrożenia ze strony nieumarłych.', '', 0),
(35803, 'plPL', 'Dlatego, by atak się powiódł, potrzebujemy niewielkiego, zwartego oddziału uderzeniowego. Z tego powodu stworzyliśmy Turniej Argentu.', '', 0),
(35805, 'plPL', 'W tych murach zostaniecie poddani próbie. Pod czujnym okiem waszych przywódców wasze umiejętności bojowe zmierzą się z najgroźniejszymi niebezpieczeństwami, jakie ma do zaoferowania Północna Grań.', '', 0),
(35806, 'plPL', 'Wasza waleczność, siła i spryt będą bacznie obserwowane. Te igrzyska wyłonią najlepszych, jakich ma Azeroth.', '', 0),
(35807, 'plPL', 'Zwycięzcy zajmą należne im miejsce w szturmie na Cytadelę. Staniemy razem w obliczu zła, a Arthas UPADNIE!', '', 0),
(35861, 'plPL', 'Do pierwszego wyzwania musisz dosiąść konia bojowego Argentu. Te wierzchowce znajdziesz pod ścianami koloseum.$b$bDosiądź konia bojowego i porozmawiaj ze mną, a wtedy zaczniemy.', '', 0),
(35950, 'plPL', 'Niech ktoś zatrzyma tego ghula!', '', 0),
(35952, 'plPL', 'To musiało boleć! Mózgi!', '', 0),
(35954, 'plPL', 'Co za strzał w Mózgi!', '', 0),
(35957, 'plPL', '$n pada pod kopytami!', '$n pada pod kopytami!', 0),
(35968, 'plPL', '%s wyłania się z ziemi!', '', 0),
(36147, 'plPL', 'Widząc śmierć towarzysza, %s wpada w szał!', '', 0),
(36323, 'plPL', 'Zaraziła cię paraliżująca toksyna!', 'Zaraziła cię paraliżująca toksyna!', 0),
(36370, 'plPL', '', 'No? Czego chcesz?', 0),
(36536, 'plPL', 'Nie, tamtego! Tamtego! Bierz tamtego!', '', 0),
(36537, 'plPL', 'Szybko! Zatruj ich wszystkich, póki są blisko!', '', 0),
(36538, 'plPL', 'Dość tego biegania! Stój spokojnie, a ja ich wszystkich wysadzę!', '', 0),
(36550, 'plPL', '%s zaczyna błyskawicznie wyczarowywać wybuchowe miny!', '', 0),
(36670, 'plPL', 'Do pierwszego wyzwania musisz dosiąść worga bojowego Argentu. Te wierzchowce znajdziesz pod ścianami koloseum.$b$bDosiądź worga bojowego i porozmawiaj ze mną, a wtedy zaczniemy.', '', 0),
(36714, 'plPL', 'Szronokle, uwięź ich w tunelu! POGRZEB ICH ŻYWCEM!', 'Szronokle, uwięź ich w tunelu! POGRZEB ICH ŻYWCEM!', 0),
(36720, 'plPL', '|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t|cFFBC0000 PRZEGRZANIE  |r|TInterface\\Icons\\Spell_Fire_Flameshock.blp:20|t', '', 0),
(36765, 'plPL', 'Inny zajmie jego miejsce. Marnujecie czas.', '', 0),
(36841, 'plPL', 'Czekajcie! Stójcie! Nie zabijajcie mnie, błagam! Wszystko wam powiem!', '', 0),
(36842, 'plPL', 'To, czego szukacie, znajduje się w leżu pana, ale żeby się tam dostać, musicie zniszczyć Tyrannusa. A w Salach Odbić znajdziecie Ostrze Mrozu. Ono... Ono kryje prawdę.', '', 0),
(36843, 'plPL', 'Przysięgam, że to prawda! Proszę, nie zabijajcie mnie!!', '', 0),
(36844, 'plPL', 'Urg... nie!!', '', 0),
(36919, 'plPL', 'Stare rany wciąż dają o sobie znać, $gchłopcze:dziewczyno;. Do dziś czuję je w kościach. Ano, mam z Arthasem rachunki do wyrównania i możesz mi wierzyć, że spuszczę temu chłopakowi lanie, które powinienem był mu spuścić, kiedy był jeszcze smarkaczem. Zawsze wiedziałem, że coś z nim jest nie tak.$B$BDaj znać, kiedy twoja załoga będzie gotowa, a wystartujemy na szczyt cytadeli.$B$BArthas się tego nie spodziewa!', '', 0),
(36920, 'plPL', 'Wszyscy moi towarzysze są na miejscu, Muradinie. Ruszajmy!', 'Wszyscy moi towarzysze są na miejscu, Muradinie. Ruszajmy!', 0),
(36986, 'plPL', '$GZgubiłeś:Zgubiłaś; plecak rakietowy? A w torbach $gsprawdziłeś:sprawdziłaś;?', '', 0),
(37025, 'plPL', 'No proszę, właśnie kogoś takiego jak ty szukałem! Testuję nowe urządzenie latające o napędzie rakietowym i potrzebuję twojej pomocy!\nPo prostu weź jedną z tych uprzęży i załóż ją pod zbroję. Wciśnij guzik z boku i BUM, lecisz.\nTylko nie próbuj kraść mojego dzieła. Każde z tych cacek ma wbudowany transponder 8000 połączony z tym, który trzymam w ręce. Jeśli za bardzo się ode mnie oddalisz, transponder wyłączy główną rakietę i nie wystartujesz, dopóki nie wrócisz.\nZaraz, gdzie ja położyłem te formularze o zrzeczeniu się roszczeń?', '', 0),
(37026, 'plPL', 'Jasne, na pewno bezpieczeństwo jest dla ciebie najważniejsze. Dawaj ten plecak rakietowy.', 'Jasne, na pewno bezpieczeństwo jest dla ciebie najważniejsze. Dawaj ten plecak rakietowy.', 0),
(37037, 'plPL', 'Czy to możliwe, lordzie Fordringu? Jeśli Bolvar żyje, to może jest jeszcze nadzieja na pokój między Przymierzem a Hordą. Musimy dotrzeć na szczyt tego przeklętego miejsca i uwolnić paladyna!', '', 0),
(37043, 'plPL', 'Przygotować Niebołamacza do powietrznego szturmu na cytadelę!', '', 0),
(37046, 'plPL', 'Bohaterowie, musicie wywalczyć sobie drogę do bezpiecznego punktu ewakuacji w Lodowej Koronie. Spróbujemy spotkać się z wami na murach!', '', 0),
(37108, 'plPL', '', '%s szykuje się, by uwolnić falę parzącego chłodu!', 0),
(37109, 'plPL', '', 'A teraz poczujcie bezgraniczną moc mojego pana i rozpaczajcie!', 0),
(37133, 'plPL', '', 'Gińcie!', 0),
(37134, 'plPL', '', 'Skaza śmiertelności...', 0),
(37136, 'plPL', '', 'Wasz najazd kończy się tutaj! Nikt nie przeżyje!', 0),
(37137, 'plPL', '', 'Czujecie zimną dłoń śmierci na swoich sercach?', 0),
(37138, 'plPL', '', 'Cierpcie, śmiertelnicy, gdy zdradza was wasza żałosna magia!', 0),
(37139, 'plPL', '', 'Wolna... nareszcie...', 0),
(37140, 'plPL', '', 'Dość! Męczą mnie te gierki!', 0),
(37160, 'plPL', 'Upadniesz, tak jak przed tobą upadły twoje ziemie i twoje miasto. Mój pan odniesie tu wielkie zwycięstwo i nikt nie będzie pamiętał twojego imienia!', '', 0),
(37161, 'plPL', 'Powietrze w górze przeszywa przeraźliwy skrzek!', '', 0),
(37162, 'plPL', 'Naprzód!', '', 0),
(37167, 'plPL', 'Sam cię zabiję!', '', 0),
(37222, 'plPL', 'Nie wolno przerywać nam pracy! Ick, zajmij się nimi!', '', 0),
(37223, 'plPL', 'Te części pewnie nam się przydadzą.', '', 0),
(37224, 'plPL', 'Rąk i nóg ciągle nam brakuje! Dzięki za wkład!', '', 0),
(37225, 'plPL', 'Rozmyśliłem się, bierz jednak tamtego!', '', 0),
(37226, 'plPL', 'Czemu atakujesz tego? Niebezpieczny jest tamten!', '', 0),
(37301, 'plPL', 'Ghule, zabić tego żałosnego wysokiego elfa!', '', 0),
(37302, 'plPL', 'Upadniesz przed potęgą Plagi. Grabieżcy krypt, do ataku!', '', 0),
(37445, 'plPL', 'Zacięta to była bitwa, $n! Odpocznij chwilę i zbierz siły. Kto wie, co czeka za tymi drzwiami?$B$BDaj znać, kiedy będziesz $ggotów:gotowa;, a zaczniemy wspinaczkę do górnych partii cytadeli.', '', 0),
(37446, 'plPL', 'Jesteśmy gotowi, Muradinie.', 'Jesteśmy gotowi, Muradinie.', 0),
(37447, 'plPL', 'Na pewno, $gchłopcze:dziewczyno;? Nie potrzebujesz jeszcze minuty czy dwóch?', '', 0),
(37448, 'plPL', 'Na pewno. Ruszajmy!', 'Na pewno. Ruszajmy!', 0),
(37457, 'plPL', 'No to ruszamy! Wymar...', '', 0),
(37460, 'plPL', 'Samotny ork przeciwko potędze Przymierza???', '', 0),
(37461, 'plPL', 'Do szarży!!!', '', 0),
(37484, 'plPL', '', 'Quel\'Delar.', 0),
(37485, 'plPL', '', 'Tak jak Quel\'Serrar został wykuty przez smoki i podarowany kaldorei, tak jego bliźniak, Quel\'Delar, został podarowany mojemu ludowi.', 0),
(37486, 'plPL', '', 'Król powierzył to ostrze mojemu przyjacielowi, Thalorienowi Szukającemu Świtu.', 0),
(37487, 'plPL', '', 'Lecz nawet kunszt Thaloriena i magia Quel\'Delara nie zdołały ocalić Srebrnej Luny przed potęgą Plagi.', 0),
(37488, 'plPL', '', 'Thalorien poległ u bram Słonecznej Studni, by inni zyskali czas na ucieczkę.', 0),
(37490, 'plPL', '', 'Po bitwie zabrałam miecz z pola walki. Poniosłam go do Północnej Grani w służbie mojego księcia, pragnąc pomścić klęskę naszego ludu.', 0),
(37491, 'plPL', '', 'Arthas rozbił nasze siły, a najpotężniejszych z nas wziął na swoją służbę jako San\'layn.', 0),
(37492, 'plPL', '', 'Moje wspomnienia o Thalorienie ostygły, a wraz z nimi jego ostrze.', 0),
(37493, 'plPL', '', 'To ja przyniosłam tu Quel\'Delar, by zwrócić go twórcom. Łamiąc tę broń, złamałam też jej moc.', 0),
(37494, 'plPL', '', 'Quel\'Delar już nigdy nikomu nie posłuży!', 0),
(37502, 'plPL', '%s z trudem łapie powietrze.', '', 0),
(37503, 'plPL', 'To był chłopak Zaurzykła – dowódca Hordy spod Bramy Gniewu. Cóż za tragiczny koniec...', '', 0),
(37504, 'plPL', 'Co u licha... Tam, w oddali!', '', 0),
(37505, 'plPL', 'Żołnierze, zbiórka! Wygląda na to, że Horda chce spróbować jeszcze raz!', '', 0),
(37511, 'plPL', '', 'Głupcy z was, że tu przybyliście. Lodowate wichry Północnej Grani pochłoną wasze dusze!', 0),
(37524, 'plPL', 'Nie zmuszaj mnie, orku. Nie możemy cię przepuścić.', '', 0),
(37526, 'plPL', 'Nie... Nie potrafię. Wracaj na swój statek, a darujemy ci życie.', '', 0),
(37527, 'plPL', 'Odstąp, Muradinie. Przepuść ojca w żałobie.', '', 0),
(37530, 'plPL', 'Ja... Nie było mnie pod Bramą Gniewu, ale żołnierze, którzy przeżyli, wiele mi opowiedzieli o tym, co się tam stało. Twój syn walczył z honorem. Zginął śmiercią bohatera. Zasługuje na pogrzeb godny bohatera.', '', 0),
(37537, 'plPL', 'Plecak rakietowy aktywny!', 'Plecak rakietowy aktywny!', 0),
(37538, 'plPL', 'Plecak rakietowy wyłączony. Podejdź bliżej do Zafoda Boomboxa, by włączyć go ponownie.', 'Plecak rakietowy wyłączony. Podejdź bliżej do Zafoda Boomboxa, by włączyć go ponownie.', 0),
(37543, 'plPL', 'Jaino? Dlaczego płaczesz?', '', 0),
(37544, 'plPL', '', '%s ociera łzy i uśmiecha się do króla Variana Wrynna.', 0),
(37545, 'plPL', 'Ba! Muradinie, zabezpiecz pokład i przygotuj naszych żołnierzy do szturmu na górną część cytadeli. Wyślę z Wichrogrodu kolejny pułk.', '', 0),
(37546, 'plPL', '', 'To nic, Wasza Wysokość. Po prostu... jestem dumna z mojego króla.', 0),
(37547, 'plPL', 'Natychmiast, Wasza Wysokość!', '', 0),
(37563, 'plPL', 'Czego ci trzeba, to Brazie Getz załatwi! Łapiesz?$B$BI nie mówię tylko o „legalnym” towarze. CZEGOKOLWIEK CI TRZEBA! Cokolwiek...', '', 0),
(37565, 'plPL', 'Nie kręcą mnie te twoje dziwactwa, Brazie. Pokaż mi po prostu „legalny” towar.', 'Nie kręcą mnie te twoje dziwactwa, Brazie. Pokaż mi po prostu „legalny” towar.', 0),
(37619, 'plPL', 'Dziwny z ciebie mały gość.', 'Dziwny z ciebie mały gość.', 0),
(37636, 'plPL', 'Doszły mnie słuchy, że jest tu mój chłopiec. Że jest teraz potężnym rycerzem śmierci w służbie Króla Lisza. Jeśli to prawda, to ja muszę zakończyć nasz ród.$B$BMoim zadaniem jest teraz poprowadzić Młot Orgrima na szczyt Cytadeli Lodowej Korony i zniszczyć całą Plagę, która stanie nam na drodze. Wyruszymy, gdy ty i twoi sojusznicy będziecie gotowi.', '', 0),
(37637, 'plPL', 'Wszyscy moi towarzysze są na miejscu, Zaurzykieł. Ruszajmy!', 'Wszyscy moi towarzysze są na miejscu, Zaurzykieł. Ruszajmy!', 0),
(37650, 'plPL', 'Słyszę i jestem posłuszny, panie...', '', 0),
(37651, 'plPL', 'Wróg będzie srodze cierpiał, panie!', '', 0),
(37677, 'plPL', 'Odpalać silniki! Mamy spotkanie z przeznaczeniem, chłopaki!', '', 0),
(37678, 'plPL', 'Trzymajcie czapki!', '', 0),
(37679, 'plPL', 'A cóż to takiego? Podaj no mi lunetę, marynarzu!', '', 0),
(37680, 'plPL', 'Na moją brodę! HORDA WALI NA NAS PEŁNĄ PARĄ!', '', 0),
(37681, 'plPL', 'UNIK! DO DZIAŁ!', '', 0),
(37682, 'plPL', 'Tchórzliwe psy! Zaszliście nas znienacka!', '', 0),
(37683, 'plPL', 'Nie moja bitwa? Nie wiem, za kogo się masz, mój panie, ale mam z Arthasem rachunki do wyrównania i nie wejdziesz mi w drogę! OGNIA ZE WSZYSTKICH DZIAŁ! OGNIA! OGNIA!', '', 0),
(37685, 'plPL', 'To nie twoja bitwa, krasnoludzie. Wycofaj się albo będziemy zmuszeni zniszczyć twój statek.', '', 0),
(37689, 'plPL', 'Powstańcie, synowie i córki Hordy! Dziś walczymy ze znienawidzonym wrogiem Hordy! LOK\'TAR OGAR!', '', 0),
(37691, 'plPL', 'Kor\'kronie, startujemy!', '', 0),
(37692, 'plPL', 'Co to? Coś zbliża się z oddali.', '', 0),
(37694, 'plPL', 'KANONIERKA PRZYMIERZA! WSZYSCY NA POKŁAD!', '', 0),
(37697, 'plPL', 'Teraz odpowiadacie przed Zaurzykłem!', '', 0),
(37698, 'plPL', 'Wkrótce poznacie nasze sprawy. Kor\'kronie, UNICESTWIĆ ICH!', '', 0),
(37699, 'plPL', 'Zabieraj tego gruchota albo zdmuchniemy go z nieba, orku! Horda nie ma tu czego szukać.', '', 0),
(37700, 'plPL', 'Strzelcy, strzelać szybciej!', '', 0),
(37701, 'plPL', 'Moździerzyści, ładuj!', '', 0),
(37702, 'plPL', 'Piechota morska, sierżanci, do ataku!', '', 0),
(37703, 'plPL', 'Kadłub obrywa, dajcie tu czarownika, niech uciszy te działa!', '', 0),
(37704, 'plPL', 'A to co?! Nie zabierzecie statku temu synowi Żelaznej Kuźni bez walki!', '', 0),
(37705, 'plPL', 'Nie mówcie, że nie ostrzegałem, łotry! Naprzód, bracia i siostry!', '', 0),
(37706, 'plPL', 'Kapitanie Bartlett, zabieraj nas stąd! Za mocno oberwaliśmy, żeby utrzymać się w powietrzu!', '', 0),
(37708, 'plPL', 'Miotacze toporów, miotać szybciej!', '', 0),
(37709, 'plPL', 'Rakietnicy, ładuj!', '', 0),
(37710, 'plPL', 'Łupieżcy, sierżanci, do ataku!', '', 0),
(37711, 'plPL', 'Kadłub obrywa, dajcie tu maga bojowego, niech uciszy te działa!', '', 0),
(37712, 'plPL', 'ŚMIECIE wdzierać się na mój statek? Wasza śmierć nadejdzie szybko.', '', 0),
(37713, 'plPL', 'Przymierze słabnie. Naprzód, na Króla Lisza!', '', 0),
(37714, 'plPL', 'Brygada awaryjna! Gasić te pożary. Jeszcze usłyszycie o Hordzie!', '', 0),
(37894, 'plPL', '', 'Cisza, głupcy. Gdybym chciała was zabić, już bylibyście martwi.', 0),
(38049, 'plPL', 'APOKALIPSA!', '', 0),
(38109, 'plPL', 'Podarujemy ci szybką śmierć, Arthasie. To więcej, niż dostały tysiące tych, których torturowałeś i zabiłeś.', '', 0),
(38110, 'plPL', 'Niech tak będzie. Czempioni, do ataku!', '', 0),
(38111, 'plPL', 'ŚWIATŁOŚCI, UDZIEL MI OSTATNIEGO BŁOGOSŁAWIEŃSTWA! DAJ MI SIŁĘ... BYM STRZASKAŁ TE WIĘZY!', '', 0),
(38112, 'plPL', 'Dość, Arthasie! Twoja nienawiść nie pochłonie już ani jednego życia!', '', 0),
(38113, 'plPL', 'Król Lisz musi upaść!!', '', 0),
(38114, 'plPL', 'Przybywasz, by wymierzyć Arthasowi sprawiedliwość? By ujrzeć zagładę Króla Lisza?', '', 0),
(38115, 'plPL', 'Najpierw musisz wyrwać się z uścisku Ostrza Mrozu, inaczej czeka cię potępienie jak mnie – uwięzienie w tym przeklętym ostrzu na całą wieczność.', '', 0),
(38116, 'plPL', 'Pomóż mi zniszczyć te udręczone dusze! Razem poluzujemy uścisk Ostrza Mrozu i osłabimy Króla Lisza od środka!', '', 0),
(38117, 'plPL', 'Nareszcie wolny! To koniec, mój synu. Nadeszła chwila rozrachunku.', '', 0),
(38118, 'plPL', 'Powstańcie, czempioni Światłości!', '', 0),
(38129, 'plPL', 'Długo czekałem na ten dzień, $gbohaterze:bohaterko;. Czy ty i twoi sojusznicy jesteście gotowi wymierzyć Królowi Liszowi sprawiedliwość? Ruszymy do szarży na twój rozkaz!', '', 0),
(38131, 'plPL', 'Jesteśmy gotowi, najwyższy lordzie. Stoczmy bitwę o los Azeroth! Za światło brzasku!', 'Jesteśmy gotowi, najwyższy lordzie. Stoczmy bitwę o los Azeroth! Za światło brzasku!', 0),
(38160, 'plPL', 'Arthasie...', '', 0),
(38161, 'plPL', 'Ach, $gbohaterze:bohaterko; Azeroth, dajesz mi większy dar, niż ci się wydaje.', '', 0),
(38162, 'plPL', 'Długo zmagałem się ze sobą, by wybaczyć księciu jego straszliwe występki.', '', 0),
(38163, 'plPL', 'Moją duszę dręczył nieznośny niepokój i mroczne myśli... które oddalały mnie od Światłości.', '', 0),
(38165, 'plPL', 'Wyraźnie pamiętam błysk dumy w jego oku, gdy stał przede mną, żądny pokonania wrogów Światłości...', '', 0),
(38166, 'plPL', 'Żądny bronić swego ludu, bez względu na cenę.', '', 0),
(38167, 'plPL', 'Takie właśnie wspomnienie Arthasa postanawiam zachować w sercu.', '', 0),
(38168, 'plPL', 'Na zawsze pozostanę twoim dłużnikiem, $gprzyjacielu:przyjaciółko;.', '', 0),
(38169, 'plPL', 'Dziękuję.', '', 0),
(38171, 'plPL', 'Och, chłopcze...', '', 0),
(38172, 'plPL', 'Jak ja tęsknię za tymi niekończącymi się dniami w Lordaeronie...', '', 0),
(38173, 'plPL', '...kiedy szlifowałem twoje umiejętności tym tępym ostrzem...', '', 0),
(38174, 'plPL', '...kiedy wykuwałem z ciebie broń, która miała sprostać wymogom wielkiego przeznaczenia.', '', 0),
(38175, 'plPL', 'Heh... Zrobiłeś z tych umiejętności niezły użytek, co, chłopcze?', '', 0),
(38176, 'plPL', 'Gdybym tylko zdołał cię wtedy powstrzymać, jakże inaczej wszystko mogłoby się potoczyć.', '', 0),
(38177, 'plPL', 'Gdybym tylko nigdy nie odkrył tego przeklętego ostrza...', '', 0),
(38178, 'plPL', 'Żegnaj, Arthasie... mój bracie.', '', 0),
(38179, 'plPL', '', 'A więc stało się.', 0),
(38180, 'plPL', '', 'Nie śmiałam ufać własnym zmysłom – zbyt wiele razy Król Lisz zrobił ze mnie głupią.', 0),
(38181, 'plPL', '', 'Wreszcie zapłacił za okrucieństwa, jakich dopuścił się wobec mojego ludu.', 0),
(38183, 'plPL', '', 'Oby Azeroth nigdy nie zapomniało o straszliwej cenie, jaką zapłaciliśmy za naszą słabość... za naszą pychę.', 0),
(38184, 'plPL', '', 'Ale co teraz, $gbohaterze:bohaterko;? Co z tymi, którzy wyrwali się z jego uścisku, lecz wciąż są przykuci do swych śmiertelnych powłok?', 0),
(38185, 'plPL', '', 'Zostaw mnie.', 0),
(38186, 'plPL', '', 'Mam wiele do przemyślenia.', 0),
(38201, 'plPL', '', 'Co to!?', 0),
(38202, 'plPL', '', 'On... on to zachował? Przez cały ten czas to trzymał!?', 0),
(38203, 'plPL', '', 'Wiedziałam!', 0),
(38204, 'plPL', '', 'Czułam, że jakaś jego cząstka wciąż żyje! Uwięziona... walcząca... Och, Arthasie!', 0),
(38205, 'plPL', '', 'Może... może kiedyś przypomni sobie, kim niegdyś był.', 0),
(38206, 'plPL', '', 'Na Światłość, oby wreszcie zaznał spokoju, wolny od lodowatego uścisku tego strasznego ostrza.', 0),
(38253, 'plPL', 'To cię nauczy pilnować własnego nosa!', '', 0),
(38276, 'plPL', 'Na co się gapisz? Geniusza nie $gwidziałeś:widziałaś;?', '', 0),
(38510, 'plPL', '', 'Naprawdę odszedł, prawda?$b$bJa... Ja to czuję.', 0),
(38511, 'plPL', '', 'Czy naprawdę nie dało się go ocalić?$b$bObawiam się, że już zawsze będę się nad tym zastanawiać.', 0),
(38512, 'plPL', 'G-gdzie ja jestem...? Cóż za koszmar mi się śnił... Ale nie pora na rozmyślania, mam wiele do zameldowania!', '', 0),
(38516, 'plPL', 'Gińcie, intruzi! Nikt nie przeszkodzi planom Kultu!', '', 0),
(38550, 'plPL', '', 'Aaach! To pali! Co to za czary!?', 0),
(38595, 'plPL', 'Służba u twojego boku była największym zaszczytem w moim życiu, Hummel.', '', 0),
(38596, 'plPL', 'Świetnie. Nie jesteśmy tchórzami, tylko nieudacznikami.', '', 0),
(38672, 'plPL', '', '%s wystrzeliwuje zamrożoną sferę w $n!', 0),
(39333, 'plPL', '', '%s wyraźnie słabnie!', 0),
(39400, 'plPL', 'Nieustanne poświęcenie Popielnego Werdyktu i bohaterów takich jak ty przybliża nas wszystkich do ostatecznego zwycięstwa. Przybyłem do Cytadeli Lodowej Korony, by wesprzeć tych, którzy walczą z Plagą. Razem położymy kres tyranii Króla Lisza!', '', 0),
(39401, 'plPL', 'Z całym szacunkiem, Wasza Wysokość, poradzimy sobie sami.', 'Z całym szacunkiem, Wasza Wysokość, poradzimy sobie sami.', 0),
(39402, 'plPL', 'Poradzicie sobie sami, powiadasz? Czy to zwykła głupota, czy nieuzasadniona pewność siebie?\nNie, widzę to w twoich oczach. Musisz wiedzieć. Musisz sobie udowodnić, że podołasz temu bez niczyjej pomocy. Dobrze. Wycofam się z pola bitwy, skoro tego sobie życzysz.', '', 0),
(39405, 'plPL', 'Tak, życzymy sobie, byś się wycofał, Wasza Wysokość.', 'Tak, życzymy sobie, byś się wycofał, Wasza Wysokość.', 0),
(39406, 'plPL', 'Do pokonania Króla Lisza trzeba czegoś więcej niż odwagi. Powodzenia.', '', 0),
(39424, 'plPL', 'Nie zawiodę!', 'Nie zawiodę!', 0),
(39811, 'plPL', '$n, $n. Mogę ci mówić $n?$B$BWiszę na haku rzeźnickim w głębi jaskini ogrów.$B$BJak MYŚLISZ, jak mi idą badania, ty nadęta, żrąca piach dupo-$c? Chodź no tu! Chodź no tu, pomiocie świniopasa!$B$B<Kristoff buja się na łańcuchu w tę i z powrotem, rozpaczliwie próbując kopnąć cię w twarz.>', '', 0),
(39812, 'plPL', '<Kristoff stęka.>', '', 0),
(39814, 'plPL', 'Ze wszystkich pradawnych Goldrinn jest najwspanialszy. Jego furia, jego nieugiętość... warto brać z niego przykład.', '', 0),
(40069, 'plPL', 'Strzeżcie się cienia!', '', 0),
(40071, 'plPL', 'Krążące kule pulsują mroczną energią!', '', 0),
(40072, 'plPL', 'Jam jest światło i ciemność! Kulcie się, śmiertelnicy, przed heroldem Śmiercioskrzydłego!', '', 0),
(40080, 'plPL', 'Dzięki wysiłkom twoich towarzyszy %s zostaje zepchnięty głębiej w królestwo zmierzchu!', '', 0),
(40227, 'plPL', 'Dzięki twoim wysiłkom %s zostaje zepchnięty dalej poza królestwo zmierzchu!', '', 0),
(40546, 'plPL', 'Twoje ciało leży zbite, połamane i skatowane! Niech ma klątwa spadnie na ciebie – tak zostało zapisane!', '', 0),
(41575, 'plPL', 'Jak żyję, czegoś takiego jeszcze nie było mi dane zobaczyć...', '', 0),
(41576, 'plPL', 'Jesteśmy słabo przygotowani do walki w tym miejscu.$b$bTrzeba poczynić przygotowania...', '', 0),
(45681, 'plPL', 'Chrońcie Davila Świetlistego Płomienia!', '', 0),
(45683, 'plPL', 'Na polu bitwy pojawił się kapitan Redpath! Chrońcie go!', '', 0),
(45684, 'plPL', 'Kapitan Joseph Redpath został splugawiony! Zabijcie go szybko!', '', 0),
(45685, 'plPL', 'Porozmawiaj z Josephem Redpathem na środku Włości Darrow.', '', 0),
(46528, 'plPL', 'Machina wojenna Hordy cię potrzebuje!', '', 0),
(47896, 'plPL', '', 'Brzemię przywództwa to dla mnie nowość. Niesubordynację Narkralla należało przewidzieć. Tymczasem sprzątam po nim bałagan.$B$BNie wiem, jak Garosz Piekłorycz to robi. Musi mieć wielką siłę, skoro utrzymuje w ryzach coś tak różnorodnego jak Horda... Chętnie poznam go lepiej.', 0),
(49174, 'plPL', '', 'No? Czego chcesz?', 0),
(50710, 'plPL', 'To tutaj, $n! Tu stawimy im czoła!', '', 0),
(50715, 'plPL', 'Wygląda na to, że tego urządzenia teleportacyjnego niedawno używano do przesyłania różnych towarów w głąb kopalni.', 'Wygląda na to, że tego urządzenia teleportacyjnego niedawno używano do przesyłania różnych towarów w głąb kopalni.', 0),
(50743, 'plPL', '', 'Ach... no tak, no tak. To idź. Idź na spotkanie śmierci.', 0),
(50747, 'plPL', '', 'Witaj na festiwalu Wiklinowego Człowieka, $N!$B$BW Zaduszniki palimy Wiklinowego Człowieka na znak oczyszczenia samych siebie. Tak jak lasy wzdychają i zrzucają liście, tak i my musimy przejść katharsis. Lęki, smutki, żale – wrzucając gałąź w płomienie, możesz uwolnić się od każdego brzemienia, którego nie chcesz dźwigać przez zimę.$B$BProszę, weź gałąź z ogniska i przyłącz się do obchodów!', 0),
(50748, 'plPL', 'Czujesz zło, które kala samą ziemię, $N? Bije z głębi Warowni Cienia. Jeśli nikt go nie powstrzyma, pochłonie wszystko na swojej drodze.$B$B<Nocny elf kaszle, odsłaniając krwawą ranę w boku.>', '', 0),
(52525, 'plPL', 'Przychodzisz przyłączyć się do walki, $N?', 'Przychodzisz przyłączyć się do walki, $N?', 0),
(53398, 'plPL', 'Witaj na Placu Zbornym Festynu Lunomroku.$b$bTen portal przeniesie cię na Festyn Lunomroku.$b$bAle jeśli przedtem masz jakieś pytania, chętnie na nie odpowiem.', 'Witaj na Placu Zbornym Festynu Lunomroku.$b$bTen portal przeniesie cię na Festyn Lunomroku.$b$bAle jeśli przedtem masz jakieś pytania, chętnie na nie odpowiem.', 0),
(53401, 'plPL', 'Miniaturowe czołgi, czyli tonki, jak je sprytnie nazwaliśmy, są ulubioną atrakcją festynu, odkąd pamiętam.$b$bMamy dwie areny przeznaczone do bitew tonków.$b$bNa jednej ścigasz się z czasem: niszczysz cele i unikasz wrogich tonków. Żeby zagrać, wystarczy żeton do gier!$b$bDruga arena to miejsce, gdzie możesz stoczyć bitwę z przyjaciółmi, używając własnych tonków albo minizepów.', 'Miniaturowe czołgi, czyli tonki, jak je sprytnie nazwaliśmy, są ulubioną atrakcją festynu, odkąd pamiętam.$b$bMamy dwie areny przeznaczone do bitew tonków.$b$bNa jednej ścigasz się z czasem: niszczysz cele i unikasz wrogich tonków. Żeby zagrać, wystarczy żeton do gier!$b$bDruga arena to miejsce, gdzie możesz stoczyć bitwę z przyjaciółmi, używając własnych tonków albo minizepów.', 0),
(61812, 'plPL', 'DO ATAKU!!!', '', 0),
(69412, 'plPL', 'Tak.', 'Tak.', 0);
